function result = execute_m12_contact_engagement_policy(varargin)
%EXECUTE_M12_CONTACT_ENGAGEMENT_POLICY Shared M12/M10 KST+Bota task engine.
%
% Dedicated no-argument entrypoints select Proposed+, Proposed, Pure
% Outward, Improved Direct x3, the paired four-method experiment, or a
% 26-point sampling campaign without duplicating the physical task loop.
% Calling this engine with no argument
% retains the historical Proposed+ default, but operators should normally
% launch one of the explicitly named public entrypoints.  Every full-loop
% mode treats the fresh stationary live flange pose as this run's manually
% taught near-hole start, then executes one bounded task.  All full-loop
% modes share touchdown, force-held endpoint control, physical capture,
% insertion and terminal verification; only the registered routing/search
% policy differs.  Every search origin is the measured touchdown XY after a
% separate pure-Z lateral-drift gate, never the manually taught air-pose XY.
%
% Put MatlabToolboxServer in Running before an explicitly chosen full-loop
% entry.  There is no preview, token, or normal automatic return.  Improved
% Direct alone has its registered finite three-attempt reset policy.  A task
% failure stops future commands and sends "end" at the measured current pose
% so the operator can recover manually.  Every active comparison route uses
% either a promoted real-data conical posterior or a purely geometric path.
% In the three conical full-loop modes the model owns only the high-level
% direction/state-posterior route.  MATLAB remains the sole robot command
% owner and retains force transport, capture, insertion, terminal and hard
% protection authority.  The sampling entrypoint loads no model at all; it
% records real raw/relative signals for offline QC.
%
% The full-loop entry intentionally supports the already field-proven
% predecessor's commissioning level while retaining this newer controller.
% Until post-print pivot/payload/fixture metrology is completed, KST receives
% the observed axial TCP [0 0 92] mm, the operator-taught near-hole start is
% treated as WORLD-aligned, and the fresh touchdown/capture positions define
% this run's local surface and insertion datum.  This compatibility state is
% written explicitly to every manifest; it is not represented as measured or
% certified metrology.  The M12 sampling entrypoint instead records an
% operator-taught run-local centre and preserves all raw acquisition evidence.
% A conical full-loop requires the hash-bound CAPPED_SHORTCUT promotion
% contract before KST opens.  There is no classical direction fallback.
%
% The conical scan starts at the measured touchdown and keeps the registered
% tip TCP WORLD XY fixed.  A transparent support-function feedforward raises
% the TCP just enough for the rotating 8 mm-AF hex edge while asymmetric
% WORLD-Z force following holds a light bounded load.  A soft force governor freezes the
% current cone phase and unloads in +Z before continuing; the independent
% 25 N / 0.75 Nm guards remain immediate.  The tool axis ramps to 15 degrees,
% completes one continuous 360 degree nutation, and returns upright.  No
% separate air-reference lift is inserted.  The displayed
% WORLD* force rotates the current and upright-start baseline vectors into
% WORLD separately before subtraction; this cancels a rigid gravity-force
% vector without pretending that missing tool CoM/inertia or the
% measurement-origin-to-tip torque shift is calibrated.  Torque remains a
% provisional measurement-origin signal and is not used to steer the shortcut.
% The deployed MatlabToolboxServer predates the optional
% DcSeCarEEfP_ command-plus-pose protocol.  Match the KST tutorials and the
% predecessor experiments: stream DcSeCar_ with sendEEfPositionf.  Synchronous
% KST state queries are deliberately excluded from the command loop because a
% measured query took about 0.18 s on the deployed server and broke the
% DirectServo cadence.  Fresh robot state is checked immediately before start
% and immediately after DirectServo stops; in-loop pose rows are explicitly
% marked command-propagated rather than measured feedback.
%
% KST line moves are blocking.  Bota is observed only after every commanded
% endpoint.  Touchdown/insertion use 0.10 mm commands; force-held surface
% transport can combine 0.60 mm XY with 0.08 mm Z (about 0.61 mm resultant).
% These are geometric maximum-unobserved commands, not certified stopping
% distances.

[executionMode, resumeParentRunDir] = parseExecutionMode(varargin{:});
pairedTrialSpec = parsePairedTrialSpec(executionMode, varargin{:});
policy = executionPolicy(executionMode);
pairedTrialMode = pairedTrialSpec.enabled;
if strcmp(executionMode, ...
        'FULL_LOOP_PROPOSED_PLUS_LEARNED_ENTROPY_M10')
    assert(pairedTrialMode && strcmp(char(pairedTrialSpec.schema), ...
            'M10_PROPOSED_PLUS_FIXED_DEMO_PRIVATE_TRIAL_V1'), ...
        'M12Demo:M10FixedDemoPrivateSpecRequired', ...
        ['M10 learned hardware routing is authorized only through the ', ...
         'hash-pinned fixed-demo launcher and its exact private offset.']);
end
if pairedTrialMode
    % Take the launcher name from the validated spec.  Hardcoding the
    % four-method entrypoint here would have mislabelled every
    % proposed-vs-direct run as a paired-campaign run in its own record.
    policy.public_entrypoint = ...
        char(pairedTrialSpec.public_entrypoint);
    policy.description = [policy.description, ...
        '  This invocation was selected by a fixed private demo campaign; ', ...
        'the private offset is consumed only by the pre-touchdown air ', ...
        'transport and is never supplied to learned or CAD routing.'];
end
if ~isempty(resumeParentRunDir)
    switch executionMode
        case 'DATASET_M8_CONICAL_FINGERPRINTS_26PT'
            policy.public_entrypoint = ...
                'run_m8_sampling_conical_fingerprints_26pt_resume';
            policy.run_prefix = 'M8_conical_fingerprints_26pt_resume_';
            resumeSize = 'M8';
        case 'DATASET_M10_CONICAL_FINGERPRINTS_26PT'
            policy.public_entrypoint = ...
                'run_m10_sampling_conical_fingerprints_26pt_resume';
            policy.run_prefix = 'M10_conical_fingerprints_26pt_resume_';
            resumeSize = 'M10';
        otherwise
            policy.public_entrypoint = ...
                'run_m12_sampling_conical_fingerprints_26pt_resume';
            policy.run_prefix = 'M12_conical_fingerprints_26pt_resume_';
            resumeSize = 'M12';
    end
    policy.description = ...
        ['Explicit child-run continuation of a validated incomplete ', ...
         resumeSize, ' ', ...
         'sampling lineage; completed cones are never replayed.'];
end
samplingMode = policy.sampling_mode;
realDir = fileparts(mfilename('fullpath'));
workspaceRoot = fileparts(fileparts(realDir));
sourcePath = [mfilename('fullpath'), '.m'];
cfg = makeConfig(realDir, workspaceRoot, policy.cad_size);
cfg.execution_mode = executionMode;
cfg = applySamplingSizeProfile(cfg, executionMode, realDir);
if strcmp(executionMode, ...
        'FULL_LOOP_PROPOSED_PLUS_LEARNED_ENTROPY_M10')
    assert(strcmp(char(pairedTrialSpec.controller_tuning_revision), ...
            char(cfg.insertion.controller_tuning_revision)), ...
        'M12Demo:M10ControllerTuningRevisionMismatch', ...
        ['The M10 launcher and shared engine disagree on the force/terminal ', ...
         'tuning revision; no run directory or robot connection is allowed.']);
end
cfg.sampling.resume_parent_run_dir = resumeParentRunDir;
cfg.sampling.resume_requested = ~isempty(resumeParentRunDir);
cfg.public_entrypoint_path = canonicalPath(fullfile( ...
    realDir, [policy.public_entrypoint, '.m']));
assert(isfile(cfg.public_entrypoint_path), ...
    'M12Demo:PublicEntrypointMissing', ...
    'The selected public entrypoint is missing: %s', ...
    cfg.public_entrypoint_path);
cfg.public_entrypoint_sha256 = ...
    sha256File(cfg.public_entrypoint_path);
if samplingMode
    cfg.learning.enabled = false;
    cfg.learning.default_authority = 'NONE';
    cfg.sensor.baseline_samples = cfg.sampling.baseline_samples;
    cfg.motion.maximum_active_time_s = ...
        cfg.sampling.maximum_active_time_s;
    cfg.motion.maximum_up_excursion_mm = max( ...
        cfg.motion.maximum_up_excursion_mm, ...
        cfg.sampling.maximum_retract_mm + 1.0);
end
plan = makePlan(cfg, policy);
validateSurfaceTransportContract(cfg);
validateBaselinePolicyContract(cfg);
samplingPlan = struct();
samplingResume = struct('enabled', false);
if samplingMode
    samplingPlan = loadM12SamplingPlan( ...
        cfg.files.fixture_sampling_plan, cfg);
    if cfg.sampling.resume_requested
        samplingResume = loadM12SamplingResumeParent( ...
            cfg.sampling.resume_parent_run_dir, realDir, ...
            samplingPlan, cfg);
    end
    cfg.motion.maximum_lateral_excursion_mm = max( ...
        cfg.motion.maximum_lateral_excursion_mm, ...
        samplingPlan.required_sampling_only_lateral_excursion_mm);
    validateM12SamplingContract(cfg);
end

runStamp = char(datetime('now', 'TimeZone', 'local', ...
    'Format', 'yyyyMMdd_HHmmss_SSS'));
runPrefix = policy.run_prefix;
runDir = fullfile(realDir, 'data', ...
    [runPrefix, runStamp]);
[made, makeMessage] = mkdir(runDir);
assert(made, 'M12Demo:RunDirectory', ...
    'Cannot create run directory %s: %s', runDir, makeMessage);
paths = initializeRunFiles(runDir, samplingMode);
if samplingMode
    writeSamplingExecutionPlan(paths.plan, samplingPlan, cfg);
else
    writePlan(paths.plan, plan, cfg);
end

result = makeInitialResult(runDir, sourcePath, cfg);
manifest = makeManifest(sourcePath, result, cfg, plan);
[result, manifest] = discloseExecutionPolicy( ...
    result, manifest, policy, cfg);
if pairedTrialMode
    result.paired_trial_public_token = ...
        pairedTrialSpec.public_trial_token;
    result.paired_trial_firewall_contract = ...
        'M12_PAIRED_TRUTH_FIREWALL_V1';
    manifest.paired_trial_public_token = ...
        pairedTrialSpec.public_trial_token;
    if isfield(pairedTrialSpec, 'controller_tuning_revision')
        result.paired_trial_controller_tuning_revision = ...
            char(pairedTrialSpec.controller_tuning_revision);
        manifest.paired_trial_controller_tuning_revision = ...
            char(pairedTrialSpec.controller_tuning_revision);
    end
    manifest.paired_trial_firewall_contract = struct( ...
        'schema', 'M12_PAIRED_TRUTH_FIREWALL_V1', ...
        'oracle_available_to_learned_or_cad_routing', false, ...
        'offset_used_only_for_pre_touchdown_air_transport', true, ...
        'fresh_center_retained_only_by_m10_head_support_fail_stop', ...
            strcmp(executionMode, ...
                'FULL_LOOP_PROPOSED_PLUS_LEARNED_ENTROPY_M10'), ...
        'control_origin', ...
            'FRESH_MEASURED_POST_AIR_START_THEN_MEASURED_TOUCHDOWN', ...
        'learned_input_contains_offset_or_hole_center', false);
end
manifest.kst_state_recovery_policy = struct( ...
    'post_motion_protocol_settle_s', ...
        cfg.kst.post_motion_protocol_settle_s, ...
    'inter_state_query_settle_s', ...
        cfg.kst.inter_state_query_settle_s, ...
    'read_only_recovery_attempts', ...
        cfg.kst.read_only_recovery_attempts, ...
    'read_only_recovery_pause_s', ...
        cfg.kst.read_only_recovery_pause_s, ...
    'motion_reissue_permitted', false, ...
    'recovery_requires_exact_pose_and_joint_vectors', true, ...
    'recovery_requires_two_consistent_observations', true, ...
    'known_server_race', ...
        'UNSYNCHRONIZED_SHARED_DACOMMAND_CLEAR_AFTER_REPLY');
if samplingMode
    manifest.sampling_resume_requested = samplingResume.enabled;
    if samplingResume.enabled
        manifest.sampling_resume_parent_run_directory = ...
            samplingResume.parent_run_dir;
        manifest.sampling_resume_parent_run_session_id = ...
            samplingResume.parent_run_session_id;
        manifest.sampling_campaign_lineage_id = ...
            samplingResume.campaign_lineage_id;
        manifest.sampling_resume_completed_cone_indices = ...
            samplingResume.completed_cone_indices;
        manifest.sampling_resume_pending_execution_indices = ...
            samplingResume.pending_execution_indices;
    end
end
if samplingMode
    result.claim_endpoint = ...
        'commissioning_data_only_not_full_loop_authorization';
    result.control_classification = sprintf( ...
        'guarded_run_local_%s_conical_fingerprint_acquisition', ...
        cfg.sampling.size_lower);
    result.sampling_data_authority = ...
        cfg.sampling.campaign_authority;
    result.sampling_model_policy = cfg.sampling.model_policy;
    manifest.sampling_plan_path = cfg.files.fixture_sampling_plan;
    manifest.sampling_plan_sha256 = ...
        sha256File(cfg.files.fixture_sampling_plan);
    manifest.sampling_attempt_count = numel(samplingPlan.points);
    manifest.sampling_printed_cad_sources = samplingPlan.source_files;
    manifest.sampling_printed_cad_geometry_mm = samplingPlan.geometry_mm;
    manifest.sampling_touchdown_contact_state_definition = ...
        samplingPlan.contact_state_definition;
    manifest.sampling_cone_command_geometry = ...
        samplingPlan.cone_command_geometry;
    manifest.sampling_design = samplingPlan.sampling_design;
    manifest.sampling_required_lateral_excursion_mm = ...
        samplingPlan.required_sampling_only_lateral_excursion_mm;
    manifest.sampling_data_authority = ...
        'COMMISSIONING_DATA_ONLY_NOT_FULL_LOOP_AUTHORIZATION';
    manifest.sampling_simulation_contract_hash_only_not_loaded = true;
    manifest.installed_tool_gravity_policy = ...
        ['current installed ', cfg.sampling.size_upper, ...
         ' tool gravity is absorbed only by the fresh start and per-point ', ...
         'air baselines; raw Bota six-axis samples remain unchanged'];
    manifest.run_local_installation_record_path = ...
        cfg.files.fixture_frame_commissioning;
    manifest.run_local_installation_record_sha256 = ...
        sha256File(cfg.files.fixture_frame_commissioning);
    manifest.run_local_installation_record_authority = ...
        'IDENTITY_AND_DISCLOSURE_ONLY_NOT_PAYLOAD_OR_AS_BUILT_METROLOGY';
    manifest.operator_start_contract = ...
        ['invoking the dedicated sampling entrypoint is the motion ', ...
         'authorization; the operator has already placed the upright, ', ...
         'non-contact tip above the ', cfg.sampling.size_upper, ...
         ' centre with WORLD-aligned fixture ', ...
         'X/Y and the printed peg yaw datum; the first fresh stationary ', ...
         'capture defines this run''s local XY centre; no second phrase'];
    manifest.sampling_motion_authorization_source = ...
        cfg.sampling.motion_authorization_source;
    manifest.sampling_interactive_confirmation_required = ...
        cfg.sampling.interactive_confirmation_required;
    manifest.sampling_touchdown_tracking_policy = struct( ...
        'immediate_acceptance_mm', ...
            cfg.sampling.step_tracking_tolerance_mm, ...
        'recheck_acceptance_mm', ...
            cfg.sampling.step_tracking_recheck_acceptance_mm, ...
        'recheck_count', cfg.sampling.step_tracking_recheck_count, ...
        'recheck_pause_s', cfg.sampling.step_tracking_recheck_pause_s, ...
        'minimum_measured_down_progress_mm', ...
            cfg.sampling.minimum_touchdown_down_progress_mm, ...
        'xy_landing_gate_mm', ...
            cfg.sampling.maximum_touchdown_xy_lock_error_mm, ...
        'per_step_downward_progress_abort_enabled', false, ...
        'finite_touchdown_schedule_and_contact_event_are_authoritative', ...
            true, ...
        'generic_vector_ratio_gate_applied_after_acceptance', false);
    manifest.sampling_contact_observation_policy = struct( ...
        'preferred_target_normal_force_n', ...
            cfg.sampling.contact_stability.target_normal_force_n, ...
        'preferred_force_deadband_n', ...
            cfg.sampling.contact_stability.force_deadband_n, ...
        'preferred_maximum_force_std_n', ...
            cfg.sampling.contact_stability.maximum_force_std_n, ...
        'passive_observation_s', ...
            cfg.sampling.contact_stability.passive_observation_s, ...
        'maximum_observation_s', ...
            cfg.sampling.contact_stability.maximum_observation_s, ...
        'issues_motion_commands', false, ...
        'soft_force_quality_can_skip_cone', false, ...
        'confirmed_contact_continues_to_cone', true, ...
        'nonpreferred_load_requires_offline_qc', true);
    manifest.sampling_point_acquisition_retry_policy = struct( ...
        'maximum_attempts', ...
            cfg.sampling.maximum_point_acquisition_attempts, ...
        'retryable_conditions', {{ ...
            'POINT_AIR_BASELINE_CONTAMINATED', ...
            'NO_PERSISTENT_CONTACT', ...
            'MEASURED_CONTACT_XY_OUTSIDE_PLAN_TOLERANCE'}}, ...
        'retry_requires_clear_retract_after_touchdown', true, ...
        'capture_or_bore_entry_is_not_retried', true, ...
        'hard_or_unknown_state_is_not_caught', true);
    manifest.shortcut_rule = ...
        'not_applicable_to_data_acquisition_no_runtime_model_or_inference';
    manifest.policy_uses_learned_direction_for_motion = false;
    manifest.learned_motion_preflight_rule = ...
        'not_run_in_sampling_mode';
    manifest.bayesian_model_status = ...
        'not_loaded_real_device_acquisition_only';
    manifest.trained_model_active_inference_scheduled = false;
    manifest.trained_model_deployment_status = ...
        'not_loaded_by_sampling_entrypoint';
    manifest.trained_model_id = '';
    manifest.trained_model_manifest_path = '';
    manifest.trained_model_default_authority = 'NONE';
    manifest.grid_rule = ...
        ['printed-CAD polygon-overlap 26-point local-offset plan around ', ...
         'the operator-taught run-local centre, with supported, double-', ...
         'overhang and outer-partial touchdown states and no centre sample'];
    manifest.terminal_rule = ...
        ['after each point lift 0.75mm locally and immediately test two ', ...
         'wrench-clear dwells; extend by 0.25mm only when still loaded, ', ...
         'to at most the run-local home+3mm ceiling'];
    manifest.workflow = {{ ...
        ['OPERATOR_TAUGHT_RUN_LOCAL_', ...
         cfg.sampling.size_upper, '_CENTER'], ...
        'INITIAL_2MM_LIFT_EXTEND_TO_3MM_IF_NEEDED', ...
        'PRINTED_CAD_DERIVED_SENTINEL_CONSTRAINED_SHORT_ROUTE', ...
        'UP_TO_3_POINT_LOCAL_BASELINE_AND_TOUCHDOWN_ATTEMPTS', ...
        ['XY_ANCHORED_TOUCHDOWN_THEN_PASSIVE_FRESH_BOTA_OBSERVATION_', ...
         'WITH_SOFT_LOAD_QUALITY_NONBLOCKING'], ...
        'FULL_15DEG_40HZ_6S_CONE_WITH_UI_FROZEN', ...
        'ADAPTIVE_CLEAR_RETRACT_AND_POST_CONE_BATCH_EXPORT', ...
        'STRICT_PARTITION_AND_OFFLINE_QC_CHECKPOINT', ...
        'SAFE_ONLY_RETURN_TO_INITIAL_AIR_POSE_AND_KST_END'}};
    manifest.claim_boundary = {{ ...
        'Commissioning data only; not full-loop authorization.', ...
        'No online model update or automatic training admission.', ...
        ['Each point retains raw wrench plus an independent fresh local air ', ...
         'baseline; no simulation or learned output changes sample validity.'], ...
        sprintf(['Touchdown state is an AF%.3g printed-tip polygon label; ', ...
         'the AF%.3g/chamfer 15-degree cone projection is stored separately.'], ...
         cfg.sampling.expected_geometry_mm(5), ...
         cfg.sampling.expected_geometry_mm(6)), ...
        'Unknown state aborts at current pose without blind return.'}};
    if samplingResume.enabled
        manifest.operator_start_contract = ...
            ['explicit resume child: retain the hash-validated parent ', ...
             cfg.sampling.size_upper, ' ', ...
             'centre and route; the fresh child stationary pose supplies ', ...
             'only current robot/Bota state, clear-height/Z budget and the ', ...
             'child return pose; completed cones are never replayed'];
        manifest.workflow = {{ ...
            'VALIDATE_PARENT_CHECKPOINT_PLAN_CAD_IDENTITIES_AND_HASHES', ...
            'CAPTURE_FRESH_CHILD_STATIONARY_STATE_AND_AIR_BASELINE', ...
            'VERIFY_PARENT_BASELINE_CONTINUITY_BEFORE_ANY_MOTION', ...
            'ADAPTIVE_INITIAL_LIFT_AND_CLEAR_CONFIRMATION', ...
            'CLOSE_PENDING_PARENT_MOTION_LIFECYCLE_WITH_RECOVERY_CLEAR', ...
            'SKIP_HASH_VALIDATED_COMPLETE_CONES', ...
            'RUN_ONLY_PENDING_26_POINT_ROUTE_ACTIONS', ...
            'CONE_ATOMIC_CHECKPOINT_BEFORE_EACH_RETRACT', ...
            'RETURN_TO_CHILD_INITIAL_POSE_ONLY_FROM_KNOWN_CLEAR_STATE'}};
    end
end
writeJson(paths.manifest, manifest);
writeEndState(paths, false, 'NOT_OPENED', ...
    'MatlabToolboxServer has not been opened by this run.');
logTransition(paths.transitions, 'NONE', 'LIVE_EXECUTION_ENTRY', ...
    'F5_ENTRY_ACCEPTED', ...
    'Direct live entry; state, sensor, command-owner, workspace, and hard guards follow.');
result.live_entry_accepted = true;

iiwa = [];
kstOpened = false;
endState = struct('sent', false, 'method', 'NOT_OPENED');
ctx = struct();
rosCleanup = [];
kstCleanup = [];
realtimeLogCleanup = [];
compatibilityMode = ~samplingMode && ...
    cfg.compatibility.old_kernel_motion_compatibility_enabled;
runLocalSamplingMode = samplingMode;

try
qualification = loadQualification(cfg.files.qualification, cfg);
if samplingMode
    cfg.sampling.conical_phase_pose_tracking = struct( ...
        'status', 'COLLECTION_ONLY_PRE_POST_MEASURED_POSE', ...
        'qualified_for_training_candidates', false, ...
        'rule', ['Command phase and raw wrench are recorded in full; ', ...
                 'offline QC decides later and no runtime model is loaded.']);
else
    cfg.sampling.conical_phase_pose_tracking = ...
        loadConicalPhasePoseTrackingQualification( ...
            cfg.files.tool_metrology_commissioning, cfg);
end
if compatibilityMode || runLocalSamplingMode
    [toolingGeometryValid, payloadComplete, toolingGate] = ...
        validateM12ToolingOldKernelCompatibility( ...
            cfg.files.tooling, cfg, ~samplingMode);
    toolingGate.controller_load_handling = ...
        makeOldKernelControllerCompatibilityGate();
    cfg.frame = makeOldKernelCompatibilityFrame( ...
        cfg.files.fixture_frame_commissioning, cfg);
    [toolingGate, toolFixtureGate] = ...
        makeOldKernelToolFixtureCompatibilityGate( ...
            toolingGate, cfg.frame);
else
    [toolingGeometryValid, payloadComplete, toolingGate] = ...
        validateM12Tooling(cfg.files.tooling, cfg, ~samplingMode);
    assert(payloadComplete, 'M12Demo:ToolPayloadMetrologyRequired', ...
        ['Complete M12 mass/CoM/inertia and sensor-origin-to-tip transform ', ...
         'must be hash-qualified before KST connection.']);
    toolingGate.controller_load_handling = ...
        validateControllerLoadHandlingQualification( ...
            cfg.files.tool_metrology_commissioning, ...
            cfg.sampling.conical_phase_pose_tracking, ~samplingMode, cfg);
    cfg.frame = loadFixtureFrameCommissioning( ...
        cfg.files.fixture_frame_commissioning, cfg, ~samplingMode);
    [toolingGate, toolFixtureGate] = ...
        validateToolFixtureIdentityAndLateralUncertainty( ...
            toolingGate, cfg.frame, cfg);
end
cfg.tool.translation_mm = ...
    toolingGate.measured_media_flange_to_tip_translation_mm;
cfg.tool.flange_to_tip_mm = norm(cfg.tool.translation_mm);
cfg.tool.flange_to_tip_uncertainty_mm = ...
    toolingGate.tcp_translation_standard_uncertainty_mm;
cfg.tool.sensor_measurement_origin_to_tip_transform = ...
    toolingGate.sensor_measurement_origin_to_tip_transform;
cfg.tool.sensor_to_tcp_rotation = ...
    toolingGate.sensor_to_tcp_rotation;
if compatibilityMode
    cfg.tool.status = ...
        'PROVISIONAL_OLD_KERNEL_COMPATIBILITY_92MM_AXIAL_TCP';
elseif runLocalSamplingMode
    cfg.tool.status = ...
        'OPERATOR_INSTALLED_92MM_AXIAL_TCP_RUN_LOCAL_SAMPLING';
else
    cfg.tool.status = ...
        'MEASURED_FULL_3D_TCP_PIVOT_TOUCH_OFF_HASH_QUALIFIED';
end
if ~samplingMode
    if ~compatibilityMode
        cfg.insertion.target_depth_mm = ...
            cfg.frame.m12_socket_top_to_bottom_depth_mm;
        cfg.insertion.depth_source = ...
            'MEASURED_AS_BUILT_M12_TOP_TO_BOTTOM_DEPTH_HASH_QUALIFIED';
    else
        cfg.insertion.target_depth_mm = ...
            cfg.insertion.cad_reference_depth_mm;
        cfg.insertion.depth_source = sprintf( ...
            ['PROVISIONAL_%.1fMM_ACTIVE_SIZE_SIMULATION_AND_', ...
             'PROVEN_OLD_KERNEL_COMPATIBILITY'], ...
            cfg.insertion.cad_reference_depth_mm);
    end
    cfg.insertion.success_depth_minimum_mm = ...
        cfg.insertion.target_depth_mm - ...
        cfg.insertion.success_depth_before_bottom_margin_mm;
    cfg.insertion.success_depth_maximum_mm = ...
        cfg.insertion.target_depth_mm + ...
        cfg.insertion.success_depth_after_bottom_margin_mm;
    result.active_socket_size = cfg.sampling.size_upper;
    result.active_socket_depth_mm = cfg.insertion.target_depth_mm;
    result.active_socket_depth_source = cfg.insertion.depth_source;
    manifest.active_socket_size = cfg.sampling.size_upper;
    manifest.active_socket_depth_mm = cfg.insertion.target_depth_mm;
    manifest.active_socket_depth_source = cfg.insertion.depth_source;
    validateSurfaceTransportContract(cfg);
end
validateConicalContract(cfg);
result.qualification_sha256 = sha256File(cfg.files.qualification);
result.tooling_sha256 = sha256File(cfg.files.tooling);
result.tool_metrology_commissioning_sha256 = ...
    sha256File(cfg.files.tool_metrology_commissioning);
result.fixture_frame_commissioning_sha256 = ...
    sha256File(cfg.files.fixture_frame_commissioning);
result.pink_m12_step_sha256 = sha256File(cfg.files.pink_m12_step);
result.simulation_m12_contract_sha256 = ...
    sha256File(cfg.files.simulation_m12_contract);
result.active_peg_step_sha256 = ...
