    result.active_simulation_contract_sha256;
manifest.sampling_legacy_m12_named_hash_fields_are_aliases = ...
    ~strcmp(cfg.sampling.size_lower, 'm12');
manifest.legacy_m12_named_artifact_and_datum_fields_are_aliases = ...
    ~strcmp(cfg.sampling.size_lower, 'm12');
manifest.tooling_geometry_validated = toolingGeometryValid;
manifest.tool_payload_metrology_complete = payloadComplete;
manifest.old_kernel_motion_compatibility_enabled = compatibilityMode;
manifest.run_local_sampling_frame_enabled = runLocalSamplingMode;
manifest.commissioning_authority = cfg.compatibility.authority;
manifest.commissioning_compatibility_rule = ...
    cfg.compatibility.rule;
if compatibilityMode
    manifest.commissioning_authority = ...
        'PROVEN_OLD_KERNEL_FIELD_ASSUMPTIONS_FOR_FULL_LOOP';
    manifest.claim_boundary = ...
        ['Experimental task execution with a provisional 92 mm axial TCP, ', ...
         'manual stationary near-hole start and same-run local contact ', ...
         'datum; this is not payload or fixture metrology certification.'];
end
manifest.conical_phase_pose_tracking_qualification = ...
    cfg.sampling.conical_phase_pose_tracking;
manifest.tip_tcp_translation_mm = cfg.tool.translation_mm;
manifest.tip_tcp_status = cfg.tool.status;
manifest.tip_tcp_translation_standard_uncertainty_mm = ...
    cfg.tool.flange_to_tip_uncertainty_mm;
manifest.sensor_measurement_origin_to_tip_translation_mm = ...
    toolingGate.sensor_measurement_origin_to_tip_translation_mm;
manifest.sensor_to_tcp_rotation = ...
    toolingGate.sensor_to_tcp_rotation;
manifest.measured_complete_tool_mass_kg = ...
    toolingGate.measured_complete_tool_mass_kg;
manifest.measured_com_in_sensor_measurement_frame_m = ...
    toolingGate.measured_com_in_sensor_measurement_frame_m;
manifest.measured_inertia_at_com_kg_m2 = ...
    toolingGate.measured_inertia_at_com_kg_m2;
manifest.tooling_commissioning_gate = toolingGate;
manifest.tool_fixture_identity_and_lateral_uncertainty_gate = ...
    toolFixtureGate;
if ~samplingMode
    result.measured_m12_socket_top_to_bottom_depth_mm = ...
        cfg.frame.m12_socket_top_to_bottom_depth_mm;
    result.measured_m12_socket_depth_standard_uncertainty_mm = ...
        cfg.frame.m12_socket_depth_standard_uncertainty_mm;
    manifest.measured_m12_socket_top_to_bottom_depth_mm = ...
        cfg.frame.m12_socket_top_to_bottom_depth_mm;
    manifest.measured_m12_socket_depth_standard_uncertainty_mm = ...
        cfg.frame.m12_socket_depth_standard_uncertainty_mm;
    manifest.measured_m12_socket_bottom_datum_world_point_mm = ...
        cfg.frame.m12_socket_bottom_datum_world_point_mm;
    manifest.measured_m12_socket_top_datum_world_point_mm = ...
        cfg.frame.m12_socket_top_datum_world_point_mm;
    result.active_socket_top_to_bottom_depth_mm = ...
        cfg.frame.m12_socket_top_to_bottom_depth_mm;
    result.active_socket_depth_standard_uncertainty_mm = ...
        cfg.frame.m12_socket_depth_standard_uncertainty_mm;
    manifest.active_socket_top_to_bottom_depth_mm = ...
        cfg.frame.m12_socket_top_to_bottom_depth_mm;
    manifest.active_socket_depth_standard_uncertainty_mm = ...
        cfg.frame.m12_socket_depth_standard_uncertainty_mm;
    manifest.active_socket_bottom_datum_world_point_mm = ...
        cfg.frame.m12_socket_bottom_datum_world_point_mm;
    manifest.active_socket_top_datum_world_point_mm = ...
        cfg.frame.m12_socket_top_datum_world_point_mm;
    manifest.terminal_rule = sprintf([ ...
        '%s depth %.3f mm; success band %.3f..%.3f mm plus persistent ', ...
        'bounded bottom-force event or %d low-wrench stable-depth dwells ', ...
        '(dF <= %.2f N, dT <= %.3f Nm)'], ...
        cfg.insertion.depth_source, ...
        cfg.insertion.target_depth_mm, ...
        cfg.insertion.success_depth_minimum_mm, ...
        cfg.insertion.success_depth_maximum_mm, ...
        cfg.insertion.terminal_stable_dwells, ...
        cfg.insertion.terminal_low_wrench_force_n, ...
        cfg.insertion.terminal_low_wrench_torque_nm);
end
if policy.uses_conical_fingerprint && ~samplingMode
    learnedRuntimePreflight = validateLearnedRuntimePreflight(cfg, paths);
    result.learned_runtime_preflight_passed = true;
    result.learned_runtime_preflight = learnedRuntimePreflight;
    manifest.learned_runtime_preflight = learnedRuntimePreflight;
end
writeJson(paths.manifest, manifest);
if compatibilityMode
    logEvent(paths.events, ...
        'PROVISIONAL_OLD_KERNEL_COMPATIBILITY_ACTIVE_NO_MOTION', ...
        sprintf(['new shared controller active; TCP [%+.3f %+.3f %+.3f] ', ...
        'mm from the proven predecessor; current stationary start defines ', ...
        'WORLD-aligned task orientation; fresh contact/capture binds the ', ...
        'local %.1f mm active-size insertion datum; payload/CoM/inertia ', ...
        'and physical IDs ', ...
        'remain unqualified and are recorded as such'], ...
        cfg.tool.translation_mm, cfg.insertion.target_depth_mm));
elseif runLocalSamplingMode
    logEvent(paths.events, ...
        'RUN_LOCAL_SAMPLING_GEOMETRY_READY_NO_MOTION', ...
        [cfg.sampling.size_upper, ...
         ' acquisition uses the installed 92 mm axial TCP and a fresh ', ...
         'per-point Bota baseline; the confirmed start will define the ', ...
         'run-local ', cfg.sampling.size_upper, ...
         ' centre.  No simulation model is loaded.']);
else
    logEvent(paths.events, ...
        'TCP_PAYLOAD_SENSOR_METROLOGY_GATE_PASS_NO_MOTION', ...
        sprintf(['full media-flange->tip [%+.3f %+.3f %+.3f] mm; ', ...
         'standard uncertainty %.3f mm; complete tool mass %.6f kg; ', ...
         'sensor-origin->tip [%+.3f %+.3f %+.3f] mm; combined lateral ', ...
         'budget %.3f/%.3f mm; evidence hashes verified'], ...
        cfg.tool.translation_mm, cfg.tool.flange_to_tip_uncertainty_mm, ...
        toolingGate.measured_complete_tool_mass_kg, ...
        toolingGate.sensor_measurement_origin_to_tip_translation_mm, ...
        toolFixtureGate.combined_lateral_uncertainty_mm, ...
        toolFixtureGate.acceptance_mm));
end
logEvent(paths.events, 'CONICAL_QUALIFICATION_BOUNDARY', ...
    ['The stored SN001349 qualification covers fixed-orientation relative ', ...
     'binary events.  It supplies identity/range/unit/hard-limit evidence ', ...
     'only; it does not certify this orientation-changing cone.']);

kstClientDir = fullfile(workspaceRoot, 'reference', ...
    'KST-Kuka-Sunrise-Toolbox-master', 'Matlab_client');
assert(isfolder(kstClientDir), 'M12Demo:KstClient', ...
    'KST client directory is missing: %s', kstClientDir);
% Put the maintained client first even when another experiment left an older
% KST copy on the MATLAB path.  The class itself may already be cached, but
% its delegated state-reader functions must resolve to the maintained,
% validated implementation used by this run.
addpath(kstClientDir, '-begin');
rehash path;
% The real-robot lane is edited between consecutive runs in one MATLAB
% session. Reload the small protocol helpers so pre-motion setup recovery
% and completion-ACK handling cannot remain stuck on an older in-memory
% implementation.
clear movePTPLineEefRelBase sendEEfPositions
clear kstExecuteIdempotentPremotionSetup
clear kstReadAcknowledgmentReply kstReadLine kstWriteLine
if exist('KST', 'class') ~= 8
    logEvent(paths.events, 'KST_CLIENT_PATH_ADD_BEGIN_NO_MOTION', ...
        'KST class was not loaded before the maintained client path was pinned.');
else
    logEvent(paths.events, 'KST_CLIENT_ALREADY_LOADED_NO_MOTION', ...
        ['KST class was already available; maintained state-reader ', ...
         'functions were pinned to the front of the MATLAB path.']);
end
assert(exist('KST', 'class') == 8, 'M12Demo:KstClass', ...
    'KST class is unavailable after addpath.');
kstClassPath = canonicalPath(which('KST'));
kstEefPath = canonicalPath(which('getEEFPos'));
kstJointsPath = canonicalPath(which('getJointsPos'));
kstVectorReaderPath = canonicalPath(which('kstReadNumericVectorReply'));
kstMotionHelperPath = canonicalPath(which('movePTPLineEefRelBase'));
kstTargetHelperPath = canonicalPath(which('sendEEfPositions'));
kstSetupRecoveryPath = canonicalPath(which( ...
    'kstExecuteIdempotentPremotionSetup'));
kstAcknowledgmentReaderPath = canonicalPath(which( ...
    'kstReadAcknowledgmentReply'));
kstLineReaderPath = canonicalPath(which('kstReadLine'));
kstLineWriterPath = canonicalPath(which('kstWriteLine'));
expectedKstClassPath = canonicalPath(fullfile(kstClientDir, 'KST.m'));
expectedEefPath = canonicalPath(fullfile(kstClientDir, 'getEEFPos.m'));
expectedJointsPath = canonicalPath(fullfile(kstClientDir, 'getJointsPos.m'));
expectedVectorReaderPath = canonicalPath(fullfile( ...
    kstClientDir, 'kstReadNumericVectorReply.m'));
expectedMotionHelperPath = canonicalPath(fullfile( ...
    kstClientDir, 'movePTPLineEefRelBase.m'));
expectedTargetHelperPath = canonicalPath(fullfile( ...
    kstClientDir, 'sendEEfPositions.m'));
expectedSetupRecoveryPath = canonicalPath(fullfile( ...
    kstClientDir, 'kstExecuteIdempotentPremotionSetup.m'));
expectedAcknowledgmentReaderPath = canonicalPath(fullfile( ...
    kstClientDir, 'kstReadAcknowledgmentReply.m'));
expectedLineReaderPath = canonicalPath(fullfile( ...
    kstClientDir, 'kstReadLine.m'));
expectedLineWriterPath = canonicalPath(fullfile( ...
    kstClientDir, 'kstWriteLine.m'));
assert(strcmp(kstClassPath, expectedKstClassPath) && ...
    strcmp(kstEefPath, expectedEefPath) && ...
    strcmp(kstJointsPath, expectedJointsPath) && ...
    strcmp(kstVectorReaderPath, expectedVectorReaderPath) && ...
    strcmp(kstMotionHelperPath, expectedMotionHelperPath) && ...
    strcmp(kstTargetHelperPath, expectedTargetHelperPath) && ...
    strcmp(kstSetupRecoveryPath, expectedSetupRecoveryPath) && ...
    strcmp(kstAcknowledgmentReaderPath, ...
        expectedAcknowledgmentReaderPath) && ...
    strcmp(kstLineReaderPath, expectedLineReaderPath) && ...
    strcmp(kstLineWriterPath, expectedLineWriterPath), ...
    'M12Demo:KstStateReaderShadowed', ...
    ['Maintained KST client is shadowed. KST=%s; getEEFPos=%s; ', ...
     'getJointsPos=%s; vectorReader=%s; motionHelper=%s; ', ...
     'setupRecovery=%s. Restart MATLAB or clear the ', ...
     'previous KST class before this no-motion preflight.'], ...
    kstClassPath, kstEefPath, kstJointsPath, kstVectorReaderPath, ...
    kstMotionHelperPath, kstSetupRecoveryPath);
manifest.kst_client_provenance = struct( ...
    'class_path', kstClassPath, ...
    'get_eef_pos_path', kstEefPath, ...
    'get_joints_pos_path', kstJointsPath, ...
    'numeric_vector_reader_path', kstVectorReaderPath, ...
    'relative_motion_helper_path', kstMotionHelperPath, ...
    'relative_target_helper_path', kstTargetHelperPath, ...
    'idempotent_setup_recovery_path', kstSetupRecoveryPath, ...
    'acknowledgment_reader_path', kstAcknowledgmentReaderPath, ...
    'line_reader_path', kstLineReaderPath, ...
    'line_writer_path', kstLineWriterPath, ...
    'get_eef_pos_sha256', sha256File(kstEefPath), ...
    'get_joints_pos_sha256', sha256File(kstJointsPath), ...
    'numeric_vector_reader_sha256', ...
        sha256File(kstVectorReaderPath), ...
    'relative_motion_helper_sha256', ...
        sha256File(kstMotionHelperPath), ...
    'relative_target_helper_sha256', ...
        sha256File(kstTargetHelperPath), ...
    'idempotent_setup_recovery_sha256', ...
        sha256File(kstSetupRecoveryPath), ...
    'acknowledgment_reader_sha256', ...
        sha256File(kstAcknowledgmentReaderPath), ...
    'line_reader_sha256', sha256File(kstLineReaderPath), ...
    'line_writer_sha256', sha256File(kstLineWriterPath), ...
    'state_reader_path_validated', true);
writeJson(paths.manifest, manifest);
logEvent(paths.events, 'KST_CLIENT_PROVENANCE_PINNED_NO_MOTION', sprintf( ...
    ['class %s; state/motion protocol helpers %s; vector parser hash %s; ', ...
     'premotion recovery hash %s; ', ...
     'no controller command sent'], ...
    kstClassPath, kstClientDir, ...
    manifest.kst_client_provenance.numeric_vector_reader_sha256, ...
    manifest.kst_client_provenance.idempotent_setup_recovery_sha256));
logEvent(paths.events, 'KST_CLIENT_READY_NO_MOTION', ...
    'KST class is available; no controller connection has been attempted.');

    logEvent(paths.events, 'ROOT_STATUS_BEGIN_NO_MOTION', ...
        'Running bounded read-only PC/ROS/Bota status checks (timeout 30 s).');
    assertRootStatus(workspaceRoot);
    logEvent(paths.events, 'ROOT_STATUS_PASS_NO_MOTION', ...
        'Root preparation status passed.');
    logEvent(paths.events, 'COMMAND_OWNER_CHECK_BEGIN_NO_MOTION', ...
        'Checking ROS nodes and OS processes for a second command owner.');
    assertNoRosControlConflict(workspaceRoot);
    logEvent(paths.events, 'COMMAND_OWNER_CHECK_PASS_NO_MOTION', ...
        'No responsive ROS/OS robot command owner conflict found.');
    configureRosEnvironment(cfg.ros.master_uri, cfg.ros.node_host);
    logEvent(paths.events, 'MATLAB_ROS_RESTART_BEGIN_NO_MOTION', ...
        'Restarting only this MATLAB ROS global node.');
    restartMatlabRosNode(cfg.ros.master_uri, cfg.ros.node_host, ...
        cfg.sensor.ros_teardown_settle_s);
    logEvent(paths.events, 'MATLAB_ROS_RESTART_PASS_NO_MOTION', ...
        'MATLAB ROS global node is initialized; no robot command sent.');
    rosCleanup = onCleanup(@safeRosShutdown);

    diagnosticSub = rossubscriber(cfg.sensor.diagnostics_topic, ...
        'diagnostic_msgs/DiagnosticArray');
    [diagnosticWaitS, diagnosticAttempts, diagnosticSource] = ...
        waitForHealthyDiagnostic(diagnosticSub, cfg, ...
        cfg.sensor.startup_diagnostic_timeout_s);
    result.bota_startup_diagnostic = ...
        diagnosticSnapshot(diagnosticSub.LatestMessage, cfg);
    logEvent(paths.events, 'BOTA_DIAGNOSTIC_OK', sprintf( ...
        'wait %.3f s; attempts %d; source %s', ...
        diagnosticWaitS, diagnosticAttempts, diagnosticSource));

    wrenchSub = rossubscriber(cfg.sensor.wrench_topic, ...
        'geometry_msgs/WrenchStamped');
    [wrenchWaitS, wrenchAttempts] = waitForFreshWrench( ...
        wrenchSub, cfg, cfg.sensor.startup_wrench_timeout_s);
    logEvent(paths.events, 'BOTA_WRENCH_RX_OK', sprintf( ...
        'frame %s; wait %.3f s; attempts %d', ...
        cfg.sensor.wrench_frame, wrenchWaitS, wrenchAttempts));

    if ~samplingMode && ~compatibilityMode
        toolingGate.controller_load_handling = ...
            revalidateControllerLoadHandlingBoundary( ...
                cfg.files.tool_metrology_commissioning, ...
                cfg.sampling.conical_phase_pose_tracking, cfg, ...
                toolingGate.controller_load_handling, ...
                'IMMEDIATELY_BEFORE_KST_CONNECTION');
        logEvent(paths.events, ...
            'CONTROLLER_DEPLOYMENT_REATTESTED_BEFORE_KST_NO_MOTION', ...
            sprintf('deployment %s; readback age %.3f s', ...
            toolingGate.controller_load_handling. ...
                controller_deployment_session_id, ...
            toolingGate.controller_load_handling. ...
                controller_readback_age_s));
    elseif compatibilityMode
        logEvent(paths.events, ...
            'CONTROLLER_LOAD_ATTESTATION_COMPATIBILITY_NO_MOTION', ...
            ['Fresh Sunrise LoadData/readback attestation is not used by ', ...
             'the proven predecessor path.  The task proceeds with the same ', ...
             'KST geometry-only tool registration and same-run Bota baseline.']);
    end
    toolTransform = eye(4);
    toolTransform(1:3, 4) = cfg.tool.translation_mm(:) / 1000.0;
    iiwa = KST(cfg.robot.ip, KST.LBR14R820, KST.None, toolTransform);
    logEvent(paths.events, 'CONNECTING_KST', ...
        sprintf(['%s:30001; active tip TCP [%+.3f %+.3f %+.3f] mm; ', ...
        'status %s; stated uncertainty %.3f mm'], cfg.robot.ip, ...
        cfg.tool.translation_mm, cfg.tool.status, ...
        cfg.tool.flange_to_tip_uncertainty_mm));
    connectionFlag = iiwa.net_establishConnection();
    if connectionFlag ~= 1
        [endState.sent, endState.method] = requestKstEndOnce( ...
            iiwa, cfg.robot.ip, runDir, paths, false);
        error('M12Demo:KstAttachRejected', ...
            ['Controller rejected identity tool-frame setup; an explicit ', ...
             'best-effort KST end was attempted and is separately logged.']);
    end
    kstOpened = true;
    result.kst_opened = true;
    kstCleanup = onCleanup(@() cleanupKst( ...
        iiwa, cfg.robot.ip, runDir, paths));
    logEvent(paths.events, 'CONNECTED_KST_NO_MOTION_YET', ...
        'Capturing fresh stationary task-local near-hole start.');

    [startPose, startJoints, stationarity] = ...
        captureStationaryStart(iiwa, cfg, paths);
    if compatibilityMode || runLocalSamplingMode
        [cfg.frame, liveUpright] = ...
            bindOldKernelCompatibilityFrameToLiveStart( ...
                cfg.frame, startPose, paths);
        cfg.tool.sensor_to_tcp_rotation = ...
            kukaAbcToRotm(startPose(4:6)).' * ...
            cfg.compatibility.start_world_axis_map;
        toolingGate.sensor_to_tcp_rotation = ...
            cfg.tool.sensor_to_tcp_rotation;
        manifest.world_from_fixture_yaw_deg = ...
            cfg.frame.world_from_fixture_yaw_deg;
        manifest.world_from_fixture_rotation_matrix = ...
            cfg.frame.world_from_fixture_rotation;
        manifest.world_from_fixture_translation_mm = ...
            cfg.frame.world_from_fixture_translation_mm;
        manifest.expected_world_from_upright_tcp_rotation_matrix = ...
            cfg.frame.expected_world_from_upright_tcp_rotation;
        manifest.sensor_to_tcp_rotation = ...
            cfg.tool.sensor_to_tcp_rotation;
        manifest.compatibility_start_world_axis_map = ...
            cfg.compatibility.start_world_axis_map;
        writeJson(paths.manifest, manifest);
    else
        liveUpright = validateLiveUprightPose(startPose, cfg, paths, ...
            'INITIAL_CAPTURED_UPRIGHT_POSE');
    end
    stationarity.live_upright_rotation_error_deg = ...
        liveUpright.rotation_error_deg;
    stationarity.live_peg_axis_to_negative_fixture_z_error_deg = ...
        liveUpright.peg_axis_error_deg;
    if samplingMode
        samplingCenterPose = startPose;
        if samplingResume.enabled
            [startPose, startJoints, stationarity] = ...
                confirmSamplingResumeStart(iiwa, cfg, paths, ...
                    startPose, startJoints, stationarity, ...
                    samplingPlan, samplingResume);
            samplingCenterPose(1:2) = ...
                samplingResume.run_local_hole_center_world_xy_mm;
            cfg.motion.maximum_lateral_excursion_mm = max( ...
                cfg.motion.maximum_lateral_excursion_mm, ...
                norm(startPose(1:2) - samplingCenterPose(1:2)) + ...
                samplingPlan.maximum_planned_radius_mm + ...
                cfg.sampling.maximum_touchdown_xy_lock_error_mm + ...
                cfg.sampling.air_tracking_tolerance_mm);
        else
            [startPose, startJoints, stationarity] = ...
                confirmSamplingStart(iiwa, cfg, paths, startPose, ...
                    startJoints, stationarity, samplingPlan);
            samplingCenterPose = startPose;
        end
        cfg.frame.status = ...
            ['OPERATOR_TAUGHT_RUN_LOCAL_', ...
             cfg.sampling.size_upper, '_CENTER'];
        cfg.frame.claim_boundary = ...
            cfg.sampling.coordinate_authority;
        cfg.tool.sensor_to_tcp_rotation = ...
            kukaAbcToRotm(startPose(4:6)).' * ...
            cfg.compatibility.start_world_axis_map;
        toolingGate.sensor_to_tcp_rotation = ...
            cfg.tool.sensor_to_tcp_rotation;
        % Sampling fixture coordinates are run-local.  On a resume the
        % stationary child start may be above the interrupted point rather
        % than above the hole centre, so the live compatibility-frame
        % translation must be rebound to the immutable parent centre before
        % any world-to-fixture conversion or top-view update is created.
        cfg.frame.world_from_fixture_rotation = eye(3);
        cfg.frame.world_from_fixture_translation_mm = ...
            [samplingCenterPose(1:2), startPose(3)];
        samplingPlan = rebaseM12SamplingPlanToRunLocalStart( ...
            samplingPlan, samplingCenterPose, cfg);
        writeText(paths.plan, ...
            ['kind,index,x_mm,y_mm,detail', newline]);
        writeSamplingExecutionPlan(paths.plan, samplingPlan, cfg);
        result.sampling_run_local_center_world_xy_mm = ...
            samplingCenterPose(1:2);
        result.sampling_nominal_m12_center_fixture_xy_mm = ...
            samplingPlan.nominal_fixture_center_xy_mm;
        result.sampling_nominal_socket_center_fixture_xy_mm = ...
            samplingPlan.nominal_fixture_center_xy_mm;
        result.sampling_coordinate_authority = ...
            samplingPlan.coordinate_authority;
        manifest.sampling_coordinate_authority = ...
            samplingPlan.coordinate_authority;
        manifest.sampling_run_local_center_world_xy_mm = ...
            samplingCenterPose(1:2);
        manifest.sampling_run_local_start_pose_mm_rad = startPose;
        manifest.world_from_fixture_rotation_matrix = eye(3);
        manifest.world_from_fixture_translation_mm = ...
            [samplingCenterPose(1:2), startPose(3)];
        manifest.expected_world_from_upright_tcp_rotation_matrix = ...
            cfg.frame.expected_world_from_upright_tcp_rotation;
        manifest.sensor_to_tcp_rotation = cfg.tool.sensor_to_tcp_rotation;
        writeJson(paths.manifest, manifest);
        if samplingResume.enabled
            logEvent(paths.events, ...
                'SAMPLING_RESUME_PARENT_CENTER_BOUND_NO_MOTION', sprintf( ...
                ['parent centre [%+.3f %+.3f] mm retained; child ', ...
                 'stationary start [%+.3f %+.3f] mm; pending %s'], ...
                samplingCenterPose(1:2), startPose(1:2), ...
                mat2str(samplingResume.pending_execution_indices)));
        else
            logEvent(paths.events, ...
                ['RUN_LOCAL_', cfg.sampling.size_upper, ...
                 '_CENTER_BOUND_NO_MOTION'], sprintf( ...
                ['confirmed TCP XY [%+.3f %+.3f] mm is this run''s hole ', ...
                 'centre; 26 local offsets use WORLD-aligned X/Y; route %.3f mm'], ...
                startPose(1:2), ...
                samplingPlan.closed_route_distance_mm));
        end
    end
    operatorTaughtStartPose = startPose;
    operatorTaughtStartJoints = startJoints;
    operatorTaughtStationarity = stationarity;
    if pairedTrialMode
        logEvent(paths.events, ...
            'PAIRED_OPERATOR_CENTER_CAPTURED_PRIVATE', ...
            ['The stationary taught centre was captured and retained only ', ...
             'for preregistered air transport/evaluation; its coordinates ', ...
             'are not supplied to learned or CAD routing.']);
    else
        result.start_pose_mm_rad = startPose;
        result.start_joints_rad = startJoints;
        result.start_stationarity = stationarity;
        logEvent(paths.events, 'TASK_LOCAL_MANUAL_START_CAPTURED', sprintf( ...
            ['xyz [%.3f %.3f %.3f] mm; translation span %.3f mm; ', ...
             'orientation span %.6f rad; joint span %.6f rad'], ...
            startPose(1:3), stationarity.translation_span_mm, ...
            stationarity.orientation_span_rad, stationarity.joint_span_rad));
    end

    realtimeLogs = openRealtimeLogFiles(paths);
    realtimeLogCleanup = onCleanup(@() closeRealtimeLogFiles( ...
        realtimeLogs));
    ctx = makeContext(iiwa, wrenchSub, diagnosticSub, cfg, paths, ...
        startPose, startJoints, qualification, realtimeLogs);
    if pairedTrialMode
        [ctx, pairedCenterAirReference] = measureBaseline( ...
            ctx, 'PAIRED_CENTER_AIR_REFERENCE_ONLY');
        [ctx, startPose, startJoints, stationarity, ...
            pairedPreposition] = executePairedAirPreposition( ...
                ctx, iiwa, pairedTrialSpec, ...
                operatorTaughtStartPose, ...
                operatorTaughtStartJoints, ...
                operatorTaughtStationarity);
        cfg = ctx.cfg;
        result.start_pose_mm_rad = startPose;
        result.start_joints_rad = startJoints;
        result.start_stationarity = stationarity;
        result.paired_air_preposition_complete = true;
        result.paired_air_preposition_path_length_mm = ...
            pairedPreposition.measured_path_length_mm;
        result.paired_air_preposition_command_count = ...
            pairedPreposition.command_count;
        manifest.world_from_fixture_yaw_deg = ...
            cfg.frame.world_from_fixture_yaw_deg;
        manifest.world_from_fixture_rotation_matrix = ...
            cfg.frame.world_from_fixture_rotation;
        manifest.world_from_fixture_translation_mm = ...
            cfg.frame.world_from_fixture_translation_mm;
        manifest.expected_world_from_upright_tcp_rotation_matrix = ...
            cfg.frame.expected_world_from_upright_tcp_rotation;
        manifest.sensor_to_tcp_rotation = ...
            cfg.tool.sensor_to_tcp_rotation;
        manifest.paired_air_preposition_complete = true;
        manifest.paired_air_preposition_coordinates_redacted = true;
        if ctx.m10_fixed_demo_support_envelope.enabled
            result.m10_fixed_demo_support_envelope_enabled = true;
            result.m10_fixed_demo_support_envelope_safety_only = true;
            result.m10_fixed_demo_support_maximum_commanded_radius_mm = ...
                ctx.m10_fixed_demo_support_envelope. ...
                    maximum_commanded_radius_mm;
            result.m10_fixed_demo_support_maximum_physical_radius_mm = ...
                ctx.m10_fixed_demo_support_envelope. ...
                    maximum_physical_radius_mm;
            manifest.m10_fixed_demo_support_envelope = struct( ...
                'enabled', true, ...
                'center_coordinates_redacted', true, ...
                'safety_fail_stop_only', true, ...
                'posterior_input', false, ...
                'target_ranking_input', false, ...
                'steering_input', false, ...
                'maximum_commanded_tip_center_radius_mm', ...
                    ctx.m10_fixed_demo_support_envelope. ...
                        maximum_commanded_radius_mm, ...
                'maximum_physical_tip_center_radius_mm', ...
                    ctx.m10_fixed_demo_support_envelope. ...
                        maximum_physical_radius_mm, ...
                'endpoint_tracking_allowance_mm', ...
                    ctx.m10_fixed_demo_support_envelope. ...
                        endpoint_tracking_allowance_mm);
        end
        writeJson(paths.manifest, manifest);
        writePairedEvaluationTruth(realDir, pairedTrialSpec, ...
            operatorTaughtStartPose, operatorTaughtStartJoints, ...
            operatorTaughtStationarity, startPose, startJoints, ...
            stationarity, pairedCenterAirReference, ...
            pairedPreposition);
        % Drop the oracle-bearing trial struct before the ordinary task path.
        % From this line onward the learned/CAD policy receives only the
        % measured post-air origin and touchdown-relative observations.  The
        % M10 pilot alone retains the fresh centre inside an independent
        % command-envelope fail-stop; that value is never serialized into
        % model input, posterior construction, target ranking, or steering.
        pairedTrialSpec = struct('enabled', true, ...
            'public_trial_token', result.paired_trial_public_token);
        logEvent(paths.events, ...
            'PAIRED_TRIAL_ORIGIN_REBASED_MODEL_BLINDED', ...
            ['Measured post-air pose is now the task-local origin; ', ...
             'the requested offset and taught centre were erased from ', ...
             'learned/CAD routing before START_BASELINE/touchdown; M10 ', ...
             'retains only the no-steering head-support fail-stop.']);
    end
    [ctx, baseline] = measureBaseline(ctx, 'START_BASELINE');
    result.start_baseline = baseline;
    logEvent(paths.events, 'START_UNLOADED_BASELINE_COMPLETE', sprintf( ...
        ['sustained/average receive %.1f/%.1f Hz; p95/max gap ', ...
         '%.4f/%.4f s; max force std %.4f N; max torque std %.5f Nm'], ...
        baseline.sustained_rate_hz, baseline.average_rate_hz, ...
        baseline.p95_source_interval_s, ...
        baseline.maximum_source_interval_s, ...
        max(baseline.force_std_n), max(baseline.torque_std_nm)));
    activeContactTargetN = cfg.surface.target_normal_force_n;
    if samplingMode
        activeContactTargetN = ...
            cfg.sampling.contact_stability.target_normal_force_n;
    end
    logEvent(paths.events, 'DATA_DERIVED_CONTACT_POLICY', sprintf( ...
        ['touchdown %.2f N for %d consecutive fresh samples; contact ', ...
         'target %.2f N; capture requires at least %.2f mm total and ', ...
         '%.2f mm recent downward progress inside the %.1f N soft envelope'], ...
        cfg.sensor.contact_event_n, ...
        cfg.sensor.contact_consecutive_samples, ...
        activeContactTargetN, ...
        cfg.surface.capture_depth_drop_mm, ...
        cfg.surface.capture_minimum_recent_drop_mm, ...
        min(cfg.surface.capture_soft_force_delta_n, ...
            cfg.surface.soft_relief_trigger_force_n)));
    if samplingMode
        contactPolicy = cfg.sampling.contact_stability;
        logEvent(paths.events, ...
            'SAMPLING_PASSIVE_CONTACT_OBSERVATION_POLICY', sprintf( ...
            ['after confirmed touchdown, issue no settle motion and ', ...
             'observe fresh Bota data for at least %.2f s / %d samples ', ...
             '(bounded by %.2f s); %.2f +/- %.2f N with std <= %.2f N ', ...
             'is the preferred quality grade, while every other fresh ', ...
             'load remains nonblocking and continues to the 40 Hz cone ', ...
             'with explicit offline-QC metadata'], ...
            contactPolicy.passive_observation_s, ...
            contactPolicy.minimum_samples, ...
            contactPolicy.maximum_observation_s, ...
            contactPolicy.target_normal_force_n, ...
            contactPolicy.force_deadband_n, ...
            contactPolicy.maximum_force_std_n));
    end
    logEvent(paths.events, 'DASHBOARD_INITIALIZING_NO_MOTION', ...
        ['Baseline is complete.  Creating the visualization before the ', ...
         'first robot command; no blocking full-render drawnow is used.']);
    if samplingMode
        ctx.dashboard = struct( ...
            'enabled', false, ...
            'last_refresh_elapsed_s', -Inf, ...
            'failure', 'GENERIC_3D_WRENCH_DASHBOARD_DISABLED_FOR_SAMPLING');
        try
            ctx.sampling_dashboard = callSamplingTopview( ...
                cfg, 'initialize', [], samplingPlan, cfg);
        catch samplingDashboardError
            ctx.sampling_dashboard = struct( ...
                'enabled', false, ...
                'failure', sprintf('%s: %s', ...
                    samplingDashboardError.identifier, ...
                    oneLine(samplingDashboardError.message)));
            bestEffortLogEvent(paths.events, ...
                'SAMPLING_TOPVIEW_INITIALIZATION_DISABLED_NO_CONTROL_EFFECT', ...
                ctx.sampling_dashboard.failure);
        end
    else
        ctx.dashboard = initializeDashboard(cfg, startPose);
    end
    if samplingMode && ctx.sampling_dashboard.enabled
        logEvent(paths.events, 'SAMPLING_TOPVIEW_READY_NO_MOTION', ...
            ['Single lightweight top view created; it refreshes at no more ', ...
             'than 2 Hz outside DirectServo and freezes during each cone.']);
    elseif ctx.dashboard.enabled
        logEvent(paths.events, 'DASHBOARD_READY_NO_MOTION', ...
            'Visualization objects created; first robot command still pending.');
    elseif ~samplingMode
        logEvent(paths.events, 'DASHBOARD_DISABLED_NO_MOTION', ...
            ['Visualization unavailable; task control remains independent: ', ...
             ctx.dashboard.failure]);
    else
        logEvent(paths.events, 'SAMPLING_TOPVIEW_DISABLED_NO_MOTION', ...
            ['Sampling visualization unavailable; acquisition remains ', ...
             'independent: ', ctx.sampling_dashboard.failure]);
    end

    if samplingMode
        [result, endState, ctx] = runM12SamplingCampaign( ...
            result, ctx, iiwa, cfg, paths, runDir, ...
            samplingPlan, samplingResume);
        clear realtimeLogCleanup kstCleanup rosCleanup;
        return;
    end

    if compatibilityMode
        logEvent(paths.events, ...
            'OLD_KERNEL_COMPATIBILITY_FIRST_MOTION_READY', ...
            ['Stationary start, Bota baseline, diagnostic freshness and ', ...
             'single command-owner checks passed; proceeding with the new ', ...
             'controller under the predecessor commissioning level.']);
    else
        toolingGate.controller_load_handling = ...
            revalidateControllerLoadHandlingBoundary( ...
                cfg.files.tool_metrology_commissioning, ...
                cfg.sampling.conical_phase_pose_tracking, cfg, ...
                toolingGate.controller_load_handling, ...
                'IMMEDIATELY_BEFORE_FIRST_ROBOT_MOTION');
        logEvent(paths.events, ...
            'CONTROLLER_DEPLOYMENT_REATTESTED_BEFORE_FIRST_MOTION', ...
            sprintf('deployment %s; readback age %.3f s', ...
            toolingGate.controller_load_handling. ...
                controller_deployment_session_id, ...
            toolingGate.controller_load_handling.controller_readback_age_s));
    end
    manualStartXY = startPose(1:2);
    result.manual_start_xy_mm = manualStartXY;
    logTransition(paths.transitions, 'TASK_LOCAL_START', ...
        'SHORT_EVENT_TRIGGER_TOUCHDOWN', 'BASELINE_STABLE', ...
        ['At the operator-provided near-hole XY with a reasonable air gap and ', ...
         'some solid top-surface support under the tip; WORLD -Z at most ', ...
         '20.0 mm in 0.10 mm blocking segments']);
    [ctx, touchdown] = guardedTouchdown(ctx, ...
        cfg.motion.touchdown_maximum_down_mm, 'TOUCHDOWN');
    result.touchdown_found = touchdown.contact_confirmed;
    result.touchdown_pose_mm_rad = touchdown.pose_mm_rad;
    result.touchdown_force_delta_n = touchdown.maximum_force_delta_n;
    result.touchdown_lateral_drift_mm = ...
        touchdown.maximum_lateral_deviation_mm;
    result.touchdown_cumulative_lateral_motion_mm = ...
        touchdown.cumulative_lateral_motion_mm;
    result.touchdown_xy_lock_error_mm = ...
        touchdown.landing_xy_error_mm;
    result.touchdown_xy_anchor_correction_actions = ...
        touchdown.xy_anchor_correction_actions;
    if ~touchdown.contact_confirmed
        error('M12Demo:TouchdownNotFound', ...
            ['No persistent contact was found within %.1f mm.  The program ', ...
             'will end at the measured current pose; recover manually.'], ...
            cfg.motion.touchdown_maximum_down_mm);
    end
    [ctx, touchdownContactMode] = ...
        observeTouchdownContactModeFresh(ctx, ...
        touchdown.normal_sign_world_z, ...
        'TOUCHDOWN_CONTACT_MODE');
    result.touchdown_contact_mode = touchdownContactMode.mode;
    result.touchdown_contact_mode_evidence = touchdownContactMode;
    logEvent(paths.events, ...
        ['TOUCHDOWN_CONTACT_MODE_', touchdownContactMode.mode], sprintf( ...
        ['fresh median axial/lateral/total %.3f/%.3f/%.3f N; ', ...
         'axial fraction %.3f; persistent total-contact %d.  ', ...
         'CHAMFER_SIDE remains valid learned state evidence and does not ', ...
         'invalidate or stop a complete cone.'], ...
        touchdownContactMode.normal_force_n, ...
        touchdownContactMode.lateral_force_n, ...
        touchdownContactMode.total_force_n, ...
        touchdownContactMode.axial_fraction, ...
        touchdownContactMode.persistent_contact));

    % The manually taught air pose is an audit datum, not the surface-search
    % origin.  Bind every full-loop policy to the measured contact endpoint
    % only after the bounded anchored touchdown has corrected back toward the
    % fixed air-preposition XY and passed its independent landing gate.  This
    % prevents touchdown tracking drift from being silently counted as a
    % shortcut, grid action, reset, or spiral radius.
    centerXY = touchdown.pose_mm_rad(1:2);
    result.search_anchor_xy_mm = centerXY;
    result.search_anchor_source = ...
        'MEASURED_TOUCHDOWN_POSE_AFTER_FIXED_XY_CORRECTION_AND_0P25MM_GATE';
    manifest.manual_start_xy_mm = manualStartXY;
    manifest.search_anchor_xy_mm = centerXY;
    manifest.search_anchor_source = result.search_anchor_source;
    manifest.touchdown_lateral_drift_mm = ...
        touchdown.maximum_lateral_deviation_mm;
    manifest.touchdown_cumulative_lateral_motion_mm = ...
        touchdown.cumulative_lateral_motion_mm;
    manifest.touchdown_xy_lock_error_mm = ...
        touchdown.landing_xy_error_mm;
    manifest.touchdown_xy_anchor_correction_actions = ...
        touchdown.xy_anchor_correction_actions;
    writeJson(paths.manifest, manifest);
    logEvent(paths.events, 'MEASURED_TOUCHDOWN_SEARCH_ANCHOR_BOUND', ...
        sprintf(['manual air-start XY [%+.3f %+.3f] mm; measured ', ...
        'touchdown/search XY [%+.3f %+.3f] mm; maximum/cumulative ', ...
        'lateral motion %.3f/%.3f mm; fixed-XY landing error %.3f mm; ', ...
        'correction actions %d; finite drift/landing gates %.3f/%.3f mm'], ...
        manualStartXY, centerXY, ...
        touchdown.maximum_lateral_deviation_mm, ...
        touchdown.cumulative_lateral_motion_mm, ...
        touchdown.landing_xy_error_mm, ...
        touchdown.xy_anchor_correction_actions, ...
        cfg.motion.maximum_touchdown_lateral_drift_mm, ...
        cfg.motion.maximum_touchdown_xy_lock_error_mm));

    initialSurfaceZ = touchdown.pose_mm_rad(3);
    result.initial_surface_z_mm = initialSurfaceZ;
    logEvent(paths.events, 'FRESH_SURFACE_CONTACT', sprintf( ...
        ['initial surface tip-TCP WORLD Z %.3f mm; contact WORLD* Fz ', ...
         'sign %+.0f'], initialSurfaceZ, touchdown.normal_sign_world_z));

    surfaceZ = touchdown.pose_mm_rad(3);
    result.surface_z_mm = surfaceZ;
    contactNormalSign = touchdown.normal_sign_world_z;
    ctx.contact_normal_sign_world_z = contactNormalSign;
    result.contact_normal_sign_world_z = contactNormalSign;
    if compatibilityMode
        cfg.frame = bindOldKernelCompatibilityInsertionDatum( ...
            cfg.frame, touchdown.pose_mm_rad, surfaceZ, ...
            cfg.insertion.target_depth_mm);
        ctx.cfg.frame = cfg.frame;
        result.provisional_surface_datum_world_point_mm = ...
            cfg.frame.m12_socket_top_datum_world_point_mm;
        result.provisional_bottom_datum_world_point_mm = ...
            cfg.frame.m12_socket_bottom_datum_world_point_mm;
        manifest.measured_m12_socket_top_datum_world_point_mm = ...
            cfg.frame.m12_socket_top_datum_world_point_mm;
        manifest.measured_m12_socket_bottom_datum_world_point_mm = ...
            cfg.frame.m12_socket_bottom_datum_world_point_mm;
        manifest.world_from_fixture_translation_mm = ...
            cfg.frame.world_from_fixture_translation_mm;
        writeJson(paths.manifest, manifest);
        logEvent(paths.events, ...
            'PROVISIONAL_CONTACT_LOCAL_DATUM_BOUND', sprintf( ...
            ['fresh surface [%+.3f %+.3f %+.3f] mm; provisional bottom ', ...
             'is %.3f mm along WORLD -Z; this is same-run control datum, ', ...
             'not fixture metrology'], ...
            cfg.frame.m12_socket_top_datum_world_point_mm, ...
            cfg.insertion.target_depth_mm));
    end
    policyClock = tic;
    capture = emptyCapture();

    if strcmp(executionMode, 'FULL_LOOP_BASELINE_PURE_OUTWARD_SPIRAL')
        fixtureXAxisWorld = cfg.frame.world_from_fixture_rotation(1:2, 1).';
        outwardPhase = atan2(fixtureXAxisWorld(2), ...
            fixtureXAxisWorld(1));
        logTransition(paths.transitions, ...
            'SHORT_EVENT_TRIGGER_TOUCHDOWN', ...
            'PURE_OUTWARD_ARCHIMEDEAN_SEARCH', ...
            'CONTACT_EVENT_LATCHED_NO_PROBE_NO_MODEL', sprintf( ...
            ['%.2f mm/revolution outward path about the measured touchdown ', ...
             'anchor; maximum radius %.2f mm per phase-shifted pass; ', ...
             'ordinary stage deadline disabled (configured %.1f s); ', ...
             'same low-force transport, capture cue, insertion, and terminal ', ...
             'verification as every other method.'], ...
            cfg.baselines.spiral_pitch_mm_per_revolution, ...
            cfg.baselines.pure_outward_radius_mm, ...
            cfg.baselines.active_time_budget_s));
        [ctx, capture, outwardDiagnostics] = ...
            runOutwardArchimedeanSearch(ctx, centerXY, centerXY, ...
                surfaceZ, contactNormalSign, outwardPhase, ...
                cfg.baselines.spiral_pitch_mm_per_revolution, ...
                cfg.baselines.pure_outward_radius_mm, policyClock, ...
                cfg.baselines.active_time_budget_s, ...
                'PURE_OUTWARD', ...
                'PURE_OUTWARD_SENSOR_DOWNWARD_PROGRESS_CAPTURE_CANDIDATE');
        result.policy_search_diagnostics = outwardDiagnostics;
        result.bayesian_grid_steps = 0;
        result.posterior_entropy_final_nat = NaN;
    else
    logTransition(paths.transitions, 'SHORT_EVENT_TRIGGER_TOUCHDOWN', ...
        'CONTINUOUS_15_DEG_TIP_CENTERED_CONE', ...
        'CONTACT_EVENT_LATCHED_NO_AIR_LIFT', ...
        sprintf(['%.2f s contact settle; %.2f s smooth ramp to 15 deg; ', ...
         'up to %.2f s clockwise 360 deg scan; %.2f s return upright; ', ...
         '%.2f s upright verification.  Tip WORLD XY is fixed; WORLD Z ', ...
         'uses rotating-hex edge-relief feedforward plus asymmetric ', ...
         'bounded force following.  At %.1f N the cone phase holds and ', ...
         'unloads until <= %.1f N for %d samples, then resumes from the ', ...
         'same phase.  Low normal and low total force together freeze ', ...
         'phase/XY for bounded ', ...
         'recontact or an upright physical-capture handoff.  Loads above ', ...
         '%.1f N receive one immediate +%.2f mm fixed-phase relief kick; ', ...
         'the %.1f N hard guard remains immediate.'], ...
         cfg.conical.settle_s, cfg.conical.ramp_s, ...
         cfg.conical.scan_s, cfg.conical.return_s, ...
         cfg.conical.upright_verify_s, ...
         cfg.conical.force_relief_hold_n, ...
         cfg.conical.force_relief_resume_n, ...
         cfg.conical.force_relief_resume_samples, ...
         cfg.conical.force_relief_fast_trigger_n, ...
         cfg.conical.force_relief_fast_step_mm, ...
         cfg.sensor.hard_force_delta_n));
    [ctx, conical] = runConicalFingerprint(ctx, ...
        touchdown.pose_mm_rad, 'CONTACT_CONE', contactNormalSign);
    throwIfConicalPostStateUnknown(conical);
    captureRequalified = false;
    capturePose = conical.post_stop_pose_mm_rad;
    captureRequalification = struct();
    apertureRescanIndex = 0;
    while conical.aperture_candidate && ~captureRequalified
        logTransition(paths.transitions, ...
            'LOW_FORCE_EARLY_UPRIGHT_RETURN', ...
            'CONICAL_APERTURE_CANDIDATE_REQUALIFICATION', ...
            'INCOMPLETE_CONE_NEVER_USED_FOR_DIRECTION', ...
            ['The cone is upright and truncated.  Learned direction ', ...
             'consumers are bypassed; only measured-Z plus fresh Bota ', ...
             'physical requalification may enter insertion.']);
        [ctx, captureRequalified, capturePose, ...
            captureRequalification] = ...
            requalifyConicalApertureCandidate(ctx, surfaceZ, ...
                contactNormalSign, sprintf( ...
                'CONTACT_CONE_LOW_FORCE_%02d', apertureRescanIndex));
        if captureRequalified
            break;
        end
        apertureRescanIndex = apertureRescanIndex + 1;
        logEvent(paths.events, ...
            'CONTACT_CONE_AMBIGUOUS_LOW_FORCE_RESCAN_IN_PLACE', sprintf( ...
            ['rescan %d; physical capture was not confirmed.  Keep the ', ...
             'fresh bounded measured pose, do not return to the original ', ...
             'anchor and repeat a complete cone for an actionable ', ...
             'fingerprint.'], apertureRescanIndex));
        [ctx, conical] = runConicalFingerprint(ctx, capturePose, ...
            sprintf('CONTACT_CONE_RESCAN_%02d', apertureRescanIndex), ...
            contactNormalSign);
        throwIfConicalPostStateUnknown(conical);
        enforceTime(ctx);
    end
    result.fingerprint_phase_rad = conical.phase_rad;
    result.fingerprint_force_world_n = conical.force_world_n;
    result.fingerprint_torque_world_nm = conical.torque_world_nm;
    result.fingerprint_tip_z_mm = conical.actual_pose_mm_rad(:, 3);
    result.fingerprint_sample_count = numel(conical.phase_rad);
    result.fingerprint_phase_coverage_fraction = ...
        conical.phase_coverage_fraction;
    result.fingerprint_post_stop_tip_error_mm = ...
        conical.post_stop_tip_error_mm;
    result.fingerprint_post_stop_orientation_error_deg = ...
        conical.post_stop_orientation_error_deg;
    result.fingerprint_return_orientation_error_deg = ...
        conical.return_orientation_error_deg;
    result.fingerprint_feedback_policy = conical.feedback_policy;
    result.fingerprint_max_tick_lateness_s = ...
        conical.maximum_tick_lateness_s;
    result.fingerprint_effective_command_rate_hz = ...
        conical.effective_command_rate_hz;
    result.fingerprint_force_relief_episodes = ...
        conical.force_relief_episodes;
    result.fingerprint_fast_force_relief_kicks = ...
        conical.fast_force_relief_kicks;
    result.fingerprint_force_relief_total_ticks = ...
        conical.force_relief_total_ticks;
    result.fingerprint_force_relief_total_wall_s = ...
        conical.force_relief_total_wall_s;
    result.fingerprint_maximum_residual_relief_mm = ...
        conical.maximum_residual_relief_mm;
    result.fingerprint_schedule_completed = conical.schedule_completed;
    result.fingerprint_direction_valid = ...
        conical.direction_fingerprint_valid;
    result.fingerprint_routing_valid = ...
        conical.routing_fingerprint_valid;
    result.fingerprint_training_valid = ...
        conical.training_fingerprint_valid;
    result.fingerprint_mode_transition_outcome = ...
        conical.mode_transition_outcome;
    result.fingerprint_low_force_episodes = ...
        conical.low_force_episodes;
    result.fingerprint_low_force_ramp_episodes = ...
        conical.low_force_ramp_episodes;
    result.fingerprint_low_force_scan_episodes = ...
        conical.low_force_scan_episodes;
    result.fingerprint_low_force_total_ticks = ...
        conical.low_force_total_ticks;
    result.fingerprint_low_force_total_wall_s = ...
        conical.low_force_total_wall_s;
    result.fingerprint_low_force_quick_recontacts = ...
        conical.low_force_quick_recontacts;
    result.fingerprint_maximum_low_force_reacquire_mm = ...
        conical.maximum_low_force_reacquire_mm;
    result.fingerprint_low_force_thresholds = ...
        conical.low_force_thresholds;
    result.fingerprint_routing_quality = ...
        conical.routing_fingerprint_quality;
    result.fingerprint_routing_quality_factors = ...
        conical.routing_fingerprint_quality_factors;

    if conical.aperture_candidate
        result.fingerprint_capture_requalification = ...
            captureRequalification;
        assert(captureRequalified, ...
            'M12Demo:ConicalApertureRescanInvariant', ...
            ['An aperture candidate may reach capture handoff only after ', ...
             'fresh physical requalification; otherwise the in-place cone ', ...
             'rescan loop must still be active.']);
        capture = makeCapture(true, ...
            ['CONICAL_LOW_FORCE_DOWNWARD_PROGRESS_', ...
             'PHYSICALLY_REQUALIFIED_CAPTURE_CANDIDATE'], ...
            capturePose(1:2) - centerXY, capturePose);
        result.learned_inference_attempted = false;
        result.learned_inference_completed = false;
        result.learned_inference_error = ...
            'BYPASSED_INCOMPLETE_CONE_CAPTURE_HANDOFF';
        result.learned_shortcut_model_used = false;
        result.shortcut_policy_class = ...
            'BYPASSED_CONICAL_CAPTURE_HANDOFF';
        result.shortcut_evidence = struct( ...
            'model', 'NONE_PHYSICAL_CAPTURE_HANDOFF');
        result.bayesian_grid_steps = 0;
        result.posterior_entropy_final_nat = NaN;
    else
    assert(conical.direction_fingerprint_valid, ...
        'M12Demo:ConicalDirectionFingerprintInvalid', ...
        ['A non-capture cone reached direction routing without a complete ', ...
         'valid fingerprint.']);
    learned = inferFrozenConicalModel(conical, cfg, paths);
    result.learned_inference_attempted = learned.attempted;
    result.learned_inference_completed = learned.completed;
    result.learned_inference_error = learned.error;
    centerHypotheses = plan.center_hypotheses_mm;
    actionOffsets = plan.action_offsets_mm;
    modelPosterior = ones(size(centerHypotheses, 1), 1);
    modelPosterior = modelPosterior / sum(modelPosterior);
    learnedShortcut = struct('offset_mm', [0.0, 0.0], ...
        'distance_mm', 0.0, 'confidence', 0.0, ...
        'residual_radius_mm', cfg.baselines.proposed_residual_radius_mm, ...
        'direction_world_xy', [0.0, 0.0], ...
        'evidence', struct());
    corridorHalfAngleDeg = 0.5 * ...
        cfg.search.directional_corridor_maximum_full_width_deg;
    corridorCredible = struct( ...
        'control_center_task_deg', NaN, ...
        'target_mass', cfg.search.directional_corridor_probability_mass, ...
        'required_full_width_deg', Inf, ...
        'bounded_full_width_deg', ...
            2.0 * corridorHalfAngleDeg, ...
        'contained_probability_mass', 0.0, ...
        'mass_requirement_satisfied', false);
    if learned.completed
        result.learned_model_id = learned.output.model_id;
        result.learned_model_manifest_sha256 = ...
            learned.output.manifest_sha256;
        result.learned_deployment_authority = ...
            learned.output.deployment_authority;
        result.learned_hardware_control_allowed = ...
            logical(learned.output.hardware_control_allowed);
        result.learned_top_state = learned.output.top_state;
        result.learned_state_probabilities = ...
            learned.output.state_probabilities;
        % Preserve TOP1 and circular mean as diagnostics.  Proposed methods
        % command the learned TOP1 direction with a posterior/CAD-sized
        % distance; Direct retries keep each fresh TOP1 inside the first
        % learned-direction sector.
        result.learned_direction_task_deg = ...
            learned.output.top_direction_deg;
        result.learned_top_direction_task_deg = ...
            learned.output.top_direction_deg;
        result.learned_circular_mean_direction_task_deg = ...
            learned.output.circular_mean_direction_deg;
        result.learned_direction_world_xy = ...
            learned.output.direction_world_xy;
        result.learned_direction_probabilities = ...
            learned.output.direction_probabilities;
        result.learned_aps_set_size = learned.output.aps_set_size;
        result.learned_circular_concentration = ...
            learned.output.circular_concentration;
        result.learned_ensemble_top1_span_deg = ...
            learned.output.ensemble_top1_span_deg;
        result.learned_sample_quality = ...
            double(learned.output.sample_quality);
        modelPosterior = modelGridPosterior( ...
            centerHypotheses, learned.output, conical, cfg);
        learnedShortcut = planLearnedShortcut( ...
            centerHypotheses, modelPosterior, ...
            learned.output, conical, cfg);
        [corridorHalfAngleDeg, corridorCredible] = ...
            posteriorCorridorHalfAngleDeg(learned.output, cfg, ...
                learnedShortcut.direction_world_xy);
        if ~strcmp(executionMode, ...
                'FULL_LOOP_BASELINE_IMPROVED_DIRECT_X3_LEARNED')
            ctx = bestEffortRenderLearnedPostConeDecision( ...
                ctx, conical, learned, centerHypotheses, ...
                modelPosterior, learnedShortcut, corridorCredible, ...
                'POST_CONE_ACTIVE_MODEL_AND_CAD_SHORTCUT');
        end
        result.learned_active_shortcut_offset_mm = ...
            learnedShortcut.offset_mm;
        result.learned_active_shortcut_distance_mm = ...
            learnedShortcut.distance_mm;
        result.learned_active_shortcut_confidence = ...
            learnedShortcut.confidence;
        result.learned_active_shortcut_evidence = ...
            learnedShortcut.evidence;
        result.learned_active_residual_radius_mm = ...
            learnedShortcut.residual_radius_mm;
        result.learned_active_grid_offsets_mm = ...
            centerHypotheses;
        result.learned_active_action_offsets_mm = ...
            actionOffsets;
        result.learned_active_grid_posterior = ...
            modelPosterior;
        logEvent(paths.events, 'ACTIVE_MODEL_INFERENCE_OK', sprintf( ...
            ['model %s; state %s; direction %.2f deg task; APS %d; ', ...
             'concentration %.3f; sample quality %.3f; ', ...
             'authority %s; active shortcut [%+.3f %+.3f] mm; ', ...
             'posterior residual radius %.3f mm'], ...
            learned.output.model_id, learned.output.top_state, ...
            learned.output.top_direction_deg, ...
            learned.output.aps_set_size, ...
            learned.output.circular_concentration, ...
            learned.output.sample_quality, ...
            learned.output.deployment_authority, ...
            learnedShortcut.offset_mm, ...
            learnedShortcut.residual_radius_mm));
    else
        logEvent(paths.events, 'LATEST_MODEL_INFERENCE_REQUIRED_FAILED', ...
            ['The completed conical fingerprint could not be inferred.  ', ...
             'Stop this run instead of silently substituting a different ', ...
             'direction source: ', learned.error]);
        error('M12Demo:LearnedInferenceRequired', ...
            ['Frozen conical inference is required after a completed cone; ', ...
             'runtime/input failure: %s'], learned.error);
    end
    assertPolicyDeadline(policyClock, ...
        cfg.baselines.active_time_budget_s, ...
        'POST_CONICAL_FINGERPRINT_AND_PHASE_BOUNDARY_INFERENCE');

    shortcutOffset = learnedShortcut.offset_mm;
    shortcutConfidence = learnedShortcut.confidence;
    shortcutDistance = learnedShortcut.distance_mm;
    shortcutDirectionWorld = learnedShortcut.direction_world_xy;
    shortcutEvidence = learnedShortcut.evidence;
    posterior = modelPosterior;
    activeGridRoutingDirection = ...
        learnedShortcut.direction_world_xy;
    activeGridPriorSource = ...
        'ACTIVE_REAL_MODEL_DIRECTION_STATE_AND_CAD_POSTERIOR';
    result.active_grid_prior_source = activeGridPriorSource;
    result.active_grid_prior_direction_world_xy = ...
        activeGridRoutingDirection;
    result.active_grid_prior_direction_confidence = ...
        shortcutConfidence;
    result.active_grid_routing_direction_world_xy = ...
        activeGridRoutingDirection;
    result.active_grid_directional_corridor_half_angle_deg = ...
        corridorHalfAngleDeg;
    result.active_grid_directional_corridor_full_width_deg = ...
        2.0 * corridorHalfAngleDeg;
    result.active_grid_directional_corridor_control_center_task_deg = ...
        corridorCredible.control_center_task_deg;
    result.active_grid_directional_corridor_required_full_width_deg = ...
        corridorCredible.required_full_width_deg;
    result.active_grid_directional_corridor_contained_probability_mass = ...
        corridorCredible.contained_probability_mass;
    result.active_grid_directional_corridor_mass_requirement_satisfied = ...
        corridorCredible.mass_requirement_satisfied;
    result.active_grid_prior = posterior;
    logEvent(paths.events, 'ACTIVE_GRID_PRIOR_BOUND', sprintf( ...
        ['%s; direction [%+.4f %+.4f], sample quality %.3f; ', ...
         'pitch/radius %.2f/%.2f mm; %d fully enumerated nodes.  ', ...
         'The promoted model owns this high-level route.'], ...
        activeGridPriorSource, activeGridRoutingDirection, ...
        shortcutConfidence, cfg.search.grid_pitch_mm, ...
        cfg.search.action_reach_mm, size(actionOffsets, 1)));
    learnedModelUsedForControl = true;
        if strcmp(executionMode, ...
            'FULL_LOOP_BASELINE_IMPROVED_DIRECT_X3_LEARNED')
        [ctx, capture, directDiagnostics] = ...
            runImprovedDirectRetry3(ctx, conical, learned, centerXY, ...
                surfaceZ, contactNormalSign, policyClock, ...
                cfg.baselines.active_time_budget_s);
        result.policy_search_diagnostics = directDiagnostics;
        result.direct_attempt_records = ...
            directDiagnostics.attempt_records;
        result.direct_successful_attempt = ...
            directDiagnostics.successful_attempt;
        result.direct_success_kind = ...
            directDiagnostics.success_kind;
        result.learned_shortcut_model_used = true;
        result.shortcut_policy_class = ...
            'IMPROVED_DIRECT_ACTIVE_LEARNED_INDEPENDENT_REPROBE';
        result.shortcut_evidence = struct( ...
            'model', ...
                'IMPROVED_DIRECT_ACTIVE_LEARNED_INDEPENDENT_REPROBE', ...
            'direction_source', ...
                'FRESH_ACTIVE_REAL_MODEL_DIRECTION_PER_ATTEMPT', ...
            'ray_limit_mm', cfg.baselines.direct_ray_limit_mm, ...
            'maximum_attempts', cfg.baselines.direct_max_attempts, ...
            'perpendicular_adjustment_mm', ...
                cfg.baselines.direct_adjustment_mm, ...
            'fan_angles_deg', [0.0, 0.0, 0.0]);
        result.bayesian_grid_steps = 0;
        result.posterior_entropy_final_nat = NaN;
    else
    shortcutTargetXY = centerXY + shortcutOffset;
    result.shortcut_offset_mm = shortcutOffset;
    result.shortcut_confidence = shortcutConfidence;
    result.shortcut_distance_mm = shortcutDistance;
    result.shortcut_direction_world_xy = shortcutDirectionWorld;
    result.shortcut_evidence = shortcutEvidence;
    result.learned_shortcut_model_used = learnedModelUsedForControl;
    result.shortcut_policy_class = shortcutEvidence.model;
    logEvent(paths.events, 'SHORTCUT_POLICY_DISCLOSURE', sprintf( ...
        ['%s.  The promoted model selects the bounded high-level route; ', ...
         'MATLAB/KST remains the sole command owner and retains every ', ...
         'physical guard, capture, insertion and terminal decision.'], ...
        shortcutEvidence.model));
    logTransition(paths.transitions, ...
        'CONTINUOUS_15_DEG_TIP_CENTERED_CONE', ...
        'CONTACT_FORCE_SHORTCUT', 'FINGERPRINT_DIRECTION_RESOLVED', ...
        sprintf(['phase confidence %.3f; shortcut %.3f mm to WORLD XY ', ...
         'offset [%+.3f %+.3f] mm; remain upright and transport in ', ...
         '%.2f mm XY microsegments while holding about %.1f N.  A persistent ', ...
         'soft-envelope downward-progress event hands off to insertion.'], ...
        shortcutConfidence, shortcutDistance, shortcutOffset, ...
        cfg.surface.xy_segment_mm, ...
        cfg.surface.target_normal_force_n));
    [ctx, shortcutTransport] = moveSurfaceWithPolicyDeadline(ctx, ...
        shortcutTargetXY, surfaceZ, contactNormalSign, ...
        'SHORTCUT_CONTACT_TRANSPORT', policyClock, ...
        cfg.baselines.active_time_budget_s);
    measuredShortcutOffset = ...
        shortcutTransport.pose_mm_rad(1:2) - centerXY;
    shortcutAnchorXY = shortcutTransport.pose_mm_rad(1:2);
    result.shortcut_measured_endpoint_offset_mm = ...
        measuredShortcutOffset;

    % Center hypotheses stay expressed about the measured touchdown contact
    % anchor.  The shortcut changes only the current robot position;
    % it does not reset the belief or translate the entire search domain.
    plannedTestedOffsets = zeros(0, 2);
    measuredTestedOffsets = zeros(0, 2);
    measuredSweptSegments = zeros(0, 4);
    measuredTestedOffsets(end + 1, :) = measuredShortcutOffset;
    measuredSweptSegments = appendMeasuredSurfaceSegments( ...
        measuredSweptSegments, ...
        shortcutTransport.measured_xy_polyline_mm, centerXY, ...
        [0.0, 0.0], measuredShortcutOffset);
    if shortcutTransport.capture_confirmed
        measuredCaptureOffset = ...
            shortcutTransport.pose_mm_rad(1:2) - centerXY;
        capture = makeCapture(true, ...
            'SHORTCUT_SENSOR_DOWNWARD_PROGRESS_CAPTURE_CANDIDATE', ...
            measuredCaptureOffset, shortcutTransport.pose_mm_rad);
        logEvent(paths.events, 'SHORTCUT_CAPTURE_HANDOFF', sprintf( ...
            ['surface-relative depth %.3f mm; dF %.3f N; dT %.4f Nm; ', ...
             'skip residual grid and begin upright insertion'], ...
            shortcutTransport.depth_below_surface_mm, ...
            shortcutTransport.force_delta_n, ...
            shortcutTransport.torque_delta_nm));
    else
        capture = emptyCapture();
        % A miss updates the posterior only when the measured endpoint was
        % actually reached with a valid contact-held observation.  A
        % degraded, low-force, or no-lift contact hypothesis is useful
        % evidence but is not a geometric no-capture constraint.
        if surfaceNegativeObservationValid(shortcutTransport)
            posterior = updatePosteriorAlongSegment(posterior, ...
                centerHypotheses, [0.0, 0.0], ...
                measuredShortcutOffset, false, cfg);
            result.shortcut_negative_observation_valid = true;
        else
            result.shortcut_negative_observation_valid = false;
            logEvent(paths.events, ...
                'SHORTCUT_AMBIGUOUS_OBSERVATION_POSTERIOR_UNCHANGED', ...
                sprintf([ ...
                'terminal %s; degraded %d; no-lift hold %d; preserve the ', ...
                'learned/CAD posterior and continue physical verification'], ...
                shortcutTransport.terminal_reason, ...
                shortcutTransport.degraded_waypoint, ...
                shortcutTransport.no_lift_contact_hold));
        end
        % Both Proposed methods use the same learned-direction sector after
        % the measured shortcut has supplied its physical negative evidence.
        % The probability support remains in the original touchdown frame;
        % only its angular support is conditioned before sizing or routing the
        % residual action.
        posterior = conditionPosteriorOnDirectionalSector( ...
            posterior, centerHypotheses, ...
            activeGridRoutingDirection, corridorHalfAngleDeg, ...
            cfg.search.directional_sector_outside_likelihood_floor);
        result.residual_posterior_scope = ...
            'LEARNED_DIRECTION_SECTOR_AFTER_MEASURED_SHORTCUT_OBSERVATION';
        result.residual_posterior_coordinate_frame = ...
            'ORIGINAL_MEASURED_TOUCHDOWN_ANCHOR';
        % Recompute Proposed-local q95 about the measured shortcut endpoint
        % with that same conditioned posterior.  A distant secondary mode can
        % no longer inflate the local spiral while the original touchdown
        % coordinate system remains unchanged.
        measuredResidualRadiusMm = weightedQuantile( ...
            vecnorm(centerHypotheses - measuredShortcutOffset, 2, 2), ...
            posterior, 0.95) - cfg.search.bayes_capture_radius_mm;
        measuredResidualRadiusMm = min(max(measuredResidualRadiusMm, ...
            cfg.surface.endpoint_xy_tolerance_mm), ...
            cfg.baselines.proposed_residual_radius_mm);
        learnedShortcut.residual_radius_mm = measuredResidualRadiusMm;
        shortcutEvidence.posterior_residual_radius_measured_endpoint_mm = ...
            measuredResidualRadiusMm;
        shortcutEvidence.residual_posterior_scope = ...
            result.residual_posterior_scope;
        shortcutEvidence.residual_posterior_coordinate_frame = ...
            result.residual_posterior_coordinate_frame;
        shortcutEvidence.residual_posterior_sector_half_angle_deg = ...
            corridorHalfAngleDeg;
        shortcutEvidence.residual_radius_uses_measured_shortcut_endpoint = ...
            true;
        result.shortcut_evidence = shortcutEvidence;
        result.learned_active_residual_radius_mm = ...
            measuredResidualRadiusMm;
        plannedTestedOffsets = [0.0, 0.0; shortcutOffset];
        measuredTestedOffsets = [0.0, 0.0; measuredShortcutOffset];
        measuredSweptSegments = ...
            [0.0, 0.0, measuredShortcutOffset];
        logEvent(paths.events, ...
            'SHORTCUT_ENDPOINT_NEGATIVE_CAPTURE_EVIDENCE', ...
            sprintf([ ...
            'No downward-progress capture cue at the force-held shortcut ', ...
            'endpoint; original-anchor posterior updated, conditioned to ', ...
            'the learned %.1f deg half-width sector, and planned/measured ', ...
            'endpoints plus the measured swept segment were recorded.  ', ...
            'Measured-endpoint conditioned q95 residual radius %.3f mm.'], ...
            corridorHalfAngleDeg, measuredResidualRadiusMm));
        if strcmp(executionMode, ...
                'FULL_LOOP_PROPOSED_LEARNED_LOCAL_SPIRAL')
            logTransition(paths.transitions, ...
                'CONTACT_FORCE_SHORTCUT', ...
                'CONTACT_FORCE_LOCAL_OUTWARD_RESIDUAL', ...
                'SHORTCUT_ENDPOINT_REACHED', ...
                ['The learned shortcut is frozen.  Residual capture uses ', ...
                 'a bounded outward Archimedean path about that endpoint; ', ...
                 'the model never declares capture or terminal success.']);
        else
            logTransition(paths.transitions, 'CONTACT_FORCE_SHORTCUT', ...
                'CONTACT_FORCE_ENTROPY_GRID', ...
                'SHORTCUT_ENDPOINT_REACHED', ...
                ['Entropy-grid actions remain on the surface under the same ', ...
                 'bounded down-force outer loop; the conical scan is a routing ', ...
                 'prior, not a capture declaration.']);
        end
    end

    gridStep = 0;
    currentGridOffset = measuredShortcutOffset;
    if strcmp(executionMode, ...
            'FULL_LOOP_PROPOSED_LEARNED_LOCAL_SPIRAL')
        if ~capture.found
            if norm(shortcutOffset) > 1e-12
                residualPhase = atan2(shortcutOffset(2), ...
                    shortcutOffset(1));
            else
                fixtureXAxisWorld = ...
                    cfg.frame.world_from_fixture_rotation(1:2, 1).';
                residualPhase = atan2(fixtureXAxisWorld(2), ...
                    fixtureXAxisWorld(1));
            end
            [ctx, capture, outwardDiagnostics] = ...
                runOutwardArchimedeanSearch(ctx, shortcutAnchorXY, ...
                    centerXY, surfaceZ, contactNormalSign, ...
                    residualPhase, ...
                    cfg.baselines.proposed_local_pitch_mm_per_revolution, ...
                    learnedShortcut.residual_radius_mm, ...
                    policyClock, ...
                    cfg.baselines.active_time_budget_s, ...
                    'PROPOSED_LOCAL_OUTWARD_RESIDUAL', ...
                    ['PROPOSED_LOCAL_OUTWARD_SENSOR_DOWNWARD_', ...
                     'PROGRESS_CAPTURE_CANDIDATE']);
            result.policy_search_diagnostics = outwardDiagnostics;
        end
        result.bayesian_grid_steps = 0;
        result.posterior_entropy_final_nat = ...
            discreteEntropy(posterior);
    else
    result.entropy_grid_selection_regions = cell(0, 1);
    directionQualified = norm(activeGridRoutingDirection) > 1e-12;
    activeResidualActionMask = true(size(actionOffsets, 1), 1);
    totalSearchTargets = 0;
    residualEigSteps = 0;
    residualGridSteps = 0;
    residualCadCoverageSteps = 0;
    noncontractingUpdates = 0;
    cadCoverageMode = false;
    residualSectorReleased = false;
    result.residual_sector_released = false;
    result.residual_sector_release_step = NaN;
    if directionQualified
        activeResidualActionMask = directionalSectorMask( ...
            actionOffsets, activeGridRoutingDirection, ...
            corridorHalfAngleDeg);
        result.entropy_grid_scope_initial = ...
            ['FROZEN_LEARNED_DIRECTION_MONOTONIC_CENTERLINE_THEN_', ...
             'CONNECTED_NOVEL_RESIDUAL'];
        [corridorOffsets, corridorLaneOffsets, corridorDiagnostics] = ...
            buildDirectionalCadCorridor(currentGridOffset, ...
                activeGridRoutingDirection, corridorHalfAngleDeg, cfg);
        result.directional_corridor_planned_offsets_mm = ...
            corridorOffsets;
        result.directional_corridor_lane_offsets_mm = ...
            corridorLaneOffsets;
        result.directional_corridor_path_length_mm = ...
            corridorDiagnostics.path_length_mm;
        result.directional_corridor_exit_reason = 'COMPLETED';
        logEvent(paths.events, ...
            'DIRECTIONAL_CAD_CORRIDOR_PLANNED', sprintf( ...
            ['frozen posterior/CAD monotonic centerline [%+.4f %+.4f] ', ...
             '(task %.2f deg); ', ...
             'credible-sector full/half width %.1f/%.1f deg; ', ...
             'contained posterior mass %.4f/%.4f; ', ...
             'mass gate diagnostic only %d; learned direction retains control; ', ...
             '%d targets; %.3f mm path; %.3f mm maximum advance; ', ...
             'no serpentine lanes; robust capture radius %.3f mm'], ...
            activeGridRoutingDirection, ...
            corridorCredible.control_center_task_deg, ...
            2.0 * corridorHalfAngleDeg, corridorHalfAngleDeg, ...
            corridorCredible.contained_probability_mass, ...
            corridorCredible.target_mass, ...
            corridorCredible.mass_requirement_satisfied, ...
            max(0, size(corridorOffsets, 1) - 1), ...
            corridorDiagnostics.path_length_mm, ...
            corridorDiagnostics.maximum_advance_mm, ...
            corridorDiagnostics.robust_capture_radius_mm));
        for corridorIndex = 2:size(corridorOffsets, 1)
            if capture.found || ...
                    totalSearchTargets >= cfg.search.maximum_grid_nodes
                result.directional_corridor_exit_reason = ...
                    'TOTAL_SEARCH_TARGET_BUDGET_EXHAUSTED';
                break;
            end
            offset = corridorOffsets(corridorIndex, :);
            totalSearchTargets = totalSearchTargets + 1;
            logTransition(paths.transitions, ...
                'CONTACT_FORCE_DIRECTIONAL_CAD_CORRIDOR', ...
                'DIRECTIONAL_CORRIDOR_CONTACT_TRANSPORT', ...
                'FROZEN_CONICAL_DIRECTION_CENTERLINE_TARGET', sprintf( ...
                ['target %d/%d; offset [%+.3f %+.3f] mm; ', ...
                 'learned-direction projection never decreases by more than ', ...
                 'the %.2f mm measurement tolerance; ', ...
                 'WORLD XY endpoint is internally split into %.2f mm ', ...
                 'force-observed microsegments'], ...
                corridorIndex - 1, size(corridorOffsets, 1) - 1, ...
                offset, cfg.search.directional_progress_tolerance_mm, ...
                cfg.surface.xy_segment_mm));
            [ctx, probe] = moveSurfaceWithPolicyDeadline(ctx, ...
                centerXY + offset, surfaceZ, contactNormalSign, ...
                sprintf('DIRECTIONAL_CORRIDOR_%02d', ...
                    corridorIndex - 1), ...
                policyClock, cfg.baselines.active_time_budget_s);
            segmentStartOffset = currentGridOffset;
            measuredProbeOffset = ...
                probe.pose_mm_rad(1:2) - centerXY;
            currentGridOffset = measuredProbeOffset;
            reachedPlannedTarget = norm( ...
                measuredProbeOffset - offset) <= ...
                cfg.surface.endpoint_xy_tolerance_mm;
            if reachedPlannedTarget
                plannedTestedOffsets(end + 1, :) = offset; %#ok<AGROW>
            end
            measuredTestedOffsets(end + 1, :) = ... %#ok<AGROW>
                measuredProbeOffset;
            measuredSweptSegments = appendMeasuredSurfaceSegments( ...
                measuredSweptSegments, ...
                probe.measured_xy_polyline_mm, centerXY, ...
                segmentStartOffset, measuredProbeOffset);
            result.directional_corridor_completed_targets = ...
                result.directional_corridor_completed_targets + 1;
            if probe.capture_confirmed
                posterior = updatePosteriorAlongSegment(posterior, ...
                    centerHypotheses, segmentStartOffset, ...
                    measuredProbeOffset, true, cfg);
                capture = makeCapture(true, ...
                    ['DIRECTIONAL_CAD_CORRIDOR_SENSOR_DOWNWARD_', ...
                     'PROGRESS_CAPTURE_CANDIDATE'], ...
                    measuredProbeOffset, probe.pose_mm_rad);
                result.directional_corridor_exit_reason = ...
                    'PHYSICAL_CAPTURE_HANDOFF';
                break;
            end
            if surfaceNegativeObservationValid(probe)
                posterior = updatePosteriorAlongSegment(posterior, ...
                    centerHypotheses, segmentStartOffset, ...
                    measuredProbeOffset, false, cfg);
            else
                logEvent(paths.events, ...
                    'CORRIDOR_AMBIGUOUS_OBSERVATION_POSTERIOR_UNCHANGED', ...
                    sprintf([ ...
                    'target %d; terminal %s; reached planned target %d; ', ...
                    'degraded %d; no-lift hold %d'], ...
                    corridorIndex - 1, probe.terminal_reason, ...
                    reachedPlannedTarget, probe.degraded_waypoint, ...
                    probe.no_lift_contact_hold));
            end
        end
    else
        error('M12Demo:ActiveGridDirectionMissing', ...
            ['Proposed+ requires the finite learned TOP1 direction that ', ...
             'already passed active model validation; full-disk routing ', ...
             'fallback is forbidden.']);
    end
    while ~capture.found && ...
            totalSearchTargets < cfg.search.maximum_grid_nodes
        residualCredibleRadiusMm = posteriorSpreadQuantile( ...
            posterior, centerHypotheses, 0.95);
        if ~cadCoverageMode && residualCredibleRadiusMm <= ...
                cfg.search.bayes_capture_radius_mm
            cadCoverageMode = true;
            logEvent(paths.events, ...
                'RESIDUAL_EIG_CREDIBLE_RADIUS_SWITCH_TO_CAD_COVERAGE', ...
                sprintf([ ...
                'posterior q95 radius %.3f mm is inside robust capture ', ...
                'radius %.3f mm but no physical capture event exists; ', ...
                'switching from information utility to CAD verification ', ...
                'coverage instead of stopping'], ...
                residualCredibleRadiusMm, ...
                cfg.search.bayes_capture_radius_mm));
        end
        if cadCoverageMode
            [candidateIndex, expectedInformation, predictiveOpen, ...
                bestUtility, selectionRegion] = ...
                selectCadCoverageNode(posterior, ...
                centerHypotheses, actionOffsets, ...
                plannedTestedOffsets, measuredTestedOffsets, ...
                measuredSweptSegments, currentGridOffset, ...
                activeResidualActionMask, activeGridRoutingDirection, cfg);
        else
            [candidateIndex, expectedInformation, predictiveOpen, ...
                bestUtility, selectionRegion] = ...
                selectExpectedInformationNode(posterior, ...
                centerHypotheses, actionOffsets, ...
                plannedTestedOffsets, measuredTestedOffsets, ...
                measuredSweptSegments, currentGridOffset, ...
                activeResidualActionMask, activeGridRoutingDirection, cfg);
            if candidateIndex == 0
                cadCoverageMode = true;
                logEvent(paths.events, ...
                    'RESIDUAL_EIG_UTILITY_SWITCH_TO_CAD_COVERAGE', ...
                    sprintf([ ...
                    'EIG region %s; best utility %.6f <= %.6f or no ', ...
                    'credible EIG node; continuing physical CAD coverage'], ...
                    selectionRegion, bestUtility, ...
                    cfg.search.eig_minimum_utility));
                [candidateIndex, expectedInformation, predictiveOpen, ...
                    bestUtility, selectionRegion] = ...
                    selectCadCoverageNode(posterior, ...
                    centerHypotheses, actionOffsets, ...
                    plannedTestedOffsets, measuredTestedOffsets, ...
                    measuredSweptSegments, currentGridOffset, ...
                    activeResidualActionMask, ...
                    activeGridRoutingDirection, cfg);
            end
        end
        if candidateIndex == 0 && directionQualified && ...
                ~residualSectorReleased
            % Exhausting the sector-conditioned nodes does not mean the hole
            % is unreachable -- it usually means the hole is not in the
            % sector.  The sector is only as good as the learned direction,
            % and when that direction is wrong by more than the corridor
            % half-width the sector provably cannot contain the hole.
            %
            % Breaking here handed control to the blind phase-shifted
            % coverage fallback, which re-walks ground the grid had already
            % swept.  The 2026-07-30 run at 39 deg exhausted 11 s after the
            % grid was bound, with essentially no productive node, and then
            % spent 130 s and seven passes repeating itself: what the
            % operator watched was never the entropy search at all.
            %
            % Release the sector to the full residual disk and keep using the
            % same information-driven selection instead.  The posterior, the
            % swept-coverage bookkeeping and every physical guard are
            % unchanged; only the admissible action set widens.
            residualSectorReleased = true;
            result.residual_sector_released = true;
            result.residual_sector_release_step = residualGridSteps;
            activeResidualActionMask = true(size(actionOffsets, 1), 1);
            cadCoverageMode = false;
            % Widening the action mask alone accomplished nothing on the first
            % attempt at this fix: selection is driven by the posterior's 95%
            % credible region, and the posterior is still conditioned to the
            % sector that has just been refuted.  The 2026-07-30 02:18 run
            % released the sector and then reported NO_UNTESTED_95PCT_CREDIBLE
            % _NODE with utility -Inf 12 ms later, because every reachable node
            % outside the collapsed credible blob counted as incredible.  The
            % same collapse drives the fallback radius, which is
            % min(q95 spread, ...) floored at the 0.75 mm capture radius, so
            % the fallback then spiralled inside 0.75 mm for ten passes.
            %
            % Exhausting the sector without capture is evidence AGAINST the
            % directional prior, so that prior must be given up here, not kept.
            % Mix the posterior back toward uniform over its own support: the
            % measured swept-coverage evidence is retained, while the refuted
            % directional concentration is released and the credible region
            % reopens.  Physical guards, reach and capture radius are
            % untouched; only belief is widened.
            posterior = posterior(:);
            posterior = (1.0 - cfg.search.sector_release_uniform_weight) * ...
                    posterior + ...
                cfg.search.sector_release_uniform_weight / numel(posterior);
            posterior = posterior / sum(posterior);
            logEvent(paths.events, ...
                'RESIDUAL_SECTOR_RELEASED_TO_FULL_DISK', sprintf( ...
                ['region %s exhausted after %d grid steps with the ', ...
                 'admissible set conditioned to the learned %.1f deg ', ...
                 'half-width sector.  The sector cannot contain the hole ', ...
                 'when the direction error exceeds that half-width, so the ', ...
                 'residual disk is reopened in full and information-driven ', ...
                 'selection continues rather than degrading to blind ', ...
                 'repeated coverage.'], ...
                selectionRegion, residualGridSteps, corridorHalfAngleDeg));
            continue;
        end
        if candidateIndex == 0
            logEvent(paths.events, ...
                'RESIDUAL_CAD_COVERAGE_GEOMETRICALLY_EXHAUSTED', ...
                sprintf([ ...
                'region %s; all admissible CAD nodes have been swept, would ', ...
                'move backward, add too little new measured coverage, or the ', ...
                'finite %d-target common reach is exhausted; sector ', ...
                'released earlier: %d'], ...
                selectionRegion, cfg.search.maximum_grid_nodes, ...
                double(residualSectorReleased)));
            break;
        end
        residualGridSteps = residualGridSteps + 1;
        if cadCoverageMode
            residualCadCoverageSteps = residualCadCoverageSteps + 1;
        else
            residualEigSteps = residualEigSteps + 1;
        end
        totalSearchTargets = totalSearchTargets + 1;
        gridStep = residualGridSteps;
        result.entropy_grid_selection_regions{residualGridSteps, 1} = ...
            selectionRegion;
        result.bayesian_grid_steps = residualGridSteps;
        result.posterior_entropy_final_nat = ...
            discreteEntropy(posterior);
        offset = actionOffsets(candidateIndex, :);
        entropyBefore = discreteEntropy(posterior);
        spreadBeforeMm = posteriorSpreadQuantile( ...
            posterior, centerHypotheses, 0.95);
        logBayes(paths.bayes, residualGridSteps, ...
            candidateIndex, offset, ...
            entropyBefore, expectedInformation, predictiveOpen, ...
            max(posterior));
        if cadCoverageMode
            selectionEvent = ...
                'POSTERIOR_RANKED_PHYSICAL_CAD_COVERAGE';
        else
            selectionEvent = 'MAX_EXPECTED_INFORMATION';
        end
        logTransition(paths.transitions, ...
            'CONTACT_FORCE_ENTROPY_GRID', ...
            'ENTROPY_GRID_CONTACT_TRANSPORT', ...
            selectionEvent, sprintf( ...
            ['step %d; node %d; offset [%+.3f %+.3f] mm; ', ...
             'EIG %.6f nat; p(open) %.4f; utility %.6f; region %s'], ...
            residualGridSteps, candidateIndex, offset, ...
            expectedInformation, predictiveOpen, bestUtility, ...
            selectionRegion));
        [ctx, probe] = moveSurfaceWithPolicyDeadline(ctx, ...
            centerXY + offset, surfaceZ, contactNormalSign, ...
            sprintf('BAYES_GRID_%02d', residualGridSteps), ...
            policyClock, cfg.baselines.active_time_budget_s);
        segmentStartOffset = currentGridOffset;
        measuredProbeOffset = probe.pose_mm_rad(1:2) - centerXY;
        currentGridOffset = measuredProbeOffset;
        reachedPlannedTarget = norm(measuredProbeOffset - offset) <= ...
            cfg.surface.endpoint_xy_tolerance_mm;
        if reachedPlannedTarget
            plannedTestedOffsets(end + 1, :) = offset; %#ok<AGROW>
        end
        measuredTestedOffsets(end + 1, :) = ... %#ok<AGROW>
            measuredProbeOffset;
        measuredSweptSegments = appendMeasuredSurfaceSegments( ...
            measuredSweptSegments, probe.measured_xy_polyline_mm, ...
            centerXY, segmentStartOffset, measuredProbeOffset);
        if probe.capture_confirmed
            measuredCaptureOffset = probe.pose_mm_rad(1:2) - centerXY;
            % A real sensor-only downward-progress cue outranks the conical
            % direction prior.  The posterior may route search efficiently,
            % but it may never veto a physically observed capture candidate.
            posterior = updatePosteriorAlongSegment(posterior, ...
                centerHypotheses, segmentStartOffset, ...
                measuredProbeOffset, true, cfg);
            capture = makeCapture(true, ...
                'FINITE_BAYES_SENSOR_DOWNWARD_PROGRESS_CAPTURE_CANDIDATE', ...
                measuredCaptureOffset, probe.pose_mm_rad);
        elseif surfaceNegativeObservationValid(probe)
            posterior = updatePosteriorAlongSegment(posterior, ...
                centerHypotheses, segmentStartOffset, ...
                measuredProbeOffset, false, cfg);
        else
            logEvent(paths.events, ...
                'GRID_AMBIGUOUS_OBSERVATION_POSTERIOR_UNCHANGED', ...
                sprintf([ ...
                'step %d; terminal %s; reached planned target %d; ', ...
                'degraded %d; no-lift hold %d; no false Bayes miss update'], ...
                residualGridSteps, probe.terminal_reason, ...
                reachedPlannedTarget, probe.degraded_waypoint, ...
                probe.no_lift_contact_hold));
        end
        result.posterior_entropy_final_nat = ...
            discreteEntropy(posterior);
        spreadAfterMm = posteriorSpreadQuantile( ...
            posterior, centerHypotheses, 0.95);
        if spreadAfterMm >= spreadBeforeMm - ...
                cfg.search.tested_offset_tolerance_mm
            noncontractingUpdates = noncontractingUpdates + 1;
        else
            noncontractingUpdates = 0;
        end
        if ~capture.found && ~cadCoverageMode && ...
                noncontractingUpdates >= ...
                cfg.search.eig_maximum_noncontracting_updates
            cadCoverageMode = true;
            logEvent(paths.events, ...
                'RESIDUAL_EIG_NONCONTRACTING_SWITCH_TO_CAD_COVERAGE', ...
                sprintf( ...
                ['posterior q95 spread %.3f -> %.3f mm; ', ...
                 '%d consecutive noncontracting updates; continue with ', ...
                 'physical CAD coverage instead of stopping'], ...
                spreadBeforeMm, spreadAfterMm, noncontractingUpdates));
        end
    end
    if ~capture.found
        % The finite discrete action set is only the information-search
        % stage.  Its exhaustion is not a task failure.  Continue with
        % phase-shifted capture-verification coverage about the posterior
        % MAP, while preserving the original touchdown coordinate frame.
        % This is a paper-inspired perception-to-contact handoff only: the
        % upright endpoint-controlled implementation does not instantiate
        % the paper's inclined-corner impedance funnel or inherit its proof.
        [~, posteriorMapIndex] = max(posterior);
        posteriorMapOffset = centerHypotheses(posteriorMapIndex, :);
        posteriorVerificationRadiusMm = min( ...
            posteriorSpreadQuantile(posterior, centerHypotheses, 0.95), ...
            max(cfg.search.bayes_capture_radius_mm, ...
                cfg.search.action_reach_mm - norm(posteriorMapOffset)));
        posteriorVerificationRadiusMm = max( ...
            cfg.search.bayes_capture_radius_mm, ...
            posteriorVerificationRadiusMm);
        posteriorVerificationCenterXY = ...
            centerXY + posteriorMapOffset;
        result.posterior_funnel_verification_center_offset_mm = ...
            posteriorMapOffset;
        result.posterior_funnel_verification_radius_mm = ...
            posteriorVerificationRadiusMm;
        logTransition(paths.transitions, ...
            'CONTACT_FORCE_ENTROPY_GRID', ...
            'POSTERIOR_CAPTURE_VERIFICATION_COVERAGE', ...
            'NONIDENTICAL_EIG_CAD_ACTIONS_EXHAUSTED_NO_CAPTURE', ...
            sprintf([ ...
            'MAP offset [%+.3f %+.3f] mm; q95/CAD radius %.3f mm; ', ...
            'EIG yields to continuous phase-shifted capture coverage; ', ...
            'no classical direction fallback and no stage clock'], ...
            posteriorMapOffset, posteriorVerificationRadiusMm));
        [ctx, capture, posteriorFunnelDiagnostics] = ...
            runOutwardArchimedeanSearch(ctx, ...
                posteriorVerificationCenterXY, centerXY, ...
                surfaceZ, contactNormalSign, ...
                atan2(activeGridRoutingDirection(2), ...
                    activeGridRoutingDirection(1)), ...
                cfg.baselines.proposed_local_pitch_mm_per_revolution, ...
                posteriorVerificationRadiusMm, policyClock, ...
                cfg.baselines.active_time_budget_s, ...
                'PROPOSED_PLUS_POSTERIOR_COVERAGE', ...
                ['PROPOSED_PLUS_POSTERIOR_CAPTURE_COVERAGE_', ...
                 'DOWNWARD_PROGRESS_CAPTURE']);
        result.posterior_funnel_verification_diagnostics = ...
            posteriorFunnelDiagnostics;
    end
    result.bayesian_grid_steps = residualGridSteps;
    result.residual_eig_steps = residualEigSteps;
    result.residual_cad_coverage_mode_used = cadCoverageMode;
    result.residual_cad_coverage_steps = residualCadCoverageSteps;
    result.total_search_targets = totalSearchTargets;
    result.residual_eig_noncontracting_updates = ...
        noncontractingUpdates;
    result.posterior_entropy_final_nat = discreteEntropy(posterior);
    end
    end
    end
    end

    if strcmp(executionMode, ...
            'FULL_LOOP_BASELINE_IMPROVED_DIRECT_X3_LEARNED') && ...
            ~capture.found
        % Direct x3 is deliberately a finite comparison method.  The
        % referenced conical-exploration recovery changes the initial pose
        % slightly, repeats the complete probe and inference, and declares
        % failure after more than three attempts.  Do not silently turn this
        % baseline into repeated x3 rounds or another search method.
        result.capture_found = false;
        result.capture_method = 'NONE_STRICT_DIRECT_X3_EXHAUSTED';
        result.capture_offset_mm = [];
        result.capture_pose_mm_rad = [];
        assert(directDiagnostics.attempts_completed == ...
                cfg.baselines.direct_max_attempts, ...
            'M12Demo:DirectRetryAccounting', ...
            ['Direct x3 returned without capture after %d/%d completed ', ...
             'attempts; this is not a valid finite-method outcome.'], ...
            directDiagnostics.attempts_completed, ...
            cfg.baselines.direct_max_attempts);
        [result, endState, ctx] = finishDirectX3WithoutCapture( ...
            result, ctx, iiwa, cfg, paths, runDir);
        clear realtimeLogCleanup kstCleanup rosCleanup;
        return;
    end

    assert(capture.found, ...
        'M12Demo:PersistentSearchReturnedWithoutCapture', ...
        ['%s returned from its persistent completion-first search without ', ...
         'a measured capture.  This is an internal state invariant, not a ', ...
         'normal time/path exhaustion exit.'], executionMode);

    result.capture_found = true;
    result.capture_method = capture.method;
    result.capture_offset_mm = capture.offset_mm;
    result.capture_pose_mm_rad = capture.pose_mm_rad;
    logTransition(paths.transitions, 'SEARCH', ...
        'PROVISIONAL_SENSOR_DOWNWARD_PROGRESS_CAPTURE', ...
        capture.method, sprintf( ...
        ['offset [%+.3f %+.3f] mm; >= %.2f mm surface-relative ', ...
         'downward progress under the independent soft wrench envelope'], ...
        capture.offset_mm, cfg.surface.capture_depth_drop_mm));

    if compatibilityMode
        cfg.frame = bindOldKernelCompatibilityInsertionDatum( ...
            cfg.frame, capture.pose_mm_rad, surfaceZ, ...
            cfg.insertion.target_depth_mm);
        ctx.cfg.frame = cfg.frame;
        result.provisional_capture_axis_top_datum_world_point_mm = ...
            cfg.frame.m12_socket_top_datum_world_point_mm;
        result.provisional_capture_axis_bottom_datum_world_point_mm = ...
            cfg.frame.m12_socket_bottom_datum_world_point_mm;
        manifest.measured_m12_socket_top_datum_world_point_mm = ...
            cfg.frame.m12_socket_top_datum_world_point_mm;
        manifest.measured_m12_socket_bottom_datum_world_point_mm = ...
            cfg.frame.m12_socket_bottom_datum_world_point_mm;
        manifest.world_from_fixture_translation_mm = ...
            cfg.frame.world_from_fixture_translation_mm;
        writeJson(paths.manifest, manifest);
        logEvent(paths.events, ...
            'PROVISIONAL_CAPTURE_AXIS_INSERTION_DATUM_REBOUND', sprintf( ...
            ['capture XY [%+.3f %+.3f] mm; surface Z %.3f mm; ', ...
             'bottom Z %.3f mm; segmented insertion now follows this ', ...
             'same-run WORLD -Z axis'], ...
            cfg.frame.m12_socket_top_datum_world_point_mm(1:2), ...
            cfg.frame.m12_socket_top_datum_world_point_mm(3), ...
            cfg.frame.m12_socket_bottom_datum_world_point_mm(3)));
    end
    [ctx, insertion] = guardedM12Insertion(ctx);
    result.insertion_depth_mm = insertion.depth_mm;
    result.insertion_actions = insertion.actions;
    result.insertion_maximum_consecutive_stagnant_actions = ...
        insertion.maximum_consecutive_stagnant_actions;
    result.insertion_soft_recovery_actions = ...
        insertion.soft_recovery_actions;
    result.insertion_soft_recovery_episodes = ...
        insertion.soft_recovery_episodes;
    result.insertion_cumulative_relief_mm = ...
        insertion.cumulative_relief_mm;
    result.insertion_bore_axis_rebased = ...
        insertion.bore_axis_rebased;
    result.insertion_active_funnel_axis_xy_mm = ...
        insertion.active_funnel_axis_xy_mm;
    result.insertion_terminal_verification_kind = ...
        insertion.terminal_verification_kind;
    result.bottom_force_event = insertion.bottom_event;
    result.insertion_terminal_reason = insertion.reason;
    result.peak_insertion_force_delta_n = insertion.maximum_force_delta_n;
    result.peak_insertion_torque_delta_nm = insertion.maximum_torque_delta_nm;
    assert(insertion.bottom_event, ...
        'M12Demo:PersistentInsertionReturnedWithoutTerminal', ...
        ['Persistent insertion returned without a depth-band terminal event ', ...
         '(%s).  This is an internal state invariant, not a normal timeout ', ...
         'or recovery-exhaustion exit.'], insertion.reason);
    result.claim_endpoint = sprintf( ...
        'provisional_%s_bottom_event_in_depth_band_candidate', ...
        cfg.sampling.size_lower);
    [result, endState, ctx] = finishAtBottom( ...
        result, ctx, iiwa, cfg, paths, runDir);
    clear realtimeLogCleanup kstCleanup rosCleanup;

catch experimentError
    result.error = [experimentError.identifier, ': ', ...
        oneLine(experimentError.message)];
    result.terminal_reason = ['END_AT_CURRENT_POSE_AFTER_', ...
        regexprep(upper(experimentError.identifier), '[^A-Z0-9]+', '_')];
    if ~isempty(fieldnames(ctx))
        result = copyContextMetrics(result, ctx);
    end
    % End robot command authority before doing any nonessential table reads
    % or exception-evidence reconstruction.
    if kstOpened
        [endState.sent, endState.method] = requestKstEndOnce( ...
            iiwa, cfg.robot.ip, runDir, paths);
    else
        % The operator may already have placed MatlabToolboxServer in
        % Running before an entirely local JSON/preflight gate rejects the
        % run.  End that application lifecycle explicitly without creating
        % a KST motion object or writing any pose/velocity/force command.
        [endState.sent, endState.method] = requestKstEndOnce( ...
            [], cfg.robot.ip, runDir, paths, true);
    end
    bestEffortLogEvent(paths.events, ...
        'EXCEPTION_NO_BLIND_RETURN', result.error);
    % The realtime wrench files are long-lived buffered writers.  Close them
    % only after the KST end request, then reconstruct the audit summary from
    % fully flushed endpoint ledgers.  The onCleanup remains idempotent.
    if ~isempty(fieldnames(ctx)) && isfield(ctx, 'realtime_logs')
        closeRealtimeLogFiles(ctx.realtime_logs);
    end
    % MATLAB value semantics discard an inner function's updated ctx when
    % that function throws before returning.  Recover the already committed
    % endpoint ledger so a guarded touchdown stop cannot be misreported as
    % "no motion / zero commands" in summary.json.
    result = refreshResultMetricsFromRuntimeLogs(result, paths);
    if samplingMode
        result = refreshSamplingMetricsFromCheckpoint(result, paths);
    end
    % runConicalFingerprint cannot return its by-value ctx when an inner hard
    % guard throws.  Recover already-written conical evidence, plus the
    % guard value embedded in the exception, so an aborted summary never
    % reports only the earlier touchdown peak.
    result = refreshResultPeaksFromConicalEvidence( ...
        result, paths.conicalTrace, result.error);
    result.kst_end_request_sent = endState.sent;
    result.kst_end_request_method = endState.method;
    result.human_selected_confirmation_pending = endState.sent;
    if endState.sent
        result.completion_status = ...
            'TASK_ABORTED_KST_END_SENT_PENDING_SMARTPAD_SELECTED_OBSERVATION';
    elseif kstOpened
        result.completion_status = ...
            'TASK_ABORTED_KST_END_NOT_CONFIRMED';
    else
        result.completion_status = ...
            'TASK_ABORTED_BEFORE_KST_OPEN';
    end
    writeJson(paths.summary, result);
    if ~isempty(kstCleanup)
        clear kstCleanup;
    end
    if ~isempty(realtimeLogCleanup)
        clear realtimeLogCleanup;
    end
    if ~isempty(rosCleanup)
        clear rosCleanup;
    end
    rethrow(experimentError);
end
end

function [mode, resumeParentRunDir] = parseExecutionMode(varargin)
resumeParentRunDir = '';
if nargin == 0
        mode = 'FULL_LOOP_PROPOSED_PLUS_LEARNED_ENTROPY';
    return;
end
assert(any(nargin == [1, 2]) && ...
    (ischar(varargin{1}) || isstring(varargin{1})) && ...
    isscalar(string(varargin{1})), ...
    'M12Demo:ExecutionModeInput', ...
    ['Execution mode must be one scalar character vector or string, ', ...
     'optionally followed by one sampling parent run directory.']);
mode = upper(char(string(varargin{1})));
allowed = {'FULL_LOOP_PROPOSED_PLUS_LEARNED_ENTROPY', ...
    'FULL_LOOP_PROPOSED_PLUS_LEARNED_ENTROPY_M10', ...
    'FULL_LOOP_PROPOSED_LEARNED_LOCAL_SPIRAL', ...
    'FULL_LOOP_BASELINE_PURE_OUTWARD_SPIRAL', ...
    'FULL_LOOP_BASELINE_IMPROVED_DIRECT_X3_LEARNED', ...
    'DATASET_M12_CONICAL_FINGERPRINTS_26PT', ...
    'DATASET_M10_CONICAL_FINGERPRINTS_26PT', ...
    'DATASET_M8_CONICAL_FINGERPRINTS_26PT'};
assert(any(strcmp(mode, allowed)), 'M12Demo:ExecutionMode', ...
    'Unsupported execution mode %s.', mode);
if nargin == 2 && isstruct(varargin{2})
    fullLoopModes = { ...
        'FULL_LOOP_PROPOSED_PLUS_LEARNED_ENTROPY', ...
        'FULL_LOOP_PROPOSED_PLUS_LEARNED_ENTROPY_M10', ...
        'FULL_LOOP_PROPOSED_LEARNED_LOCAL_SPIRAL', ...
        'FULL_LOOP_BASELINE_PURE_OUTWARD_SPIRAL', ...
        'FULL_LOOP_BASELINE_IMPROVED_DIRECT_X3_LEARNED'};
    assert(any(strcmp(mode, fullLoopModes)), ...
        'M12Demo:PairedTrialMode', ...
        'A private paired trial spec is accepted only by a full-loop mode.');
    validatePairedTrialSpec(varargin{2}, mode);
elseif nargin == 2
    assert(any(strcmp(mode, { ...
            'DATASET_M12_CONICAL_FINGERPRINTS_26PT', ...
            'DATASET_M10_CONICAL_FINGERPRINTS_26PT', ...
            'DATASET_M8_CONICAL_FINGERPRINTS_26PT'})) && ...
        (ischar(varargin{2}) || isstring(varargin{2})) && ...
        isscalar(string(varargin{2})) && ...
        strlength(string(varargin{2})) > 0, ...
        'M12Demo:SamplingResumeInput', ...
        ['A second argument is allowed only for an M12/M10/M8 sampling mode ', ...
         'and must name one parent run directory.']);
    resumeParentRunDir = canonicalPath(char(string(varargin{2})));
end
end

function spec = parsePairedTrialSpec(mode, varargin)
spec = struct('enabled', false);
if numel(varargin) == 2 && isstruct(varargin{2})
    spec = validatePairedTrialSpec(varargin{2}, mode);
end
end

function spec = validatePairedTrialSpec(spec, mode)
required = {'schema', 'campaign_id', 'trial_index', ...
    'offset_index', 'offset_fixture_mm', 'method_index', ...
    'method_mode', 'order_position', 'public_trial_token', ...
    'campaign_center_world_xy_mm', ...
    'public_entrypoint', 'truth_firewall'};
assert(isstruct(spec) && isscalar(spec) && ...
    all(isfield(spec, required)), ...
    'M12Demo:PairedTrialSpec', ...
    'The private paired trial specification is incomplete.');
schema = char(spec.schema);
isLegacyV1 = strcmp(schema, ...
    'M12_PAIRED_FULL_LOOP_PRIVATE_TRIAL_V1');
isFixedDemoV2 = strcmp(schema, ...
    'M12_PAIRED_FULL_LOOP_PRIVATE_TRIAL_V2');
% The two-method proposed-vs-direct case study is a second sanctioned
% launcher.  It shares this engine, offset firewall and private-record
% handling, but declares its own schema and entrypoint so neither launcher
% can be mistaken for the other in the run record.
isProposedVsDirectV1 = strcmp(schema, ...
    'M12_PROPOSED_VS_DIRECT_PRIVATE_TRIAL_V1');
isM10FixedDemoV1 = strcmp(schema, ...
    'M10_PROPOSED_PLUS_FIXED_DEMO_PRIVATE_TRIAL_V1');
if isM10FixedDemoV1
    expectedEntrypoint = 'run_m10_proposed_plus_entropy_trial';
elseif isProposedVsDirectV1
    expectedEntrypoint = 'run_m12_proposed_vs_direct_trial';
else
    expectedEntrypoint = 'run_m12_paired_full_loop_trial';
end
assert((isLegacyV1 || isFixedDemoV2 || isProposedVsDirectV1 || ...
        isM10FixedDemoV1) && ...
    strcmp(char(spec.method_mode), mode) && ...
    strcmp(char(spec.public_entrypoint), expectedEntrypoint) && ...
    strcmp(char(spec.truth_firewall), ...
        ['OFFSET_USED_ONLY_FOR_PRE_TOUCHDOWN_AIR_TRANSPORT_', ...
         'NOT_POLICY_INPUT']), ...
    'M12Demo:PairedTrialSpecContract', ...
    'The private paired trial specification contract does not match.');
offset = double(reshape(spec.offset_fixture_mm, 1, []));
assert(numel(offset) == 2 && all(isfinite(offset)), ...
    'M12Demo:PairedTrialOffsetFinite', ...
    'The paired fixture-XY offset must contain two finite values.');
identityFinite = all(isfinite([double(spec.trial_index), ...
        double(spec.offset_index), double(spec.method_index), ...
        double(spec.order_position)]));
if isM10FixedDemoV1
    methodSlotCount = 1;
elseif isProposedVsDirectV1
    methodSlotCount = 2;
else
    methodSlotCount = 4;
end
commonIdentityValid = identityFinite && ...
    double(spec.method_index) >= 1 && ...
    double(spec.method_index) <= methodSlotCount && ...
    double(spec.order_position) >= 1 && ...
    double(spec.order_position) <= methodSlotCount && ...
    ~isempty(char(spec.campaign_id)) && ...
    ~isempty(char(spec.public_trial_token));
if isM10FixedDemoV1
    m10Required = {'demo_design_id', 'demo_seed_token', ...
        'source_sample_id', 'source_sample_offset_fixture_mm', ...
        'offset_selection_rationale', 'pilot_authorization_id', ...
        'controller_tuning_revision'};
    expectedOffset = [ ...
        4.590151046897575, 0.3008543944586581];
    expectedSourceOffset = [5.521449100, 0.361894894];
    designValid = all(isfield(spec, m10Required)) && ...
        norm(offset - expectedOffset) <= 1e-9 && ...
        double(spec.trial_index) >= 1 && ...
        double(spec.trial_index) <= 3 && ...
        double(spec.trial_index) == round(double(spec.trial_index)) && ...
        double(spec.offset_index) == 1 && ...
        double(spec.method_index) == 1 && ...
        double(spec.order_position) == 1 && ...
        strcmp(char(spec.method_mode), ...
            'FULL_LOOP_PROPOSED_PLUS_LEARNED_ENTROPY_M10') && ...
        strcmp(char(spec.demo_design_id), ...
            'M10_FIXED_PROPOSED_PLUS_NEAR_A003P75_R4P600_V1') && ...
        strcmp(char(spec.demo_seed_token), ...
            'M10_DEMO_20260730_A003P75_INWARD') && ...
        strcmp(char(spec.source_sample_id), ...
            'M10-CLEAN_CANDIDATE-SUPPORTED-A003p75') && ...
        norm(double(reshape( ...
            spec.source_sample_offset_fixture_mm, 1, [])) - ...
            expectedSourceOffset) <= 1e-9 && ...
        strcmp(char(spec.pilot_authorization_id), ...
            'M10_FIXED_PROPOSED_PLUS_DEMO_20260730_V1') && ...
        strcmp(char(spec.controller_tuning_revision), ...
            'M10_CHAMFER_FORCE14_TERMINAL_TORQUE010_V2') && ...
        contains(string(spec.offset_selection_rationale), ...
            "INWARD_SAME_RAY_NEAR_TWICE_COMPLETED_REAL_M10_SAMPLE");
elseif isLegacyV1
    designValid = norm(offset) >= 0.75 && norm(offset) <= 2.40 && ...
        double(spec.trial_index) >= 1 && ...
        double(spec.trial_index) <= 16 && ...
        double(spec.offset_index) >= 1 && ...
        double(spec.offset_index) <= 4;
elseif isProposedVsDirectV1
    % The four-method demo pins one exact offset literal because it is a
    % fixed unbiased point.  This case study instead exposes documented
    % radius and angle knobs, so pinning literals here would force a
    % two-file edit for every sweep step and would drift silently the first
    % time someone forgot.  Bound the geometry that actually matters: the
    % peg must stay on the 21.275 mm socket head at touchdown, which caps
    % the radius near 6.0 mm, and the angle must stay inside the range where
    % the direction model is measured to hold its trained lobe.
    pvdRequired = {'demo_design_id', 'demo_seed_token', ...
        'source_sample_id', 'offset_selection_rationale'};
    offsetRadiusMm = norm(offset);
    offsetAngleDeg = mod(atan2d(offset(2), offset(1)), 360.0);
    designValid = all(isfield(spec, pvdRequired)) && ...
        offsetRadiusMm >= 4.00 && offsetRadiusMm <= 6.10 && ...
        offsetAngleDeg >= 15.0 && offsetAngleDeg <= 48.0 && ...
        double(spec.trial_index) >= 1 && ...
        double(spec.trial_index) <= 2 && ...
        double(spec.offset_index) == 1 && ...
        startsWith(string(spec.demo_design_id), ...
            "M12_DISCRIMINATING_OFFSET_PROPOSED_VS_DIRECT_") && ...
        startsWith(string(spec.demo_seed_token), ...
            "M12_PROPOSED_VS_DIRECT_") && ...
        strcmp(char(spec.source_sample_id), ...
            'M12-CLEAN_CANDIDATE-SUPPORTED-A003p75') && ...
        contains(string(spec.offset_selection_rationale), ...
            "DELIBERATELY_DISCRIMINATING_NOT_RANDOM_");
else
    v2Required = {'demo_design_id', 'demo_seed_token', ...
        'source_sample_id'};
    expectedOffset = [4.580702667, 0.420907446];
    designValid = all(isfield(spec, v2Required)) && ...
        norm(offset - expectedOffset) <= 1e-9 && ...
        double(spec.trial_index) >= 1 && ...
        double(spec.trial_index) <= 4 && ...
        double(spec.offset_index) == 1 && ...
        strcmp(char(spec.demo_design_id), ...
            'M12_FIXED_SEED_DEMO_NEAR_CLEAN_A003P75_R4P600_V2') && ...
        strcmp(char(spec.demo_seed_token), ...
            'M12_DEMO_SEED_20260729_A003P75') && ...
        strcmp(char(spec.source_sample_id), ...
            'M12-CLEAN_CANDIDATE-SUPPORTED-A003p75');
end
assert(commonIdentityValid && designValid, ...
    'M12Demo:PairedTrialIdentity', ...
    ['The paired trial identity or schema-specific fixed-design fields ', ...
     'are invalid.']);
campaignCenter = double(reshape( ...
    spec.campaign_center_world_xy_mm, 1, []));
if isM10FixedDemoV1
    assert(isempty(campaignCenter), ...
        'M12Demo:M10FreshTaughtCenterRequired', ...
        ['The fixed M10 pilot must derive its centre from this invocation''s ', ...
         'fresh stationary taught pose; historical absolute WORLD XY is ', ...
         'forbidden.']);
else
    assert(isempty(campaignCenter) || ...
        (numel(campaignCenter) == 2 && all(isfinite(campaignCenter))), ...
        'M12Demo:PairedCampaignCenter', ...
        'The private fixed campaign centre must be empty or finite WORLD XY.');
end
spec.campaign_center_world_xy_mm = campaignCenter;
spec.offset_fixture_mm = offset;
spec.enabled = true;
end

function policy = executionPolicy(mode)
policy = struct( ...
    'mode', mode, ...
    'cad_size', 'm12', ...
    'public_entrypoint', ...
        'run_m12_full_loop_proposed_plus_entropy_grid', ...
    'run_prefix', 'M12_proposed_plus_entropy_grid_', ...
    'sampling_mode', false, ...
    'uses_conical_fingerprint', true, ...
    'residual_search', 'FINITE_ENTROPY_GRID', ...
    'direct_attempts', 0, ...
    'description', ...
        ['Proposed+: one cone, one learned CAD-posterior bounded shortcut, ', ...
         'a learned-direction CAD corridor, and a 95%-credible residual EIG ', ...
         'search.  The promoted model owns high-level routing only.']);
switch mode
    case 'DATASET_M8_CONICAL_FINGERPRINTS_26PT'
        policy.public_entrypoint = ...
            'run_m8_sampling_conical_fingerprints_26pt';
        policy.run_prefix = 'M8_conical_fingerprints_26pt_';
        policy.sampling_mode = true;
        policy.residual_search = 'NONE_SAMPLING_ONLY';
        policy.description = ...
            ['Run-local M8 real-device conical fingerprint acquisition; ', ...
             'raw Bota and measured endpoint evidence only, no runtime model.'];
    case 'DATASET_M10_CONICAL_FINGERPRINTS_26PT'
        policy.public_entrypoint = ...
            'run_m10_sampling_conical_fingerprints_26pt';
        policy.run_prefix = 'M10_conical_fingerprints_26pt_';
        policy.sampling_mode = true;
        policy.residual_search = 'NONE_SAMPLING_ONLY';
        policy.description = ...
            ['Run-local M10 real-device conical fingerprint acquisition; ', ...
             'raw Bota and measured endpoint evidence only, no runtime model.'];
    case 'DATASET_M12_CONICAL_FINGERPRINTS_26PT'
        policy.public_entrypoint = ...
            'run_m12_sampling_conical_fingerprints_26pt';
        policy.run_prefix = 'M12_conical_fingerprints_26pt_';
        policy.sampling_mode = true;
        policy.residual_search = 'NONE_SAMPLING_ONLY';
        policy.description = ...
            ['Run-local M12 real-device conical fingerprint acquisition; ', ...
             'raw Bota and measured endpoint evidence only, no runtime model.'];
    case 'FULL_LOOP_PROPOSED_PLUS_LEARNED_ENTROPY_M10'
        % Same proposed method, M10 hardware.  Only the CAD size changes; the
        % search, capture, insertion and terminal logic are shared verbatim
        % with the M12 mode so the two are directly comparable.
        policy.public_entrypoint = ...
            'run_m10_proposed_plus_entropy_trial';
        policy.run_prefix = 'M10_proposed_plus_entropy_grid_';
        policy.cad_size = 'm10';
        policy.description = ...
            ['Run-local M10 proposed learned-posterior plus residual ', ...
             'entropy search; identical policy to the M12 mode with the ', ...
             'M10 printed CAD geometry and a 5.0 mm socket depth.'];
    case 'FULL_LOOP_PROPOSED_LEARNED_LOCAL_SPIRAL'
        policy.public_entrypoint = ...
            'run_m12_full_loop_proposed_local_spiral';
        policy.run_prefix = 'M12_proposed_local_spiral_';
        policy.residual_search = 'LOCAL_OUTWARD_ARCHIMEDEAN';
        policy.description = ...
            ['Proposed: one independent cone, learned CAD-posterior bounded ', ...
             'shortcut, and posterior-sized local outward residual search.'];
    case 'FULL_LOOP_BASELINE_PURE_OUTWARD_SPIRAL'
        policy.public_entrypoint = ...
            'run_m12_full_loop_baseline_pure_outward_spiral';
        policy.run_prefix = 'M12_baseline_pure_outward_spiral_';
        policy.uses_conical_fingerprint = false;
        policy.residual_search = 'GLOBAL_OUTWARD_ARCHIMEDEAN';
        policy.description = ...
            ['Pure Outward: no conical probe and no learned inference; ', ...
             'persistent phase-shifted outward/inward Archimedean surface ', ...
             'coverage until measured capture or an independent hard guard.'];
    case 'FULL_LOOP_BASELINE_IMPROVED_DIRECT_X3_LEARNED'
        policy.public_entrypoint = ...
            'run_m12_full_loop_baseline_improved_direct_x3';
        policy.run_prefix = 'M12_baseline_improved_direct_x3_';
        policy.residual_search = 'NONE_DIRECT_RAYS_ONLY';
        policy.direct_attempts = 3;
        policy.description = ...
            ['Strict Direct x3: exactly three independent cone, fresh-model ', ...
             'direction and direct-ray attempts.  Failed attempts use small ', ...
             '0/+0.25/-0.25 mm shifted initial poses, no angle fan and no ', ...
             'outer repeated-x3 loop.'];
end
end

function [result, manifest] = discloseExecutionPolicy( ...
        result, manifest, policy, cfg)
result.policy_description = policy.description;
result.public_entrypoint = policy.public_entrypoint;
result.public_entrypoint_path = cfg.public_entrypoint_path;
result.public_entrypoint_sha256 = cfg.public_entrypoint_sha256;
result.learned_motion_authority_required = ...
    policy.uses_conical_fingerprint;
result.learned_motion_authority_preflight_passed = false;
result.learned_motion_authority_manifest_sha256 = '';
result.learned_motion_promotion_contract_sha256 = '';
result.policy_time_budget_s = cfg.baselines.active_time_budget_s;
result.policy_search_diagnostics = struct();
result.direct_attempt_records = struct([]);
result.direct_successful_attempt = NaN;
result.direct_success_kind = 'NONE';
manifest.policy_description = policy.description;
manifest.public_entrypoint = policy.public_entrypoint;
manifest.public_entrypoint_path = cfg.public_entrypoint_path;
manifest.public_entrypoint_sha256 = cfg.public_entrypoint_sha256;
manifest.policy_uses_conical_fingerprint = ...
    policy.uses_conical_fingerprint;
manifest.policy_uses_learned_direction_for_motion = ...
    policy.uses_conical_fingerprint;
manifest.policy_residual_search = policy.residual_search;
manifest.policy_direct_attempts = policy.direct_attempts;
manifest.policy_active_time_budget_s = ...
    cfg.baselines.active_time_budget_s;
manifest.learned_motion_authority_required = ...
    policy.uses_conical_fingerprint;
manifest.learned_motion_preflight_rule = ...
    ['Every conical full-loop entrypoint requires a hash-bound ', ...
     'CAPPED_SHORTCUT promotion contract before KST and active inference ', ...
     'after each completed cone.  Failure stops; there is no hidden ', ...
     'classical direction fallback.'];
if strcmp(policy.mode, 'FULL_LOOP_BASELINE_PURE_OUTWARD_SPIRAL')
    result.control_classification = ...
        'geometric_persistent_outward_search_shared_hard_guards_and_terminal_loop';
    result.fingerprint_claim = 'none_pure_outward_has_no_conical_probe';
    result.bayesian_role = 'none_pure_outward_has_no_model_or_posterior';
    manifest.shortcut_rule = 'none';
    manifest.grid_rule = ...
        ['1p00mm_per_revolution_phase_shifted_persistent_Archimedean_', ...
         'from_measured_touchdown_anchor'];
    manifest.bayesian_model_status = ...
        'not_invoked_by_pure_outward_baseline';
    manifest.fingerprint_interpretation = ...
        'none_pure_outward_has_no_conical_probe';
    manifest.fixed_orientation_only = true;
    manifest.trained_model_active_inference_scheduled = false;
    manifest.trained_model_deployment_status = ...
        'not_invoked_by_pure_outward_baseline';
    manifest.directservo_command_protocol = ...
        'not_used_by_pure_outward_baseline';
    manifest.directservo_measured_feedback = 'not_applicable';
    manifest.engineering_biases = { ...
        'manual_table_mark_and_task_local_near_hole_start', ...
        'measured_touchdown_XY_search_anchor_after_lateral_drift_gate', ...
        'hardware_easy_v2_printed_chamfers', ...
        'upright_start_world_rotated_force_baseline', ...
        'force_observed_1p00mm_pitch_phase_shifted_persistent_spiral', ...
        'physical_downward_progress_capture_only', ...
        'shared_insertion_and_terminal_verifier'};
    manifest.claim_boundary = { ...
        'Pure Outward has no conical fingerprint or learned inference.', ...
        ['Measured-touchdown-anchored geometric search with endpoint Bota ', ...
         'observations; not certified force control or a certified stop.'], ...
        ['Capture, insertion and terminal claims remain provisional physical ', ...
         'event-chain outcomes under the shared full-loop boundary.'], ...
        'Hard/stale/tracking/KST exception requests end without blind return.'};
elseif strcmp(policy.mode, ...
        'FULL_LOOP_PROPOSED_LEARNED_LOCAL_SPIRAL')
    result.control_classification = ...
        'active_learned_shortcut_plus_posterior_local_outward_residual_shared_loop';
    result.bayesian_role = ...
        'active_high_level_routing_never_capture_or_terminal_verification';
    manifest.shortcut_rule = ...
        ['active_real_model_CAD_posterior_nonzero_bounded_shortcut_', ...
         'weak_complete_fingerprints_remain_actionable'];
    manifest.grid_rule = ...
        'posterior_radius_local_outward_residual_about_measured_shortcut_endpoint';
    manifest.bayesian_model_status = ...
        'required_CAPPED_SHORTCUT_active_high_level_only';
elseif strcmp(policy.mode, ...
        'FULL_LOOP_BASELINE_IMPROVED_DIRECT_X3_LEARNED')
    result.control_classification = ...
        ['active_learned_strict_three_attempt_independent_conical_', ...
         'direct_retry_baseline'];
    result.bayesian_role = ...
        'fresh_active_direction_per_attempt_never_capture_or_terminal_verification';
    manifest.shortcut_rule = ...
        ['exactly_three_maximum_5p40mm_fresh_learned_direction_rays_', ...
         'independent_complete_reprobe_after_small_shifted_initial_pose_', ...
         'no_angle_fan_no_outer_repeat'];
    manifest.grid_rule = ...
        'none_direct_retry_no_fan_anchors_0_plus0p25_minus0p25mm_perpendicular';
    manifest.direct_retry_reference_semantics = ...
        ['conical_exploration_paper_failure_recovery_slightly_changes_the_', ...
         'initial_pose_and_repeats_the_full_probe_with_more_than_three_', ...
         'attempts_declared_failure'];
    manifest.direct_retry_engineering_parameters_not_from_reference = ...
        'M12_real_CAD_0p25mm_perpendicular_anchor_shift_and_20deg_local_sector';
    manifest.bayesian_model_status = ...
        'required_CAPPED_SHORTCUT_active_high_level_only';
    manifest.direct_reset_capture_rule = ...
        ['A physical downward-progress cue encountered during the low-force ', ...
         'shifted reset immediately hands off to insertion for safety.  It ', ...
         'is logged as RESET_CAPTURE, not credited as a completed direct ', ...
         'ray, and must be reported separately as a method-fairness confound.'];
end
end

function valid = isValidSha256(value)
valid = ischar(value) && ...
    ~isempty(regexp(value, '^[0-9a-f]{64}$', 'once'));
end

function plan = loadM12SamplingPlan(path, cfg)
assert(isfile(path), 'M12Demo:SamplingPlanMissing', ...
    'Fixture sampling plan is missing: %s', path);
record = jsondecode(fileread(path));
assert(double(record.schema_version) == 2 && ...
    strcmp(char(record.name), cfg.sampling.plan_name) && ...
    logical(record.claim_boundary.no_centre_attempt) && ...
    double(record.sampling_design.attempt_count) == 26 && ...
    logical(record.validation.actual_printed_cad_hashes_verified) && ...
    logical(record.validation.no_simulation_geometry_input), ...
    'M12Demo:SamplingPlanSchema', ...
    'The printed-CAD %s plan schema or no-centre contract changed.', ...
    cfg.sampling.size_upper);
pegSource = record.source_files.(cfg.sampling.plan_source_peg_key);
assert(strcmp(char(record.source_files.design_parameters.sha256), ...
        sha256File(cfg.files.printed_cad_design_parameters)) && ...
    strcmp(char(record.source_files.generated_cad_manifest.sha256), ...
        sha256File(cfg.files.printed_cad_manifest)) && ...
    strcmp(char(pegSource.sha256), ...
        sha256File(cfg.files.active_peg_step)) && ...
    strcmp(char(record.source_files.printed_hardware_easy_v2_socket_step.sha256), ...
        sha256File(cfg.files.printed_socket_step)), ...
    'M12Demo:SamplingPrintedCadHash', ...
    ['The %s plan is not bound to the installed-design CAD parameter, ', ...
     'manifest, peg STEP, and socket STEP artifacts.'], ...
    cfg.sampling.size_upper);
geometry = record.geometry_mm;
expectedGeometry = cfg.sampling.expected_geometry_mm;
actualGeometry = [double(geometry.head_outer_diameter), ...
    double(geometry.socket_mouth_af), ...
    double(geometry.socket_deep_wall_af), ...
    double(geometry.socket_chamfer_width), ...
    double(geometry.peg_tip_face_af), ...
    double(geometry.peg_shaft_af), ...
    double(geometry.peg_chamfer_axial_length), ...
    double(geometry.center_through_hole_diameter)];
assert(max(abs(actualGeometry - expectedGeometry)) < 1e-9, ...
    'M12Demo:SamplingPrintedCadGeometry', ...
    'The printed %s peg/socket contact dimensions changed.', ...
    cfg.sampling.size_upper);
points = record.points;
if iscell(points)
    points = [points{:}];
end
assert(numel(points) == 26 && double(record.attempt_count) == 26 && ...
    max(abs(double(record.fixture_centre_xy_mm(:).') - ...
        cfg.sampling.nominal_fixture_center_xy_mm)) < 1e-9, ...
    'M12Demo:SamplingPlanM12Count', ...
    'The %s plan must contain exactly 26 non-centre attempts.', ...
    cfg.sampling.size_upper);
partitions = strings(numel(points), 1);
sampleIds = strings(numel(points), 1);
contactStates = strings(numel(points), 1);
coneSweepSubtypes = strings(numel(points), 1);
for index = 1:numel(points)
    point = points(index);
    offset = double(point.local_offset_fixture_mm(:).');
    fixtureXY = double(point.fixture_xy_mm(:).');
    truth = double(point.true_direction_to_centre_fixture_unit(:).');
    assert(numel(offset) == 2 && all(isfinite(offset)) && ...
        norm(offset) > 1e-6 && numel(fixtureXY) == 2 && ...
        max(abs(fixtureXY - ...
            (cfg.sampling.nominal_fixture_center_xy_mm + offset))) < 1e-8 && ...
        numel(truth) == 2 && all(isfinite(truth)) && ...
        norm(truth + offset / norm(offset)) < 1e-8, ...
        'M12Demo:SamplingPlanDirection', ...
        '%s point %d violates the CAD centre-to-point direction contract.', ...
        cfg.sampling.size_upper, index);
    assert(double(point.attempt_index) == index && ...
        isfield(point, 'contact_state') && ...
        isfield(point, 'cone_sweep_subtype') && ...
        isfield(point, 'nominal_touchdown_geometry') && ...
        isfield(point, 'printed_frustum_cone_phase_diagnostics'), ...
        'M12Demo:SamplingPlanAttemptIndex', ...
        '%s point-array order or printed-CAD contact metadata changed.', ...
        cfg.sampling.size_upper);
    partitions(index) = string(point.partition);
    sampleIds(index) = string(point.sample_id);
    contactStates(index) = string(point.contact_state);
    coneSweepSubtypes(index) = string(point.cone_sweep_subtype);
    metrics = point.nominal_touchdown_geometry;
    outerFraction = double(metrics.outer_overhang_fraction);
    mouthFraction = double(metrics.mouth_overlap_fraction);
    supportFraction = double(metrics.head_top_support_fraction);
    assert(all(isfinite([outerFraction, mouthFraction, supportFraction])) && ...
        min([outerFraction, mouthFraction, supportFraction]) >= -1e-8 && ...
        max([outerFraction, mouthFraction, supportFraction]) <= 1.0 + 1e-8 && ...
        abs(outerFraction + mouthFraction + supportFraction - 1.0) < 2e-6, ...
        'M12Demo:SamplingPlanAreaFractions', ...
        '%s point %d has invalid CAD footprint area fractions.', ...
        cfg.sampling.size_upper, index);
    coneMetrics = point.printed_frustum_cone_phase_diagnostics;
    coneFractions = [ ...
        double(coneMetrics.maximum_mouth_overlap_fraction), ...
        double(coneMetrics.minimum_mouth_overlap_fraction), ...
        double(coneMetrics.mouth_overlap_phase_fraction), ...
        double(coneMetrics.outer_overhang_phase_fraction)];
    assert(double(coneMetrics.phase_bins) == 360 && ...
        all(isfinite(coneFractions)) && min(coneFractions) >= -1e-8 && ...
        max(coneFractions) <= 1.0 + 1e-8 && ...
        isfinite(double(coneMetrics.minimum_outer_clearance_mm)) && ...
        double(coneMetrics.minimum_projected_area_mm2) > 0.0 && ...
        double(coneMetrics.maximum_projected_area_mm2) >= ...
            double(coneMetrics.minimum_projected_area_mm2), ...
        'M12Demo:SamplingPlanConeProjection', ...
        ['%s point %d has invalid 360-phase printed tip-to-shaft ', ...
         'frustum diagnostics.'], cfg.sampling.size_upper, index);
    if strcmp(char(point.cone_sweep_subtype), ...
            'full_frustum_mouth_clear')
        assert(double(coneMetrics.maximum_mouth_overlap_fraction) <= 1e-6, ...
            'M12Demo:SamplingPlanFullFrustumClear', ...
            ['%s point %d is labelled full-frustum clear but a sampled ', ...
             '15-degree cone phase still overlaps the mouth.'], ...
            cfg.sampling.size_upper, index);
    end
    if strcmp(char(point.partition), 'clean_candidate')
        if strcmp(char(point.contact_state), 'supported_search')
            stateValid = outerFraction <= 1e-5;
        elseif strcmp(char(point.contact_state), 'double_overhang')
            stateValid = outerFraction > 0.10 && mouthFraction > 0.05 && ...
                supportFraction > 0.20;
        elseif strcmp(char(point.contact_state), ...
                'outer_partial_support')
            stateValid = outerFraction > 0.50 && mouthFraction <= 1e-5 && ...
                supportFraction > 0.20;
        else
            stateValid = false;
        end
        assert(stateValid, 'M12Demo:SamplingPlanContactState', ...
            ['Clean %s point %d does not satisfy its hash-bound printed-', ...
             'CAD touchdown contact state.'], cfg.sampling.size_upper, index);
    end
end
assert(numel(unique(sampleIds)) == 26 && ...
    sum(partitions == "clean_candidate") == 16 && ...
    sum(partitions == "holdout") == 4 && ...
    sum(partitions == "quarantine") == 4 && ...
    sum(partitions == "sentinel") == 2, ...
    'M12Demo:SamplingPlanPartition', ...
    '%s clean/holdout/quarantine/sentinel partition counts changed.', ...
    cfg.sampling.size_upper);
assert(sum(partitions == "clean_candidate" & ...
        contactStates == "supported_search") == 6 && ...
    sum(partitions == "clean_candidate" & ...
        contactStates == "double_overhang") == 6 && ...
    sum(partitions == "clean_candidate" & ...
        contactStates == "outer_partial_support") == 4 && ...
    sum(partitions == "clean_candidate" & ...
        coneSweepSubtypes == "landing_mouth_clear_cone_transition") == 2 && ...
    sum(partitions == "clean_candidate" & ...
        coneSweepSubtypes == "full_frustum_mouth_clear") == 2, ...
    'M12Demo:SamplingPlanStateCoverage', ...
    ['The 16 clean points must cover supported/double/outer-partial as ', ...
     '6/6/4 printed-CAD touchdown states, including two landing-only and ', ...
     'two complete-frustum-clear outer-partial points.']);
executionAttemptIndices = double(record.execution.attempt_indices(:).');
assert(numel(executionAttemptIndices) == 26 && ...
    isequal(sort(executionAttemptIndices), 1:26), ...
    'M12Demo:SamplingExecutionOrder', ...
    'The sampling execution order must be a permutation of attempts 1:26.');
executionPoints = points(executionAttemptIndices);
routeOffsets = zeros(numel(executionPoints), 2);
for executionIndex = 1:numel(executionPoints)
    executionPoints(executionIndex).source_attempt_index = ...
        double(executionPoints(executionIndex).attempt_index);
    executionPoints(executionIndex).execution_index = executionIndex;
    routeOffsets(executionIndex, :) = double( ...
        executionPoints(executionIndex).local_offset_fixture_mm(:).');
    sourceIndex = executionAttemptIndices(executionIndex);
    points(sourceIndex).source_attempt_index = ...
        double(points(sourceIndex).attempt_index);
    points(sourceIndex).execution_index = executionIndex;
end
closedRoute = [[0.0, 0.0]; routeOffsets; [0.0, 0.0]];
closedRouteDistanceMm = sum(vecnorm(diff(closedRoute, 1, 1), 2, 2));
assert(abs(closedRouteDistanceMm - ...
        double(record.execution.closed_route_distance_mm)) < 0.02 && ...
    closedRouteDistanceMm < ...
        double(record.execution.source_order_closed_route_distance_mm), ...
    'M12Demo:SamplingRouteDistance', ...
    'The generated closed %s sampling route changed (%.4f mm).', ...
    cfg.sampling.size_upper, closedRouteDistanceMm);
sentinelExecutionIndices = find(strcmp( ...
    {executionPoints.partition}, 'sentinel'));
sentinelExecutionIndices = sentinelExecutionIndices(:).';
assert(numel(sentinelExecutionIndices) == 2, ...
    'M12Demo:SamplingSentinelCount', ...
    'The generated route must contain exactly two sentinels.');
executionPosition = zeros(1, 26);
executionPosition(executionAttemptIndices) = 1:26;
for sentinelIndex = sentinelExecutionIndices
    sentinel = executionPoints(sentinelIndex);
    sourceIndex = find(sampleIds == string(sentinel.duplicate_of), 1);
    assert(~isempty(sourceIndex) && ...
        norm(double(sentinel.local_offset_fixture_mm(:).') - ...
            double(points(sourceIndex).local_offset_fixture_mm(:).')) < 1e-8 && ...
        abs(executionPosition(double(sentinel.attempt_index)) - ...
            executionPosition(sourceIndex)) >= 10, ...
        'M12Demo:SamplingSentinelSpacing', ...
        'Each sentinel must exactly repeat its source after >=10 attempts.');
end
requiredLateralExcursionMm = double( ...
    record.motion_contract.required_sampling_only_lateral_excursion_mm);
maximumPlannedRadiusMm = max(vecnorm(routeOffsets, 2, 2));
assert(requiredLateralExcursionMm >= maximumPlannedRadiusMm + ...
        double(record.motion_contract.measured_landing_tolerance_mm) + ...
        double(record.motion_contract.air_tracking_tolerance_mm) && ...
    requiredLateralExcursionMm < 15.0, ...
    'M12Demo:SamplingLateralEnvelope', ...
    'The generated %s sampling-only lateral envelope is invalid.', ...
    cfg.sampling.size_upper);
plan = struct( ...
    'schema_version', 2, ...
    'name', char(record.name), ...
    'source_path', path, ...
    'source_sha256', sha256File(path), ...
    'coordinate_authority', ...
        'PREREGISTERED_LOCAL_OFFSETS_AWAITING_RUN_LOCAL_START_CENTER', ...
    'nominal_fixture_center_xy_mm', ...
        double(record.fixture_centre_xy_mm(:).'), ...
    'fixture_center_xy_mm', ...
        double(record.fixture_centre_xy_mm(:).'), ...
    'fixture_center_xyz_mm', ...
        [double(record.fixture_centre_xy_mm(:).'), 0.0], ...
    'geometry_mm', geometry, ...
    'coordinate_contract', record.coordinate_contract, ...
    'contact_state_definition', record.contact_state_definition, ...
    'cone_command_geometry', record.cone_command_geometry, ...
    'sampling_design', record.sampling_design, ...
    'plan_validation', record.validation, ...
    'source_files', record.source_files, ...
    'points', points, ...
    'execution_points', executionPoints, ...
    'execution_attempt_indices', executionAttemptIndices, ...
    'route_indices', executionAttemptIndices, ...
    'route_fixture_xy_mm', closedRoute, ...
    'closed_route_distance_mm', closedRouteDistanceMm, ...
    'source_order_closed_route_distance_mm', ...
        double(record.execution.source_order_closed_route_distance_mm), ...
    'required_sampling_only_lateral_excursion_mm', ...
        requiredLateralExcursionMm, ...
    'maximum_planned_radius_mm', maximumPlannedRadiusMm, ...
    'attempt_count', numel(points), ...
    'claim_boundary', record.claim_boundary);
end

function plan = rebaseM12SamplingPlanToRunLocalStart(plan, startPose, cfg)
assert(numel(startPose) == 6 && all(isfinite(startPose)), ...
    'M12Demo:SamplingRunLocalStart', ...
    'The confirmed run-local start pose is unavailable.');
runLocalCenter = [0.0, 0.0, 0.0];
for index = 1:numel(plan.points)
    offset = double( ...
        plan.points(index).local_offset_fixture_mm(:).');
    nominalXY = double(plan.points(index).fixture_xy_mm(:).');
    plan.points(index).nominal_fixture_xy_mm = nominalXY;
    plan.points(index).fixture_xy_mm = offset;
    plan.points(index).fixture_point_mm = [offset, 0.0];
    plan.points(index).as_built_center_shift_xy_mm = [NaN, NaN];
    plan.points(index).run_local_center_world_xy_mm = startPose(1:2);
    plan.points(index).world_target_xy_mm = startPose(1:2) + offset;
end
plan.execution_points = plan.points(plan.execution_attempt_indices);
routeOffsets = zeros(numel(plan.execution_points), 2);
for executionIndex = 1:numel(plan.execution_points)
    plan.execution_points(executionIndex).source_attempt_index = ...
        double(plan.execution_points(executionIndex).attempt_index);
    plan.execution_points(executionIndex).execution_index = executionIndex;
    routeOffsets(executionIndex, :) = double( ...
        plan.execution_points(executionIndex).local_offset_fixture_mm(:).');
end
plan.route_indices = plan.execution_attempt_indices;
plan.route_fixture_xy_mm = [[0.0, 0.0]; routeOffsets; [0.0, 0.0]];
plan.fixture_center_xy_mm = runLocalCenter(1:2);
plan.fixture_center_xyz_mm = runLocalCenter;
plan.run_local_center_world_xy_mm = startPose(1:2);
plan.run_local_start_pose_mm_rad = startPose;
plan.coordinate_authority = cfg.sampling.coordinate_authority;
plan.socket_center_standard_uncertainty_mm = NaN;
plan.fixture_top_plane_fit_rms_mm = NaN;
end

function resume = loadM12SamplingResumeParent( ...
        parentRunDir, realDir, plan, cfg)
% Validate an immutable parent campaign before any KST connection is opened.
% This loader intentionally runs before the main execution try-block resolves
% the run-local compatibility frame and collection-only cone qualification.
% Build equivalent read-only values locally instead of depending on later
% mutable initialization order.
resumeFrame = makeOldKernelCompatibilityFrame( ...
    cfg.files.fixture_frame_commissioning, cfg);
resumeCfg = cfg;
if ~isfield(resumeCfg.sampling, 'conical_phase_pose_tracking')
    resumeCfg.sampling.conical_phase_pose_tracking = struct( ...
        'status', 'COLLECTION_ONLY_PRE_POST_MEASURED_POSE', ...
        'qualified_for_training_candidates', false, ...
        'rule', ['Command phase and raw wrench are recorded in full; ', ...
                 'offline QC decides later and no runtime model is loaded.']);
end
dataRoot = canonicalPath(fullfile(realDir, 'data'));
parentRunDir = canonicalPath(parentRunDir);
assert(isfolder(parentRunDir) && ...
    (strcmp(parentRunDir, dataRoot) || startsWith( ...
        parentRunDir, [dataRoot, filesep])), ...
    'M12Demo:SamplingResumeParentScope', ...
    'Resume parent must be an existing child of %s.', dataRoot);
summaryPath = fullfile(parentRunDir, 'sampling_campaign.json');
assert(isfile(summaryPath), ...
    'M12Demo:SamplingResumeParentCheckpoint', ...
    'Parent sampling checkpoint is missing: %s', summaryPath);
parent = jsondecode(fileread(summaryPath));
parentStatusEligible = isfield(parent, 'status') && ...
    (contains(char(parent.status), 'ABORTED') || ...
     strcmp(char(parent.status), 'RUNNING') || ...
     strcmp(char(parent.status), ...
        'RETURNED_TO_INITIAL_POSE_BUT_CAMPAIGN_FINALIZATION_FAILED'));
assert(parentStatusEligible && ...
    isfield(parent, 'campaign') && ...
    strcmp(char(parent.campaign), cfg.sampling.campaign_id) && ...
    isfield(parent, 'sampling_plan_sha256') && ...
    strcmp(char(parent.sampling_plan_sha256), plan.source_sha256), ...
    'M12Demo:SamplingResumeParentStatus', ...
    ['Resume requires an aborted or atomically checkpointed RUNNING parent ', ...
     'bound to the current 26-point sampling plan.  Command-owner checks ', ...
     'still run before any KST connection.']);
[~, parentDirectoryName] = fileparts(parentRunDir);
assert(isfield(parent, 'run_session_id') && ...
    strcmp(parentDirectoryName, char(parent.run_session_id)) && ...
    isfield(parent, 'dataset_group_key') && ...
    ~isempty(char(parent.dataset_group_key)) && ...
    isfield(parent, 'initial_air_pose_mm_rad') && ...
    numel(parent.initial_air_pose_mm_rad) == 6 && ...
    all(isfinite(double(parent.initial_air_pose_mm_rad(:)))) && ...
    isfield(parent, 'run_local_hole_center_world_xy_mm') && ...
    numel(parent.run_local_hole_center_world_xy_mm) == 2 && ...
    all(isfinite(double( ...
        parent.run_local_hole_center_world_xy_mm(:)))), ...
    'M12Demo:SamplingResumeParentIdentity', ...
    ['Parent directory/session identity, dataset group, original pose, ', ...
     'or run-local centre is malformed.']);
assert(isfield(parent, 'execution_attempt_indices') && ...
    isequal(double(parent.execution_attempt_indices(:).'), ...
        plan.execution_attempt_indices), ...
    'M12Demo:SamplingResumeExecutionOrder', ...
    'Parent execution order differs from the current registered plan.');
resumeCenterPose = double( ...
    reshape(parent.initial_air_pose_mm_rad, 1, 6));
resumeCenterPose(1:2) = double(reshape( ...
    parent.run_local_hole_center_world_xy_mm, 1, 2));
resumePlan = rebaseM12SamplingPlanToRunLocalStart( ...
    plan, resumeCenterPose, resumeCfg);
activePegHashMatches = strcmp(cfg.sampling.size_lower, 'm12');
if isfield(parent, 'cad_and_configuration_hashes') && ...
        isfield(parent.cad_and_configuration_hashes, ...
            'active_peg_step_sha256')
    activePegHashMatches = strcmp(char( ...
        parent.cad_and_configuration_hashes.active_peg_step_sha256), ...
        sha256File(cfg.files.active_peg_step));
end
assert(isfield(parent, 'cad_and_configuration_hashes') && ...
    strcmp(char(parent.cad_and_configuration_hashes. ...
        fixture_sampling_plan_sha256), plan.source_sha256) && ...
    strcmp(char(parent.cad_and_configuration_hashes.tooling_sha256), ...
        sha256File(cfg.files.tooling)) && ...
    strcmp(char(parent.cad_and_configuration_hashes. ...
        pink_m12_step_sha256), sha256File(cfg.files.pink_m12_step)) && ...
    strcmp(char(parent.cad_and_configuration_hashes. ...
        printed_socket_step_sha256), ...
        sha256File(cfg.files.printed_socket_step)) && ...
    strcmp(char(parent.cad_and_configuration_hashes. ...
        printed_cad_design_parameters_sha256), ...
        sha256File(cfg.files.printed_cad_design_parameters)) && ...
    strcmp(char(parent.cad_and_configuration_hashes. ...
        printed_cad_manifest_sha256), ...
        sha256File(cfg.files.printed_cad_manifest)) && ...
    activePegHashMatches, ...
    'M12Demo:SamplingResumeCadHash', ...
    'Parent campaign CAD/configuration hashes do not match this checkout.');
assert(strcmp(char(parent.cad_and_configuration_hashes. ...
        fixture_frame_record_sha256), resumeFrame.record_sha256) && ...
    strcmp(char(parent.physical_tool_instance_id), ...
        resumeFrame.physical_tool_instance_id) && ...
    strcmp(char(parent.fixture_instance_id), ...
        resumeFrame.fixture_instance_id) && ...
    strcmp(char(parent.installation_session_id), ...
        resumeFrame.installation_session_id), ...
    'M12Demo:SamplingResumePhysicalInstance', ...
    ['Parent fixture frame, tool, fixture, or installation identity does ', ...
     'not match the current immutable commissioning records.']);

rawAttempts = parent.attempts;
if iscell(rawAttempts)
    rawAttempts = [rawAttempts{:}];
end
assert(isstruct(rawAttempts) && ~isempty(rawAttempts), ...
    'M12Demo:SamplingResumeAttemptsMissing', ...
    'Parent campaign has no persisted attempts to resume.');
executionIndices = double([rawAttempts.execution_index]);
assert(all(isfinite(executionIndices)) && ...
    all(executionIndices == round(executionIndices)) && ...
    all(executionIndices >= 1 & executionIndices <= plan.attempt_count) && ...
    numel(unique(executionIndices)) == numel(executionIndices), ...
    'M12Demo:SamplingResumeAttemptIndices', ...
    'Parent attempts must have unique execution indices in 1:26.');
attemptOriginRunSessionIds = cell(numel(rawAttempts), 1);
for rawIndex = 1:numel(rawAttempts)
    executionIndex = executionIndices(rawIndex);
    expectedPoint = plan.execution_points(executionIndex);
    attemptOriginRunSessionIds{rawIndex} = ...
        samplingResumeAttemptOriginRunSessionId( ...
            rawAttempts(rawIndex), char(parent.run_session_id));
    assert(strcmp(char(rawAttempts(rawIndex).sample_id), ...
            char(expectedPoint.sample_id)) && ...
        double(rawAttempts(rawIndex).source_attempt_index) == ...
            double(expectedPoint.attempt_index) && ...
        strcmp(char(rawAttempts(rawIndex).dataset_group_key), ...
            char(parent.dataset_group_key)) && ...
        strcmp(char(rawAttempts(rawIndex).physical_tool_instance_id), ...
            resumeFrame.physical_tool_instance_id) && ...
        strcmp(char(rawAttempts(rawIndex).fixture_instance_id), ...
            resumeFrame.fixture_instance_id), ...
        'M12Demo:SamplingResumeAttemptIdentity', ...
        ['Parent execution %d sample/source, dataset, tool, or fixture ', ...
         'identity differs from the current hash-bound route.'], ...
        executionIndex);
end

coneMask = arrayfun(@(attempt) ...
    logical(attempt.cone_completed), rawAttempts);
completedConeIndices = sort(executionIndices(coneMask));
assert(~isempty(completedConeIndices), ...
    'M12Demo:SamplingResumeNoCompletedCone', ...
    'Parent contains no complete cone evidence to preserve.');
completeEvidenceRawIndices = reshape(find(coneMask), 1, []);
for rawIndex = completeEvidenceRawIndices
    attempt = rawAttempts(rawIndex);
    assert(logical(attempt.cone_completed) && ...
        double(attempt.phase_coverage_fraction) >= ...
            cfg.sampling.minimum_phase_coverage_fraction, ...
        'M12Demo:SamplingResumeConeQuality', ...
        ['Execution %d is marked cone-complete without a complete physical ', ...
         'schedule and registered phase coverage. Direction/routing quality ', ...
         'is deliberately not a replay gate.'], ...
        double(attempt.execution_index));
    validateSamplingResumeEvidencePath(dataRoot, ...
        attemptOriginRunSessionIds{rawIndex}, ...
        char(attempt.mat_path), ...
        char(attempt.file_hashes.attempt_mat_sha256), ...
        'attempt MAT');
    validateSamplingResumeEvidencePath(dataRoot, ...
        attemptOriginRunSessionIds{rawIndex}, ...
        char(attempt.baseline_csv_path), ...
        char(attempt.file_hashes.baseline_csv_sha256), ...
        'point baseline CSV');
    validateSamplingResumeEvidencePath(dataRoot, ...
        attemptOriginRunSessionIds{rawIndex}, ...
        char(attempt.contact_settle_csv_path), ...
        char(attempt.file_hashes.contact_settle_csv_sha256), ...
        'contact observation CSV');
    validateSamplingResumeEvidencePath(dataRoot, ...
        attemptOriginRunSessionIds{rawIndex}, ...
        char(attempt.cone_csv_path), ...
        char(attempt.file_hashes.cone_csv_sha256), ...
        'cone CSV');
    validateSamplingResumeCompleteConeMat( ...
        char(attempt.mat_path), attempt, cfg);
end
pendingExecutionIndices = setdiff( ...
    1:plan.attempt_count, completedConeIndices, 'stable');

normalizedAttempts = normalizeSamplingResumeAttempts( ...
    rawAttempts(coneMask), resumePlan, resumeCfg, ...
    char(parent.run_session_id));
completeRawIndices = find(coneMask);
[~, latestCompleteOrder] = max( ...
    executionIndices(completeRawIndices));
latestCompleteRawIndex = completeRawIndices(latestCompleteOrder);
baselineRecord = load(char( ...
    rawAttempts(latestCompleteRawIndex).mat_path), 'pointBaseline');
assert(isfield(baselineRecord, 'pointBaseline') && ...
    isfield(baselineRecord.pointBaseline, 'force_n') && ...
    isfield(baselineRecord.pointBaseline, 'torque_nm'), ...
    'M12Demo:SamplingResumeReferenceBaseline', ...
    'Latest completed parent point has no point-local baseline in MAT.');
referenceForce = double( ...
    baselineRecord.pointBaseline.force_n(:).');
referenceTorque = double( ...
    baselineRecord.pointBaseline.torque_nm(:).');
assert(numel(referenceForce) == 3 && ...
    numel(referenceTorque) == 3 && ...
    all(isfinite([referenceForce, referenceTorque])), ...
    'M12Demo:SamplingResumeReferenceBaseline', ...
    'Parent point-local baseline is not a finite six-axis reference.');

if isfield(parent, 'campaign_lineage_id') && ...
        ~isempty(parent.campaign_lineage_id)
    campaignLineageId = char(parent.campaign_lineage_id);
else
    campaignLineageId = char(parent.run_session_id);
end
resumeGeneration = 1;
if isfield(parent, 'resume_generation') && ...
        isscalar(parent.resume_generation) && ...
        isfinite(double(parent.resume_generation))
    resumeGeneration = double(parent.resume_generation) + 1;
end
resume = struct( ...
    'enabled', true, ...
    'parent_run_dir', parentRunDir, ...
    'parent_checkpoint_path', summaryPath, ...
    'parent_checkpoint_sha256', sha256File(summaryPath), ...
    'parent_run_session_id', char(parent.run_session_id), ...
    'campaign_lineage_id', campaignLineageId, ...
    'resume_generation', resumeGeneration, ...
    'dataset_group_key', char(parent.dataset_group_key), ...
    'run_local_hole_center_world_xy_mm', double( ...
        parent.run_local_hole_center_world_xy_mm(:).'), ...
    'campaign_home_pose_mm_rad', double( ...
        parent.initial_air_pose_mm_rad(:).'), ...
    'reference_air_baseline_force_n', referenceForce, ...
    'reference_air_baseline_torque_nm', referenceTorque, ...
    'reference_air_baseline_execution_index', double( ...
        rawAttempts(latestCompleteRawIndex).execution_index), ...
    'reference_air_baseline_sample_id', char( ...
        rawAttempts(latestCompleteRawIndex).sample_id), ...
    'completed_cone_indices', completedConeIndices, ...
    'pending_execution_indices', pendingExecutionIndices, ...
    'recovery_only_resume', isempty(pendingExecutionIndices), ...
    'inherited_attempts', normalizedAttempts, ...
    'parent_status', char(parent.status));
end

function validateSamplingResumeCompleteConeMat(path, attempt, cfg)
record = load(path, 'cone');
assert(isfield(record, 'cone') && isstruct(record.cone) && ...
    isscalar(record.cone), ...
    'M12Demo:SamplingResumeConeEvidence', ...
    'Execution %d attempt MAT has no scalar cone evidence.', ...
    double(attempt.execution_index));
cone = record.cone;
physicalComplete = isfield(cone, 'schedule_completed') && ...
    logical(cone.schedule_completed);
if isfield(cone, 'physical_schedule_completed')
    physicalComplete = physicalComplete && ...
        logical(cone.physical_schedule_completed);
end
requiredFields = {'schedule_fraction', 'stage', 'raw_force_n', ...
    'raw_torque_nm', 'source_stamp_s', 'all_command_pose_mm_rad'};
for fieldIndex = 1:numel(requiredFields)
    assert(isfield(cone, requiredFields{fieldIndex}), ...
        'M12Demo:SamplingResumeConeEvidence', ...
        'Execution %d cone evidence lacks %s.', ...
        double(attempt.execution_index), requiredFields{fieldIndex});
end
sampleCount = numel(cone.schedule_fraction);
assert(physicalComplete && sampleCount > 0 && ...
    numel(cone.stage) == sampleCount && ...
    size(cone.raw_force_n, 1) == sampleCount && ...
    size(cone.raw_torque_nm, 1) == sampleCount && ...
    numel(cone.source_stamp_s) == sampleCount && ...
    size(cone.all_command_pose_mm_rad, 1) == sampleCount && ...
    all(isfinite(double(cone.source_stamp_s(:)))) && ...
    all(diff(double(cone.source_stamp_s(:))) > 0.0) && ...
    double(attempt.phase_coverage_fraction) >= ...
        cfg.sampling.minimum_phase_coverage_fraction, ...
    'M12Demo:SamplingResumeConeEvidence', ...
    ['Execution %d cone MAT is hash-valid but its physical schedule, ', ...
     'phase coverage, sample cardinality, or source timestamps are incomplete.'], ...
    double(attempt.execution_index));
end

function originRunSessionId = samplingResumeAttemptOriginRunSessionId( ...
        rawAttempt, immediateParentRunSessionId)
originRunSessionId = scalarTextOrEmpty( ...
    immediateParentRunSessionId, 'immediate parent run session ID');
if isfield(rawAttempt, 'origin_run_session_id')
    recordedOrigin = scalarTextOrEmpty( ...
        rawAttempt.origin_run_session_id, ...
        'attempt origin run session ID');
    if ~isempty(recordedOrigin)
        originRunSessionId = recordedOrigin;
    end
end
assert(~isempty(originRunSessionId), ...
    'M12Demo:SamplingResumeEvidenceOrigin', ...
    'Every inherited attempt must resolve to one nonempty origin run.');
end

function validateSamplingResumeEvidencePath( ...
        dataRoot, originRunSessionId, evidencePath, expectedHash, label)
dataRoot = canonicalPath(dataRoot);
originRunSessionId = scalarTextOrEmpty( ...
    originRunSessionId, 'attempt origin run session ID');
parentRunDir = canonicalPath(fullfile(dataRoot, originRunSessionId));
[~, originDirectoryName] = fileparts(parentRunDir);
evidencePath = canonicalPath(evidencePath);
assert(~isempty(originRunSessionId) && ...
    isfolder(parentRunDir) && ...
    startsWith(parentRunDir, [dataRoot, filesep]) && ...
    strcmp(originDirectoryName, originRunSessionId) && ...
    startsWith(evidencePath, [parentRunDir, filesep]) && ...
    isfile(evidencePath) && isValidSha256(expectedHash) && ...
    strcmp(sha256File(evidencePath), expectedHash), ...
    'M12Demo:SamplingResumeEvidenceHash', ...
    ['%s is missing, outside its immutable origin run %s, or ', ...
     'hash-invalid: %s'], label, originRunSessionId, evidencePath);
end

function attempts = normalizeSamplingResumeAttempts( ...
        rawAttempts, plan, cfg, parentRunSessionId)
attempts = repmat( ...
    makeSamplingAttempt(plan.execution_points(1), cfg), 0, 1);
for rawIndex = 1:numel(rawAttempts)
    rawAttempt = rawAttempts(rawIndex);
    executionIndex = double(rawAttempt.execution_index);
    attempt = makeSamplingAttempt( ...
        plan.execution_points(executionIndex), cfg);
    rawFields = fieldnames(rawAttempt);
    for fieldIndex = 1:numel(rawFields)
        fieldName = rawFields{fieldIndex};
        if isfield(attempt, fieldName)
            attempt.(fieldName) = rawAttempt.(fieldName);
        end
    end
    attempt.origin_run_session_id = ...
        samplingResumeAttemptOriginRunSessionId( ...
            rawAttempt, parentRunSessionId);
    attempt.inherited_from_parent_run = true;
    immutableQualityStatus = '';
    if isfield(rawAttempt, 'immutable_parent_data_quality_status')
        immutableQualityStatus = scalarTextOrEmpty( ...
            rawAttempt.immutable_parent_data_quality_status, ...
            'immutable parent data-quality status');
    end
    if isempty(immutableQualityStatus)
        immutableQualityStatus = scalarTextOrEmpty( ...
            rawAttempt.status, 'parent attempt status');
    end
    attempt.immutable_parent_data_quality_status = ...
        immutableQualityStatus;
    if isempty(scalarTextOrEmpty( ...
            attempt.resume_status_overlay_reason, ...
            'resume status overlay reason'))
        attempt.resume_status_overlay_reason = ...
            'PARENT_EVIDENCE_IMMUTABLE_CHILD_CAMPAIGN_OVERLAY';
    end
    if isempty(scalarTextOrEmpty( ...
            attempt.data_quality_status, 'attempt data-quality status'))
        attempt.data_quality_status = attempt.status;
    end
    if isempty(scalarTextOrEmpty( ...
            attempt.operational_error, 'attempt operational error'))
        attempt.operational_error = attempt.error;
    end
    safeRetractCompleted = logical(attempt.safe_retract_completed);
    recoveryClearVerified = logical(attempt.recovery_clear_verified);
    motionLifecycleClosed = logical(attempt.motion_lifecycle_closed);
    assert(isscalar(safeRetractCompleted) && ...
        isscalar(recoveryClearVerified) && ...
        isscalar(motionLifecycleClosed) && ...
        (~motionLifecycleClosed || safeRetractCompleted || ...
            recoveryClearVerified) && ...
        (~recoveryClearVerified || motionLifecycleClosed), ...
        'M12Demo:SamplingResumeRecoveryOverlay', ...
        ['Inherited execution %d has an inconsistent retract/recovery ', ...
         'motion-lifecycle overlay.'], executionIndex);
    if recoveryClearVerified
        recoveryRunSessionId = scalarTextOrEmpty( ...
            attempt.recovery_run_session_id, ...
            'recovery run session ID');
        recoveryVerifiedLocal = scalarTextOrEmpty( ...
            attempt.recovery_clear_verified_local, ...
            'recovery clear verification timestamp');
        assert(~isempty(recoveryRunSessionId) && ...
            ~isempty(recoveryVerifiedLocal) && ...
            isscalar(attempt.recovery_clear_max_force_n) && ...
            isfinite(double(attempt.recovery_clear_max_force_n)) && ...
            double(attempt.recovery_clear_max_force_n) >= 0.0 && ...
            isscalar(attempt.recovery_clear_max_torque_nm) && ...
            isfinite(double(attempt.recovery_clear_max_torque_nm)) && ...
            double(attempt.recovery_clear_max_torque_nm) >= 0.0, ...
            'M12Demo:SamplingResumeRecoveryProvenance', ...
            ['Inherited execution %d recovery-clear closure lacks its ', ...
             'run, timestamp, or finite wrench provenance.'], executionIndex);
    end
    attempt.safe_retract_completed = safeRetractCompleted;
    attempt.recovery_clear_verified = recoveryClearVerified;
    attempt.motion_lifecycle_closed = safeRetractCompleted || ...
        (recoveryClearVerified && motionLifecycleClosed);
    if attempt.cone_completed && ...
            ~attempt.safe_retract_completed && ...
            startsWith(char(attempt.quarantine_reason), 'ABORT_AFTER_')
        attempt.effective_partition = attempt.requested_partition;
        attempt.quarantine_reason = '';
        attempt = classifyCompletedSamplingAttempt(attempt, cfg);
        attempt.operational_status = ...
            'CONE_COMPLETE_RETRACT_UNVERIFIED_PARENT';
        attempt.campaign_must_abort = false;
        attempt.error = '';
    elseif attempt.safe_retract_completed
        attempt.operational_status = ...
            'POINT_COMMITTED_ORIGINAL_RETRACT_VERIFIED';
        attempt.campaign_must_abort = false;
        attempt.error = '';
    end
    attempts(end + 1, 1) = attempt; %#ok<AGROW>
end
[~, order] = sort([attempts.execution_index]);
attempts = reshape(attempts(order), [], 1);
end

function [pose, joints, stationarity] = confirmSamplingStart( ...
        iiwa, cfg, paths, pose, joints, stationarity, samplingPlan) %#ok<INUSD>
worldFromTcp = kukaAbcToRotm(pose(4:6));
pegAxisAlignmentDeg = rad2deg(acos(min(max(dot( ...
    worldFromTcp(:, 3), -cfg.frame.world_from_fixture_rotation(:, 3)), ...
    -1.0), 1.0)));
fprintf('\n%s conical commissioning campaign: 26 planned points.\n', ...
    cfg.sampling.size_upper);
fprintf(['The confirmed TCP XY will become this run''s %s hole centre; ', ...
    'fixture X/Y are assumed aligned with KUKA WORLD X/Y.\n'], ...
    cfg.sampling.size_upper);
fprintf(['The run will first lift %.1f mm and may extend to %.1f mm only ', ...
    'when the two wrench-clear checks do not pass.\n'], ...
    cfg.sampling.initial_lift_mm, cfg.sampling.maximum_retract_mm);
fprintf([ ...
    'Sampling entrypoint invocation is the motion authorization; no typed ', ...
    'arming phrase is required. Continuing automatically after the fresh ', ...
    'stationary start capture.\n']);
fprintf('Current +TCP-Z to WORLD -Z diagnostic error: %.3f deg.\n', ...
    pegAxisAlignmentDeg);
stationarity.run_local_m12_center_world_xy_mm = pose(1:2);
stationarity.run_local_socket_center_world_xy_mm = pose(1:2);
stationarity.run_local_start_z_mm = pose(3);
stationarity.coordinate_authority = cfg.sampling.coordinate_authority;
stationarity.motion_authorization_source = ...
    cfg.sampling.motion_authorization_source;
stationarity.interactive_confirmation_required = false;
stationarity.entrypoint_start_contract_assumed = true;
stationarity.peg_axis_to_negative_fixture_z_error_deg = ...
    pegAxisAlignmentDeg;
logEvent(paths.events, ...
    'SAMPLING_ENTRYPOINT_AUTHORIZED_AUTOMATIC_CONTINUE_NO_MOTION', ...
    sprintf(['confirmed run-local %s centre WORLD XY [%+.3f %+.3f] mm; ', ...
    'start Z %.3f mm; +TCP-Z to WORLD -Z diagnostic error %.3f deg; ', ...
    'dedicated entrypoint invocation authorized motion; no typed phrase'], ...
    cfg.sampling.size_upper, pose(1:3), pegAxisAlignmentDeg));
end

function [pose, joints, stationarity] = confirmSamplingResumeStart( ...
        iiwa, cfg, paths, pose, joints, stationarity, ...
        samplingPlan, samplingResume) %#ok<INUSD>
% Bind an explicit child run without issuing motion or replaying a cone.
parentHome = double(reshape( ...
    samplingResume.campaign_home_pose_mm_rad, 1, []));
parentCenter = double(reshape( ...
    samplingResume.run_local_hole_center_world_xy_mm, 1, []));
assert(numel(parentHome) == 6 && all(isfinite(parentHome)) && ...
    numel(parentCenter) == 2 && all(isfinite(parentCenter)) && ...
    samplingPlan.attempt_count == 26, ...
    'M12Demo:SamplingResumeStartEvidence', ...
    'Resume parent centre/home evidence is incomplete.');
orientationDifferenceDeg = rad2deg(rotationDistance( ...
    kukaAbcToRotm(pose(4:6)), kukaAbcToRotm(parentHome(4:6))));
zOffsetFromParentHomeMm = pose(3) - parentHome(3);
startRadiusFromParentCenterMm = norm(pose(1:2) - parentCenter);
assert(orientationDifferenceDeg <= ...
        cfg.sampling.resume_maximum_orientation_difference_deg && ...
    startRadiusFromParentCenterMm <= ...
        samplingPlan.required_sampling_only_lateral_excursion_mm + ...
            cfg.sampling.air_tracking_tolerance_mm && ...
    zOffsetFromParentHomeMm >= ...
        -cfg.sampling.resume_maximum_start_below_home_mm && ...
    zOffsetFromParentHomeMm <= ...
        cfg.sampling.maximum_retract_mm + ...
            cfg.sampling.air_tracking_tolerance_mm, ...
    'M12Demo:SamplingResumeStartOutsideEnvelope', ...
    ['Resume start is %.3f mm from the parent centre and differs from ', ...
     'parent upright/home by %.3f deg and %+.3f mm Z; allowed radius ', ...
     '%.3f mm, %.3f deg, and Z [%+.3f, %+.3f] mm.'], ...
    startRadiusFromParentCenterMm, orientationDifferenceDeg, ...
    zOffsetFromParentHomeMm, ...
    samplingPlan.required_sampling_only_lateral_excursion_mm + ...
        cfg.sampling.air_tracking_tolerance_mm, ...
    cfg.sampling.resume_maximum_orientation_difference_deg, ...
    -cfg.sampling.resume_maximum_start_below_home_mm, ...
    cfg.sampling.maximum_retract_mm + ...
        cfg.sampling.air_tracking_tolerance_mm);

fprintf('\n%s conical sampling child-run resume.\n', ...
    cfg.sampling.size_upper);
fprintf(['Parent hole centre WORLD XY [%+.3f %+.3f] mm is retained; ', ...
    'completed cones %s will not be replayed.\n'], ...
    parentCenter, mat2str(samplingResume.completed_cone_indices));
fprintf(['The child start is used only to establish fresh stationary/Bota ', ...
    'state.  A parent-baseline drift gate and verified +Z clear state ', ...
    'precede every lateral command; no typed phrase is required.\n']);
stationarity.motion_authorization_source = ...
    'EXPLICIT_DEDICATED_SAMPLING_RESUME_ENTRYPOINT_INVOCATION';
stationarity.interactive_confirmation_required = false;
stationarity.entrypoint_start_contract_assumed = true;
stationarity.resume_parent_run_session_id = ...
    samplingResume.parent_run_session_id;
stationarity.resume_parent_center_world_xy_mm = parentCenter;
stationarity.resume_orientation_difference_deg = ...
    orientationDifferenceDeg;
stationarity.resume_z_offset_from_parent_home_mm = ...
    zOffsetFromParentHomeMm;
logEvent(paths.events, ...
    'SAMPLING_RESUME_ENTRYPOINT_AUTHORIZED_NO_MOTION', sprintf( ...
    ['parent %s; retained centre [%+.3f %+.3f] mm; child start ', ...
     '[%+.3f %+.3f %+.3f] mm; radius %.3f mm; ', ...
     'orientation difference %.3f deg; ', ...
     'completed cones %s; motion_replayed=0'], ...
    samplingResume.parent_run_session_id, parentCenter, pose(1:3), ...
    startRadiusFromParentCenterMm, orientationDifferenceDeg, ...
    mat2str(samplingResume.completed_cone_indices)));
end

function observation = validateLiveUprightPose(pose, cfg, paths, phase)
worldFromTcp = kukaAbcToRotm(pose(4:6));
rotationErrorDeg = rad2deg(rotationDistance( ...
    cfg.frame.expected_world_from_upright_tcp_rotation, worldFromTcp));
pegAxisErrorDeg = rad2deg(acos(min(max(dot( ...
    worldFromTcp(:, 3), -cfg.frame.world_from_fixture_rotation(:, 3)), ...
    -1.0), 1.0)));
assert(rotationErrorDeg <= ...
        cfg.frame.upright_tcp_rotation_acceptance_deg && ...
    pegAxisErrorDeg <= ...
        cfg.frame.upright_tcp_rotation_acceptance_deg, ...
    'M12Demo:LiveUprightPoseOutsideCommissioning', ...
    ['%s live TCP rotation differs from the measured installed upright ', ...
     'rotation by %.3f deg; +TCP-Z to -Z_F error %.3f deg; limit %.3f deg.'], ...
    phase, rotationErrorDeg, pegAxisErrorDeg, ...
    cfg.frame.upright_tcp_rotation_acceptance_deg);
observation = struct( ...
    'rotation_error_deg', rotationErrorDeg, ...
    'peg_axis_error_deg', pegAxisErrorDeg);
logEvent(paths.events, 'LIVE_UPRIGHT_POSE_GATE_PASS_NO_MOTION', sprintf( ...
    '%s; SO(3) error %.3f deg; +TCP-Z to -Z_F error %.3f deg', ...
    phase, rotationErrorDeg, pegAxisErrorDeg));
end

function [result, endState, ctx] = runM12SamplingCampaign( ...
        result, ctx, iiwa, cfg, paths, runDir, plan, samplingResume)
if nargin < 8 || isempty(samplingResume)
    samplingResume = struct('enabled', false);
end
childStartPose = ctx.start_pose;
[~, runSessionId] = fileparts(runDir);
if samplingResume.enabled
    % The child stationary start is the only freshly observed home pose and
    % therefore owns this run's Z budget and final return.  Parent XY remains
    % the immutable fixture centre used for every target and label.
    homePose = childStartPose;
    runLocalHoleCenterWorldXY = double(reshape( ...
        samplingResume.run_local_hole_center_world_xy_mm, 1, 2));
    datasetGroupKey = samplingResume.dataset_group_key;
    campaignLineageId = samplingResume.campaign_lineage_id;
    resumeGeneration = samplingResume.resume_generation;
    inheritedAttempts = samplingResume.inherited_attempts;
    resumeParentRunDir = samplingResume.parent_run_dir;
    resumeParentRunSessionId = samplingResume.parent_run_session_id;
    resumeParentCheckpointSha256 = ...
        samplingResume.parent_checkpoint_sha256;
else
    homePose = childStartPose;
    runLocalHoleCenterWorldXY = homePose(1:2);
    datasetGroupKey = sprintf('%s__%s__%s__%s__%s__%s__%s', ...
        cfg.frame.physical_tool_instance_id, ...
        cfg.frame.fixture_instance_id, ...
        cfg.frame.installation_session_id, ...
        cfg.frame.record_sha256, ...
        sha256File(cfg.files.active_peg_step), ...
        sha256File(cfg.files.printed_socket_step), runSessionId);
    campaignLineageId = runSessionId;
    resumeGeneration = 0;
    inheritedAttempts = repmat( ...
        makeSamplingAttempt(plan.execution_points(1), cfg), 0, 1);
    resumeParentRunDir = '';
    resumeParentRunSessionId = '';
    resumeParentCheckpointSha256 = '';
end
safeAirZMm = homePose(3) + cfg.sampling.initial_lift_mm;
campaign = struct( ...
    'schema_version', 1, ...
    'campaign', cfg.sampling.campaign_id, ...
    'size', cfg.sampling.size_upper, ...
    'created_local', isoTimestamp(), ...
    'status', 'RUNNING', ...
    'authority', cfg.sampling.campaign_authority, ...
    'model_policy', cfg.sampling.model_policy, ...
    'sampling_plan_path', plan.source_path, ...
    'sampling_plan_sha256', plan.source_sha256, ...
    'fixture_frame_commissioning_sha256', cfg.frame.record_sha256, ...
    'tooling_sha256', sha256File(cfg.files.tooling), ...
    'physical_tool_instance_id', ...
        cfg.frame.physical_tool_instance_id, ...
    'fixture_instance_id', cfg.frame.fixture_instance_id, ...
    'installation_session_id', cfg.frame.installation_session_id, ...
    'run_session_id', runSessionId, ...
    'dataset_group_key', datasetGroupKey, ...
    'campaign_lineage_id', campaignLineageId, ...
    'resume_generation', resumeGeneration, ...
    'resume_enabled', logical(samplingResume.enabled), ...
    'resume_parent_run_directory', resumeParentRunDir, ...
    'resume_parent_run_session_id', resumeParentRunSessionId, ...
    'resume_parent_checkpoint_sha256', ...
        resumeParentCheckpointSha256, ...
    'resume_child_start_pose_mm_rad', childStartPose, ...
    'resume_parent_original_home_pose_mm_rad', ...
        samplingResumeField(samplingResume, ...
            'campaign_home_pose_mm_rad', childStartPose), ...
    'resume_completed_cone_indices', ...
        samplingResumeField(samplingResume, ...
            'completed_cone_indices', zeros(1, 0)), ...
    'resume_pending_execution_indices_at_start', ...
        samplingResumeField(samplingResume, ...
            'pending_execution_indices', 1:plan.attempt_count), ...
    'resume_air_baseline_force_shift_n', NaN, ...
    'resume_air_baseline_torque_shift_nm', NaN, ...
    'resume_start_clear_verified', false, ...
    'initial_air_pose_mm_rad', homePose, ...
    'campaign_safe_air_z_mm', safeAirZMm, ...
    'run_local_hole_center_world_xy_mm', ...
        runLocalHoleCenterWorldXY, ...
    'center_sample_excluded', true, ...
    'sampling_coordinate_authority', plan.coordinate_authority, ...
    'nominal_m12_center_fixture_xy_mm', ...
        plan.nominal_fixture_center_xy_mm, ...
    'nominal_socket_center_fixture_xy_mm', ...
        plan.nominal_fixture_center_xy_mm, ...
    'run_local_m12_center_fixture_xyz_mm', ...
        plan.fixture_center_xyz_mm, ...
    'run_local_socket_center_fixture_xyz_mm', ...
        plan.fixture_center_xyz_mm, ...
    'execution_attempt_indices', plan.execution_attempt_indices, ...
    'closed_route_distance_mm', plan.closed_route_distance_mm, ...
    'maximum_planned_radius_mm', plan.maximum_planned_radius_mm, ...
    'sampling_only_lateral_excursion_mm', ...
        plan.required_sampling_only_lateral_excursion_mm, ...
    'printed_cad_geometry_mm', plan.geometry_mm, ...
    'touchdown_contact_state_definition', ...
        plan.contact_state_definition, ...
    'cone_command_geometry', plan.cone_command_geometry, ...
    'sampling_design', plan.sampling_design, ...
    'true_label_rule', ...
        ['measured_touchdown_run_local_XY_to_operator_taught_', ...
         cfg.sampling.size_upper, '_center; ', ...
         'preregistered CAD local offsets define targets and labels'], ...
    'wrench_reference_boundary', ...
        ['raw_Bota_is_preserved_and_each_point_has_30_fresh_air_samples_', ...
         'no_simulation_or_model_changes_motion_label_or_quality_status'], ...
    'cad_and_configuration_hashes', struct( ...
        'fixture_sampling_plan_sha256', plan.source_sha256, ...
        'fixture_frame_record_sha256', cfg.frame.record_sha256, ...
        'tooling_sha256', sha256File(cfg.files.tooling), ...
        'pink_m12_step_sha256', sha256File(cfg.files.pink_m12_step), ...
        'active_peg_step_sha256', ...
            sha256File(cfg.files.active_peg_step), ...
        'printed_socket_step_sha256', ...
            sha256File(cfg.files.printed_socket_step), ...
        'printed_cad_design_parameters_sha256', ...
            sha256File(cfg.files.printed_cad_design_parameters), ...
        'printed_cad_manifest_sha256', ...
            sha256File(cfg.files.printed_cad_manifest)), ...
    'automatic_weight_update_permitted', false, ...
    'offline_compensation_and_qc_required', true, ...
    'touchdown_tracking_policy', struct( ...
        'immediate_acceptance_mm', ...
            cfg.sampling.step_tracking_tolerance_mm, ...
        'recheck_acceptance_mm', ...
            cfg.sampling.step_tracking_recheck_acceptance_mm, ...
        'recheck_count', cfg.sampling.step_tracking_recheck_count, ...
        'recheck_pause_s', cfg.sampling.step_tracking_recheck_pause_s, ...
        'minimum_measured_down_progress_mm', ...
            cfg.sampling.minimum_touchdown_down_progress_mm, ...
        'xy_landing_gate_mm', ...
            cfg.sampling.maximum_touchdown_xy_lock_error_mm, ...
        'per_step_downward_progress_abort_enabled', false, ...
        'finite_touchdown_schedule_and_contact_event_are_authoritative', ...
            true, ...
        'generic_vector_ratio_gate_applied_after_acceptance', false), ...
    'contact_observation_policy', struct( ...
        'preferred_target_normal_force_n', ...
            cfg.sampling.contact_stability.target_normal_force_n, ...
        'preferred_force_deadband_n', ...
            cfg.sampling.contact_stability.force_deadband_n, ...
        'preferred_maximum_force_std_n', ...
            cfg.sampling.contact_stability.maximum_force_std_n, ...
        'passive_observation_s', ...
            cfg.sampling.contact_stability.passive_observation_s, ...
        'maximum_observation_s', ...
            cfg.sampling.contact_stability.maximum_observation_s, ...
        'issues_motion_commands', false, ...
        'soft_force_quality_can_skip_cone', false, ...
        'confirmed_contact_continues_to_cone', true, ...
        'nonpreferred_load_requires_offline_qc', true), ...
    'point_acquisition_retry_policy', struct( ...
        'maximum_attempts', ...
            cfg.sampling.maximum_point_acquisition_attempts, ...
        'retry_requires_clear_retract_after_touchdown', true, ...
        'capture_or_bore_entry_is_not_retried', true, ...
        'hard_or_unknown_state_is_not_caught', true), ...
    'attempt_count_planned', plan.attempt_count, ...
    'attempts_completed', 0, ...
    'attempt_records_persisted', 0, ...
    'cones_completed', 0, ...
    'points_committed', 0, ...
    'original_retracts_verified', 0, ...
    'motion_lifecycles_closed', 0, ...
    'pending_execution_indices', 1:plan.attempt_count, ...
    'attempts_quarantined', 0, ...
    'returned_to_initial_air_pose', false, ...
    'attempts', inheritedAttempts, ...
    'error', '');
campaign = refreshSamplingCampaignCounters(campaign);
writeSamplingCheckpoint(paths, campaign);
if samplingResume.enabled
    logEvent(paths.events, ...
        'SAMPLING_RESUME_CHILD_CHECKPOINT_CREATED', sprintf( ...
        ['child %s; parent %s; inherited complete cones %s; ', ...
         'pending %s; parent remains immutable'], ...
        runSessionId, samplingResume.parent_run_session_id, ...
        mat2str(samplingResume.completed_cone_indices), ...
        mat2str(samplingResume.pending_execution_indices)));
    ctx = hydrateSamplingResumeDashboard( ...
        ctx, campaign.attempts, false);
end
logEvent(paths.events, 'M12_SAMPLING_CAMPAIGN_ARMED', ...
    ['Real-device raw signal and per-point baseline are authoritative.  ', ...
     'No learned inference, simulation validity gate, online normalization ', ...
     'update, or automatic training admission is executed.']);

try
if samplingResume.enabled
    resumeForceShiftN = norm(double(ctx.baseline_force(:).') - ...
        samplingResume.reference_air_baseline_force_n);
    resumeTorqueShiftNm = norm(double(ctx.baseline_torque(:).') - ...
        samplingResume.reference_air_baseline_torque_nm);
    campaign.resume_air_baseline_force_shift_n = resumeForceShiftN;
    campaign.resume_air_baseline_torque_shift_nm = resumeTorqueShiftNm;
    writeSamplingCheckpoint(paths, campaign);
    assert(resumeForceShiftN <= ...
            cfg.sampling.resume_maximum_air_baseline_force_shift_n && ...
        resumeTorqueShiftNm <= ...
            cfg.sampling.resume_maximum_air_baseline_torque_shift_nm, ...
        'M12Demo:SamplingResumeAirBaselineShift', ...
        ['Fresh child air baseline differs from the latest validated ', ...
         'parent point by %.3f N / %.4f Nm; limits %.3f N / %.4f Nm. ', ...
         'No motion was sent. Reposition unloaded without moving the fixture.'], ...
        resumeForceShiftN, resumeTorqueShiftNm, ...
        cfg.sampling.resume_maximum_air_baseline_force_shift_n, ...
        cfg.sampling.resume_maximum_air_baseline_torque_shift_nm);
    baselineEvent = 'SAMPLING_RESUME_BASELINE_COMPATIBLE_NO_MOTION';
    if resumeForceShiftN > ...
            cfg.sampling.resume_air_baseline_force_shift_warning_n || ...
        resumeTorqueShiftNm > ...
            cfg.sampling.resume_air_baseline_torque_shift_warning_nm
        baselineEvent = ...
            'SAMPLING_RESUME_BASELINE_DRIFT_ACCEPTED_NO_MOTION';
    end
    logEvent(paths.events, baselineEvent, sprintf( ...
        ['fresh-to-parent baseline shift %.3f N / %.4f Nm; ', ...
         'warning %.3f N / %.4f Nm; hard limits %.3f N / %.4f Nm; ', ...
         'fresh child baseline remains authoritative'], ...
        resumeForceShiftN, resumeTorqueShiftNm, ...
        cfg.sampling.resume_air_baseline_force_shift_warning_n, ...
        cfg.sampling.resume_air_baseline_torque_shift_warning_nm, ...
        cfg.sampling.resume_maximum_air_baseline_force_shift_n, ...
        cfg.sampling.resume_maximum_air_baseline_torque_shift_nm));
end
% Lift before the first lateral command.  The near-contact operator start is
% never used as an XY transit plane.
[ctx, safeAirZMm, initialClear] = retractSamplingUntilClear( ...
    ctx, homePose, safeAirZMm, 'SAMPLING_INITIAL_LIFT');
campaign.campaign_safe_air_z_mm = safeAirZMm;
ctx = setSamplingTopviewPhase(ctx, ...
    'READY_AT_CLEAR_TRANSIT_HEIGHT', true);
logEvent(paths.events, 'SAMPLING_INITIAL_SAFE_AIR_CONFIRMED', sprintf( ...
    'clear Z %.3f mm; two-window max dF %.3f N; max dT %.4f Nm', ...
    safeAirZMm, ...
    initialClear.maximum_force_delta_n, ...
    initialClear.maximum_torque_delta_nm));
if samplingResume.enabled
    campaign.resume_start_clear_verified = true;
    for inheritedIndex = 1:numel(campaign.attempts)
        if campaign.attempts(inheritedIndex).cone_completed && ...
                ~campaign.attempts(inheritedIndex).motion_lifecycle_closed
            campaign.attempts(inheritedIndex).recovery_clear_verified = true;
            campaign.attempts(inheritedIndex).recovery_run_session_id = ...
                runSessionId;
            campaign.attempts(inheritedIndex).recovery_clear_max_force_n = ...
                initialClear.maximum_force_delta_n;
            campaign.attempts(inheritedIndex). ...
                recovery_clear_max_torque_nm = ...
                initialClear.maximum_torque_delta_nm;
            campaign.attempts(inheritedIndex). ...
                recovery_clear_verified_local = isoTimestamp();
            campaign.attempts(inheritedIndex).motion_lifecycle_closed = true;
            campaign.attempts(inheritedIndex).operational_status = ...
                'CONE_COMPLETE_RECOVERY_CLEAR_VERIFIED_CHILD';
            campaign.attempts(inheritedIndex).campaign_must_abort = false;
        end
    end
    campaign = refreshSamplingCampaignCounters(campaign);
    writeSamplingCheckpoint(paths, campaign);
    ctx = hydrateSamplingResumeDashboard(ctx, campaign.attempts, true);
    logEvent(paths.events, ...
        'SAMPLING_RESUME_START_CLEAR_VERIFIED', sprintf( ...
        ['verified clear at Z %.3f mm; cones %d/26; secured motion ', ...
         'lifecycles %d/26; original retracts %d/26; no cone replay'], ...
        safeAirZMm, campaign.cones_completed, ...
        campaign.motion_lifecycles_closed, ...
        campaign.original_retracts_verified));
end
safeToMoveLaterally = true;

for executionIndex = 1:numel(plan.execution_points)
    point = plan.execution_points(executionIndex);
    if samplingResume.enabled && ismember(executionIndex, ...
            samplingResume.completed_cone_indices)
        logEvent(paths.events, ...
            'SAMPLING_RESUME_POINT_SKIPPED_EXISTING_CONE', sprintf( ...
            ['execution %02d sample %s has hash-validated complete cone ', ...
             'evidence in lineage %s; no target, motion, or cone replay'], ...
            executionIndex, char(point.sample_id), campaignLineageId));
        continue;
    end
    attempt = makeSamplingAttempt(point, cfg);
    attempt.execution_index = executionIndex;
    attempt.source_attempt_index = double(point.attempt_index);
    attempt.cone_run_kind = sprintf('%s_%02d', ...
        cfg.sampling.run_kind_prefix, executionIndex);
    attempt.physical_tool_instance_id = ...
        cfg.frame.physical_tool_instance_id;
    attempt.fixture_instance_id = cfg.frame.fixture_instance_id;
    attempt.dataset_group_key = campaign.dataset_group_key;
    attempt.origin_run_session_id = runSessionId;
    cone = struct();
    pointBaseline = emptySamplingPointBaseline();
    contactSettle = emptySamplingContactSettle();
    persistenceOutcome = struct( ...
        'committed', false, 'attempts', 0, ...
        'immutable_evidence_committed', false, ...
        'error_identifier', '', 'error_message', '');
    attemptDir = fullfile(paths.samplingAttempts, ...
        sprintf('%02d_%s', executionIndex, char(point.sample_id)));
    [made, makeMessage] = mkdir(attemptDir);
    assert(made, 'M12Demo:SamplingAttemptDirectory', ...
        'Cannot create %s: %s', attemptDir, makeMessage);
    attempt.mat_path = fullfile(attemptDir, 'attempt.mat');
    attempt.json_path = fullfile(attemptDir, 'attempt.json');
    attempt.baseline_csv_path = ...
        fullfile(attemptDir, 'point_air_baseline_raw.csv');
    attempt.contact_settle_csv_path = ...
        fullfile(attemptDir, 'contact_settle_raw.csv');
    attempt.cone_csv_path = ...
        fullfile(attemptDir, 'conical_trace_raw.csv');
    targetWorldXY = runLocalHoleCenterWorldXY + double(point.local_offset_fixture_mm(:).');
    attempt.target_world_xy_mm = targetWorldXY;
    attempt.run_local_hole_center_world_xy_mm = ...
        runLocalHoleCenterWorldXY;
    attempt.nominal_direction_world_xy = fixtureVectorToWorldXY( ...
        double(point.true_direction_to_centre_fixture_unit(:).'), ...
        cfg.frame);
    try
        ctx = bestEffortSamplingTopviewAction(ctx, ...
            'target', struct( ...
                'index', double(point.attempt_index), ...
                'name', sprintf('TARGET %02d/26', executionIndex), ...
                'allow_drawnow', true));
        assert(safeToMoveLaterally, ...
            'M12Demo:SamplingUnsafeLateralMove', ...
            'No XY command is permitted before a verified retract.');
        [ctx, ~] = requireWrenchClearDwells( ...
            ctx, sprintf('SAMPLE_%02d_PRE_AIR_XY_CLEAR', executionIndex));
        [ctx, ~] = moveAirSegmented(ctx, ...
            [targetWorldXY, safeAirZMm], ...
            sprintf('SAMPLE_%02d_AIR_XY', executionIndex));
        [ctx, preTouchClear] = requireWrenchClearDwells( ...
            ctx, sprintf('SAMPLE_%02d_PRE_TOUCH_CLEAR', executionIndex));
        attempt.pre_touch_clear_max_force_n = ...
            preTouchClear.maximum_force_delta_n;
        attempt.pre_touch_clear_max_torque_nm = ...
            preTouchClear.maximum_torque_delta_nm;
        safeToMoveLaterally = false;
        [ctx, pointBaseline, touchdown, safeAirZMm, ...
            pointAcquisition] = acquireSamplingTouchdownWithRetries( ...
                ctx, homePose, safeAirZMm, targetWorldXY, ...
                executionIndex);
        attempt.point_acquisition_attempts = ...
            pointAcquisition.attempt_count;
        attempt.point_touchdown_attempts = ...
            pointAcquisition.touchdown_attempt_count;
        attempt.point_retry_reasons = ...
            pointAcquisition.retry_reasons;
        attempt.point_air_baseline_valid = pointBaseline.valid;
        attempt.point_air_baseline_reason = pointBaseline.reason;
        attempt.point_air_baseline_force_std_n = ...
            pointBaseline.force_std_n;
        attempt.point_air_baseline_torque_std_nm = ...
            pointBaseline.torque_std_nm;
        attempt.touchdown_confirmed = touchdown.contact_confirmed;
        attempt.touchdown_pose_mm_rad = touchdown.pose_mm_rad;
        attempt.touchdown_max_force_n = ...
            touchdown.maximum_force_delta_n;
        attempt.touchdown_max_torque_nm = ...
            touchdown.maximum_torque_delta_nm;
        attempt.touchdown_maximum_xy_error_mm = ...
            touchdown.maximum_target_xy_error_mm;
        attempt.touchdown_landing_gate_passed = ...
            touchdown.landing_gate_passed;
        captureDuringTouchdown = touchdown.contact_confirmed && ...
            homePose(3) - touchdown.pose_mm_rad(3) >= ...
                cfg.sampling.maximum_touchdown_below_start_mm - ...
                cfg.sampling.touchdown_step_mm;
        physicalTouchdownForCone = pointBaseline.valid && ...
            touchdown.landing_gate_passed && ...
            touchdown.contact_confirmed && ~captureDuringTouchdown;

        if ~pointBaseline.valid
            attempt = quarantineSamplingAttempt(attempt, ...
                ['POINT_AIR_BASELINE_CONTAMINATED_', ...
                 pointBaseline.reason]);
        elseif ~touchdown.landing_gate_passed
            attempt = quarantineSamplingAttempt(attempt, ...
                'MEASURED_CONTACT_XY_OUTSIDE_PLAN_TOLERANCE');
        elseif ~touchdown.contact_confirmed
            attempt = quarantineSamplingAttempt(attempt, ...
                'NO_PERSISTENT_CONTACT_WITHIN_RUN_LOCAL_TOUCHDOWN_BUDGET');
        elseif captureDuringTouchdown
            attempt = quarantineSamplingAttempt(attempt, ...
                'CAPTURE_OR_BORE_ENTRY_DETECTED_DURING_TOUCHDOWN');
        else
            assert(physicalTouchdownForCone, ...
                'M12Demo:SamplingPhysicalConeEligibilityInvariant', ...
                'Unexpected point-acquisition branch before cone.');
            attempt = addMeasuredSamplingLabel( ...
                attempt, touchdown.pose_mm_rad, plan, cfg);
            if ~attempt.measured_label_gate_passed
                attempt = quarantineSamplingAttempt(attempt, ...
                    attempt.measured_label_gate_reason);
            end
            ctx = setSamplingTopviewPhase(ctx, ...
                sprintf(['POINT_%02d_PASSIVE_CONTACT_', ...
                    'OBSERVATION_NO_MOTION'], ...
                    executionIndex), true);
            [ctx, contactSettle] = observeSamplingContactBeforeCone( ...
                ctx, touchdown.pose_mm_rad, targetWorldXY, ...
                touchdown.normal_sign_world_z, sprintf( ...
                    'SAMPLE_%02d_CONTACT_OBSERVATION', ...
                    executionIndex));
            attempt.contact_settle_passed = contactSettle.valid;
            attempt.contact_settle_reason = contactSettle.reason;
            attempt.contact_settle_normal_mean_n = ...
                contactSettle.final_normal_mean_n;
            attempt.contact_settle_normal_std_n = ...
                contactSettle.final_normal_std_n;
            attempt.contact_settle_samples = contactSettle.sample_count;
            attempt.contact_settle_off_target_continuation = ...
                contactSettle.off_target_continuation;
            attempt.contact_settle_quality_grade = ...
                contactSettle.quality_grade;
            attempt.contact_settle_completion_first_continuation = ...
                contactSettle.completion_first_continuation;
            attempt.contact_settle_observed_dwell_s = ...
                contactSettle.observed_dwell_s;
            attempt.contact_settle_normal_min_n = ...
                contactSettle.final_normal_min_n;
            attempt.contact_settle_normal_max_n = ...
                contactSettle.final_normal_max_n;
            attempt.contact_settle_adjustment_commands = ...
                contactSettle.adjustment_command_count;
            attempt.contact_settle_unobserved_adjustments = ...
                contactSettle.unobserved_adjustment_count;
            assert(contactSettle.valid, ...
                'M12Demo:SamplingCompletionFirstInvariant', ...
                ['A confirmed, XY-qualified, non-captured touchdown may ', ...
                 'not skip its cone because of a soft pre-cone force or ', ...
                 'label-quality metric.']);
            ctx = setSamplingTopviewPhase( ...
                ctx, '锥扫中，界面冻结', true);
            [ctx, cone] = runConicalFingerprint(ctx, ...
                contactSettle.final_pose_mm_rad, ...
                attempt.cone_run_kind, ...
                touchdown.normal_sign_world_z);
            attempt = addSamplingConeEvidence(attempt, cone, ...
                contactSettle.final_pose_mm_rad, cfg);
            ctx = bestEffortAppendSamplingConeToTopview(ctx, cone);
            attempt.weak_but_complete_fingerprint = ...
                cone.schedule_completed && ...
                (cone.low_force_episodes > 0 || ...
                 cone.force_relief_episodes > 0 || ...
                 ~cone.training_fingerprint_valid);
            if ~attempt.cone_post_stop_state_known
                attempt = quarantineSamplingAttempt(attempt, ...
                    'POST_DIRECTSERVO_STATE_UNKNOWN_AFTER_COMPLETE_CONE');
            elseif attempt.capture_during_cone
                attempt = quarantineSamplingAttempt(attempt, ...
                    'CAPTURE_OR_BORE_ENTRY_DETECTED_DURING_CONE');
            elseif cone.aperture_candidate
                attempt = quarantineSamplingAttempt(attempt, ...
                    'CONTACT_LOSS_OR_APERTURE_DURING_CONE');
            elseif ~cone.schedule_completed || ...
                    ~cone.direction_fingerprint_valid || ...
                    cone.phase_coverage_fraction < ...
                    cfg.sampling.minimum_phase_coverage_fraction
                attempt = quarantineSamplingAttempt(attempt, ...
                    'INCOMPLETE_CONICAL_PHASE_OR_TIMING_COVERAGE');
            elseif isempty(attempt.quarantine_reason)
                attempt = classifyCompletedSamplingAttempt( ...
                    attempt, cfg);
            end
            attempt.operational_status = ...
                'CONE_COMPLETE_RETRACT_PENDING';
            ctx = bestEffortSamplingTopviewAction(ctx, ...
                'cone_complete', struct( ...
                    'index', double(point.attempt_index), ...
                    'name', sprintf( ...
                        'CONE_%02d_COMPLETE_RETRACT_PENDING', ...
                        executionIndex), ...
                    'allow_drawnow', true, ...
                    'force_render', true));
            % Commit the complete fingerprint before attempting the physical
            % retract.  A process/transport failure after this boundary can
            % resume without replaying the cone; the later retract commit
            % upserts the same execution index.
            [attempt, campaign, persistenceOutcome] = ...
                persistSamplingAttemptWithRetry( ...
                    attempt, pointBaseline, contactSettle, cone, ...
                    campaign, cfg, paths, true, 'PRE_RETRACT');
            if persistenceOutcome.committed
                bestEffortLogEvent(paths.events, ...
                    'SAMPLING_CONE_COMPLETE_ATOMIC_CHECKPOINT', sprintf( ...
                    ['execution %02d sample %s; immutable cone retained ', ...
                     'before retract; phase coverage %.5f; motion ', ...
                     'lifecycle pending'], ...
                    executionIndex, char(point.sample_id), ...
                    attempt.phase_coverage_fraction));
            end
            % A failed post-stop state read must never cause this physical
            % cone to be replayed.  It is checkpointed above, then command
            % authority ends at the current pose because retract state is
            % unknown.
            throwIfConicalPostStateUnknown(cone);
        end

        ctx = setSamplingTopviewPhase(ctx, ...
            sprintf('POINT_%02d_CLEAR_RETRACT', executionIndex), true);
        [ctx, safeAirZMm, clearObservation] = ...
            retractSamplingUntilClear(ctx, homePose, safeAirZMm, ...
                sprintf('SAMPLE_%02d_RETRACT', executionIndex));
        attempt.post_retract_clear_max_force_n = ...
            clearObservation.maximum_force_delta_n;
        attempt.post_retract_clear_max_torque_nm = ...
            clearObservation.maximum_torque_delta_nm;
        attempt.safe_retract_completed = true;
        attempt.operational_status = ...
            'POINT_COMMITTED_ORIGINAL_RETRACT_VERIFIED';
        attempt.motion_lifecycle_closed = true;
        safeToMoveLaterally = true;
        attempt.finished_local = isoTimestamp();
        [attempt, campaign, persistenceOutcome] = ...
            persistSamplingAttemptWithRetry( ...
                attempt, pointBaseline, contactSettle, cone, campaign, ...
                cfg, paths, ~attempt.immutable_evidence_committed, ...
                'POST_RETRACT');
        if ~persistenceOutcome.committed
            error('M12Demo:SamplingPersistenceExhaustedAfterClear', ...
                ['Execution %02d completed its physical retract and is ', ...
                 'wrench-clear, but bounded persistence failed: %s: %s'], ...
                executionIndex, persistenceOutcome.error_identifier, ...
                persistenceOutcome.error_message);
        end
    catch attemptError
        if attempt.safe_retract_completed
            attempt.operational_status = ...
                'POINT_MOTION_COMPLETE_PERSISTENCE_FAILED';
        elseif attempt.cone_completed
            attempt.operational_status = ...
                'CONE_COMPLETE_RETRACT_UNVERIFIED';
        else
            attempt = quarantineSamplingAttempt(attempt, ...
                ['ABORT_AFTER_', ...
                 regexprep(upper(attemptError.identifier), ...
                    '[^A-Z0-9]+', '_')]);
            if any(strcmp(attemptError.identifier, { ...
                    'M12Demo:HardForceGuard', ...
                    'M12Demo:ConicalHardForceGuard'}))
                attempt.operational_status = ...
                    'ACQUISITION_ABORTED_25N_FORCE_GUARD_STATE_UNKNOWN';
            elseif any(strcmp(attemptError.identifier, { ...
                    'M12Demo:HardTorqueGuard', ...
                    'M12Demo:ConicalHardTorqueGuard'}))
                attempt.operational_status = ...
                    'ACQUISITION_ABORTED_0P75NM_TORQUE_GUARD_STATE_UNKNOWN';
            elseif startsWith(attemptError.identifier, 'MATLAB:') || ...
                    startsWith(attemptError.identifier, ...
                        'M12Demo:SamplingConfiguration')
                attempt.operational_status = ...
                    'ACQUISITION_ABORTED_SOFTWARE_ERROR';
            else
                attempt.operational_status = ...
                    'ACQUISITION_ABORTED_STATE_UNKNOWN';
            end
        end
        attempt.error = [attemptError.identifier, ': ', ...
            oneLine(attemptError.message)];
        attempt.operational_error = attempt.error;
        attempt.campaign_must_abort = true;
        attempt.finished_local = isoTimestamp();
        ctx = bestEffortSamplingTopviewAction(ctx, ...
            'phase', struct( ...
                'name', attempt.operational_status, ...
                'allow_drawnow', true, ...
                'force_render', true));
        campaign.status = 'ABORTED_NO_BLIND_RETURN';
        campaign.error = attempt.error;
        if ~strcmp(attemptError.identifier, ...
                'M12Demo:SamplingPersistenceExhaustedAfterClear')
            [attempt, campaign, persistenceOutcome] = ...
                persistSamplingAttemptWithRetry( ...
                    attempt, pointBaseline, contactSettle, cone, ...
                    campaign, cfg, paths, ...
                    ~attempt.immutable_evidence_committed, ...
                    ternarySamplingPersistencePhase( ...
                        attempt.safe_retract_completed));
        end
        if persistenceOutcome.committed
            if attempt.cone_completed && ...
                    ~attempt.safe_retract_completed
                bestEffortLogEvent(paths.events, ...
                    ['SAMPLING_CONE_COMPLETE_CHECKPOINTED_', ...
                     'RETRACT_UNVERIFIED'], sprintf( ...
                    ['%s retained its completed fingerprint and data ', ...
                     'quality status; operational failure %s'], ...
                    char(point.sample_id), attempt.error));
            else
                bestEffortLogEvent(paths.events, ...
                    'SAMPLING_ATTEMPT_QUARANTINED_ABORT_NO_BLIND_RETURN', ...
                    sprintf('%s: %s', ...
                    char(point.sample_id), attempt.error));
            end
        else
            bestEffortLogEvent(paths.events, ...
                'SAMPLING_ABORT_EVIDENCE_PERSISTENCE_FAILED', sprintf( ...
                ['original %s; persistence %s: %s; preserving the ', ...
                 'original hard-state exception'], ...
                attemptError.identifier, ...
                persistenceOutcome.error_identifier, ...
                persistenceOutcome.error_message));
        end
        rethrow(attemptError);
    end

    ctx = bestEffortSamplingTopviewAction(ctx, ...
        'complete', struct( ...
            'index', double(point.attempt_index), ...
            'effective_partition', attempt.effective_partition, ...
            'name', sprintf('%02d/26 %s', ...
                executionIndex, attempt.status), ...
            'allow_drawnow', true));
end

assert(safeToMoveLaterally, 'M12Demo:SamplingHomeReturnUnsafe', ...
    'Campaign ended without a verified wrench-clear retract; no blind return.');
[ctx, ~] = moveAirSegmented(ctx, ...
    [homePose(1:2), safeAirZMm], 'SAMPLING_RETURN_HOME_XY');
[ctx, ~] = requireWrenchClearDwells( ...
    ctx, 'SAMPLING_RETURN_HOME_XY_CLEAR');
[ctx, returnedPose] = moveAirSegmented(ctx, ...
    homePose(1:3), 'SAMPLING_RETURN_INITIAL_AIR_Z');
[ctx, ~] = requireWrenchClearDwells( ...
    ctx, 'SAMPLING_RETURN_INITIAL_AIR_CLEAR');
assert(norm(returnedPose(1:3) - homePose(1:3)) <= ...
    cfg.sampling.home_return_tolerance_mm, ...
    'M12Demo:SamplingHomeReturnTolerance', ...
    'Measured home-return error %.3f mm exceeds %.3f mm.', ...
    norm(returnedPose(1:3) - homePose(1:3)), ...
    cfg.sampling.home_return_tolerance_mm);
campaign.returned_to_initial_air_pose = true;
assert(campaign.cones_completed == plan.attempt_count && ...
    campaign.motion_lifecycles_closed == plan.attempt_count && ...
    isempty(campaign.pending_execution_indices), ...
    'M12Demo:SamplingCampaignIncomplete', ...
    ['Route motion ended with %d/26 complete cones and %d/26 secured ', ...
     'motion lifecycles; pending execution indices %s.'], ...
    campaign.cones_completed, campaign.motion_lifecycles_closed, ...
    mat2str(campaign.pending_execution_indices));
logEvent(paths.events, ...
    'SAMPLING_ALL_CONES_AND_MOTION_LIFECYCLES_COMPLETE', sprintf( ...
    ['cones %d/26; secured %d/26; original retracts %d/26; ', ...
     'returned to this run''s measured initial air pose'], ...
    campaign.cones_completed, campaign.motion_lifecycles_closed, ...
    campaign.original_retracts_verified));

[endState.sent, endState.method] = requestKstEndOnce( ...
    iiwa, cfg.robot.ip, runDir, paths);
if endState.sent
    campaign.status = ...
        'COMPLETE_RETURNED_TO_INITIAL_AIR_POSE_KST_END_SENT';
else
    campaign.status = ...
        'COMPLETE_RETURNED_TO_INITIAL_AIR_POSE_KST_END_NOT_CONFIRMED';
end
campaign.completed_local = isoTimestamp();
ctx = bestEffortSamplingTopviewAction(ctx, ...
    'finalize', struct( ...
        'name', campaign.status, 'allow_drawnow', true, ...
        'force_render', true));
writeSamplingCheckpoint(paths, campaign);
result = copyContextMetrics(result, ctx);
result.sampling_data_authority = cfg.sampling.campaign_authority;
result.sampling_plan_sha256 = plan.source_sha256;
result.sampling_attempts_completed = campaign.attempts_completed;
result.sampling_cones_completed = campaign.cones_completed;
result.sampling_points_committed = campaign.points_committed;
result.sampling_attempts_quarantined = campaign.attempts_quarantined;
result.sampling_returned_to_initial_air_pose = true;
result.sampling_model_policy = cfg.sampling.model_policy;
result.sampling_campaign_lineage_id = campaign.campaign_lineage_id;
result.sampling_resume_generation = campaign.resume_generation;
result.sampling_resume_parent_run_session_id = ...
    campaign.resume_parent_run_session_id;
result.kst_end_request_sent = endState.sent;
result.kst_end_request_method = endState.method;
result.human_selected_confirmation_pending = endState.sent;
result.task_completed = endState.sent;
result.success = false;
result.claim_endpoint = ...
    'commissioning_data_only_not_full_loop_authorization';
result.completion_status = campaign.status;
result.terminal_reason = sprintf( ...
    '%s_26_POINT_CONICAL_COMMISSIONING_COMPLETE_NO_ONLINE_TRAINING', ...
    cfg.sampling.size_upper);
writeJson(paths.summary, result);
fprintf('\n%s 26-point conical commissioning campaign complete.\n', ...
    cfg.sampling.size_upper);
fprintf(['The robot returned to the measured initial non-contact pose before ', ...
    'KST end: %d (%s).\n'], endState.sent, endState.method);
fprintf(['No learned model or simulation output was loaded.  No model weight ', ...
    'was updated and no raw trace was automatically admitted to training.\n']);
fprintf('Run record: %s\n', runDir);
catch campaignError
    if campaign.returned_to_initial_air_pose
        campaign.status = ...
            'RETURNED_TO_INITIAL_POSE_BUT_CAMPAIGN_FINALIZATION_FAILED';
    else
        campaign.status = 'ABORTED_NO_BLIND_RETURN';
    end
    campaign.error = [campaignError.identifier, ': ', ...
        oneLine(campaignError.message)];
    campaign.completed_local = isoTimestamp();
    try
        writeSamplingCheckpoint(paths, campaign);
    catch checkpointError
        try
            logEvent(paths.events, ...
                'SAMPLING_CAMPAIGN_ABORT_CHECKPOINT_FAILED', sprintf( ...
                '%s: %s', checkpointError.identifier, ...
                oneLine(checkpointError.message)));
        catch
            % Preserve and rethrow the original campaign exception.
        end
    end
    try
        logEvent(paths.events, ...
            'SAMPLING_CAMPAIGN_ABORTED_NO_BLIND_RETURN', campaign.error);
    catch
        % Preserve and rethrow the original campaign exception.
    end
    rethrow(campaignError);
end
end

function attempt = makeSamplingAttempt(point, cfg)
duplicateOf = '';
if isfield(point, 'duplicate_of') && ~isempty(point.duplicate_of)
    duplicateOf = char(point.duplicate_of);
end
attempt = struct( ...
    'attempt_index', double(point.attempt_index), ...
    'source_attempt_index', double(point.attempt_index), ...
    'execution_index', NaN, ...
    'sample_id', char(point.sample_id), ...
    'requested_partition', char(point.partition), ...
    'effective_partition', char(point.partition), ...
    'training_use_contract', char(point.training_use), ...
    'duplicate_of_sample_id', duplicateOf, ...
    'physical_tool_instance_id', '', ...
    'fixture_instance_id', '', ...
    'dataset_group_key', '', ...
    'origin_run_session_id', '', ...
    'inherited_from_parent_run', false, ...
    'immutable_parent_data_quality_status', '', ...
    'resume_status_overlay_reason', '', ...
    'contact_state', char(point.contact_state), ...
    'cone_sweep_subtype', char(point.cone_sweep_subtype), ...
    'contact_state_definition_phase', ...
        char(point.state_definition_phase), ...
    'printed_cad_radius_rule', char(point.radius_rule), ...
    'nominal_touchdown_geometry', ...
        point.nominal_touchdown_geometry, ...
    'touchdown_geometry_over_plus_minus_1deg_peg_yaw', ...
        point.touchdown_geometry_over_plus_minus_1deg_peg_yaw, ...
    'printed_frustum_cone_phase_diagnostics', ...
        point.printed_frustum_cone_phase_diagnostics, ...
    'radius_mm', double(point.radius_mm), ...
    'angle_fixture_deg', double(point.angle_fixture_deg), ...
    'local_offset_fixture_mm', ...
        double(point.local_offset_fixture_mm(:).'), ...
    'nominal_fixture_xy_mm', ...
        double(point.nominal_fixture_xy_mm(:).'), ...
    'fixture_xy_mm', double(point.fixture_xy_mm(:).'), ...
    'fixture_point_mm', double(point.fixture_point_mm(:).'), ...
    'nominal_direction_fixture_deg', ...
        double(point.true_direction_to_centre_fixture_deg), ...
    'nominal_direction_fixture_unit', ...
        double(point.true_direction_to_centre_fixture_unit(:).'), ...
    'nominal_direction_world_xy', [NaN, NaN], ...
    'measured_contact_fixture_xy_mm', [NaN, NaN], ...
    'measured_sampling_error_mm', NaN, ...
    'measured_label_direction_deviation_deg', NaN, ...
    'measured_label_direction_warning', false, ...
    'measured_label_gate_passed', false, ...
    'measured_label_gate_reason', 'NO_MEASURED_CONTACT_LABEL', ...
    'true_direction_fixture_deg', NaN, ...
    'true_direction_fixture_unit', [NaN, NaN], ...
    'true_direction_world_xy', [NaN, NaN], ...
    'target_world_xy_mm', [NaN, NaN], ...
    'run_local_hole_center_world_xy_mm', [NaN, NaN], ...
    'status', 'NOT_STARTED', ...
    'data_quality_status', 'NOT_STARTED', ...
    'operational_status', 'NOT_STARTED', ...
    'operational_error', '', ...
    'recovery_clear_verified', false, ...
    'recovery_run_session_id', '', ...
    'recovery_clear_max_force_n', NaN, ...
    'recovery_clear_max_torque_nm', NaN, ...
    'recovery_clear_verified_local', '', ...
    'motion_lifecycle_closed', false, ...
    'quarantine_reason', '', ...
    'offline_training_candidate', false, ...
    'automatic_training_admission', false, ...
    'conical_phase_pose_tracking_qualified_for_training', ...
        logical(cfg.sampling.conical_phase_pose_tracking. ...
            qualified_for_training_candidates), ...
    'campaign_must_abort', false, ...
    'touchdown_confirmed', false, ...
    'touchdown_pose_mm_rad', [], ...
    'touchdown_max_force_n', NaN, ...
    'touchdown_max_torque_nm', NaN, ...
    'touchdown_maximum_xy_error_mm', NaN, ...
    'touchdown_landing_gate_passed', false, ...
    'pre_touch_clear_max_force_n', NaN, ...
    'pre_touch_clear_max_torque_nm', NaN, ...
    'point_air_baseline_valid', false, ...
    'point_air_baseline_reason', 'NOT_CAPTURED', ...
    'point_air_baseline_force_std_n', [NaN, NaN, NaN], ...
    'point_air_baseline_torque_std_nm', [NaN, NaN, NaN], ...
    'point_acquisition_attempts', 0, ...
    'point_touchdown_attempts', 0, ...
    'point_retry_reasons', {cell(0, 1)}, ...
    'contact_settle_passed', false, ...
    'contact_settle_reason', 'NOT_RUN', ...
    'contact_settle_normal_mean_n', NaN, ...
    'contact_settle_normal_std_n', NaN, ...
    'contact_settle_samples', 0, ...
    'contact_settle_off_target_continuation', false, ...
    'contact_settle_quality_grade', 'NOT_OBSERVED', ...
    'contact_settle_completion_first_continuation', false, ...
    'contact_settle_observed_dwell_s', NaN, ...
    'contact_settle_normal_min_n', NaN, ...
    'contact_settle_normal_max_n', NaN, ...
    'contact_settle_adjustment_commands', 0, ...
    'contact_settle_unobserved_adjustments', 0, ...
    'cone_completed', false, ...
    'cone_physical_schedule_completed', false, ...
    'cone_directservo_stop_acknowledged', false, ...
    'cone_post_stop_state_known', false, ...
    'cone_post_stop_state_error_identifier', '', ...
    'cone_post_stop_state_error_message', '', ...
    'cone_run_kind', '', ...
    'cone_mode_transition_outcome', 'NOT_RUN', ...
    'cone_low_force_episodes', 0, ...
    'cone_force_relief_episodes', 0, ...
    'cone_fast_force_relief_kicks', 0, ...
    'cone_direction_fingerprint_valid', false, ...
    'cone_routing_fingerprint_valid', false, ...
    'cone_training_fingerprint_valid', false, ...
    'weak_but_complete_fingerprint', false, ...
    'fingerprint_signal_rms_lateral_force_n', NaN, ...
    'fingerprint_signal_peak_lateral_force_n', NaN, ...
    'capture_during_cone', false, ...
    'cone_pre_directservo_measured_pose_mm_rad', [], ...
    'cone_post_directservo_measured_pose_mm_rad', [], ...
    'cone_maximum_command_gap_s', NaN, ...
    'cone_maximum_tick_lateness_s', NaN, ...
    'phase_coverage_fraction', 0.0, ...
    'return_orientation_error_deg', NaN, ...
    'post_stop_tip_error_mm', NaN, ...
    'nominal_cad_distance_to_center_mm', ...
        norm(double(point.local_offset_fixture_mm(:).')), ...
    'cad_distance_to_center_mm', NaN, ...
    'post_retract_clear_max_force_n', NaN, ...
    'post_retract_clear_max_torque_nm', NaN, ...
    'safe_retract_completed', false, ...
    'immutable_evidence_committed', false, ...
    'immutable_evidence_commit_attempts', 0, ...
    'immutable_evidence_commit_error', '', ...
    'operational_overlay_commit_attempts', 0, ...
    'operational_overlay_commit_error', '', ...
    'mat_path', '', ...
    'json_path', '', ...
    'baseline_csv_path', '', ...
    'contact_settle_csv_path', '', ...
    'cone_csv_path', '', ...
    'file_hashes', struct( ...
        'attempt_mat_sha256', '', ...
        'baseline_csv_sha256', '', ...
        'contact_settle_csv_sha256', '', ...
        'cone_csv_sha256', ''), ...
    'finished_local', '', ...
    'error', '');
end

function baseline = emptySamplingPointBaseline()
baseline = struct( ...
    'valid', false, ...
    'reason', 'NOT_CAPTURED', ...
    'sample_count', 0, ...
    'raw_force_n', zeros(0, 3), ...
    'raw_torque_nm', zeros(0, 3), ...
    'source_stamp_s', zeros(0, 1), ...
    'source_age_s', zeros(0, 1), ...
    'sample_elapsed_s', zeros(0, 1), ...
    'force_n', [NaN, NaN, NaN], ...
    'torque_nm', [NaN, NaN, NaN], ...
    'force_std_n', [NaN, NaN, NaN], ...
    'torque_std_nm', [NaN, NaN, NaN], ...
    'sustained_rate_hz', NaN, ...
    'average_rate_hz', NaN, ...
    'p95_source_interval_s', NaN, ...
    'maximum_source_interval_s', NaN);
end

function settle = emptySamplingContactSettle()
settle = struct( ...
    'valid', false, ...
    'reason', 'NOT_RUN', ...
    'quality_grade', 'NOT_OBSERVED', ...
    'off_target_continuation', false, ...
    'completion_first_continuation', false, ...
    'motion_commands_issued', false, ...
    'sample_count', 0, ...
    'stable_sample_count', 0, ...
    'adjustment_command_count', 0, ...
    'unobserved_adjustment_count', 0, ...
    'raw_force_n', zeros(0, 3), ...
    'raw_torque_nm', zeros(0, 3), ...
    'relative_force_world_n', zeros(0, 3), ...
    'relative_torque_world_nm', zeros(0, 3), ...
    'normal_force_n', zeros(0, 1), ...
    'source_stamp_s', zeros(0, 1), ...
    'source_age_s', zeros(0, 1), ...
    'sample_elapsed_s', zeros(0, 1), ...
    'measured_pose_mm_rad', zeros(0, 6), ...
    'commanded_delta_mm', zeros(0, 3), ...
    'final_normal_mean_n', NaN, ...
    'final_normal_std_n', NaN, ...
    'final_normal_min_n', NaN, ...
    'final_normal_max_n', NaN, ...
    'final_pose_mm_rad', [], ...
    'z_adjustment_mm', NaN, ...
    'observed_dwell_s', NaN, ...
    'elapsed_s', NaN);
end

function [ctx, baseline] = captureSamplingPointBaseline(ctx, phase)
baseline = emptySamplingPointBaseline();
count = ctx.cfg.sampling.baseline_samples;
forces = zeros(count, 3);
torques = zeros(count, 3);
stamps = zeros(count, 1);
ages = zeros(count, 1);
elapsed = zeros(count, 1);
for index = 1:count
    [ctx, sample] = receiveWrench(ctx, phase, [], true, false);
    enforceSamplingHardWrenchSample(ctx, sample, phase);
    forces(index, :) = sample.force_n;
    torques(index, :) = sample.torque_nm;
    stamps(index) = sample.stamp_s;
    ages(index) = sample.age_s;
    elapsed(index) = sample.elapsed_s;
end
intervalsS = diff(stamps);
durationS = stamps(end) - stamps(1);
assert(durationS > 0.0 && all(intervalsS > 0.0), ...
    'M12Demo:SamplingBaselineTimestamp', ...
    'Fresh Bota timestamps did not progress during the point baseline.');
averageRateHz = (count - 1) / durationS;
sustainedRateHz = 1.0 / median(intervalsS);
sortedIntervalsS = sort(intervalsS);
p95Index = max(1, ceil(0.95 * numel(sortedIntervalsS)));
forceStd = std(forces, 0, 1);
torqueStd = std(torques, 0, 1);
baseline.sample_count = count;
baseline.raw_force_n = forces;
baseline.raw_torque_nm = torques;
baseline.source_stamp_s = stamps;
baseline.source_age_s = ages;
baseline.sample_elapsed_s = elapsed;
baseline.force_n = mean(forces, 1);
baseline.torque_nm = mean(torques, 1);
baseline.force_std_n = forceStd;
baseline.torque_std_nm = torqueStd;
baseline.sustained_rate_hz = sustainedRateHz;
baseline.average_rate_hz = averageRateHz;
baseline.p95_source_interval_s = sortedIntervalsS(p95Index);
baseline.maximum_source_interval_s = max(intervalsS);
if sustainedRateHz < ctx.cfg.sensor.minimum_receive_rate_hz
    baseline.reason = 'INSUFFICIENT_FRESH_SAMPLE_RATE';
elseif max(forceStd) > ctx.cfg.sensor.maximum_force_axis_std_n
    baseline.reason = 'FORCE_BASELINE_NOISE';
elseif max(torqueStd) > ctx.cfg.sensor.maximum_torque_axis_std_nm
    baseline.reason = 'TORQUE_BASELINE_NOISE';
else
    baseline.valid = true;
    baseline.reason = 'PASS';
    ctx.baseline_force = baseline.force_n;
    ctx.baseline_torque = baseline.torque_nm;
    ctx.baseline_force_std_n = forceStd;
    ctx.baseline_torque_std_nm = torqueStd;
    worldFromTcp = kukaAbcToRotm(ctx.last_pose(4:6));
    worldFromSensor = worldFromTcp * ctx.sensor_to_tcp_rotation;
    ctx.baseline_force_world = ...
        (worldFromSensor * ctx.baseline_force.').';
    ctx.baseline_torque_world = ...
        (worldFromSensor * ctx.baseline_torque.').';
    ctx.baseline_ready = true;
end
end

function [ctx, baseline, touchdown, safeAirZMm, evidence] = acquireSamplingTouchdownWithRetries( ...
        ctx, homePose, safeAirZMm, targetWorldXY, executionIndex)
baseline = emptySamplingPointBaseline();
touchdown = makeEmptySamplingTouchdown( ...
    ctx.last_pose, targetWorldXY, ctx.cfg);
evidence = struct( ...
    'attempt_count', 0, ...
    'touchdown_attempt_count', 0, ...
    'retry_reasons', {cell(0, 1)}, ...
    'succeeded', false);
maximumForceN = 0.0;
maximumTorqueNm = 0.0;
maximumXYErrorMm = touchdown.maximum_target_xy_error_mm;

for acquisitionIndex = ...
        1:ctx.cfg.sampling.maximum_point_acquisition_attempts
    evidence.attempt_count = acquisitionIndex;
    ctx = setSamplingTopviewPhase(ctx, sprintf( ...
        'POINT_%02d_AIR_BASELINE_TRY_%02d', ...
        executionIndex, acquisitionIndex), true);
    [ctx, baseline] = captureSamplingPointBaseline( ...
        ctx, sprintf('SAMPLE_%02d_POINT_AIR_BASELINE_TRY_%02d', ...
            executionIndex, acquisitionIndex));
    if ~baseline.valid
        failureReason = ['POINT_AIR_BASELINE_CONTAMINATED_', ...
            baseline.reason];
        evidence.retry_reasons{end + 1, 1} = failureReason;
        logEvent(ctx.paths.events, ...
            'SAMPLING_POINT_ACQUISITION_RETRYABLE_BASELINE', sprintf( ...
            ['point %02d acquisition %d/%d: %s; no motion was ', ...
             'issued and a fresh 30-sample baseline will be retried ', ...
             'when budget remains.'], ...
            executionIndex, acquisitionIndex, ...
            ctx.cfg.sampling.maximum_point_acquisition_attempts, ...
            failureReason));
        if acquisitionIndex < ...
                ctx.cfg.sampling.maximum_point_acquisition_attempts
            continue;
        end
        return;
    end

    maximumDownMm = safeAirZMm - homePose(3) + ...
        ctx.cfg.sampling.maximum_touchdown_below_start_mm;
    assert(maximumDownMm > 0.0 && ...
            maximumDownMm <= ...
                ctx.cfg.motion.touchdown_maximum_down_mm, ...
        'M12Demo:SamplingTouchdownBudget', ...
        'The run-local sampling touchdown budget is invalid.');
    evidence.touchdown_attempt_count = ...
        evidence.touchdown_attempt_count + 1;
    ctx = setSamplingTopviewPhase(ctx, sprintf( ...
        'POINT_%02d_TOUCHDOWN_TRY_%02d', ...
        executionIndex, acquisitionIndex), true);
    [ctx, currentTouchdown] = guardedSamplingTouchdown( ...
        ctx, maximumDownMm, targetWorldXY, sprintf( ...
            'SAMPLE_%02d_TOUCHDOWN_TRY_%02d', ...
            executionIndex, acquisitionIndex));
    maximumForceN = max(maximumForceN, ...
        currentTouchdown.maximum_force_delta_n);
    maximumTorqueNm = max(maximumTorqueNm, ...
        currentTouchdown.maximum_torque_delta_nm);
    maximumXYErrorMm = max(maximumXYErrorMm, ...
        currentTouchdown.maximum_target_xy_error_mm);
    touchdown = currentTouchdown;
    touchdown.maximum_force_delta_n = maximumForceN;
    touchdown.maximum_torque_delta_nm = maximumTorqueNm;
    touchdown.maximum_target_xy_error_mm = maximumXYErrorMm;

    captureAtTouchdown = currentTouchdown.contact_confirmed && ...
        homePose(3) - currentTouchdown.pose_mm_rad(3) >= ...
            ctx.cfg.sampling.maximum_touchdown_below_start_mm - ...
            ctx.cfg.sampling.touchdown_step_mm;
    if currentTouchdown.contact_confirmed && ...
            currentTouchdown.landing_gate_passed && ...
            ~captureAtTouchdown
        evidence.succeeded = true;
        return;
    end
    if captureAtTouchdown
        failureReason = ...
            'CAPTURE_OR_BORE_ENTRY_DETECTED_DURING_TOUCHDOWN';
    elseif ~currentTouchdown.landing_gate_passed
        failureReason = ...
            'MEASURED_CONTACT_XY_OUTSIDE_PLAN_TOLERANCE';
    else
        failureReason = ...
            'NO_PERSISTENT_CONTACT_WITHIN_RUN_LOCAL_TOUCHDOWN_BUDGET';
    end
    evidence.retry_reasons{end + 1, 1} = failureReason;
    if captureAtTouchdown || acquisitionIndex >= ...
            ctx.cfg.sampling.maximum_point_acquisition_attempts
        return;
    end

    logEvent(ctx.paths.events, ...
        'SAMPLING_POINT_ACQUISITION_RETRY_AFTER_CLEAR_RETRACT', sprintf( ...
        ['point %02d acquisition %d/%d: %s; performing a verified ', ...
         'clear retract, re-anchoring the same target XY, and taking a ', ...
         'new point-local baseline before retry.'], ...
        executionIndex, acquisitionIndex, ...
        ctx.cfg.sampling.maximum_point_acquisition_attempts, ...
        failureReason));
    [ctx, safeAirZMm, ~] = retractSamplingUntilClear( ...
        ctx, homePose, safeAirZMm, sprintf( ...
            'SAMPLE_%02d_RETRY_%02d_RETRACT', ...
            executionIndex, acquisitionIndex));
    [ctx, ~] = moveAirSegmented(ctx, ...
        [targetWorldXY, safeAirZMm], sprintf( ...
            'SAMPLE_%02d_RETRY_%02d_AIR_RESET', ...
            executionIndex, acquisitionIndex));
    [ctx, ~] = requireWrenchClearDwells(ctx, sprintf( ...
        'SAMPLE_%02d_RETRY_%02d_PRE_TOUCH_CLEAR', ...
        executionIndex, acquisitionIndex));
end
end

function touchdown = makeEmptySamplingTouchdown( ...
        measuredPose, targetWorldXY, cfg)
targetWorldXY = double(reshape(targetWorldXY, 1, 2));
initialErrorMm = norm(measuredPose(1:2) - targetWorldXY);
touchdown = struct( ...
    'contact_confirmed', false, ...
    'landing_gate_passed', ...
        initialErrorMm <= ...
            cfg.sampling.maximum_touchdown_xy_lock_error_mm, ...
    'pose_mm_rad', measuredPose, ...
    'maximum_force_delta_n', 0.0, ...
    'maximum_torque_delta_nm', 0.0, ...
    'maximum_target_xy_error_mm', initialErrorMm, ...
    'cumulative_lateral_motion_mm', 0.0, ...
    'normal_sign_world_z', NaN);
end

function [ctx, touchdown] = guardedSamplingTouchdown( ...
        ctx, maximumDownMm, targetWorldXY, phase)
segment = ctx.cfg.sampling.touchdown_step_mm;
segmentCount = ceil(maximumDownMm / segment);
targetWorldXY = double(reshape(targetWorldXY, 1, 2));
previousXY = ctx.last_pose(1:2);
% This value only suppresses sub-resolution XY chatter while descending.
% Keep a local completion-first fallback so a partially refreshed config can
% never strand the robot in air after it has already reached the point.
if isfield(ctx.cfg.sampling, ...
        'touchdown_xy_correction_deadband_mm') && ...
        isfinite(ctx.cfg.sampling.touchdown_xy_correction_deadband_mm) && ...
        ctx.cfg.sampling.touchdown_xy_correction_deadband_mm >= 0.0
    correctionDeadbandMm = ...
        ctx.cfg.sampling.touchdown_xy_correction_deadband_mm;
else
    correctionDeadbandMm = 0.08;
    logEvent(ctx.paths.events, ...
        'SAMPLING_TOUCHDOWN_CONFIG_DEFAULT_RECOVERED_CONTINUE', ...
        ['touchdown_xy_correction_deadband_mm was absent or invalid; ', ...
         'using the built-in 0.08 mm completion-first default.']);
end
touchdown = makeEmptySamplingTouchdown( ...
    ctx.last_pose, targetWorldXY, ctx.cfg);
if ~touchdown.landing_gate_passed
    return;
end
for index = 1:segmentCount
    remaining = maximumDownMm - (index - 1) * segment;
    step = min(segment, remaining);
    correctionXY = targetWorldXY - ctx.last_pose(1:2);
    correctionNorm = norm(correctionXY);
    if correctionNorm <= correctionDeadbandMm
        correctionXY = [0.0, 0.0];
    elseif correctionNorm > ...
            ctx.cfg.sampling.touchdown_xy_lock_warning_mm
        correctionXY = correctionXY * ...
            (ctx.cfg.sampling.touchdown_xy_lock_warning_mm / ...
             correctionNorm);
    end
    [ctx, pose] = moveOne(ctx, ...
        [correctionXY, -step], ctx.cfg.sampling.touchdown_speed_mm_s, ...
        ctx.cfg.sampling.step_tracking_tolerance_mm, ...
        sprintf('%s_%03d', phase, index));
    touchdown.cumulative_lateral_motion_mm = ...
        touchdown.cumulative_lateral_motion_mm + ...
        norm(pose(1:2) - previousXY);
    targetErrorMm = norm(pose(1:2) - targetWorldXY);
    touchdown.maximum_target_xy_error_mm = max( ...
        touchdown.maximum_target_xy_error_mm, targetErrorMm);
    touchdown.pose_mm_rad = pose;
    previousXY = pose(1:2);
    [ctx, guard] = guardDwell(ctx, [phase, '_DWELL'], ...
        ctx.cfg.sensor.contact_consecutive_samples, ...
        ctx.cfg.sensor.contact_event_n);
    ctx = updateSamplingTopviewEndpoint(ctx, phase, pose, true);
    touchdown.maximum_force_delta_n = max( ...
        touchdown.maximum_force_delta_n, guard.maximum_force_delta_n);
    touchdown.maximum_torque_delta_nm = max( ...
        touchdown.maximum_torque_delta_nm, guard.maximum_torque_delta_nm);
    if targetErrorMm > ...
            ctx.cfg.sampling.maximum_touchdown_xy_lock_error_mm
        touchdown.landing_gate_passed = false;
        return;
    end
    if guard.event_confirmed
        touchdown.contact_confirmed = true;
        touchdown.pose_mm_rad = pose;
        worldFz = guard.median_force_world_n(3);
        touchdown.normal_sign_world_z = sign(worldFz);
        if touchdown.normal_sign_world_z == 0
            touchdown.normal_sign_world_z = ...
                sign(guard.last_sample.force_world_n(3));
        end
        if touchdown.normal_sign_world_z == 0
            touchdown.normal_sign_world_z = -1.0;
        end
        return;
    end
end
end

function [ctx, settle] = observeSamplingContactBeforeCone( ...
        ctx, touchdownPose, targetWorldXY, normalSignWorldZ, phase)
settle = emptySamplingContactSettle();
policy = ctx.cfg.sampling.contact_stability;
targetWorldXY = double(reshape(targetWorldXY, 1, 2));
touchdownPose = double(reshape(touchdownPose, 1, 6));
assert(any(normalSignWorldZ == [-1.0, 1.0]), ...
    'M12Demo:SamplingContactNormalSign', ...
    '%s has no finite touchdown normal sign.', phase);

% Completion-first acquisition rule:
% touchdown has already proved persistent contact and supplied the measured
% XY label.  Do not excite the discrete KST endpoint quantizer with another
% PTP force-settle loop.  Observe fresh Bota samples at the unchanged pose,
% grade the preload for offline QC, and let the 40 Hz cone's continuous
% force-following/low-force-reacquisition channels handle the load.
settleClock = tic;
while true
    [ctx, sample] = receiveWrench(ctx, phase, [], true, false);
    enforceSamplingHardWrenchSample(ctx, sample, phase);
    [settle, ~] = appendSamplingSettleObservation( ...
        settle, sample, ctx.last_pose, [0.0, 0.0, 0.0], ...
        normalSignWorldZ);
    xyErrorMm = norm(ctx.last_pose(1:2) - targetWorldXY);
    if xyErrorMm > ...
            ctx.cfg.sampling.maximum_touchdown_xy_lock_error_mm
        settle.reason = 'XY_LOCK_ERROR';
        error('M12Demo:SamplingContactObservationXYLock', ...
            ['%s measured XY error %.3f mm exceeded the %.3f mm ', ...
             'sampling landing gate before cone motion.'], ...
            phase, xyErrorMm, ...
            ctx.cfg.sampling.maximum_touchdown_xy_lock_error_mm);
    end
    observedS = toc(settleClock);
    if observedS >= policy.passive_observation_s && ...
            settle.sample_count >= policy.minimum_samples
        break;
    end
    if observedS >= policy.maximum_observation_s
        break;
    end
end

settle.elapsed_s = toc(settleClock);
settle.final_pose_mm_rad = ctx.last_pose;
cachedPoseChange = norm(ctx.last_pose - touchdownPose);
assert(cachedPoseChange <= 1e-12, ...
    'M12Demo:SamplingPassiveObservationMovedPose', ...
    ['%s changed the cached touchdown pose by %.9f without an ', ...
     'authorized motion stage.'], phase, cachedPoseChange);
settle.z_adjustment_mm = ...
    ctx.last_pose(3) - touchdownPose(3);
settle.motion_commands_issued = false;
assert(settle.sample_count >= 1, ...
    'M12Demo:SamplingContactObservationEmpty', ...
    '%s returned without a fresh Bota observation.', phase);
settle.observed_dwell_s = 0.0;
if settle.sample_count >= 2
    settle.observed_dwell_s = ...
        settle.sample_elapsed_s(end) - settle.sample_elapsed_s(1);
end
settle.final_normal_mean_n = mean(settle.normal_force_n);
settle.final_normal_std_n = std(settle.normal_force_n, 0, 1);
settle.final_normal_min_n = min(settle.normal_force_n);
settle.final_normal_max_n = max(settle.normal_force_n);
preferredBand = abs(settle.normal_force_n - ...
    policy.target_normal_force_n) <= policy.force_deadband_n;
settle.stable_sample_count = sum(preferredBand);
preferredQuality = settle.sample_count >= policy.minimum_samples && ...
    settle.observed_dwell_s >= policy.minimum_dwell_s && ...
    all(preferredBand) && ...
    settle.final_normal_std_n <= policy.maximum_force_std_n;

% The observation itself is valid after one fresh, hard-guarded sample.
% Sample count, dwell, force magnitude and force variance affect only the
% quality grade.  They cannot silently remove a cone from a confirmed point.
settle.valid = true;
if preferredQuality
    settle.reason = 'PASS_PREFERRED_STABLE_LOAD';
    settle.quality_grade = 'PREFERRED_STABLE_LOAD';
    logEvent(ctx.paths.events, ...
        'SAMPLING_PASSIVE_CONTACT_OBSERVATION_PREFERRED', sprintf( ...
        ['%s observed %d fresh samples over %.3f s at %.3f +/- ', ...
         '%.3f N without issuing motion; proceeding to cone.'], ...
        phase, settle.sample_count, settle.observed_dwell_s, ...
        settle.final_normal_mean_n, settle.final_normal_std_n));
else
    settle.reason = 'PASS_COMPLETION_FIRST_CONTACT_OBSERVED';
    settle.quality_grade = 'NONPREFERRED_LOAD_PENDING_OFFLINE_QC';
    settle.off_target_continuation = true;
    settle.completion_first_continuation = true;
    logEvent(ctx.paths.events, ...
        'SAMPLING_PASSIVE_CONTACT_OBSERVATION_TAGGED_CONTINUE', sprintf( ...
        ['%s observed %d fresh samples over %.3f s at %.3f +/- ', ...
         '%.3f N (range %.3f..%.3f N) without issuing motion.  ', ...
         'The preferred-load grade was not met, but confirmed contact ', ...
         'continues to cone and remains explicitly pending offline QC.'], ...
        phase, settle.sample_count, settle.observed_dwell_s, ...
        settle.final_normal_mean_n, settle.final_normal_std_n, ...
        settle.final_normal_min_n, settle.final_normal_max_n));
end
end

function [settle, measuredNormalN] = appendSamplingSettleObservation( ...
        settle, sample, measuredPose, commandedDelta, normalSignWorldZ)
measuredNormalN = max( ...
    0.0, normalSignWorldZ * sample.force_world_n(3));
settle.raw_force_n(end + 1, :) = sample.force_n;
settle.raw_torque_nm(end + 1, :) = sample.torque_nm;
settle.relative_force_world_n(end + 1, :) = sample.force_world_n;
settle.relative_torque_world_nm(end + 1, :) = sample.torque_world_nm;
settle.normal_force_n(end + 1, 1) = measuredNormalN;
settle.source_stamp_s(end + 1, 1) = sample.stamp_s;
settle.source_age_s(end + 1, 1) = sample.age_s;
settle.sample_elapsed_s(end + 1, 1) = sample.elapsed_s;
settle.measured_pose_mm_rad(end + 1, :) = measuredPose;
settle.commanded_delta_mm(end + 1, :) = commandedDelta;
settle.sample_count = settle.sample_count + 1;
end

function enforceSamplingHardWrenchSample(ctx, sample, phase)
assert(sample.force_delta_n < ctx.cfg.sensor.hard_force_delta_n, ...
    'M12Demo:HardForceGuard', ...
    '%s relative force %.3f N reached the hard guard.', ...
    phase, sample.force_delta_n);
assert(sample.torque_delta_nm < ctx.cfg.sensor.hard_torque_delta_nm, ...
    'M12Demo:HardTorqueGuard', ...
    '%s relative torque %.4f Nm reached the hard guard.', ...
    phase, sample.torque_delta_nm);
end

function [ctx, safeAirZMm, aggregate] = retractSamplingUntilClear( ...
        ctx, homePose, safeAirZMm, phase)
assert(~ctx.direct_servo_active, 'M12Demo:SamplingRetractDirectServoState', ...
    'Adaptive retract is forbidden while DirectServo state is active.');
maximumAirZMm = homePose(3) + ctx.cfg.sampling.maximum_retract_mm;
initialCampaignLift = contains(phase, 'SAMPLING_INITIAL_LIFT');
if initialCampaignLift
    % Retain the one-time 2 mm initial lift before the first XY move: the
    % operator-taught centre may sit just above or partly inside the chamfer.
    targetZMm = min(maximumAirZMm, max( ...
        safeAirZMm, homePose(3) + ctx.cfg.sampling.initial_lift_mm));
else
    % Point transit is driven by measured unload, not the old global
    % home+2 mm plane.  The first 0.75 mm segment was already wrench-clear
    % in the 2026-07-28 M12 trace, so test there and stop when both fresh
    % windows agree.
    targetZMm = min(maximumAirZMm, ...
        ctx.last_pose(3) + ctx.cfg.sampling.preferred_retract_mm);
end
aggregate = struct('maximum_force_delta_n', 0.0, ...
    'maximum_torque_delta_nm', 0.0);
while true
    if targetZMm - ctx.last_pose(3) > ...
            ctx.cfg.sampling.air_endpoint_tolerance_mm
        [ctx, ~] = moveAirSegmented(ctx, ...
            [ctx.last_pose(1:2), targetZMm], phase, false);
    end
    [ctx, observation, clear] = observeSamplingClearDwells( ...
        ctx, [phase, '_CLEAR']);
    aggregate.maximum_force_delta_n = max( ...
        aggregate.maximum_force_delta_n, ...
        observation.maximum_force_delta_n);
    aggregate.maximum_torque_delta_nm = max( ...
        aggregate.maximum_torque_delta_nm, ...
        observation.maximum_torque_delta_nm);
    if clear
        safeAirZMm = ctx.last_pose(3);
        logEvent(ctx.paths.events, ...
            'SAMPLING_ADAPTIVE_CLEAR_HEIGHT_ACCEPTED', sprintf( ...
            ['%s accepted measured clear Z %.3f mm after the local ', ...
             'retract probe; dF %.3f N, dT %.4f Nm'], ...
            phase, safeAirZMm, ...
            observation.maximum_force_delta_n, ...
            observation.maximum_torque_delta_nm));
        return;
    end
    assert(targetZMm < maximumAirZMm - 1e-9, ...
        'M12Demo:SamplingClearanceNotAchieved', ...
        ['%s remained loaded at the maximum %.2f mm run-local retract.  ', ...
         'No lateral or automatic return command is permitted.'], ...
        phase, ctx.cfg.sampling.maximum_retract_mm);
    targetZMm = min(maximumAirZMm, targetZMm + ...
        ctx.cfg.sampling.retract_extension_step_mm);
end
end

function [ctx, observation, clear] = observeSamplingClearDwells(ctx, phase)
maximumForce = 0.0;
maximumTorque = 0.0;
clear = true;
for dwellIndex = 1:ctx.cfg.sampling.wrench_clear_dwell_count
    for sampleIndex = 1:ctx.cfg.sampling.wrench_clear_samples_per_dwell
        [ctx, sample] = receiveWrench(ctx, sprintf( ...
            '%s_DWELL_%d', phase, dwellIndex));
        enforceSamplingHardWrenchSample(ctx, sample, phase);
        maximumForce = max(maximumForce, sample.force_delta_n);
        maximumTorque = max(maximumTorque, sample.torque_delta_nm);
        clear = clear && ...
            sample.force_delta_n < ...
                ctx.cfg.sampling.wrench_clear_force_delta_n && ...
            sample.torque_delta_nm < ...
                ctx.cfg.sampling.wrench_clear_torque_delta_nm;
    end
end
observation = struct( ...
    'maximum_force_delta_n', maximumForce, ...
    'maximum_torque_delta_nm', maximumTorque);
end

function ctx = setSamplingTopviewPhase(ctx, phase, allowDrawnow)
forceRender = contains(char(phase), '界面冻结');
ctx = bestEffortSamplingTopviewAction(ctx, ...
    'phase', struct( ...
        'name', phase, 'allow_drawnow', logical(allowDrawnow), ...
        'force_render', forceRender));
end

function ctx = bestEffortSamplingTopviewAction(ctx, action, payload)
if ~isfield(ctx, 'sampling_dashboard') || ...
        ~isstruct(ctx.sampling_dashboard) || ...
        ~isfield(ctx.sampling_dashboard, 'enabled') || ...
        ~ctx.sampling_dashboard.enabled
    return;
end
try
    ctx.sampling_dashboard = callSamplingTopview( ...
        ctx.cfg, action, ctx.sampling_dashboard, payload);
catch dashboardError
    ctx.sampling_dashboard.enabled = false;
    ctx.sampling_dashboard.failure = sprintf('%s: %s', ...
        dashboardError.identifier, oneLine(dashboardError.message));
    if isfield(ctx, 'paths') && isfield(ctx.paths, 'events')
        bestEffortLogEvent(ctx.paths.events, ...
            'SAMPLING_TOPVIEW_DISABLED_NO_CONTROL_EFFECT', ...
            ctx.sampling_dashboard.failure);
    end
end
end

function ctx = updateSamplingTopviewEndpoint( ...
        ctx, phase, measuredPose, allowDrawnow)
if ~isfield(ctx, 'sampling_dashboard') || ...
        ~ctx.sampling_dashboard.enabled
    return;
end
measuredFixture = worldPointToFixture( ...
    measuredPose(1:3), ctx.cfg.frame);
commandFixture = worldPointToFixture( ...
    ctx.last_command_pose(1:3), ctx.cfg.frame);
ctx = bestEffortSamplingTopviewAction(ctx, ...
    'endpoint', struct( ...
        'measured_fixture_xy_mm', measuredFixture(1:2), ...
        'command_fixture_xy_mm', commandFixture(1:2), ...
        'name', phase, ...
        'allow_drawnow', logical(allowDrawnow)));
end

function ctx = appendSamplingConeToTopview(ctx, cone)
if ~isfield(ctx, 'sampling_dashboard') || ...
        ~ctx.sampling_dashboard.enabled
    return;
end
measuredWorld = [ ...
    cone.pre_directservo_pose_mm_rad(1:3); ...
    cone.post_stop_pose_mm_rad(1:3)];
measuredWorld = measuredWorld( ...
    all(isfinite(measuredWorld), 2), :);
allCommandWorld = cone.all_command_pose_mm_rad(:, 1:3);
maximumConeDisplayPoints = 200;
displayStride = max(1, ceil( ...
    size(allCommandWorld, 1) / maximumConeDisplayPoints));
displayIndices = unique([ ...
    1:displayStride:size(allCommandWorld, 1), ...
    size(allCommandWorld, 1)]);
commandWorld = allCommandWorld(displayIndices, :);
% The DirectServo stream has no synchronous KST pose feedback.  Preserve the
% two measured boundary endpoints as isolated blue points, never as a blue
% line that could be mistaken for a measured cone trajectory.
measuredFixture = NaN(max(1, 2 * size(measuredWorld, 1) - 1), 2);
commandFixture = zeros(size(commandWorld, 1), 2);
for index = 1:size(measuredWorld, 1)
    fixturePoint = worldPointToFixture( ...
        measuredWorld(index, :), ctx.cfg.frame);
    measuredFixture(2 * index - 1, :) = fixturePoint(1:2);
end
for index = 1:size(commandWorld, 1)
    fixturePoint = worldPointToFixture( ...
        commandWorld(index, :), ctx.cfg.frame);
    commandFixture(index, :) = fixturePoint(1:2);
end
ctx.sampling_dashboard = callSamplingTopview( ...
    ctx.cfg, 'cone_batch', ctx.sampling_dashboard, struct( ...
        'measured_fixture_xy_mm', measuredFixture, ...
        'command_fixture_xy_mm', commandFixture, ...
        'name', 'CONE_COMPLETE_BATCH_REFRESH', ...
        'allow_drawnow', true));
end

function dashboard = callSamplingTopview( ...
        cfg, action, dashboard, varargin)
dashboardFunction = char(cfg.sampling.dashboard_function);
assert(any(strcmp(dashboardFunction, { ...
        'm12_sampling_topview_dashboard', ...
        'm10_sampling_topview_dashboard', ...
        'm8_sampling_topview_dashboard'})), ...
    'M12Demo:SamplingDashboardIdentity', ...
    'Unsupported sampling dashboard %s.', dashboardFunction);
dashboard = feval(dashboardFunction, action, dashboard, varargin{:});
end

function ctx = bestEffortAppendSamplingConeToTopview(ctx, cone)
try
    ctx = appendSamplingConeToTopview(ctx, cone);
catch dashboardError
    if isfield(ctx, 'sampling_dashboard') && ...
            isstruct(ctx.sampling_dashboard)
        ctx.sampling_dashboard.enabled = false;
        ctx.sampling_dashboard.failure = sprintf('%s: %s', ...
            dashboardError.identifier, oneLine(dashboardError.message));
    end
    try
        logEvent(ctx.paths.events, ...
            'SAMPLING_TOPVIEW_DISABLED_AFTER_CONE_NO_CONTROL_EFFECT', ...
            sprintf('%s: %s', dashboardError.identifier, ...
            oneLine(dashboardError.message)));
    catch
        % UI and UI diagnostics never affect acquisition or motion.
    end
end
end

function attempt = addSamplingConeEvidence( ...
        attempt, cone, settledPose, cfg)
attempt.cone_completed = cone.schedule_completed;
attempt.cone_physical_schedule_completed = ...
    logical(cone.physical_schedule_completed);
attempt.cone_directservo_stop_acknowledged = ...
    logical(cone.directservo_stop_acknowledged);
attempt.cone_post_stop_state_known = logical(cone.post_stop_state_known);
attempt.cone_post_stop_state_error_identifier = ...
    char(cone.post_stop_state_error_identifier);
attempt.cone_post_stop_state_error_message = ...
    char(cone.post_stop_state_error_message);
attempt.phase_coverage_fraction = cone.phase_coverage_fraction;
attempt.return_orientation_error_deg = ...
    cone.return_orientation_error_deg;
attempt.post_stop_tip_error_mm = cone.post_stop_tip_error_mm;
attempt.cone_mode_transition_outcome = cone.mode_transition_outcome;
attempt.cone_low_force_episodes = cone.low_force_episodes;
attempt.cone_force_relief_episodes = cone.force_relief_episodes;
attempt.cone_fast_force_relief_kicks = ...
    cone.fast_force_relief_kicks;
attempt.cone_direction_fingerprint_valid = ...
    cone.direction_fingerprint_valid;
attempt.cone_routing_fingerprint_valid = ...
    cone.routing_fingerprint_valid;
attempt.cone_training_fingerprint_valid = ...
    cone.training_fingerprint_valid;
attempt.weak_but_complete_fingerprint = ...
    cone.schedule_completed && ...
    (cone.low_force_episodes > 0 || ...
     cone.force_relief_episodes > 0 || ...
     ~cone.training_fingerprint_valid);
lateralForce = vecnorm(cone.force_world_n(:, 1:2), 2, 2);
if ~isempty(lateralForce)
    attempt.fingerprint_signal_rms_lateral_force_n = ...
        sqrt(mean(lateralForce .^ 2));
    attempt.fingerprint_signal_peak_lateral_force_n = ...
        max(lateralForce);
end
attempt.cone_pre_directservo_measured_pose_mm_rad = ...
    cone.pre_directservo_pose_mm_rad;
attempt.cone_post_directservo_measured_pose_mm_rad = ...
    cone.post_stop_pose_mm_rad;
attempt.cone_maximum_command_gap_s = cone.maximum_command_gap_s;
attempt.cone_maximum_tick_lateness_s = cone.maximum_tick_lateness_s;
attempt.capture_during_cone = cone.post_stop_state_known && ...
    cone.post_stop_pose_mm_rad(3) < settledPose(3) - ...
        cfg.sampling.capture_depth_below_touchdown_mm;
end

function [attempt, hashes] = exportSamplingAttemptEvidence( ...
        attempt, pointBaseline, contactSettle, cone, globalConeTracePath)
writeSamplingPointBaselineCsvAtomic( ...
    attempt.baseline_csv_path, pointBaseline);
writeSamplingContactSettleCsvAtomic( ...
    attempt.contact_settle_csv_path, contactSettle);
writeSamplingConeTraceCsvAtomic( ...
    attempt.cone_csv_path, cone, globalConeTracePath, ...
    attempt.cone_run_kind);
hashes = struct( ...
    'attempt_mat_sha256', '', ...
    'baseline_csv_sha256', sha256File(attempt.baseline_csv_path), ...
    'contact_settle_csv_sha256', ...
        sha256File(attempt.contact_settle_csv_path), ...
    'cone_csv_sha256', sha256File(attempt.cone_csv_path));
end

function writeSamplingPointBaselineCsvAtomic(path, baseline)
temporaryPath = [tempname(fileparts(path)), '.csv'];
fileId = fopen(temporaryPath, 'w');
assert(fileId >= 0, 'M12Demo:SamplingBaselineExport', ...
    'Cannot open temporary CSV for %s.', path);
closer = onCleanup(@() fclose(fileId));
fprintf(fileId, [ ...
    'source_stamp_s,source_age_s,sample_elapsed_s,', ...
    'raw_fx_n,raw_fy_n,raw_fz_n,raw_tx_nm,raw_ty_nm,raw_tz_nm\n']);
for index = 1:baseline.sample_count
    fprintf(fileId, [ ...
        '%.9f,%.9f,%.9f,%.9f,%.9f,%.9f,', ...
        '%.9f,%.9f,%.9f\n'], ...
        baseline.source_stamp_s(index), ...
        baseline.source_age_s(index), ...
        baseline.sample_elapsed_s(index), ...
        baseline.raw_force_n(index, :), ...
        baseline.raw_torque_nm(index, :));
end
clear closer;
[moved, moveMessage] = movefile(temporaryPath, path, 'f');
assert(moved, 'M12Demo:SamplingBaselineAtomicCommit', ...
    'Cannot atomically commit %s: %s', path, moveMessage);
end

function writeSamplingContactSettleCsvAtomic(path, settle)
temporaryPath = [tempname(fileparts(path)), '.csv'];
fileId = fopen(temporaryPath, 'w');
assert(fileId >= 0, 'M12Demo:SamplingSettleExport', ...
    'Cannot open temporary CSV for %s.', path);
closer = onCleanup(@() fclose(fileId));
fprintf(fileId, [ ...
    'source_stamp_s,source_age_s,sample_elapsed_s,normal_force_n,', ...
    'raw_fx_n,raw_fy_n,raw_fz_n,raw_tx_nm,raw_ty_nm,raw_tz_nm,', ...
    'rel_fx_world_n,rel_fy_world_n,rel_fz_world_n,', ...
    'rel_tx_world_nm,rel_ty_world_nm,rel_tz_world_nm,', ...
    'x_mm,y_mm,z_mm,a_rad,b_rad,c_rad,cmd_dx_mm,cmd_dy_mm,cmd_dz_mm\n']);
for index = 1:settle.sample_count
    fprintf(fileId, [ ...
        '%.9f,%.9f,%.9f,%.9f,', ...
        '%.9f,%.9f,%.9f,%.9f,%.9f,%.9f,', ...
        '%.9f,%.9f,%.9f,%.9f,%.9f,%.9f,', ...
        '%.9f,%.9f,%.9f,%.9f,%.9f,%.9f,', ...
        '%.9f,%.9f,%.9f\n'], ...
        settle.source_stamp_s(index), ...
        settle.source_age_s(index), ...
        settle.sample_elapsed_s(index), ...
        settle.normal_force_n(index), ...
        settle.raw_force_n(index, :), ...
        settle.raw_torque_nm(index, :), ...
        settle.relative_force_world_n(index, :), ...
        settle.relative_torque_world_nm(index, :), ...
        settle.measured_pose_mm_rad(index, :), ...
        settle.commanded_delta_mm(index, :));
end
clear closer;
[moved, moveMessage] = movefile(temporaryPath, path, 'f');
assert(moved, 'M12Demo:SamplingSettleAtomicCommit', ...
    'Cannot atomically commit %s: %s', path, moveMessage);
end

function writeSamplingConeTraceCsvAtomic( ...
        path, cone, globalPath, expectedRunKind)
temporaryPath = [tempname(fileparts(path)), '.csv'];
runKind = char(expectedRunKind);
if ~isempty(fieldnames(cone)) && isfield(cone, 'run_kind')
    runKind = char(cone.run_kind);
end
if isempty(runKind) || ~isfile(globalPath)
    writeEmptySamplingConeTraceCsv(temporaryPath);
else
    trace = readtable(globalPath, 'VariableNamingRule', 'preserve');
    if ~ismember('run_kind', trace.Properties.VariableNames)
        writeEmptySamplingConeTraceCsv(temporaryPath);
    else
        mask = strcmp(string(trace.run_kind), string(runKind));
        attemptTrace = trace(mask, :);
        if isempty(attemptTrace)
            writeEmptySamplingConeTraceCsv(temporaryPath);
        else
            writetable(attemptTrace, temporaryPath);
        end
    end
end
[moved, moveMessage] = movefile(temporaryPath, path, 'f');
assert(moved, 'M12Demo:SamplingConeTraceAtomicCommit', ...
    'Cannot atomically commit %s: %s', path, moveMessage);
end

function writeEmptySamplingConeTraceCsv(path)
    writeText(path, [ ...
        'wall_time,elapsed_s,run_kind,stage,schedule_fraction,phase_rad,', ...
        'source_stamp_s,wrench_age_s,reference_kind,', ...
        'reference_orientation_error_deg,tick_lateness_s,feedback_observed,', ...
        'cmd_x_mm,cmd_y_mm,cmd_z_mm,cmd_a_rad,cmd_b_rad,cmd_c_rad,', ...
        'actual_x_mm,actual_y_mm,actual_z_mm,actual_a_rad,actual_b_rad,actual_c_rad,', ...
        'tip_error_mm,tilt_cmd_deg,tilt_actual_deg,', ...
        'raw_fx_n,raw_fy_n,raw_fz_n,raw_tx_nm,raw_ty_nm,raw_tz_nm,', ...
        'fx_world_star_n,fy_world_star_n,fz_world_star_n,', ...
        'tx_world_star_nm,ty_world_star_nm,tz_world_star_nm,', ...
        'force_delta_norm_n,torque_delta_norm_nm', newline]);
end

function attempt = addMeasuredSamplingLabel( ...
        attempt, touchdownPose, plan, cfg)
measuredWorldXY = double(touchdownPose(1:2));
measuredXY = measuredWorldXY - ...
    plan.run_local_center_world_xy_mm;
samplingErrorMm = norm( ...
    measuredWorldXY - attempt.target_world_xy_mm);
labelVector = plan.run_local_center_world_xy_mm - measuredWorldXY;
labelRadiusMm = norm(labelVector);
attempt.measured_contact_fixture_xy_mm = measuredXY;
attempt.measured_sampling_error_mm = samplingErrorMm;
attempt.cad_distance_to_center_mm = labelRadiusMm;
if labelRadiusMm <= cfg.sampling.minimum_direction_label_radius_mm
    attempt.measured_label_gate_reason = ...
        'MEASURED_CONTACT_TOO_CLOSE_TO_CENTER_FOR_DIRECTION_LABEL';
    return;
end
labelUnit = labelVector / labelRadiusMm;
labelAngleDeg = mod(rad2deg(atan2(labelUnit(2), labelUnit(1))), 360.0);
directionDeviationDeg = circularErrorDeg( ...
    labelAngleDeg, attempt.nominal_direction_fixture_deg);
attempt.true_direction_fixture_unit = labelUnit;
attempt.true_direction_fixture_deg = labelAngleDeg;
attempt.true_direction_world_xy = labelUnit;
attempt.measured_label_direction_deviation_deg = ...
    directionDeviationDeg;
if samplingErrorMm > ...
        cfg.sampling.maximum_measured_sampling_error_mm
    attempt.measured_label_gate_reason = ...
        'MEASURED_CONTACT_XY_OUTSIDE_PLAN_TOLERANCE';
    return;
end
attempt.measured_label_gate_passed = true;
attempt.measured_label_direction_warning = directionDeviationDeg > ...
    cfg.sampling.maximum_label_direction_deviation_deg;
if attempt.measured_label_direction_warning
    attempt.measured_label_gate_reason = ...
        'PASS_DIRECTION_DEVIATION_RECORDED_FOR_OFFLINE_QC';
else
    attempt.measured_label_gate_reason = 'PASS';
end
end

function attempt = classifyCompletedSamplingAttempt(attempt, cfg)
switch attempt.requested_partition
    case 'clean_candidate'
        attempt.status = 'CLEAN_CANDIDATE_PENDING_OFFLINE_QC';
        attempt.offline_training_candidate = true;
    case 'holdout'
        attempt.status = 'HOLDOUT_NEVER_TRAIN';
    case 'quarantine'
        attempt.status = 'PLANNED_QUARANTINE_DIAGNOSTIC_ONLY';
    case 'sentinel'
        attempt.status = ...
            'SENTINEL_REPEATABILITY_ONLY_NOT_INDEPENDENT_TRAINING';
    otherwise
        error('M12Demo:SamplingPartitionUnknown', ...
            'Unknown sampling partition %s.', ...
            attempt.requested_partition);
end
% Even a successful clean trace must pass offline grouping, drift, and
% leakage checks before a separate immutable dataset builder may admit it.
attempt.automatic_training_admission = false;
attempt.data_quality_status = attempt.status;
end

function attempt = quarantineSamplingAttempt(attempt, reason)
attempt.effective_partition = 'quarantine';
attempt.status = 'QUARANTINED_NEVER_TRAIN';
attempt.quarantine_reason = char(reason);
attempt.offline_training_candidate = false;
attempt.automatic_training_admission = false;
attempt.data_quality_status = attempt.status;
end

function campaign = appendSamplingAttempt(campaign, attempt)
existingIndex = find([campaign.attempts.execution_index] == ...
    attempt.execution_index);
assert(numel(existingIndex) <= 1, ...
    'M12Demo:SamplingCampaignDuplicateExecutionIndex', ...
    'Campaign contains duplicate execution index %d.', ...
    attempt.execution_index);
if isempty(existingIndex)
    campaign.attempts(end + 1, 1) = attempt;
else
    campaign.attempts(existingIndex, 1) = attempt;
end
campaign = refreshSamplingCampaignCounters(campaign);
end

function campaign = refreshSamplingCampaignCounters(campaign)
if isempty(campaign.attempts)
    executionIndices = zeros(1, 0);
else
    executionIndices = [campaign.attempts.execution_index];
end
assert(numel(unique(executionIndices)) == numel(executionIndices), ...
    'M12Demo:SamplingCampaignDuplicateExecutionIndex', ...
    'Campaign attempt records must have unique execution indices.');
campaign.attempts_completed = numel(campaign.attempts);
campaign.attempt_records_persisted = numel(campaign.attempts);
campaign.cones_completed = sum(arrayfun( ...
    @(value) logical(value.cone_completed), campaign.attempts));
campaign.points_committed = sum(arrayfun( ...
    @(value) logical(value.motion_lifecycle_closed), campaign.attempts));
campaign.original_retracts_verified = sum(arrayfun( ...
    @(value) logical(value.safe_retract_completed), campaign.attempts));
campaign.motion_lifecycles_closed = sum(arrayfun( ...
    @(value) logical(value.motion_lifecycle_closed), campaign.attempts));
completedExecutionIndices = [campaign.attempts( ...
    arrayfun(@(value) logical(value.cone_completed), ...
        campaign.attempts)).execution_index];
campaign.pending_execution_indices = setdiff( ...
    1:campaign.attempt_count_planned, completedExecutionIndices, ...
    'stable');
campaign.attempts_quarantined = sum(arrayfun( ...
    @(value) strcmp(value.effective_partition, 'quarantine'), ...
    campaign.attempts));
end

function value = samplingResumeField(resume, fieldName, defaultValue)
value = defaultValue;
if isstruct(resume) && isfield(resume, fieldName) && ...
        ~isempty(resume.(fieldName))
    value = resume.(fieldName);
end
end

function ctx = hydrateSamplingResumeDashboard(ctx, attempts, forceRender)
if ~isfield(ctx, 'sampling_dashboard') || ...
        ~ctx.sampling_dashboard.enabled
    return;
end
for attemptIndex = 1:numel(attempts)
    attempt = attempts(attemptIndex);
    if attempt.cone_completed
        ctx = bestEffortSamplingTopviewAction(ctx, ...
            'cone_complete', struct( ...
                'index', double(attempt.attempt_index), ...
                'name', 'RESUME_INHERITED_CONE', ...
                'allow_drawnow', false));
    end
    if attempt.motion_lifecycle_closed
        ctx = bestEffortSamplingTopviewAction(ctx, ...
            'complete', struct( ...
                'index', double(attempt.attempt_index), ...
                'effective_partition', attempt.effective_partition, ...
                'name', 'RESUME_INHERITED_SECURED_POINT', ...
                'allow_drawnow', false));
    end
end
ctx = bestEffortSamplingTopviewAction(ctx, ...
    'phase', struct( ...
        'name', 'RESUME_PARENT_STATE_HYDRATED', ...
        'allow_drawnow', logical(forceRender), ...
        'force_render', logical(forceRender)));
end

function [ctx, trialStartPose, trialStartJoints, ...
        trialStationarity, preposition] = executePairedAirPreposition( ...
            ctx, iiwa, privateSpec, taughtCenterPose, ...
            taughtCenterJoints, taughtCenterStationarity)
offsetFixtureMm = double(reshape( ...
    privateSpec.offset_fixture_mm, 1, 2));
rotation = ctx.cfg.frame.world_from_fixture_rotation;
offsetWorld = (rotation * [offsetFixtureMm, 0.0].').';
targetPosition = taughtCenterPose(1:3);
campaignCenterWorldXY = double(reshape( ...
    privateSpec.campaign_center_world_xy_mm, 1, []));
if isempty(campaignCenterWorldXY)
    campaignCenterWorldXY = taughtCenterPose(1:2);
end
if strcmp(char(privateSpec.schema), ...
        'M10_PROPOSED_PLUS_FIXED_DEMO_PRIVATE_TRIAL_V1')
    ctx = enableM10FixedDemoSupportEnvelope( ...
        ctx, campaignCenterWorldXY, privateSpec);
end
targetPosition(1:2) = campaignCenterWorldXY + offsetWorld(1:2);
% The operator supplies the safe air height.  Randomization is lateral only;
% fixture-frame tilt must never turn it into an implicit Z command.
targetPosition(3) = taughtCenterPose(3);
pathBefore = ctx.path_length_mm;
commandsBefore = ctx.completed_commands;
peakForceBefore = ctx.peak_force_delta_n;
peakTorqueBefore = ctx.peak_torque_delta_nm;
logEvent(ctx.paths.events, ...
    'PAIRED_AIR_PREPOSITION_BEGIN_PRIVATE', ...
    ['Executing one preregistered lateral offset at the taught air Z; ', ...
     'the value is private to setup/evaluation and is not a route prior.']);
    [ctx, ~] = moveAirSegmented(ctx, targetPosition, ...
        'PAIRED_AIR_PREPOSITION', false);
    [trialStartPose, trialStartJoints, trialStationarity] = ...
        captureStationaryStart(iiwa, ctx.cfg, ctx.paths);
    assertM10FixedDemoSupportEnvelope( ...
        ctx, trialStartPose(1:2), ...
        'PAIRED_AIR_PREPOSITION_MEASURED_ENDPOINT', 'MEASURED_STATE');
    targetErrorMm = norm(trialStartPose(1:3) - targetPosition);
assert(targetErrorMm <= ...
        ctx.cfg.sampling.air_tracking_tolerance_mm, ...
    'M12Demo:PairedAirEndpoint', ...
    ['Measured paired air endpoint differs from the preregistered target ', ...
     'by %.3f mm (limit %.3f mm).'], ...
    targetErrorMm, ctx.cfg.sampling.air_tracking_tolerance_mm);

% Rebind every task-local quantity to the measured post-air state.  The
% ordinary full-loop code below will therefore see the same inputs it would
% have seen had the operator manually taught this randomized point.
[ctx.cfg.frame, liveUpright] = ...
    bindOldKernelCompatibilityFrameToLiveStart( ...
        ctx.cfg.frame, trialStartPose, ctx.paths);
ctx.cfg.tool.sensor_to_tcp_rotation = ...
    kukaAbcToRotm(trialStartPose(4:6)).' * ...
    ctx.cfg.compatibility.start_world_axis_map;
ctx.sensor_to_tcp_rotation = ...
    ctx.cfg.tool.sensor_to_tcp_rotation;
ctx.start_world_from_sensor_rotation = ...
    kukaAbcToRotm(trialStartPose(4:6)) * ...
    ctx.sensor_to_tcp_rotation;
ctx.start_pose = trialStartPose;
ctx.start_joints = trialStartJoints;
ctx.last_pose = trialStartPose;
ctx.last_command_pose = trialStartPose;
ctx.baseline_ready = false;
ctx.baseline_force = zeros(1, 3);
ctx.baseline_torque = zeros(1, 3);
ctx.baseline_force_std_n = inf(1, 3);
ctx.baseline_torque_std_nm = inf(1, 3);
ctx.baseline_force_world = zeros(1, 3);
ctx.baseline_torque_world = zeros(1, 3);

preposition = struct( ...
    'schema', 'M12_PAIRED_AIR_PREPOSITION_EVALUATION_V1', ...
    'requested_offset_fixture_xy_mm', offsetFixtureMm, ...
    'requested_offset_world_xy_mm', offsetWorld(1:2), ...
    'campaign_center_world_xy_mm', campaignCenterWorldXY, ...
    'm10_head_support_envelope_enabled', ...
        ctx.m10_fixed_demo_support_envelope.enabled, ...
    'm10_head_support_envelope_safety_only', ...
        ctx.m10_fixed_demo_support_envelope.safety_fail_stop_only, ...
    'm10_head_support_maximum_commanded_radius_mm', ...
        ctx.m10_fixed_demo_support_envelope.maximum_commanded_radius_mm, ...
    'm10_head_support_maximum_physical_radius_mm', ...
        ctx.m10_fixed_demo_support_envelope.maximum_physical_radius_mm, ...
    'measured_offset_from_campaign_center_world_xy_mm', ...
        trialStartPose(1:2) - campaignCenterWorldXY, ...
    'air_transport_delta_from_current_taught_xy_mm', ...
        trialStartPose(1:2) - taughtCenterPose(1:2), ...
    'target_endpoint_error_mm', targetErrorMm, ...
    'measured_path_length_mm', ...
        ctx.path_length_mm - pathBefore, ...
    'command_count', ...
        ctx.completed_commands - commandsBefore, ...
    'maximum_force_delta_n', max( ...
        peakForceBefore, ctx.peak_force_delta_n), ...
    'maximum_torque_delta_nm', max( ...
        peakTorqueBefore, ctx.peak_torque_delta_nm), ...
    'upright_rotation_error_deg', ...
        liveUpright.rotation_error_deg, ...
    'taught_center_pose_mm_rad', taughtCenterPose, ...
    'taught_center_joints_rad', taughtCenterJoints, ...
    'taught_center_stationarity', taughtCenterStationarity, ...
    'trial_start_pose_mm_rad', trialStartPose, ...
    'trial_start_joints_rad', trialStartJoints, ...
    'trial_start_stationarity', trialStationarity);

% Task metrics begin at the randomized start.  Command indices and raw
% traces remain monotonic so a setup motion can never disappear from audit.
ctx.completed_commands = 0;
ctx.path_length_mm = 0.0;
ctx.maximum_unobserved_motion_mm = 0.0;
ctx.peak_force_delta_n = 0.0;
ctx.peak_torque_delta_nm = 0.0;
end

function ctx = enableM10FixedDemoSupportEnvelope( ...
        ctx, freshCenterWorldXY, privateSpec)
freshCenterWorldXY = double(reshape(freshCenterWorldXY, 1, []));
maximumPhysicalRadiusMm = ...
    ctx.cfg.learning.active_head_radius_mm - ...
    ctx.cfg.search.cad_tip_face_af_mm / sqrt(3.0);
trackingAllowanceMm = ...
    ctx.cfg.surface.maximum_z_correction_lateral_drift_mm;
maximumCommandedRadiusMm = ...
    maximumPhysicalRadiusMm - trackingAllowanceMm;
requestedOffsetMm = double(reshape( ...
    privateSpec.offset_fixture_mm, 1, []));
expectedMaximumPhysicalRadiusMm = 5.792458277186394;
expectedTrackingAllowanceMm = 0.600;
expectedMaximumCommandedRadiusMm = 5.192458277186394;
assert(numel(freshCenterWorldXY) == 2 && ...
        all(isfinite(freshCenterWorldXY)) && ...
        numel(requestedOffsetMm) == 2 && ...
        all(isfinite(requestedOffsetMm)) && ...
        abs(maximumPhysicalRadiusMm - ...
            expectedMaximumPhysicalRadiusMm) <= 1e-12 && ...
        abs(trackingAllowanceMm - ...
            expectedTrackingAllowanceMm) <= 1e-12 && ...
        abs(maximumCommandedRadiusMm - ...
            expectedMaximumCommandedRadiusMm) <= 1e-12 && ...
        maximumCommandedRadiusMm > 0.0 && ...
        norm(requestedOffsetMm) <= ...
            maximumCommandedRadiusMm + 1e-12, ...
    'M12Demo:M10FixedDemoSupportEnvelopeGeometry', ...
    ['The fresh M10 centre, fixed offset, or CAD-derived head-support ', ...
     'command envelope is invalid.']);
ctx.m10_fixed_demo_support_envelope = struct( ...
    'enabled', true, ...
    'center_world_xy_mm', freshCenterWorldXY, ...
    'maximum_commanded_radius_mm', maximumCommandedRadiusMm, ...
    'maximum_physical_radius_mm', maximumPhysicalRadiusMm, ...
    'endpoint_tracking_allowance_mm', trackingAllowanceMm, ...
    'safety_fail_stop_only', true, ...
    'posterior_input', false, ...
    'target_ranking_input', false, ...
    'steering_input', false);
logEvent(ctx.paths.events, ...
    'M10_FIXED_DEMO_HEAD_SUPPORT_ENVELOPE_ARMED_SAFETY_ONLY', sprintf( ...
    ['fresh-centre coordinates remain private; commanded/measured tip-centre ', ...
     'radii %.3f/%.3f mm; tracking allowance %.3f mm; posterior_input=0; ', ...
     'target_ranking_input=0; steering_input=0'], ...
    maximumCommandedRadiusMm, maximumPhysicalRadiusMm, ...
    trackingAllowanceMm));
end

function assertM10FixedDemoSupportEnvelope( ...
        ctx, targetWorldXY, phase, observationKind)
if ~isfield(ctx, 'm10_fixed_demo_support_envelope') || ...
        ~ctx.m10_fixed_demo_support_envelope.enabled
    return;
end
envelope = ctx.m10_fixed_demo_support_envelope;
targetWorldXY = double(reshape(targetWorldXY, 1, []));
centerWorldXY = double(reshape(envelope.center_world_xy_mm, 1, []));
assert(numel(targetWorldXY) == 2 && all(isfinite(targetWorldXY)) && ...
        numel(centerWorldXY) == 2 && all(isfinite(centerWorldXY)) && ...
        envelope.safety_fail_stop_only && ...
        ~envelope.posterior_input && ...
        ~envelope.target_ranking_input && ...
        ~envelope.steering_input, ...
    'M12Demo:M10FixedDemoSupportEnvelopeState', ...
    ['%s has an invalid M10 safety-only head-support envelope; no ', ...
     'motion is permitted.'], phase);
observationKind = upper(char(observationKind));
switch observationKind
    case 'COMMAND_TARGET'
        limitMm = envelope.maximum_commanded_radius_mm;
        identifier = 'M12Demo:M10FixedDemoCommandOutsideHeadSupport';
    case 'MEASURED_STATE'
        limitMm = envelope.maximum_physical_radius_mm;
        identifier = 'M12Demo:M10FixedDemoMeasuredOutsideHeadSupport';
    otherwise
        error('M12Demo:M10FixedDemoSupportEnvelopeKind', ...
            '%s supplied unsupported envelope observation kind %s.', ...
            phase, observationKind);
end
radiusMm = norm(targetWorldXY - centerWorldXY);
assert(isfinite(limitMm) && limitMm > 0.0 && ...
        radiusMm <= limitMm + 1e-12, identifier, ...
    ['%s M10 %s tip-centre radius %.3f mm exceeds the %.3f mm ', ...
     'fresh-centre socket-head support limit.  This independent ', ...
     'fail-stop never steers, reranks, or changes the posterior.'], ...
    phase, lower(strrep(observationKind, '_', ' ')), ...
    radiusMm, limitMm);
end

function writePairedEvaluationTruth( ...
        realDir, privateSpec, taughtCenterPose, ...
        taughtCenterJoints, taughtCenterStationarity, ...
        trialStartPose, trialStartJoints, trialStationarity, ...
        centerAirReference, preposition)
privateDir = fullfile(realDir, 'data', ...
    'paired_full_loop_private');
if ~isfolder(privateDir)
    [made, message] = mkdir(privateDir);
    assert(made, 'M12Demo:PairedPrivateDirectory', ...
        'Cannot create paired evaluation directory %s: %s', ...
        privateDir, message);
end
record = struct( ...
    'schema', 'M12_PAIRED_FULL_LOOP_EVALUATION_ONLY_V1', ...
    'created_local', isoTimestamp(), ...
    'never_runtime_policy_input', true, ...
    'campaign_id', char(privateSpec.campaign_id), ...
    'trial_index', double(privateSpec.trial_index), ...
    'offset_index', double(privateSpec.offset_index), ...
    'method_index', double(privateSpec.method_index), ...
    'order_position', double(privateSpec.order_position), ...
    'method_mode', char(privateSpec.method_mode), ...
    'public_trial_token', char(privateSpec.public_trial_token), ...
    'campaign_center_world_xy_mm', ...
        preposition.campaign_center_world_xy_mm, ...
    'requested_offset_fixture_xy_mm', ...
        double(privateSpec.offset_fixture_mm), ...
    'taught_center_pose_mm_rad', taughtCenterPose, ...
    'taught_center_joints_rad', taughtCenterJoints, ...
    'taught_center_stationarity', taughtCenterStationarity, ...
    'trial_start_pose_mm_rad', trialStartPose, ...
    'trial_start_joints_rad', trialStartJoints, ...
    'trial_start_stationarity', trialStationarity, ...
    'center_air_reference', centerAirReference, ...
    'preposition', preposition);
writeJson(fullfile(privateDir, ...
    [char(privateSpec.public_trial_token), '.json']), record);
end

function [ctx, postPose] = moveAirSegmented( ...
        ctx, targetPosition, phase, requireClearEachSegment)
if nargin < 4
    requireClearEachSegment = true;
end
targetPosition = double(reshape(targetPosition, 1, 3));
assert(all(isfinite(targetPosition)), 'M12Demo:SamplingAirTarget', ...
    '%s target is not finite.', phase);
while norm(targetPosition - ctx.last_pose(1:3)) > ...
        ctx.cfg.sampling.air_endpoint_tolerance_mm
    delta = targetPosition - ctx.last_pose(1:3);
    distance = norm(delta);
    step = min(distance, ...
        ctx.cfg.sampling.air_translation_segment_mm);
    delta = delta * (step / distance);
    [ctx, postPose] = moveOne(ctx, delta, ...
        ctx.cfg.sampling.air_translation_speed_mm_s, ...
        ctx.cfg.sampling.air_tracking_tolerance_mm, phase);
    if requireClearEachSegment
        [ctx, ~] = assertWrenchClearWindow(ctx, ...
            [phase, '_IN_FLIGHT_CLEAR'], 1);
    else
        [ctx, ~] = guardDwell(ctx, ...
            [phase, '_UPWARD_RELIEF_GUARD'], 1, ...
            ctx.cfg.sensor.hard_force_delta_n);
    end
    ctx = updateSamplingTopviewEndpoint(ctx, phase, postPose, true);
end
postPose = ctx.last_pose;
end

function [ctx, aggregate] = requireWrenchClearDwells(ctx, phase)
aggregate = struct('maximum_force_delta_n', 0.0, ...
    'maximum_torque_delta_nm', 0.0);
for dwellIndex = 1:ctx.cfg.sampling.wrench_clear_dwell_count
    [ctx, observation] = assertWrenchClearWindow(ctx, ...
        sprintf('%s_DWELL_%d', phase, dwellIndex), ...
        ctx.cfg.sampling.wrench_clear_samples_per_dwell);
    aggregate.maximum_force_delta_n = max( ...
        aggregate.maximum_force_delta_n, ...
        observation.maximum_force_delta_n);
    aggregate.maximum_torque_delta_nm = max( ...
        aggregate.maximum_torque_delta_nm, ...
        observation.maximum_torque_delta_nm);
end
end

function [ctx, observation] = assertWrenchClearWindow( ...
        ctx, phase, sampleCount)
maximumForce = 0.0;
maximumTorque = 0.0;
for index = 1:sampleCount
    [ctx, sample] = receiveWrench(ctx, phase);
    maximumForce = max(maximumForce, sample.force_delta_n);
    maximumTorque = max(maximumTorque, sample.torque_delta_nm);
    assert(sample.force_delta_n < ...
            ctx.cfg.sampling.wrench_clear_force_delta_n && ...
        sample.torque_delta_nm < ...
            ctx.cfg.sampling.wrench_clear_torque_delta_nm, ...
        'M12Demo:SamplingWrenchNotClear', ...
        ['%s sample %d is not wrench-clear: dF %.3f N, dT %.4f Nm. ', ...
         'Stop before any lateral move.'], ...
        phase, index, sample.force_delta_n, sample.torque_delta_nm);
end
observation = struct( ...
    'maximum_force_delta_n', maximumForce, ...
    'maximum_torque_delta_nm', maximumTorque);
end

function worldPoint = fixturePointToWorld(fixturePoint, frame)
fixturePoint = double(reshape(fixturePoint, 1, []));
assert(any(numel(fixturePoint) == [2, 3]) && ...
    all(isfinite(fixturePoint)), ...
    'M12Demo:FixturePoint', ...
    'Fixture point must contain finite XY or XYZ coordinates.');
if numel(fixturePoint) == 2
    fixturePoint(3) = 0.0;
end
world = frame.world_from_fixture_translation_mm(:) + ...
    frame.world_from_fixture_rotation * fixturePoint(:);
worldPoint = world.';
end

function fixturePoint = worldPointToFixture(worldPoint, frame)
worldPoint = double(reshape(worldPoint, 1, 3));
fixture = frame.world_from_fixture_rotation.' * ...
    (worldPoint(:) - frame.world_from_fixture_translation_mm(:));
fixturePoint = fixture.';
end

function worldXY = fixtureVectorToWorldXY(fixtureXY, frame)
fixtureXY = double(reshape(fixtureXY, 1, 2));
world = frame.world_from_fixture_rotation * [fixtureXY(:); 0.0];
worldXY = world(1:2).';
if norm(worldXY) > eps
    worldXY = worldXY / norm(worldXY);
end
end

function fixtureXY = worldVectorToFixtureXY(worldXY, frame)
worldXY = double(reshape(worldXY, 1, 2));
fixture = frame.world_from_fixture_rotation.' * [worldXY(:); 0.0];
fixtureXY = fixture(1:2).';
end

function errorDeg = circularErrorDeg(firstDeg, secondDeg)
errorDeg = abs(mod(firstDeg - secondDeg + 180.0, 360.0) - 180.0);
end

function saveSamplingAttempt(attempt, cone, pointBaseline, contactSettle)
temporaryPath = [tempname(fileparts(attempt.mat_path)), '.mat'];
save(temporaryPath, ...
    'attempt', 'cone', 'pointBaseline', 'contactSettle', '-v7.3');
[moved, moveMessage] = movefile(temporaryPath, attempt.mat_path, 'f');
assert(moved, 'M12Demo:SamplingAttemptAtomicCommit', ...
    'Cannot atomically commit %s: %s', ...
    attempt.mat_path, moveMessage);
end

function value = stripSamplingAttemptForJson(attempt)
value = attempt;
end

function writeSamplingCheckpoint(paths, campaign)
temporaryPath = [tempname(fileparts(paths.samplingMat)), '.mat'];
save(temporaryPath, 'campaign', '-v7.3');
[moved, moveMessage] = movefile( ...
    temporaryPath, paths.samplingMat, 'f');
assert(moved, 'M12Demo:SamplingCheckpointAtomicCommit', ...
    'Cannot atomically commit %s: %s', ...
    paths.samplingMat, moveMessage);
% JSON is the resume authority and is committed last.
writeJson(paths.samplingSummary, campaign);
end

function [attempt, campaign, outcome] = ...
        persistSamplingAttemptWithRetry( ...
            attempt, pointBaseline, contactSettle, cone, campaign, ...
            cfg, paths, includeImmutableEvidence, phase)
% Persistence is deliberately motion-free.  Before retract, an exhausted
% checkpoint is represented as deferred state so the physical clear action
% still runs.  After clear, bounded retries either commit the operational
% overlay or leave the robot clear and stop the campaign.
maximum_attempts = cfg.sampling.persistence.maximum_attempts;
retry_pause_s = cfg.sampling.persistence.retry_pause_s;
phase = upper(char(phase));
assert(any(strcmp(phase, {'PRE_RETRACT', 'POST_RETRACT'})), ...
    'M12Demo:SamplingPersistencePhase', ...
    'Unsupported sampling persistence phase %s.', phase);
outcome = struct( ...
    'committed', false, ...
    'attempts', 0, ...
    'immutable_evidence_committed', ...
        logical(attempt.immutable_evidence_committed), ...
    'error_identifier', '', ...
    'error_message', '');

for persistenceAttempt = 1:maximum_attempts
    outcome.attempts = persistenceAttempt;
    immutableReadyBeforeAttempt = ...
        logical(attempt.immutable_evidence_committed);
    immutableValidatedThisAttempt = false;
    try
        if includeImmutableEvidence && ...
                ~attempt.immutable_evidence_committed
            attempt.immutable_evidence_commit_attempts = ...
                persistenceAttempt;
            attempt.immutable_evidence_commit_error = '';
            attempt.immutable_evidence_committed = true;
            try
                [attempt, evidenceHashes] = ...
                    exportSamplingAttemptEvidence( ...
                        attempt, pointBaseline, contactSettle, cone, ...
                        paths.conicalTrace);
                attempt.file_hashes = evidenceHashes;
                % This MAT plus its three CSVs is the immutable physical
                % acquisition record.  Lifecycle closure is overlaid only
                % in JSON/campaign after this point; these four files are
                % never rewritten after a successful commit.
                saveSamplingAttempt( ...
                    attempt, cone, pointBaseline, contactSettle);
                attempt.file_hashes.attempt_mat_sha256 = ...
                    sha256File(attempt.mat_path);
            catch immutableEvidenceError
                attempt.immutable_evidence_committed = false;
                rethrow(immutableEvidenceError);
            end
        end
        validateSamplingImmutableEvidence(attempt);
        immutableValidatedThisAttempt = true;
        attempt.operational_overlay_commit_attempts = ...
            attempt.operational_overlay_commit_attempts + 1;
        attempt.operational_overlay_commit_error = '';
        writeJson(attempt.json_path, ...
            stripSamplingAttemptForJson(attempt));
        candidateCampaign = appendSamplingAttempt(campaign, attempt);
        % sampling_attempts.csv is derived and replaceable.  Write it before
        % the authoritative campaign JSON, which is committed last.
        writeSamplingAttemptsCsvSnapshot( ...
            paths.samplingAttemptsCsv, candidateCampaign);
        writeSamplingCheckpoint(paths, candidateCampaign);
        campaign = candidateCampaign;
        outcome.committed = true;
        outcome.immutable_evidence_committed = true;
        if strcmp(phase, 'POST_RETRACT') && persistenceAttempt > 1
            bestEffortLogEvent(paths.events, ...
                'POST_RETRACT_PERSISTENCE_RECOVERED', sprintf( ...
                ['execution %02d committed on bounded attempt %d/%d; ', ...
                 'robot already wrench-clear'], ...
                attempt.execution_index, persistenceAttempt, ...
                maximum_attempts));
        end
        return;
    catch persistenceError
        if ~immutableReadyBeforeAttempt && ...
                ~immutableValidatedThisAttempt
            attempt.immutable_evidence_committed = false;
        end
        outcome.error_identifier = persistenceError.identifier;
        outcome.error_message = oneLine(persistenceError.message);
        errorText = [persistenceError.identifier, ': ', ...
            outcome.error_message];
        if attempt.immutable_evidence_committed
            attempt.operational_overlay_commit_error = errorText;
        else
            attempt.immutable_evidence_commit_error = errorText;
        end
        if strcmp(phase, 'PRE_RETRACT')
            bestEffortLogEvent(paths.events, ...
                'PRE_RETRACT_PERSISTENCE_RETRY_NO_MOTION', sprintf( ...
                ['execution %02d persistence attempt %d/%d failed: %s; ', ...
                 'no robot command issued'], ...
                attempt.execution_index, persistenceAttempt, ...
                maximum_attempts, errorText));
        end
        if persistenceAttempt < maximum_attempts
            pause(retry_pause_s);
        end
    end
end

outcome.immutable_evidence_committed = ...
    logical(attempt.immutable_evidence_committed);
if strcmp(phase, 'PRE_RETRACT')
    bestEffortLogEvent(paths.events, ...
        'PRE_RETRACT_PERSISTENCE_DEFERRED_UNTIL_CLEAR', sprintf( ...
        ['execution %02d exhausted %d attempts; physical retract remains ', ...
         'authoritative and will run before persistence is retried'], ...
        attempt.execution_index, maximum_attempts));
else
    bestEffortLogEvent(paths.events, ...
        'POST_RETRACT_PERSISTENCE_EXHAUSTED_ROBOT_CLEAR', sprintf( ...
        ['execution %02d exhausted %d attempts after verified clear: ', ...
         '%s: %s'], ...
        attempt.execution_index, maximum_attempts, ...
        outcome.error_identifier, outcome.error_message));
end
end

function validateSamplingImmutableEvidence(attempt)
hashes = attempt.file_hashes;
pathsAndHashes = { ...
    attempt.mat_path, hashes.attempt_mat_sha256, 'attempt MAT'; ...
    attempt.baseline_csv_path, hashes.baseline_csv_sha256, ...
        'point baseline CSV'; ...
    attempt.contact_settle_csv_path, ...
        hashes.contact_settle_csv_sha256, 'contact-settle CSV'; ...
    attempt.cone_csv_path, hashes.cone_csv_sha256, 'cone CSV'};
for evidenceIndex = 1:size(pathsAndHashes, 1)
    evidencePath = pathsAndHashes{evidenceIndex, 1};
    expectedHash = pathsAndHashes{evidenceIndex, 2};
    assert(isfile(evidencePath) && isValidSha256(expectedHash) && ...
        strcmp(sha256File(evidencePath), expectedHash), ...
        'M12Demo:SamplingImmutableEvidenceValidation', ...
        '%s is missing or hash-invalid: %s', ...
        pathsAndHashes{evidenceIndex, 3}, evidencePath);
end
end

function phase = ternarySamplingPersistencePhase(safeRetractCompleted)
if logical(safeRetractCompleted)
    phase = 'POST_RETRACT';
else
    phase = 'PRE_RETRACT';
end
end

function writeSamplingAttemptsCsvSnapshot(path, campaign)
attempts = campaign.attempts;
if isempty(attempts)
    rows = cell(0, 1);
else
    [~, order] = sort([attempts.execution_index]);
    attempts = attempts(order);
    rows = cell(numel(attempts), 1);
    for attemptIndex = 1:numel(attempts)
        rows{attemptIndex} = samplingAttemptCsvRow(attempts(attemptIndex));
    end
end
content = samplingAttemptsCsvHeader();
for rowIndex = 1:numel(rows)
    content = [content, rows{rowIndex}]; %#ok<AGROW>
end
% The summary is a derived overlay.  Rebuild the complete execution-indexed
% snapshot and atomically replace it; never append duplicate lifecycle rows.
writeText(path, content);
end

function header = samplingAttemptsCsvHeader()
header = [ ...
    'execution_index,source_attempt_index,sample_id,', ...
    'requested_partition,effective_partition,', ...
    'status,contact_state,cone_sweep_subtype,', ...
    'nominal_outer_overhang_fraction,', ...
    'nominal_mouth_overlap_fraction,', ...
    'nominal_head_top_support_fraction,', ...
    'cone_maximum_mouth_overlap_fraction,', ...
    'cone_mouth_overlap_phase_fraction,', ...
    'cone_outer_overhang_phase_fraction,', ...
    'cone_minimum_outer_clearance_mm,', ...
    'local_x_fixture_mm,local_y_fixture_mm,', ...
    'nominal_direction_fixture_deg,measured_contact_x_fixture_mm,', ...
    'measured_contact_y_fixture_mm,measured_sampling_error_mm,', ...
    'measured_label_direction_deviation_deg,', ...
    'true_direction_fixture_deg,cone_completed,safe_retract_completed,', ...
    'phase_coverage_fraction,touchdown_max_force_n,', ...
    'touchdown_max_torque_nm,contact_settle_reason,', ...
    'contact_settle_normal_mean_n,contact_settle_normal_std_n,', ...
    'contact_settle_off_target_continuation,', ...
    'contact_settle_quality_grade,', ...
    'contact_settle_completion_first_continuation,', ...
    'contact_settle_observed_dwell_s,', ...
    'contact_settle_normal_min_n,contact_settle_normal_max_n,', ...
    'contact_settle_adjustment_commands,', ...
    'contact_settle_unobserved_adjustments,', ...
    'offline_training_candidate,quarantine_reason', newline];
end

function row = samplingAttemptCsvRow(attempt)
geometry = attempt.nominal_touchdown_geometry;
coneGeometry = attempt.printed_frustum_cone_phase_diagnostics;
row = sprintf([ ...
    '%d,%d,%s,%s,%s,%s,%s,%s,', ...
    '%.9f,%.9f,%.9f,%.9f,%.9f,%.9f,%.9f,', ...
    '%.9f,%.9f,%.9f,%.9f,%.9f,%.9f,%.9f,%.9f,', ...
    '%d,%d,%.9f,%.9f,%.9f,%s,%.9f,%.9f,%d,%s,%d,', ...
    '%.9f,%.9f,%.9f,%d,%d,%d,%s\n'], ...
    attempt.execution_index, attempt.source_attempt_index, ...
    attempt.sample_id, ...
    attempt.requested_partition, attempt.effective_partition, ...
    attempt.status, attempt.contact_state, attempt.cone_sweep_subtype, ...
    geometry.outer_overhang_fraction, ...
    geometry.mouth_overlap_fraction, ...
    geometry.head_top_support_fraction, ...
    coneGeometry.maximum_mouth_overlap_fraction, ...
    coneGeometry.mouth_overlap_phase_fraction, ...
    coneGeometry.outer_overhang_phase_fraction, ...
    coneGeometry.minimum_outer_clearance_mm, ...
    attempt.local_offset_fixture_mm, ...
    attempt.nominal_direction_fixture_deg, ...
    attempt.measured_contact_fixture_xy_mm, ...
    attempt.measured_sampling_error_mm, ...
    attempt.measured_label_direction_deviation_deg, ...
    attempt.true_direction_fixture_deg, attempt.cone_completed, ...
    attempt.safe_retract_completed, attempt.phase_coverage_fraction, ...
    attempt.touchdown_max_force_n, attempt.touchdown_max_torque_nm, ...
    attempt.contact_settle_reason, ...
    attempt.contact_settle_normal_mean_n, ...
    attempt.contact_settle_normal_std_n, ...
    attempt.contact_settle_off_target_continuation, ...
    attempt.contact_settle_quality_grade, ...
    attempt.contact_settle_completion_first_continuation, ...
    attempt.contact_settle_observed_dwell_s, ...
    attempt.contact_settle_normal_min_n, ...
    attempt.contact_settle_normal_max_n, ...
    attempt.contact_settle_adjustment_commands, ...
    attempt.contact_settle_unobserved_adjustments, ...
    attempt.offline_training_candidate, ...
    attempt.quarantine_reason);
end

function cfg = makeConfig(realDir, workspaceRoot, cadSize)
if nargin < 3 || isempty(cadSize)
    cadSize = 'm12';
end
cadSize = lower(char(string(cadSize)));
assert(any(strcmp(cadSize, {'m10', 'm12'})), ...
    'M12Demo:ActiveCadSize', ...
    'Full-loop CAD size must be exactly m10 or m12.');
cfg = struct();
cfg.schema_version = 2;
cfg.experiment = 'm12_contact_cone_force_following_insert_demo_v3';
cfg.compatibility = struct( ...
    'old_kernel_motion_compatibility_enabled', true, ...
    'authority', 'PROVISIONAL_OLD_KERNEL_COMPATIBILITY', ...
    'world_from_fixture_rotation', eye(3), ...
    'start_world_axis_map', diag([1.0, -1.0, -1.0]), ...
    'tip_tcp_translation_mm', [0.0, 0.0, 92.0], ...
    'tip_tcp_standard_uncertainty_mm', 4.0, ...
    'insertion_depth_mm', 6.0, ...
    'rule', ...
        ['Full-loop motion uses the field-proven predecessor commissioning ', ...
         'level: 92 mm axial TCP, manual stationary near-hole start, ', ...
         'WORLD-aligned fixture axes, fresh touchdown/capture local datum ', ...
         'and 6 mm segmented insertion.  Missing physical IDs, payload/', ...
         'CoM/inertia, pivot and fixture metrology are disclosed but do not ', ...
         'block this full-loop entry.  Sampling uses a separately disclosed ', ...
         'operator-taught run-local centre and acquisition-only contract.']);
cfg.robot = struct('model', 'KUKA LBR iiwa 14 R820', ...
    'ip', '192.168.1.147', 'kst_port', 30001);
cfg.kst = struct( ...
    'post_motion_protocol_settle_s', 0.04, ...
    'inter_state_query_settle_s', 0.03, ...
    'read_only_recovery_attempts', 3, ...
    'read_only_recovery_pause_s', 0.05, ...
    'recovery_position_consistency_mm', 0.25, ...
    'recovery_orientation_consistency_deg', 0.20, ...
    'recovery_joint_consistency_rad', 0.02, ...
    'motion_reissue_permitted_during_state_recovery', false, ...
    'server_shared_command_slot_race_known', true);
cfg.ros = struct('master_uri', 'http://192.168.1.41:11311', ...
    'node_host', '192.168.1.41');
cfg.frame = struct( ...
    'status', 'UNRESOLVED_UNTIL_EXECUTION_POLICY_SELECTED', ...
    'world_from_fixture_yaw_deg', NaN, ...
    'fixture_z_to_world_z_tilt_deg', NaN, ...
    'world_from_fixture_rotation', nan(3), ...
    'world_from_fixture_translation_mm', [NaN, NaN, NaN]);
% One non-overlapping axial chain:
% KUKA media flange -> white/silver adapter -> Bota robot plane
% -> Bota tool/wrench plane -> cement-gray adapter -> pink CAD mating plane
% -> pink flange+peg tip.
% The first six datums are represented by one provisional 50 mm end-to-end
% observation; the white/silver and cement-gray adapter thicknesses are not
% separately known.  Bota's official 38 mm spacing only cross-checks part of
% that whole.  The 570 mm cement-gray-bottom-to-table observation is
% pose-dependent scene geometry, not adapter thickness and not a TCP term.
% The distinct 10..11 mm blue reference connector is excluded.  The current
% pink CAD's own 8 mm flange is already inside its 42 mm CAD distance.
cfg.tool = struct( ...
    'media_flange_to_pink_cad_plane_whole_observation_mm', 50.0, ...
    'upstream_stack_uncertainty_mm', 4.0, ...
    'white_silver_adapter_thickness_mm', NaN, ...
    'bota_mounting_plane_spacing_mm_crosscheck_nonadditive', 38.0, ...
    'cement_gray_adapter_thickness_mm', NaN, ...
    'cement_gray_bottom_to_table_pose_observation_mm', 570.0, ...
    'cement_gray_bottom_to_table_used_in_tcp', false, ...
    'blue_reference_connector_thickness_mm_observation', [10.0, 11.0], ...
    'blue_reference_connector_used_in_active_tcp', false, ...
    'pink_cad_plane_to_tip_mm', 42.0, ...
    'pink_cad_flange_thickness_mm_nonadditive', 8.0, ...
    'flange_to_tip_mm', 92.0, ...
    'flange_to_tip_uncertainty_mm', 4.0, ...
    'translation_mm', [0.0, 0.0, 92.0], ...
    'rotation', eye(3), ...
    'status', 'PROVISIONAL_FULL_STACK_RULER_PLUS_PINK_DELIVERED_CAD', ...
    'upstream_crosscheck_rule', ...
        'Bota_38mm_is_within_50mm_whole_stack_crosscheck', ...
    'whole_stack_rule', ...
        '50mm_spans_white_silver_adapter_Bota_and_cement_gray_adapter_once', ...
    'blue_connector_rule', ...
        'distinct_reference_part_10to11mm_observation_excluded_from_active_pink_TCP', ...
    'pink_flange_counting_rule', ...
        'included_in_42mm_CAD_distance_never_added_separately', ...
    'pink_cad_step_sha256', ...
        '362018e71e4bb80ea07640d6fb7bc0ddbe6178c25046f0283741e5a49e52a4fe', ...
    'bota_official_datasheet_sha256', ...
        '883452b6c748ad54abf053fc3181736945067ca88c9ce52d98de7ecbdcb16871', ...
    'bota_official_step_sha256', ...
        '633b238baa56b95020fb91f78ac68a1822597c490f837d49d67cbe3c79ad2382');
cfg.sensor = struct( ...
    'product', 'BFT-SENS-CAT2-B4', ...
    'serial', 'SN001349', ...
    'wrench_topic', '/bota_ft_sensor/wrench', ...
    'wrench_frame', 'bota_ft_frame', ...
    'diagnostics_topic', '/diagnostics', ...
    'diagnostic_name', 'Bota F/T Sensor', ...
    'diagnostic_hardware_id', 'BFT-SENS-CAT2-B4:SN001349', ...
    'driver_interface', 'Bota_Binary', ...
    'driver_config_sha256', ...
        '62029c1874fd8c2eb0a1ed8aff0e1ca2ae708ef18e8904538cec85bf7c1c87ce', ...
    'driver_app_mode', '1', ...
    'driver_app_submode', '7', ...
    'minimum_sensor_rate_hz', 180.0, ...
    'maximum_driver_frame_age_s', 0.10, ...
    'baseline_samples', 150, ...
    'minimum_receive_rate_hz', 40.0, ...
    'maximum_force_axis_std_n', 0.10, ...
    'maximum_torque_axis_std_nm', 0.010, ...
    'maximum_wrench_age_s', 0.10, ...
    'maximum_diagnostic_age_s', 1.50, ...
    'transient_stale_recovery_timeout_s', 2.00, ...
    'transient_stale_recovery_poll_s', 0.05, ...
    'message_timeout_s', 0.50, ...
    'startup_diagnostic_timeout_s', 12.0, ...
    'startup_wrench_timeout_s', 5.0, ...
    'ros_teardown_settle_s', 0.75, ...
    'contact_event_n', 2.0, ...
    'contact_consecutive_samples', 3, ...
    'bottom_event_n', 2.5, ...
    'bottom_consecutive_samples', 5, ...
    'hard_force_delta_n', 25.0, ...
    'hard_torque_delta_nm', 0.75, ...
    'insertion_soft_force_delta_n', 16.0, ...
    'insertion_soft_torque_delta_nm', 0.50, ...
    'measurement_origin_definition', ...
        'OFFICIAL_TOOL_MOUNTING_PLANE_CENTER', ...
    'measurement_origin_from_robot_mounting_plane_mm', ...
        [0.0, 0.0, 38.0], ...
    'official_axis_z', ...
        'ROBOT_MOUNTING_SIDE_TO_TOOL_MOUNTING_SIDE', ...
    'world_wrench_status', ...
        'PROVISIONAL_ROTATION_ONLY_AT_BOTA_MEASUREMENT_ORIGIN');
cfg.motion = struct( ...
    'touchdown_maximum_down_mm', 20.0, ...
    'touchdown_lateral_drift_warning_mm', 0.20, ...
    'maximum_touchdown_lateral_drift_mm', 3.00, ...
    'touchdown_xy_correction_deadband_mm', 0.08, ...
    'touchdown_xy_correction_step_mm', 0.15, ...
    'maximum_touchdown_xy_lock_error_mm', 0.25, ...
    'touch_segment_mm', 0.10, ...
    'touch_speed_mm_s', 1.0, ...
    'insertion_segment_mm', 0.10, ...
    'insertion_speed_mm_s', 0.60, ...
    'touch_tracking_tolerance_mm', 0.20, ...
    'insertion_tracking_tolerance_mm', 0.20, ...
    'insertion_minimum_progress_mm', 0.005, ...
    'insertion_maximum_stagnant_steps', 5, ...
    'insertion_maximum_actions', 160, ...
    'command_deadband_mm', 0.02, ...
    'minimum_progress_fraction', 0.25, ...
    'maximum_cross_track_mm', 0.30, ...
    'maximum_lateral_excursion_mm', 10.0, ...
    'maximum_up_excursion_mm', 2.25, ...
    'maximum_down_excursion_mm', 28.0, ...
    'maximum_orientation_drift_rad', 0.03, ...
    'minimum_start_joint_margin_deg', 10.0, ...
    'minimum_run_joint_margin_deg', 8.0, ...
    'maximum_active_time_s', 900.0);
% Printed-CAD size selection.  Four across-flats constants and the socket
% depth are the only size-dependent inputs; every derived clearance, capture
% radius, grid pitch and hex-edge cone feedforward below follows from them, so
% a size is added by adding one branch here and nothing else.
%
% Socket depths come from the qualified simulation contracts
% (allen_m{10,12}_hardware_easy_v2.json, socket_depth_m), not from the
% sampling geometry blocks, which do not carry a depth.  M10 is 5.0 mm against
% M12's 6.0 mm -- running the M12 depth on M10 hardware would command 6.0 mm
% into a 5.0 mm socket and could never reach its own 5.70 mm success band, so
% it would press at the bottom until a guard fired.
switch cadSize
    case 'm10'
        m12TipFaceAfMm = 6.4;
        m12ShaftAfMm = 8.0;
        m12SocketWallAfMm = 8.54;
        m12SocketMouthAfMm = 10.54;
        cadSocketDepthMm = 5.0;
        cadChamferDepthMm = 1.0;
        cadHeadOuterDiameterMm = 18.975;
    otherwise
        m12TipFaceAfMm = 8.0;
        m12ShaftAfMm = 10.0;
        m12SocketWallAfMm = 10.6;
        m12SocketMouthAfMm = 13.0;
        cadSocketDepthMm = 6.0;
        cadChamferDepthMm = 1.2;
        cadHeadOuterDiameterMm = 21.275;
end
cfg.compatibility.insertion_depth_mm = cadSocketDepthMm;
cfg.compatibility.rule = sprintf([ ...
    'Full-loop motion uses the field-proven predecessor commissioning ', ...
    'level: 92 mm axial TCP, manual stationary near-hole start, ', ...
    'WORLD-aligned fixture axes, fresh touchdown/capture local datum ', ...
    'and %.1f mm size-correct segmented insertion for active %s.  Missing ', ...
    'physical IDs, payload/CoM/inertia, pivot and fixture metrology are ', ...
    'disclosed but do not block this fixed experimental compatibility entry.'], ...
    cadSocketDepthMm, upper(cadSize));
m12DeepClearancePerSideMm = ...
    0.5 * (m12SocketWallAfMm - m12ShaftAfMm);
m12MouthGuidanceAllowanceMm = ...
    0.5 * (m12SocketMouthAfMm - m12TipFaceAfMm);
m12ConservativeCaptureRadiusMm = ...
    0.25 * (m12SocketMouthAfMm - m12ShaftAfMm);
m12GridPitchMm = min(2.0 * m12DeepClearancePerSideMm, ...
    (2.0 / 3.0) * m12ConservativeCaptureRadiusMm);
m12CommonSearchReachMm = 4.80;
m12CenterHypothesisRadiusMm = m12CommonSearchReachMm + ...
    m12ConservativeCaptureRadiusMm + 0.20;
activeGridNodeCount = size(buildCircularOffsets( ...
    m12GridPitchMm, m12CommonSearchReachMm), 1);
activeResidualConnectedLegMm = min(1.00, 2.00 * m12GridPitchMm);
activeDirectionalCorridorAdvanceMm = activeResidualConnectedLegMm;
activeCoveragePitchMm = min(1.00, ...
    2.00 * (m12ConservativeCaptureRadiusMm - 0.20));
activeDirectRayLimitMm = min(5.70, ...
    4.20 + 2.00 * m12ConservativeCaptureRadiusMm);
activeTipMouthSupportMarginMm = ...
    0.50 * m12SocketMouthAfMm - ...
    m12TipFaceAfMm / sqrt(3.0) - ...
    cfg.motion.insertion_tracking_tolerance_mm;
activeInsertionUnwedgeMaximumRadiusMm = min( ...
    1.60, activeTipMouthSupportMarginMm);
assert(activeCoveragePitchMm > 0.0 && ...
        activeTipMouthSupportMarginMm > 0.0 && ...
        activeInsertionUnwedgeMaximumRadiusMm >= 0.25, ...
    'M12Demo:ActiveCadMotionGeometry', ...
    ['The active CAD size does not retain capture-overlapping coverage or ', ...
     'a tracking-bounded supported insertion-unwedge radius.']);
cfg.search = struct( ...
    'shortcut_cap_mm', 3.00, ...
    'shortcut_projection_quantile_low', 0.10, ...
    'shortcut_projection_quantile_high', 0.25, ...
    'shortcut_radius_cap_fraction_low', 0.50, ...
    'shortcut_radius_cap_fraction_high', 0.75, ...
    'shortcut_residual_fallback_minimum_cap_fraction', 0.75, ...
    'directional_corridor_probability_mass', 0.80, ...
    'directional_corridor_minimum_full_width_deg', 12.0, ...
    'directional_corridor_maximum_full_width_deg', 45.0, ...
    'directional_corridor_tracking_allowance_mm', 0.20, ...
    'directional_corridor_maximum_advance_mm', ...
        activeDirectionalCorridorAdvanceMm, ...
    'directional_sector_outside_likelihood_floor', 0.05, ...
    'sector_release_uniform_weight', 0.50, ...
    'grid_pitch_mm', m12GridPitchMm, ...
    'action_reach_mm', m12CommonSearchReachMm, ...
    'grid_radius_mm', m12CommonSearchReachMm, ...
    'center_hypothesis_radius_mm', m12CenterHypothesisRadiusMm, ...
    'maximum_grid_nodes', activeGridNodeCount, ...
    'residual_maximum_connected_leg_mm', ...
        activeResidualConnectedLegMm, ...
    'tested_offset_tolerance_mm', 0.10, ...
    'directional_progress_tolerance_mm', 0.10, ...
    'swept_segment_tolerance_mm', 0.10, ...
    'swept_capture_tube_tolerance_mm', ...
        m12ConservativeCaptureRadiusMm - 0.20, ...
    'minimum_novel_swept_length_mm', 0.25, ...
    'swept_segment_sample_spacing_mm', 0.05, ...
    'bayes_capture_radius_mm', m12ConservativeCaptureRadiusMm, ...
    'bayes_transition_width_mm', 0.22, ...
    'bayes_likelihood_floor', 0.08, ...
    'eig_information_weight', 0.35, ...
    'eig_capture_reward_weight', 1.50, ...
    'eig_forward_progress_weight_per_mm', 0.30, ...
    'eig_novel_coverage_weight_per_mm', 0.20, ...
    'eig_action_cost', 0.08, ...
    'eig_travel_penalty_per_mm', 0.020, ...
    'coverage_information_weight', 0.05, ...
    'coverage_capture_reward_weight', 2.25, ...
    'eig_credible_mass', 0.95, ...
    'eig_minimum_utility', 0.05, ...
    'eig_maximum_noncontracting_updates', 2, ...
    'cad_tip_face_af_mm', m12TipFaceAfMm, ...
    'cad_shaft_af_mm', m12ShaftAfMm, ...
    'cad_socket_wall_af_mm', m12SocketWallAfMm, ...
    'cad_socket_mouth_af_mm', m12SocketMouthAfMm, ...
    'cad_socket_chamfer_depth_mm', cadChamferDepthMm, ...
    'cad_head_outer_diameter_mm', cadHeadOuterDiameterMm, ...
    'cad_deep_clearance_per_side_mm', ...
        m12DeepClearancePerSideMm, ...
    'cad_mouth_guidance_allowance_mm', ...
        m12MouthGuidanceAllowanceMm, ...
    'model_radial_prior', ...
        ['UNIFORM_AREA_OVER_EXPANDED_CENTER_HYPOTHESIS_SUPPORT_', ...
         'SEPARATE_FROM_FINITE_ACTION_REACH_THEN_CAD_STATE_UPDATE'], ...
    'model_cad_transition_sigma_mm', 0.35, ...
    'model_cad_likelihood_floor', 0.02);
% Real baseline geometry retains the endpoint-observed controller and every
% independent guard.  Pure-Outward uses a size-correct capture-overlapping
% pitch (1.0 mm/revolution on M12, 0.87 on M10) and a 4.2 mm radius while
% surface waypoints use 0.60 mm chords.  The
% deployed KST endpoint transaction has a roughly fixed per-command cost, so
% the longer capture-overlapping chord removes avoidable protocol round trips
% instead of merely asking the same 0.60 mm move to run faster.
% Improved Direct is exactly three independently re-probed 5.4 mm rays inside
% the first learned direction's +/-20 degree micro-adjustment sector, without
% a hand-written fan, using 0/+0.25/-0.25 mm reset anchors.  The paper supports
% the slightly changed initial pose, complete re-probe, fresh decision, and
% three-attempt failure rule; 0.25 mm and 20 degrees are M12 CAD/real-data
% engineering choices, not paper parameters.  The former 70 s per-method clock
% was shorter than field-proven cone+shortcut+entropy runs.  It is disabled
% here: measured capture and the terminal verifier end normal motion, while
% three clean Direct misses end that finite baseline at the current pose.
% Finite EIG/CAD action exhaustion hands off to persistent
% phase-shifted coverage rather than ending the method.  The independent
% 900 s whole-run watchdog and every force/torque/workspace guard remain
% active.
cfg.baselines = struct( ...
    'active_time_budget_s', 0.0, ...
    'spiral_pitch_mm_per_revolution', activeCoveragePitchMm, ...
    'proposed_local_pitch_mm_per_revolution', ...
        1.60 * m12ConservativeCaptureRadiusMm, ...
    'proposed_residual_radius_mm', 4.20, ...
    'pure_outward_radius_mm', 4.20, ...
    'path_waypoint_arc_mm', 0.60, ...
    'coverage_phase_increment_rad', pi * (3.0 - sqrt(5.0)), ...
    'direct_ray_limit_mm', activeDirectRayLimitMm, ...
    'direct_max_attempts', 3, ...
    'direct_adjustment_mm', 0.25, ...
    'direct_retry_direction_half_width_deg', 20.0, ...
    'direct_fan_angles_deg', [0.0, 0.0, 0.0]);
% The promoted real_multisize_direction_v1 bundle is produced by the offline
% QC/training lane from the committed M8/M10/M12 real fingerprints.  Its
% manifest and promotion contract authorize only CAD-bounded high-level
% direction/state-posterior routing.  MATLAB remains the sole command owner.
activeLearnedBundleRoot = fullfile(realDir, 'model_runtime', 'bundles', ...
    'real_multisize_direction_v1');
cfg.learning = struct( ...
    'enabled', true, ...
    'size', cadSize, ...
    'model_id', 'real_multisize_direction_v1', ...
    'python_executable', fullfile(realDir, 'model_runtime', ...
        '.venv', 'bin', 'python'), ...
    'inference_script', fullfile(realDir, 'model_runtime', ...
        'infer_conical_direction.py'), ...
    'deployment_manifest', fullfile(activeLearnedBundleRoot, ...
        'deployment_manifest.json'), ...
    'deployment_manifest_sha256', '', ...
    'model_root', activeLearnedBundleRoot, ...
    'required_authority', 'CAPPED_SHORTCUT', ...
    'required_promotion_qualification', 'DEVELOPMENT_CV_CONTROL', ...
    'phase_boundary_timeout_s', 20.0, ...
    'maximum_preflight_runtime_s', 3.0, ...
    'target_down_force_n', 3.5, ...
    'preflight_trace_csv', fullfile(realDir, 'data', ...
        'M12_event_trigger_insert_live_20260724_023025_306', ...
        'conical_directservo_trace.csv'), ...
    'preflight_trace_sha256', ...
        'e2de7a701031175ffdd0a656f96f2489d28b06cb8f033487227cb5717d4b5aaa', ...
    'fixed_demo_pilot_authorization_required', false, ...
    'fixed_demo_pilot_authorization', '', ...
    'fixed_demo_pilot_authorization_sha256', '', ...
    'fixed_demo_pilot_authorization_id', '', ...
    'maximum_authorized_shortcut_mm', 3.00, ...
    'active_bit_radius_mm', m12ShaftAfMm / sqrt(3.0), ...
    'active_head_radius_mm', cadHeadOuterDiameterMm / 2.0, ...
    'active_socket_top_apothem_mm', m12SocketMouthAfMm / 2.0, ...
    'm12_bit_radius_mm', m12ShaftAfMm / sqrt(3.0), ...
    'm12_head_radius_mm', cadHeadOuterDiameterMm / 2.0, ...
    'm12_socket_top_apothem_mm', m12SocketMouthAfMm / 2.0, ...
    'default_authority', 'CAPPED_SHORTCUT');
% Contact transport is deliberately simple and observable: a blocking
% endpoint loop advances XY in short segments while a bounded WORLD-Z
% correction holds a light normal load.  Capture is not inferred from a
% model label; it requires actual downward progress plus a persistent
% soft-envelope observation.  The 2 N event boundary is retained from the
% qualified fixed-orientation contact lane and from the 2026-07-23 runs
% (touchdown peaks 2.58 N and above with <0.04 N baseline axis noise).
%
% 2026-07-29 four-method review.  The funnel_suspect_* cues used to sit
% inside the measured noise: tilt torque swings +/-0.10 Nm during ordinary
% sliding and the force-controlled Z wanders ~0.1 mm on this printed top
% face, so the old 0.025 Nm / 0.12 mm pair fired about 30 s after every
% touchdown and, because nothing ever cleared the hold, stayed on for the
% rest of the trial.  Every threshold now sits above that noise floor and
% the cue must persist (funnel_suspect_consecutive_observations) before it
% may steer the search, with a matching release count.
% maximum_down_before_capture_mm must also exceed the 1.2 mm CAD chamfer:
% at the old 1.20 mm the tip could reach the bottom of the chamfer and no
% further, so surface search could never demonstrate real bore entry.
cfg.surface = struct( ...
    'target_normal_force_n', 4.0, ...
    'force_deadband_n', 1.50, ...
    'transport_normal_force_min_n', 2.5, ...
    'transport_normal_force_max_n', 5.5, ...
    'force_correction_enter_low_n', 2.25, ...
    'force_correction_enter_high_n', 5.75, ...
    'force_correction_exit_low_n', 2.5, ...
    'force_correction_exit_high_n', 5.5, ...
    'negative_observation_normal_min_n', 1.25, ...
    'negative_observation_normal_max_n', 7.5, ...
    'negative_observation_xy_tolerance_mm', 0.30, ...
    'z_stagnation_recenter_limit_mm', 0.60, ...
    'xy_segment_mm', 1.20, ...
    'far_field_xy_segment_mm', 2.00, ...
    'far_field_remaining_mm', 2.50, ...
    'speed_mm_s', 6.0, ...
    'speed_fast_mm_s', 10.0, ...
    'speed_nominal_mm_s', 6.0, ...
    'speed_cautious_mm_s', 3.0, ...
    'speed_cautious_force_delta_n', 8.0, ...
    'speed_cautious_torque_delta_nm', 0.24, ...
    'z_gain_mm_per_n', 0.040, ...
    'minimum_actionable_z_step_mm', 0.060, ...
    'maximum_z_step_mm', 0.080, ...
    'minimum_measured_z_progress_mm', 0.005, ...
    'maximum_stagnant_z_steps', 3, ...
    'endpoint_xy_tolerance_mm', 0.20, ...
    'minimum_xy_progress_mm', 0.010, ...
    'maximum_stagnant_xy_steps', 3, ...
    'phase_timeout_s', 0.0, ...
    'maximum_up_from_surface_mm', 0.50, ...
    'maximum_down_before_capture_mm', 3.50, ...
    'capture_depth_drop_mm', 0.25, ...
    'capture_minimum_recent_drop_mm', 0.04, ...
    'capture_trend_window_steps', 3, ...
    'capture_confirmation_extra_drop_mm', 0.06, ...
    'capture_confirmation_max_normal_force_n', 9.0, ...
    'capture_confirmation_max_steps', 12, ...
    'capture_confirmation_lateral_seek_mm', 0.12, ...
    'capture_candidate_rearm_mm', 0.05, ...
    'funnel_suspect_depth_mm', 0.20, ...
    'funnel_suspect_recent_drop_mm', 0.04, ...
    'funnel_suspect_normal_force_n', 1.20, ...
    'funnel_suspect_lateral_force_n', 1.50, ...
    'funnel_suspect_tilt_torque_nm', 0.12, ...
    'funnel_suspect_consecutive_observations', 3, ...
    'funnel_release_consecutive_observations', 2, ...
    'funnel_maximum_dither_actions', 8, ...
    'funnel_xy_segment_mm', 0.40, ...
    'funnel_dither_radius_mm', 0.15, ...
    'funnel_dither_maximum_radius_mm', 0.60, ...
    'funnel_dither_radial_increment_mm', 0.15, ...
    'funnel_dither_points_per_ring', 6, ...
    'soft_relief_trigger_force_n', 10.0, ...
