% The current M12 hardware-easy tip has an 8 mm across-flats face.  Rotating
% a face-centred TCP through 15 degrees lowers a supporting hex vertex by
% roughly 1.04--1.20 mm depending on phase.  The previous cone commanded no
% such relief and its 0.30 mm/s, +/-0.25 mm residual loop reached 20.669 N
% at the 13.65 degree RAMP sample on 2026-07-23.  A later point-19 scan
% produced one fresh 22.154 N edge-load frame before the old 20 N guard
% could enter soft relief.  Keep a finite 25 N hard guard, add one bounded
% fixed-phase fast relief kick below it, and retain hysteretic unloading.
