function cfg = applySamplingSizeProfile(cfg, executionMode, realDir)
% Bind one size to the shared, field-proven 26-point acquisition state machine.
if strcmp(executionMode, 'DATASET_M8_CONICAL_FINGERPRINTS_26PT')
    cfg.experiment = 'm8_conical_fingerprint_acquisition_v2';
    cfg.sampling.size_lower = 'm8';
    cfg.sampling.size_upper = 'M8';
    cfg.sampling.campaign_id = ...
        'm8_run_local_conical_fingerprints_26pt_v2';
    cfg.sampling.dashboard_function = 'm8_sampling_topview_dashboard';
    cfg.sampling.plan_name = 'm8_printed_cad_conical_sampling_v2';
    cfg.sampling.plan_source_peg_key = ...
        'printed_m8_integrated_peg_step';
    cfg.sampling.run_kind_prefix = 'M8_SAMPLE';
    cfg.sampling.plan_row_prefix = 'm8';
    cfg.sampling.nominal_fixture_center_xy_mm = [-45.0, 0.0];
    cfg.sampling.m12_nominal_fixture_center_xy_mm = [-45.0, 0.0];
    cfg.sampling.expected_geometry_mm = ...
        [14.95, 8.10, 6.50, 0.8, 4.8, 6.0, 0.6, 0.5];
    cfg.learning.size = 'm8';
    cfg.conical.tip_face_af_mm = 4.8;
    cfg.tool.pink_cad_step_sha256 = ...
        '22303873354eeb02d82c2492cb3a5d6b8ba73860b31a67804ca501347692f24b';
    cfg.files.fixture_sampling_plan = canonicalPath(fullfile(realDir, ...
        'configs', 'm8_printed_cad_conical_sampling_v2.json'));
    cfg.files.active_peg_step = canonicalPath(fullfile(realDir, 'model', ...
        'parametric_tooling', 'generated', ...
        'integrated_flange_peg_m8.step'));
    cfg.files.active_simulation_contract = canonicalPath(fullfile(realDir, ...
        '..', 'mujoco_unscrewing_probe_new', 'configs', ...
        'allen_m8_hardware_easy_v2.json'));
    runLocalInstallationRecord = canonicalPath(fullfile(realDir, ...
        'configs', 'm8_run_local_sampling_installation_v1.json'));
    cfg.files.fixture_frame_commissioning = runLocalInstallationRecord;
    cfg.files.tool_metrology_commissioning = runLocalInstallationRecord;
    cfg.files.pink_m12_step = cfg.files.active_peg_step;
    cfg.files.simulation_m12_contract = cfg.files.active_simulation_contract;
    return;
end
isM10Sampling = strcmp(executionMode, ...
    'DATASET_M10_CONICAL_FINGERPRINTS_26PT');
isM10FixedDemo = strcmp(executionMode, ...
    'FULL_LOOP_PROPOSED_PLUS_LEARNED_ENTROPY_M10');
if ~isM10Sampling && ~isM10FixedDemo
    return;
end
if isM10FixedDemo
    cfg.experiment = 'm10_fixed_proposed_plus_demo_pilot_v1';
else
    cfg.experiment = 'm10_conical_fingerprint_acquisition_v2';
end
cfg.sampling.size_lower = 'm10';
cfg.sampling.size_upper = 'M10';
cfg.sampling.campaign_id = ...
    'm10_run_local_conical_fingerprints_26pt_v2';
cfg.sampling.dashboard_function = 'm10_sampling_topview_dashboard';
cfg.sampling.plan_name = 'm10_printed_cad_conical_sampling_v2';
cfg.sampling.plan_source_peg_key = ...
    'printed_m10_integrated_peg_step';
cfg.sampling.run_kind_prefix = 'M10_SAMPLE';
cfg.sampling.plan_row_prefix = 'm10';
cfg.sampling.nominal_fixture_center_xy_mm = [0.0, 0.0];
% Retain the legacy field only as a compatibility alias inside the shared
% executor; M10 manifests use the generic size-correct field below.
cfg.sampling.m12_nominal_fixture_center_xy_mm = [0.0, 0.0];
cfg.sampling.expected_geometry_mm = ...
    [18.975, 10.54, 8.54, 1.0, 6.4, 8.0, 0.8, 0.5];
cfg.learning.size = 'm10';
cfg.conical.tip_face_af_mm = 6.4;
cfg.tool.pink_cad_step_sha256 = ...
    '17381968212daa2b7758dcf3795df32b3a4e687b42c482d3550111e03ae8daa2';
cfg.files.fixture_sampling_plan = canonicalPath(fullfile(realDir, ...
    'configs', 'm10_printed_cad_conical_sampling_v2.json'));
cfg.files.active_peg_step = canonicalPath(fullfile(realDir, 'model', ...
    'parametric_tooling', 'generated', ...
    'integrated_flange_peg_m10.step'));
cfg.files.active_simulation_contract = canonicalPath(fullfile(realDir, ...
    '..', 'mujoco_unscrewing_probe_new', 'configs', ...
    'allen_m10_hardware_easy_v2.json'));
if isM10FixedDemo
    runLocalInstallationRecord = canonicalPath(fullfile(realDir, ...
        'configs', 'm10_fixed_demo_installation_v1.json'));
    % The first successful real M10 run on 2026-07-30 showed that capture
    % itself was light (4.131 N peak), while the following shallow insertion
    % reached 17.199/17.532 N before the shared 16 N soft branch reacted.
    % Trigger that same guarded planar release one endpoint earlier on M10.
    % At the terminal set the run reached 1.605 N / 0.0854 Nm but missed the
    % shared 0.08 Nm low-wrench gate by 0.0054 Nm, causing eight additional
    % planar actions.  The M10-only 0.10 Nm value remains below the separate
    % 0.20/0.50/0.75 Nm terminal/soft/hard torque hierarchy.  Depth band,
    % three stable dwells, force criterion, and all independent guards stay
    % unchanged.
    cfg.insertion.controller_tuning_revision = ...
        'M10_CHAMFER_FORCE14_TERMINAL_TORQUE010_V2';
    cfg.sensor.insertion_soft_force_delta_n = 14.0;
    cfg.insertion.terminal_low_wrench_torque_nm = 0.10;
    cfg.sampling.motion_authorization_source = ...
        'EXPLICIT_FIXED_M10_DEMO_ENTRYPOINT_AND_PRIVATE_OFFSET';
    cfg.learning.preflight_trace_csv = canonicalPath(fullfile( ...
        realDir, 'data', ...
        'M10_conical_fingerprints_26pt_20260728_152808_877', ...
        'sampling_attempts', ...
        '26_M10-CLEAN_CANDIDATE-SUPPORTED-A003p75', ...
        'conical_trace_raw.csv'));
    cfg.learning.preflight_trace_sha256 = ...
        '15851bf5d483a8accd77b54ade0a8d763f2cb4b7d9e1b45e028fe03fa2a5a919';
    cfg.learning.fixed_demo_pilot_authorization_required = true;
    cfg.learning.fixed_demo_pilot_authorization = canonicalPath(fullfile( ...
        realDir, 'configs', ...
        'm10_fixed_demo_pilot_authorization_v1.json'));
    cfg.learning.fixed_demo_pilot_authorization_sha256 = ...
        '8f09bdc86949ee448d29795ca7100347be4b865083f93dfa7761eae9834dc825';
    cfg.learning.fixed_demo_pilot_authorization_id = ...
        'M10_FIXED_PROPOSED_PLUS_DEMO_20260730_V1';
else
    runLocalInstallationRecord = canonicalPath(fullfile(realDir, ...
        'configs', 'm10_run_local_sampling_installation_v1.json'));
end
cfg.files.fixture_frame_commissioning = runLocalInstallationRecord;
cfg.files.tool_metrology_commissioning = runLocalInstallationRecord;
% Old field names remain aliases so stable persistence/readback code does
% not fork.  Generic active_* records are the authority written for M10.
cfg.files.pink_m12_step = cfg.files.active_peg_step;
cfg.files.simulation_m12_contract = cfg.files.active_simulation_contract;
end

function plan = makePlan(cfg, policy)
actionOffsets = buildGridOffsets(cfg);
[~, order] = sortrows([vecnorm(actionOffsets, 2, 2), ...
    mod(atan2(actionOffsets(:, 2), actionOffsets(:, 1)), 2 * pi)], [1, 2]);
actionOffsets = actionOffsets(order, :);
centerHypotheses = buildCenterHypothesisOffsets(cfg);
[~, order] = sortrows([vecnorm(centerHypotheses, 2, 2), ...
    mod(atan2(centerHypotheses(:, 2), ...
        centerHypotheses(:, 1)), 2 * pi)], [1, 2]);
centerHypotheses = centerHypotheses(order, :);
commonTerminal = { ...
    'SOFT_ENVELOPE_DOWNWARD_PROGRESS_CHAMFER_CAPTURE', ...
    sprintf('%s_0P1MM_SEGMENT_INSERT_TO_ACTIVE_TARGET_DEPTH', ...
        cfg.sampling.size_upper), ...
    'DEPTH_BAND_AND_PERSISTENT_BOTTOM_EVENT', ...
    'REMAIN_AT_BOTTOM_AND_KST_END'};
switch policy.mode
    case 'FULL_LOOP_BASELINE_PURE_OUTWARD_SPIRAL'
        workflow = [{ ...
            'FRESH_TASK_LOCAL_START', ...
            'SHORT_TOUCHDOWN_AND_MEASURED_XY_ANCHOR', ...
            'FORCE_HELD_GLOBAL_OUTWARD_ARCHIMEDEAN_SEARCH'}, ...
            commonTerminal];
    case 'FULL_LOOP_PROPOSED_LEARNED_LOCAL_SPIRAL'
        workflow = [{ ...
            'FRESH_TASK_LOCAL_START', ...
            'SHORT_TOUCHDOWN_AND_MEASURED_XY_ANCHOR', ...
            'CONTINUOUS_TIP_CENTERED_15_DEG_CONTACT_CONE_NO_LIFT', ...
            'ACTIVE_LEARNED_CAD_POSTERIOR_SHORTCUT', ...
            'FORCE_HELD_LOCAL_OUTWARD_ARCHIMEDEAN_RESIDUAL'}, ...
            commonTerminal];
    case 'FULL_LOOP_BASELINE_IMPROVED_DIRECT_X3_LEARNED'
        workflow = [{ ...
            'FRESH_TASK_LOCAL_START', ...
            'SHORT_TOUCHDOWN_AND_MEASURED_XY_ANCHOR', ...
            'EXACTLY_THREE_MAXIMUM_INDEPENDENT_QUALIFIED_CONES_AND_DIRECT_RAYS', ...
            'ON_CAPTURE_USE_COMMON_INSERTION_ELSE_METHOD_EXHAUSTED_AT_CURRENT_POSE'}, ...
            commonTerminal];
    case {'DATASET_M12_CONICAL_FINGERPRINTS_26PT', ...
            'DATASET_M10_CONICAL_FINGERPRINTS_26PT', ...
            'DATASET_M8_CONICAL_FINGERPRINTS_26PT'}
        workflow = {'SAMPLING_PLAN_WRITTEN_BY_DEDICATED_CAMPAIGN_WRITER'};
    otherwise
        workflow = [{ ...
            'FRESH_TASK_LOCAL_START', ...
            'SHORT_TOUCHDOWN_AND_MEASURED_XY_ANCHOR', ...
            'CONTINUOUS_TIP_CENTERED_15_DEG_CONTACT_CONE_NO_LIFT', ...
            'ACTIVE_LEARNED_CAD_POSTERIOR_SHORTCUT', ...
            'FORCE_HELD_FINITE_ENTROPY_GRID_OVER_MEASURED_TOUCHDOWN_ANCHOR'}, ...
            commonTerminal];
end
plan = struct( ...
    'action_offsets_mm', actionOffsets, ...
    'grid_offsets_mm', actionOffsets, ...
    'center_hypotheses_mm', centerHypotheses, ...
    'conical', cfg.conical, ...
    'workflow', {workflow});
end

function grid = buildGridOffsets(cfg)
grid = buildCircularOffsets( ...
    cfg.search.grid_pitch_mm, cfg.search.action_reach_mm);
end

function grid = buildCenterHypothesisOffsets(cfg)
grid = buildCircularOffsets(cfg.search.grid_pitch_mm, ...
    cfg.search.center_hypothesis_radius_mm);
end

function grid = buildCircularOffsets(pitchMm, radiusMm)
integerRadius = ceil(radiusMm / pitchMm);
grid = zeros(0, 2);
for ix = -integerRadius:integerRadius
    for iy = -integerRadius:integerRadius
        candidate = pitchMm * [ix, iy];
        if norm(candidate) <= radiusMm + 1e-12
            grid(end + 1, :) = candidate; %#ok<AGROW>
        end
    end
end
end

function validateConicalContract(cfg)
assert(abs(cfg.conical.tilt_deg - 15.0) < 1e-12, ...
    'M12Demo:ConicalTiltContract', ...
    'The active conical fingerprint must use exactly 15 degrees.');
assert(abs(cfg.conical.tip_vertex_phase_in_pink_cad_deg - 15.0) < ...
        1e-12 && ...
    strcmp(cfg.conical.tip_vertex_phase_semantics, ...
        ['current_v1_5_pink_CAD_frame_30deg_legacy_vertices_', ...
         'minus_15deg_shape_clocking']), ...
    'M12Demo:ConicalTipPhaseContract', ...
    ['The v1.5 one-piece peg has vertices at 15+60k degrees in the ', ...
     'pink-CAD/TCP frame.  Do not restore the legacy 30+60k phase unless ', ...
     'an explicit hashed +15-degree canonical frame adapter is installed.']);
assert(cfg.conical.command_rate_hz >= 40.0 && ...
    cfg.conical.scan_s > 3.0 && cfg.conical.phase_bins == 360, ...
    'M12Demo:ConicalTimingContract', ...
    'Conical rate, duration, or phase-bin contract changed.');
assert(strcmp(cfg.conical.feedback_policy, ...
        'PRE_AND_POST_ONLY_NO_IN_LOOP_SYNC_QUERY'), ...
    'M12Demo:ConicalFeedbackPolicy', ...
    ['The deployed server must not receive a synchronous state query ', ...
     'inside the DirectServo command loop.']);
assert(cfg.conical.maximum_single_tick_lateness_s > ...
        cfg.conical.maximum_tick_lateness_s && ...
    cfg.conical.maximum_consecutive_late_ticks >= 2, ...
    'M12Demo:ConicalOverrunContract', ...
    'Conical clock resynchronization and sustained-overrun gates changed.');
assert(cfg.conical.edge_relief_feedforward && ...
    cfg.conical.force_relief_uses_total_force_above_resume && ...
    cfg.conical.force_relief_resume_n < ...
        cfg.conical.force_relief_hold_n && ...
    cfg.conical.force_relief_resume_samples >= 3 && ...
    cfg.conical.force_relief_hold_n < cfg.sensor.hard_force_delta_n && ...
    cfg.conical.force_relief_fast_trigger_n > ...
        cfg.conical.force_relief_hold_n && ...
    cfg.conical.force_relief_fast_trigger_n < ...
        cfg.sensor.hard_force_delta_n && ...
    cfg.conical.force_relief_fast_step_mm > 0.0 && ...
    cfg.conical.force_relief_fast_step_mm <= ...
        cfg.conical.maximum_z_relief_offset_mm && ...
    cfg.conical.maximum_z_relief_speed_mm_s > ...
        cfg.conical.maximum_z_press_speed_mm_s && ...
    cfg.conical.maximum_z_relief_offset_mm > ...
        cfg.conical.maximum_z_press_offset_mm, ...
    'M12Demo:ConicalForceFollowingContract', ...
    ['The cone must retain geometric edge relief, asymmetric WORLD +Z ', ...
     'unloading, bounded fast relief, hysteresis, and the independent ', ...
     '25 N hard guard.']);
assert(cfg.conical.low_force_guard_enabled && ...
    cfg.conical.low_force_hold_target_fraction > 0.0 && ...
    cfg.conical.low_force_hold_target_fraction < ...
        cfg.conical.low_force_recover_target_fraction && ...
    cfg.conical.low_force_hold_total_force_target_fraction > ...
        cfg.conical.low_force_hold_target_fraction && ...
    cfg.conical.low_force_hold_total_force_target_fraction < ...
        cfg.conical.low_force_recover_total_force_target_fraction && ...
    cfg.conical.low_force_recover_target_fraction < 1.0 && ...
    cfg.conical.low_force_noise_sigma_multiplier >= 5.0 && ...
    cfg.conical.low_force_hysteresis_noise_sigma_multiplier >= 2.0 && ...
    cfg.conical.low_force_persistent_samples >= 2 && ...
    cfg.conical.low_force_recover_samples >= 2 && ...
    cfg.conical.low_force_recover_total_force_target_fraction > ...
        cfg.conical.low_force_hold_target_fraction && ...
    cfg.conical.low_force_recover_total_force_target_fraction < 1.0 && ...
    cfg.conical.low_force_reacquire_speed_mm_s > 0.0 && ...
    cfg.conical.low_force_reacquire_speed_mm_s < ...
        cfg.conical.maximum_z_press_speed_mm_s && ...
    cfg.conical.low_force_maximum_resume_drop_mm > 0.0 && ...
    cfg.conical.low_force_maximum_resume_drop_mm <= ...
        cfg.conical.low_force_maximum_reacquire_mm && ...
    abs(cfg.conical.low_force_maximum_reacquire_mm - ...
        cfg.surface.capture_depth_drop_mm) <= 1e-12 && ...
    cfg.conical.low_force_maximum_episode_s > ...
        cfg.conical.low_force_persistent_samples / ...
            cfg.conical.command_rate_hz && ...
    cfg.conical.low_force_maximum_total_s >= ...
        cfg.conical.low_force_maximum_episode_s && ...
    cfg.conical.low_force_obstruction_force_target_fraction > ...
        cfg.conical.low_force_recover_target_fraction && ...
    cfg.conical.low_force_obstruction_moment_target_fraction > 0.0 && ...
    cfg.conical.low_force_obstruction_persistent_samples >= 3 && ...
    cfg.conical.low_force_obstruction_relief_mm > 0.0 && ...
    cfg.conical.low_force_obstruction_relief_mm <= ...
        cfg.surface.soft_relief_step_mm && ...
    cfg.conical.routing_quality_minimum > 0.0 && ...
    cfg.conical.routing_quality_minimum < 1.0 && ...
    cfg.conical.routing_ramp_episode_log_penalty > 0.0 && ...
    cfg.conical.routing_scan_episode_log_penalty > ...
        cfg.conical.routing_ramp_episode_log_penalty && ...
    cfg.conical.routing_low_force_wall_reference_s > 0.0 && ...
    cfg.conical.routing_low_force_wall_log_penalty > 0.0 && ...
    cfg.conical.routing_reacquire_log_penalty > 0.0, ...
    'M12Demo:ConicalLowForceContract', ...
    ['The low-force mode transition must use baseline-noise/target-scaled ', ...
     'hysteresis, persistent fresh samples, a slower bounded reacquisition ', ...
     'equal to the physical capture-depth cue, and one bounded +Z ', ...
     'obstruction relief inside the existing surface envelope.']);
provisionalAxialMm = ...
    cfg.tool.media_flange_to_pink_cad_plane_whole_observation_mm + ...
    cfg.tool.pink_cad_plane_to_tip_mm;
strictMeasuredTcp = numel(cfg.tool.translation_mm) == 3 && ...
    all(isfinite(cfg.tool.translation_mm)) && ...
    strcmp(cfg.tool.status, ...
        'MEASURED_FULL_3D_TCP_PIVOT_TOUCH_OFF_HASH_QUALIFIED') && ...
    cfg.tool.flange_to_tip_uncertainty_mm > 0.0 && ...
    cfg.tool.flange_to_tip_uncertainty_mm <= 0.25 && ...
    abs(norm(cfg.tool.translation_mm) - provisionalAxialMm) <= 22.0;
oldKernelCompatibleTcp = ...
    cfg.compatibility.old_kernel_motion_compatibility_enabled && ...
    numel(cfg.tool.translation_mm) == 3 && ...
    all(isfinite(cfg.tool.translation_mm)) && ...
    strcmp(cfg.tool.status, ...
        'PROVISIONAL_OLD_KERNEL_COMPATIBILITY_92MM_AXIAL_TCP') && ...
    max(abs(cfg.tool.translation_mm - ...
        cfg.compatibility.tip_tcp_translation_mm)) <= 1e-12 && ...
    abs(cfg.tool.flange_to_tip_uncertainty_mm - ...
        cfg.compatibility.tip_tcp_standard_uncertainty_mm) <= 1e-12 && ...
    abs(norm(cfg.tool.translation_mm) - provisionalAxialMm) <= 1e-9;
runLocalSamplingTcp = any(strcmp(cfg.execution_mode, { ...
        'DATASET_M12_CONICAL_FINGERPRINTS_26PT', ...
        'DATASET_M10_CONICAL_FINGERPRINTS_26PT', ...
        'DATASET_M8_CONICAL_FINGERPRINTS_26PT'})) && ...
    numel(cfg.tool.translation_mm) == 3 && ...
    all(isfinite(cfg.tool.translation_mm)) && ...
    strcmp(cfg.tool.status, ...
        'OPERATOR_INSTALLED_92MM_AXIAL_TCP_RUN_LOCAL_SAMPLING') && ...
    max(abs(cfg.tool.translation_mm - ...
        cfg.compatibility.tip_tcp_translation_mm)) <= 1e-12 && ...
    abs(cfg.tool.flange_to_tip_uncertainty_mm - ...
        cfg.compatibility.tip_tcp_standard_uncertainty_mm) <= 1e-12;
assert(strictMeasuredTcp || oldKernelCompatibleTcp || runLocalSamplingTcp, ...
    'M12Demo:MeasuredToolTcpContract', ...
    ['Conical motion requires either the hash-qualified full 3D pivot/', ...
     'touch-off TCP, the explicitly enabled field-proven old-kernel ', ...
     '[0 0 92] mm compatibility TCP, or the disclosed run-local sampling ', ...
     'TCP with no metrology claim.']);
assert(abs(cfg.tool.pink_cad_plane_to_tip_mm - 42.0) < 1e-12 && ...
    abs(cfg.tool.pink_cad_flange_thickness_mm_nonadditive - 8.0) < 1e-12, ...
    'M12Demo:PinkCadContract', ...
    'The delivered pink CAD datum no longer matches 42 mm including flange.');
testStart = [472.8, 0.8, 563.0, pi, 0.0, pi];
testSchedule = buildConicalSchedule(testStart, cfg);
scanMask = strcmp(testSchedule.stage, 'SCAN');
assert(any(scanMask) && ...
    max(testSchedule.phase_rad(scanMask)) >= 2.0 * pi - 1e-12, ...
    'M12Demo:ConicalClosure', ...
    'The mathematical conical schedule does not complete 360 degrees.');
translationSpan = max(vecnorm( ...
    testSchedule.command_pose(:, 1:3) - testStart(1:3), 2, 2));
assert(translationSpan < 1e-12, ...
    'M12Demo:ConicalPivotContract', ...
    'The mathematical cone does not keep the registered tip fixed.');
minimumFullTiltReliefMm = ...
    0.5 * cfg.conical.tip_face_af_mm * sind(cfg.conical.tilt_deg);
maximumFullTiltReliefMm = ...
    cfg.conical.tip_face_af_mm / sqrt(3.0) * ...
        sind(cfg.conical.tilt_deg);
scanRelief = testSchedule.edge_relief_mm(scanMask);
assert(min(scanRelief) >= minimumFullTiltReliefMm - 1e-9 && ...
    max(scanRelief) <= maximumFullTiltReliefMm + 1e-9 && ...
    max(scanRelief) - min(scanRelief) > 0.05, ...
    'M12Demo:ConicalHexSupportContract', ...
    ['The 15 degree tip-centered schedule must compensate the rotating ', ...
     '%.3f mm-AF hex support edge before applying residual force control.'], ...
    cfg.conical.tip_face_af_mm);
assert(max(scanRelief) + ...
        cfg.conical.maximum_z_relief_offset_mm <= ...
        cfg.motion.maximum_up_excursion_mm + 1e-9, ...
    'M12Demo:ConicalReliefWorkspaceContract', ...
    ['Maximum geometric plus residual cone relief must fit inside the ', ...
     'task-local WORLD +Z workspace envelope.']);
end

function validateModelDeploymentTrustAnchor(cfg)
assert(isfile(cfg.learning.deployment_manifest), ...
    'M12Demo:LearnedManifestTrustAnchor', ...
    'The active deployment manifest is absent: %s', ...
    cfg.learning.deployment_manifest);
if ~isempty(cfg.learning.deployment_manifest_sha256)
    assert(strcmp(sha256File(cfg.learning.deployment_manifest), ...
            cfg.learning.deployment_manifest_sha256), ...
        'M12Demo:LearnedManifestTrustAnchor', ...
        ['The active deployment manifest changed.  Refuse before KST; ', ...
         'review and atomically re-pin the complete promoted bundle.']);
end
deployment = jsondecode(fileread(cfg.learning.deployment_manifest));
assert(isfield(deployment, 'schema_version') && ...
        double(deployment.schema_version) == 1 && ...
        strcmp(char(deployment.model_id), cfg.learning.model_id), ...
    'M12Demo:LearnedManifestIdentity', ...
    'The active bundle manifest schema/model identity is invalid.');
if isfield(deployment, 'deployment_authority')
    % real_multisize_direction_v1 uses the compact deployment schema.  Its
    % size scope lives in a separately hash-bound interface contract.
    assert(strcmp(char(deployment.deployment_authority), ...
            cfg.learning.required_authority) && ...
        any(strcmp(string(deployment.allowed_execution_modes), ...
            cfg.learning.required_authority)) && ...
        isfield(deployment, 'ensemble_interface_contract') && ...
        isfield(deployment, 'ensemble_interface_contract_sha256') && ...
        isValidSha256(char( ...
            deployment.ensemble_interface_contract_sha256)) && ...
        isfield(deployment, 'promotion_contract') && ...
        isfield(deployment, 'promotion_contract_sha256') && ...
        isValidSha256(char(deployment.promotion_contract_sha256)), ...
        'M12Demo:LearnedManifestScope', ...
        ['The compact active bundle must expose hash-bound interface and ', ...
         'promotion contracts with CAPPED_SHORTCUT authority.']);
    interfacePath = char(deployment.ensemble_interface_contract);
    if ~startsWith(interfacePath, filesep)
        interfacePath = fullfile( ...
            fileparts(cfg.learning.deployment_manifest), interfacePath);
    end
    interfacePath = canonicalPath(interfacePath);
    assert(isfile(interfacePath) && ...
        strcmp(sha256File(interfacePath), char( ...
            deployment.ensemble_interface_contract_sha256)), ...
        'M12Demo:LearnedInterfaceTrustAnchor', ...
        'The active ensemble interface contract is absent or changed.');
    interface = jsondecode(fileread(interfacePath));
    assert(double(interface.schema_version) == 1 && ...
        strcmp(char(interface.model_id), cfg.learning.model_id) && ...
        any(strcmp(string(interface.supported_sizes), ...
            cfg.learning.size)) && ...
        isfield(interface, 'policy_boundary') && ...
        ~logical(interface.policy_boundary.capture_insertion_or_terminal_authority) && ...
        ~logical(interface.policy_boundary.pure_outward_spiral_consumer), ...
        'M12Demo:LearnedInterfaceScope', ...
        ['The active interface must support M12 high-level routing only; ', ...
         'capture/insertion/terminal and Pure-Outward authority are forbidden.']);
    promotionPath = char(deployment.promotion_contract);
    promotionSha256 = char(deployment.promotion_contract_sha256);
else
    % Keep the already-deployed legacy schema readable for audit/replay, but
    % never weaken the same explicit authority, size and hash requirements.
    assert(strcmp(char(deployment.hardware_authority.default), ...
            cfg.learning.required_authority) && ...
        any(strcmp(string(deployment.hardware_authority.allowed_values), ...
            cfg.learning.required_authority)) && ...
        any(strcmp(string(deployment.supported_sizes), cfg.learning.size)) && ...
        ~isempty(deployment.hardware_authority.promotion_contract_path) && ...
        isValidSha256(char( ...
            deployment.hardware_authority.promotion_contract_sha256)), ...
        'M12Demo:LearnedManifestScope', ...
        ['The legacy active bundle must match model/size and expose an ', ...
         'explicit CAPPED_SHORTCUT promotion contract.']);
    promotionPath = char( ...
        deployment.hardware_authority.promotion_contract_path);
    promotionSha256 = char( ...
        deployment.hardware_authority.promotion_contract_sha256);
end
if ~startsWith(promotionPath, filesep)
    promotionPath = fullfile( ...
        fileparts(cfg.learning.deployment_manifest), promotionPath);
end
promotionPath = canonicalPath(promotionPath);
assert(isfile(promotionPath) && ...
    strcmp(sha256File(promotionPath), promotionSha256), ...
    'M12Demo:LearnedPromotionTrustAnchor', ...
    'The active promotion contract is absent or its hash changed.');
promotion = jsondecode(fileread(promotionPath));
promotionIdentityBound = true;
if isfield(promotion, 'deployment_manifest_model_id')
    promotionIdentityBound = strcmp( ...
        char(promotion.deployment_manifest_model_id), ...
        cfg.learning.model_id);
end
assert(double(promotion.schema_version) == 1 && ...
    strcmp(char(promotion.status), 'QUALIFIED') && ...
    strcmp(char(promotion.qualification), ...
        cfg.learning.required_promotion_qualification) && ...
    strcmp(char(promotion.model_id), cfg.learning.model_id) && ...
    promotionIdentityBound && ...
    logical(promotion.authorization.capped_shortcut_hardware_control) && ...
    (~isfield(promotion.authorization, 'capture_control') || ...
        ~logical(promotion.authorization.capture_control)) && ...
    (~isfield(promotion.authorization, 'insertion_control') || ...
        ~logical(promotion.authorization.insertion_control)) && ...
    (~isfield(promotion.authorization, 'terminal_verification') || ...
        ~logical(promotion.authorization.terminal_verification)), ...
    'M12Demo:LearnedPromotionScope', ...
    ['Promotion contract identity/qualification is invalid or does not ', ...
     'limit authority to capped high-level hardware routing.']);
if cfg.learning.fixed_demo_pilot_authorization_required
    validateM10FixedDemoPilotAuthorization(cfg);
end
end

function validateM10FixedDemoPilotAuthorization(cfg)
path = cfg.learning.fixed_demo_pilot_authorization;
assert(strcmp(cfg.learning.size, 'm10') && ...
        strcmp(cfg.execution_mode, ...
            'FULL_LOOP_PROPOSED_PLUS_LEARNED_ENTROPY_M10') && ...
        isfile(path) && ...
        strcmp(sha256File(path), ...
            cfg.learning.fixed_demo_pilot_authorization_sha256), ...
    'M12Demo:M10FixedDemoPilotTrustAnchor', ...
    ['The M10 pilot is valid only for the exact fixed-demo mode and ', ...
     'hash-pinned authorization record.']);
record = jsondecode(fileread(path));
required = {'schema_version', 'authorization_id', 'status', ...
    'model_id', 'size', 'execution_mode', 'public_entrypoint', ...
    'authorization', 'fixed_demo', 'real_source_evidence', ...
    'geometry_contract', 'control_boundary'};
offset = double(reshape(record.fixed_demo.offset_fixture_mm, 1, []));
sourceOffset = double(reshape( ...
    record.fixed_demo.source_sample_offset_fixture_mm, 1, []));
sourceTrace = canonicalPath(char( ...
    record.real_source_evidence.clean_conical_trace_csv));
physicalSupportRadiusMm = double(record.fixed_demo. ...
    maximum_physical_tip_center_radius_from_fresh_center_mm);
supportTrackingAllowanceMm = double(record.fixed_demo. ...
    endpoint_tracking_allowance_mm);
commandedSupportRadiusMm = double(record.fixed_demo. ...
    maximum_commanded_tip_center_radius_from_fresh_center_mm);
derivedPhysicalSupportRadiusMm = ...
    double(record.geometry_contract.socket_head_outer_diameter_mm) / 2.0 - ...
    double(record.geometry_contract.peg_tip_face_af_mm) / sqrt(3.0);
assert(all(isfield(record, required)) && ...
        double(record.schema_version) == 1 && ...
        strcmp(char(record.authorization_id), ...
            cfg.learning.fixed_demo_pilot_authorization_id) && ...
        strcmp(char(record.status), ...
            ['EXPERIMENTAL_FIXED_DEMO_PILOT_', ...
             'AUTHORIZED_BY_OPERATOR_REQUEST']) && ...
        strcmp(char(record.model_id), cfg.learning.model_id) && ...
        strcmp(char(record.size), 'm10') && ...
        strcmp(char(record.execution_mode), cfg.execution_mode) && ...
        strcmp(char(record.public_entrypoint), ...
            'run_m10_proposed_plus_entropy_trial') && ...
        logical(record.authorization.fixed_demo_only) && ...
        logical(record.authorization.capped_shortcut_hardware_control) && ...
        logical(record.authorization.residual_entropy_target_selection) && ...
        ~logical(record.authorization.capture_control) && ...
        ~logical(record.authorization.insertion_control) && ...
        ~logical(record.authorization.terminal_verification) && ...
        ~logical(record.authorization.online_weight_update) && ...
        double(record.authorization.maximum_launcher_attempts) == 3 && ...
        numel(offset) == 2 && ...
        norm(offset - [ ...
            4.590151046897575, 0.3008543944586581]) <= 1e-12 && ...
        numel(sourceOffset) == 2 && ...
        norm(sourceOffset - [5.521449100, 0.361894894]) <= 1e-12 && ...
        strcmp(char(record.fixed_demo.source_sample_id), ...
            'M10-CLEAN_CANDIDATE-SUPPORTED-A003p75') && ...
        logical(record.fixed_demo. ...
            fresh_operator_taught_m10_center_required_each_attempt) && ...
        logical(record.fixed_demo. ...
            historical_absolute_world_center_forbidden) && ...
        logical(record.fixed_demo. ...
            fresh_center_support_envelope_required) && ...
        strcmp(char(record.fixed_demo.support_envelope_role), ...
            ['SAFETY_FAIL_STOP_ONLY_NEVER_POSTERIOR_INPUT_', ...
             'NEVER_TARGET_RANKING_NEVER_STEERING']) && ...
        abs(physicalSupportRadiusMm - ...
            derivedPhysicalSupportRadiusMm) <= 1e-12 && ...
        abs(physicalSupportRadiusMm - 5.792458277186394) <= 1e-12 && ...
        abs(supportTrackingAllowanceMm - 0.600) <= 1e-12 && ...
        abs(commandedSupportRadiusMm - ...
            (physicalSupportRadiusMm - ...
                supportTrackingAllowanceMm)) <= 1e-12 && ...
        abs(commandedSupportRadiusMm - 5.192458277186394) <= 1e-12 && ...
        logical(record.real_source_evidence.clean_cone_completed) && ...
        logical(record.real_source_evidence.clean_safe_retract_completed) && ...
        double(record.real_source_evidence. ...
            clean_phase_coverage_fraction) >= 0.98 && ...
        isfile(sourceTrace) && ...
        strcmp(sha256File(sourceTrace), char( ...
            record.real_source_evidence.clean_conical_trace_sha256)) && ...
        abs(double(record.geometry_contract.socket_depth_mm) - 5.0) <= ...
            1e-12 && ...
        double(record.geometry_contract.grid_node_count) == ...
            cfg.search.maximum_grid_nodes && ...
        any(contains(string( ...
            record.control_boundary.independent_guards_retained), ...
            "fresh-center M10 head-support command envelope")) && ...
        contains(string(record.control_boundary.claim_limit), ...
            "not general M10 full-loop promotion"), ...
    'M12Demo:M10FixedDemoPilotContract', ...
    ['The M10 fixed-demo authorization identity, real sample evidence, ', ...
     'geometry, attempt bound, or no-general-promotion boundary changed.']);
end

function argument = learnedPilotAuthorizationCliArgument(cfg)
argument = '';
if cfg.learning.fixed_demo_pilot_authorization_required
    validateM10FixedDemoPilotAuthorization(cfg);
    argument = sprintf('--pilot-authorization %s', ...
        shellSafePath(cfg.learning.fixed_demo_pilot_authorization));
end
end

function preflight = validateLearnedRuntimePreflight(cfg, paths)
validateModelDeploymentTrustAnchor(cfg);
assert(isfile(cfg.learning.python_executable), ...
    'M12Demo:LearnedPythonMissingPreflight', ...
    'Deployment Python is missing: %s', ...
    cfg.learning.python_executable);
assert(isfile(cfg.learning.inference_script), ...
    'M12Demo:LearnedRuntimeMissingPreflight', ...
    'Frozen inference script is missing: %s', ...
    cfg.learning.inference_script);
assert(isfolder(cfg.learning.model_root), ...
    'M12Demo:LearnedModelMissingPreflight', ...
    'Frozen model root is missing: %s', cfg.learning.model_root);
assert(isfile(cfg.learning.preflight_trace_csv) && ...
        strcmp(sha256File(cfg.learning.preflight_trace_csv), ...
            cfg.learning.preflight_trace_sha256), ...
    'M12Demo:LearnedPreflightTraceTrustAnchor', ...
    ['The pinned, motion-free learned-runtime smoke trace is missing or ', ...
     'changed.  Refuse before KST connection.']);
command = sprintf([ ...
    '/usr/bin/timeout %.0f %s %s --trace-csv %s ', ...
    '--output-json %s --model-root %s --manifest %s ', ...
    '--size %s --target-down-force-n %.9f %s 2>&1'], ...
    cfg.learning.phase_boundary_timeout_s, ...
    shellSafePath(cfg.learning.python_executable), ...
    shellSafePath(cfg.learning.inference_script), ...
    shellSafePath(cfg.learning.preflight_trace_csv), ...
    shellSafePath(paths.learnedPreflightOutput), ...
    shellSafePath(cfg.learning.model_root), ...
    shellSafePath(cfg.learning.deployment_manifest), ...
    cfg.learning.size, cfg.learning.target_down_force_n, ...
    learnedPilotAuthorizationCliArgument(cfg));
preflightClock = tic;
[status, processOutput] = system(command);
preflightElapsedS = toc(preflightClock);
assert(status == 0, 'M12Demo:LearnedRuntimePreflightProcess', ...
    ['Frozen learned-runtime preflight failed before KST connection ', ...
     '(%d): %s'], status, oneLine(processOutput));
assert(isfinite(preflightElapsedS) && ...
        preflightElapsedS < cfg.learning.maximum_preflight_runtime_s, ...
    'M12Demo:LearnedRuntimePreflightTooSlow', ...
    ['Learned-runtime preflight took %.3f s, exceeding the %.3f s ', ...
     'phase-boundary contract before KST connection.'], ...
    preflightElapsedS, cfg.learning.maximum_preflight_runtime_s);
assert(isfile(paths.learnedPreflightOutput), ...
    'M12Demo:LearnedRuntimePreflightOutput', ...
    'Learned-runtime preflight returned success without output JSON.');
value = jsondecode(fileread(paths.learnedPreflightOutput));
assert(strcmp(char(value.status), 'OK') && ...
        strcmp(char(value.model_id), cfg.learning.model_id), ...
    'M12Demo:LearnedRuntimePreflightIdentity', ...
    'Learned-runtime preflight status/model identity is invalid.');
assertActiveLearnedOutput(value, cfg, ...
    'M12Demo:LearnedRuntimePreflightOutputContract');
pilotVerified = false;
pilotAuthorizationId = '';
pilotAuthorizationSha256 = '';
pilotScope = '';
if cfg.learning.fixed_demo_pilot_authorization_required
    pilotVerified = logical( ...
        value.fixed_demo_pilot_authorization_verified);
    pilotAuthorizationId = char( ...
        value.fixed_demo_pilot_authorization_id);
    pilotAuthorizationSha256 = char( ...
        value.fixed_demo_pilot_authorization_sha256);
    pilotScope = char(value.fixed_demo_pilot_scope);
end
preflight = struct( ...
    'status', 'PASS_BEFORE_KST_NO_MOTION', ...
    'python_executable', cfg.learning.python_executable, ...
    'model_id', char(value.model_id), ...
    'manifest_sha256', char(value.manifest_sha256), ...
    'trace_sha256', cfg.learning.preflight_trace_sha256, ...
    'output_path', paths.learnedPreflightOutput, ...
    'elapsed_s', preflightElapsedS, ...
    'direction_task_deg', double(value.top_direction_deg), ...
    'top_direction_task_deg', double(value.top_direction_deg), ...
    'circular_mean_direction_task_deg', ...
        double(value.circular_mean_direction_deg), ...
    'aps_set_size', double(value.aps_set_size), ...
    'sample_quality', double(value.sample_quality), ...
    'deployment_authority', char(value.deployment_authority), ...
    'hardware_control_allowed', ...
        logical(value.hardware_control_allowed), ...
    'fixed_demo_pilot_authorization_required', ...
        cfg.learning.fixed_demo_pilot_authorization_required, ...
    'fixed_demo_pilot_authorization_verified', pilotVerified, ...
    'fixed_demo_pilot_authorization_id', pilotAuthorizationId, ...
    'fixed_demo_pilot_authorization_sha256', ...
        pilotAuthorizationSha256, ...
    'fixed_demo_pilot_scope', pilotScope);
logEvent(paths.events, 'LEARNED_RUNTIME_PREFLIGHT_PASS_NO_MOTION', ...
    sprintf([ ...
    'venv/model/manifest/normalization inference complete; model %s; ', ...
    'TOP1 command direction %.2f deg; circular mean %.2f deg; APS %d; ', ...
    'sample quality %.3f; elapsed %.3f s; ', ...
    'authority %s; no robot connection or command existed'], ...
    preflight.model_id, preflight.top_direction_task_deg, ...
    preflight.circular_mean_direction_task_deg, ...
    preflight.aps_set_size, ...
    preflight.sample_quality, ...
    preflight.elapsed_s, ...
    preflight.deployment_authority));
end

function assertActiveLearnedOutput(value, cfg, identifier)
requiredFields = {'schema_version', 'manifest_sha256', ...
    'direction_probabilities', 'direction_class_angles_deg', ...
    'state_probabilities', 'state_names', 'top_state', ...
    'top_direction_deg', 'circular_mean_direction_deg', ...
    'direction_world_xy', 'aps_set_size', ...
    'circular_concentration', 'ensemble_top1_span_deg', ...
    'sample_quality', 'command_direction_source', ...
    'weak_complete_fingerprint_remains_actionable', ...
    'posterior_quality_is_validity_veto', ...
    'deployment_authority', 'hardware_control_sizes', ...
    'hardware_control_allowed'};
assert(all(cellfun(@(name) isfield(value, name), requiredFields)), ...
    identifier, ...
    'Active learned output is missing one or more required schema fields.');
directionProbability = double( ...
    reshape(value.direction_probabilities, 1, []));
stateProbability = double(reshape(value.state_probabilities, 1, []));
stateNames = string(value.state_names(:));
directionWorldXY = double(reshape(value.direction_world_xy, 1, []));
[~, topStateIndex] = max(stateProbability);
apsSetSize = double(value.aps_set_size);
concentration = double(value.circular_concentration);
top1SpanDeg = double(value.ensemble_top1_span_deg);
assert(double(value.schema_version) == 1 && ...
        strcmp(char(value.manifest_sha256), ...
            sha256File(cfg.learning.deployment_manifest)) && ...
        numel(directionProbability) == 48 && ...
        numel(value.direction_class_angles_deg) == 48 && ...
        all(isfinite(directionProbability)) && ...
        all(directionProbability >= 0.0) && ...
        abs(sum(directionProbability) - 1.0) <= 1e-6 && ...
        all(isfinite(double(value.direction_class_angles_deg))) && ...
        numel(stateProbability) == 3 && ...
        all(isfinite(stateProbability)) && ...
        all(stateProbability >= 0.0) && ...
        abs(sum(stateProbability) - 1.0) <= 1e-6 && ...
        isequal(stateNames, ["supported_search"; ...
            "double_overhang"; "outer_partial_support"]) && ...
        strcmp(char(value.top_state), ...
            char(stateNames(topStateIndex))) && ...
        isfinite(double(value.top_direction_deg)) && ...
        isfinite(double(value.circular_mean_direction_deg)) && ...
        numel(directionWorldXY) == 2 && ...
        all(isfinite(directionWorldXY)) && ...
        norm(directionWorldXY) > 1e-9 && ...
        isfinite(apsSetSize) && apsSetSize >= 1.0 && ...
        apsSetSize <= 48.0 && apsSetSize == round(apsSetSize) && ...
        isfinite(concentration) && concentration >= 0.0 && ...
        concentration <= 1.0 + 1e-9 && ...
        isfinite(top1SpanDeg) && top1SpanDeg >= 0.0 && ...
        top1SpanDeg <= 180.0 + 1e-9 && ...
        isfinite(double(value.sample_quality)) && ...
        double(value.sample_quality) >= 0.0 && ...
        double(value.sample_quality) <= 1.0 && ...
        strcmp(char(value.command_direction_source), ...
            'TOP1_POSTERIOR_MODE') && ...
        logical(value.weak_complete_fingerprint_remains_actionable) && ...
        ~logical(value.posterior_quality_is_validity_veto) && ...
        strcmp(char(value.deployment_authority), ...
            cfg.learning.required_authority) && ...
        any(strcmp(string(value.hardware_control_sizes), ...
            cfg.learning.size)) && ...
        logical(value.hardware_control_allowed), ...
    identifier, ...
    ['Active learned output violates the normalized 3-state/48-bin, ', ...
     'TOP1-command, weak-complete-actionable, or active-size CAPPED_SHORTCUT ', ...
     'runtime contract.']);
if cfg.learning.fixed_demo_pilot_authorization_required
    pilotFields = {'fixed_demo_pilot_authorization_verified', ...
        'fixed_demo_pilot_authorization_id', ...
        'fixed_demo_pilot_authorization_sha256', ...
        'fixed_demo_pilot_scope', ...
        'fixed_demo_support_envelope_role', ...
        'fixed_demo_maximum_physical_tip_center_radius_mm', ...
        'fixed_demo_endpoint_tracking_allowance_mm', ...
        'fixed_demo_maximum_commanded_tip_center_radius_mm'};
    assert(all(cellfun(@(name) isfield(value, name), pilotFields)) && ...
            logical(value.fixed_demo_pilot_authorization_verified) && ...
            strcmp(char(value.fixed_demo_pilot_authorization_id), ...
                cfg.learning.fixed_demo_pilot_authorization_id) && ...
            strcmp(char(value.fixed_demo_pilot_authorization_sha256), ...
                cfg.learning.fixed_demo_pilot_authorization_sha256) && ...
            contains(string(value.fixed_demo_pilot_scope), ...
                "not general M10 full-loop promotion") && ...
            strcmp(char(value.fixed_demo_support_envelope_role), ...
                ['SAFETY_FAIL_STOP_ONLY_NEVER_POSTERIOR_INPUT_', ...
                 'NEVER_TARGET_RANKING_NEVER_STEERING']) && ...
            abs(double(value. ...
                fixed_demo_maximum_physical_tip_center_radius_mm) - ...
                5.792458277186394) <= 1e-12 && ...
            abs(double(value. ...
                fixed_demo_endpoint_tracking_allowance_mm) - 0.600) <= ...
                1e-12 && ...
            abs(double(value. ...
                fixed_demo_maximum_commanded_tip_center_radius_mm) - ...
                5.192458277186394) <= 1e-12, ...
        identifier, ...
        ['M10 active output lacks the exact hash-pinned fixed-demo pilot ', ...
         'authorization or widened its no-general-promotion scope.']);
end
end

function validateSurfaceTransportContract(cfg)
assert(cfg.motion.touchdown_lateral_drift_warning_mm > 0.0 && ...
    cfg.motion.maximum_touchdown_lateral_drift_mm > ...
        cfg.motion.touchdown_lateral_drift_warning_mm && ...
    cfg.motion.maximum_touchdown_lateral_drift_mm <= 3.00 && ...
    cfg.motion.maximum_touchdown_lateral_drift_mm < ...
        cfg.motion.maximum_lateral_excursion_mm, ...
    'M12Demo:TouchdownLateralDriftContract', ...
    ['Touchdown must retain a non-blocking early drift warning and a ', ...
     'finite air-start maximum lateral-deviation stop no larger than ', ...
     '3.00 mm.']);
assert(cfg.motion.touchdown_xy_correction_deadband_mm >= 0.0 && ...
    cfg.motion.touchdown_xy_correction_deadband_mm < ...
        cfg.motion.touch_segment_mm && ...
    cfg.motion.touchdown_xy_correction_step_mm >= ...
        cfg.motion.touch_segment_mm && ...
    cfg.motion.touchdown_xy_correction_step_mm <= ...
        cfg.motion.touch_tracking_tolerance_mm && ...
    cfg.motion.maximum_touchdown_xy_lock_error_mm == 0.25 && ...
    cfg.motion.maximum_touchdown_xy_lock_error_mm < ...
        cfg.motion.maximum_touchdown_lateral_drift_mm, ...
    'M12Demo:AnchoredTouchdownContract', ...
    ['Full-loop touchdown must correct toward one fixed air-preposition XY ', ...
     'and finish inside the 0.25 mm demo reachability contract.']);
assert(cfg.search.shortcut_cap_mm == 3.0 && ...
    cfg.search.shortcut_projection_quantile_low == 0.10 && ...
    cfg.search.shortcut_projection_quantile_high == 0.25 && ...
    cfg.search.shortcut_radius_cap_fraction_low == 0.50 && ...
    cfg.search.shortcut_radius_cap_fraction_high == 0.75 && ...
    cfg.search.shortcut_residual_fallback_minimum_cap_fraction == 0.75 && ...
    cfg.search.directional_corridor_probability_mass == 0.80 && ...
    cfg.search.directional_corridor_minimum_full_width_deg == 12.0 && ...
    cfg.search.directional_corridor_maximum_full_width_deg == 45.0 && ...
    cfg.search.directional_corridor_tracking_allowance_mm > 0.0 && ...
    cfg.search.directional_corridor_tracking_allowance_mm < ...
        cfg.search.bayes_capture_radius_mm && ...
    cfg.search.directional_corridor_maximum_advance_mm > 0.0 && ...
    cfg.search.directional_corridor_maximum_advance_mm <= ...
        cfg.search.residual_maximum_connected_leg_mm && ...
    cfg.search.directional_sector_outside_likelihood_floor > 0.0 && ...
    cfg.search.directional_sector_outside_likelihood_floor < 0.10 && ...
    cfg.search.grid_pitch_mm <= ...
        sqrt(2.0) * cfg.search.bayes_capture_radius_mm && ...
    cfg.search.maximum_grid_nodes >= ...
        size(buildGridOffsets(cfg), 1) && ...
    cfg.search.residual_maximum_connected_leg_mm >= ...
        cfg.search.grid_pitch_mm && ...
    cfg.search.residual_maximum_connected_leg_mm <= ...
        2.0 * cfg.search.grid_pitch_mm && ...
    cfg.search.directional_progress_tolerance_mm == ...
        cfg.search.tested_offset_tolerance_mm && ...
    cfg.search.swept_segment_tolerance_mm == ...
        cfg.search.tested_offset_tolerance_mm && ...
    abs(cfg.search.swept_capture_tube_tolerance_mm - ...
        (cfg.search.bayes_capture_radius_mm - ...
         cfg.search.directional_corridor_tracking_allowance_mm)) < 1e-12 && ...
    cfg.search.swept_capture_tube_tolerance_mm > ...
        cfg.search.swept_segment_tolerance_mm && ...
    cfg.search.minimum_novel_swept_length_mm > ...
        cfg.search.swept_segment_tolerance_mm && ...
    cfg.search.minimum_novel_swept_length_mm <= ...
        cfg.search.grid_pitch_mm && ...
    cfg.search.swept_segment_sample_spacing_mm > 0.0 && ...
    cfg.search.swept_segment_sample_spacing_mm <= ...
        cfg.search.swept_segment_tolerance_mm && ...
    cfg.search.eig_information_weight == 0.35 && ...
    cfg.search.eig_capture_reward_weight == 1.50 && ...
    cfg.search.eig_forward_progress_weight_per_mm > 0.0 && ...
    cfg.search.eig_novel_coverage_weight_per_mm > 0.0 && ...
    cfg.search.eig_action_cost == 0.08 && ...
    cfg.search.eig_travel_penalty_per_mm == 0.020 && ...
    cfg.search.coverage_information_weight == 0.05 && ...
    cfg.search.coverage_capture_reward_weight == 2.25 && ...
    cfg.search.eig_credible_mass == 0.95 && ...
    cfg.search.eig_minimum_utility == 0.05 && ...
    cfg.search.eig_maximum_noncontracting_updates == 2 && ...
    abs(cfg.search.cad_deep_clearance_per_side_mm - ...
        0.5 * (cfg.search.cad_socket_wall_af_mm - ...
            cfg.search.cad_shaft_af_mm)) < 1e-12 && ...
    abs(cfg.search.action_reach_mm - 4.80) < 1e-12 && ...
    abs(cfg.search.grid_radius_mm - cfg.search.action_reach_mm) < 1e-12 && ...
    abs(cfg.search.center_hypothesis_radius_mm - ...
        (cfg.search.action_reach_mm + ...
         cfg.search.bayes_capture_radius_mm + ...
         cfg.search.directional_corridor_tracking_allowance_mm)) < 1e-12 && ...
    cfg.search.center_hypothesis_radius_mm > ...
        cfg.search.action_reach_mm && ...
    size(buildCenterHypothesisOffsets(cfg), 1) > ...
        size(buildGridOffsets(cfg), 1) && ...
    cfg.search.maximum_grid_nodes == ...
        size(buildGridOffsets(cfg), 1) && ...
    abs(cfg.search.bayes_capture_radius_mm - ...
        0.25 * (cfg.search.cad_socket_mouth_af_mm - ...
            cfg.search.cad_shaft_af_mm)) < 1e-12, ...
    'M12Demo:PersistentPosteriorSearchContract', ...
    ['The promoted shortcut must be visible above endpoint resolution.  ', ...
     'The center-hypothesis support must extend beyond the finite 4.8 mm ', ...
     'action reach by capture and tracking allowance.  Proposed+ actions ', ...
     'remain connected, forward-monotone within measurement tolerance, and ', ...
     'must buy a finite length of previously unswept physical coverage.']);
assert(cfg.surface.speed_fast_mm_s == 10.0 && ...
    cfg.surface.speed_nominal_mm_s == 6.0 && ...
    cfg.surface.speed_cautious_mm_s == 3.0 && ...
    cfg.surface.speed_fast_mm_s > cfg.surface.speed_nominal_mm_s && ...
    cfg.surface.speed_nominal_mm_s > cfg.surface.speed_cautious_mm_s && ...
    cfg.surface.speed_cautious_force_delta_n < ...
        cfg.surface.soft_relief_trigger_force_n && ...
    cfg.surface.speed_cautious_torque_delta_nm < ...
        cfg.surface.soft_relief_trigger_torque_nm, ...
    'M12Demo:AdaptiveSurfaceSpeedContract', ...
    ['Surface transport must retain the disclosed 10/6/3 mm/s adaptive ', ...
     'speed schedule and enter the cautious band before soft relief.']);
assert(cfg.surface.endpoint_xy_tolerance_mm > ...
        cfg.motion.command_deadband_mm && ...
    cfg.surface.endpoint_xy_tolerance_mm <= ...
        cfg.surface.tracking_tolerance_mm && ...
    cfg.surface.endpoint_xy_tolerance_mm < ...
        cfg.surface.xy_segment_mm, ...
    'M12Demo:SurfaceEndpointContract', ...
    ['Surface endpoint tolerance must exceed command deadband and remain ', ...
     'inside the measured endpoint tracking tolerance.']);
assert(cfg.surface.minimum_actionable_z_step_mm > ...
        cfg.motion.command_deadband_mm && ...
    cfg.surface.minimum_actionable_z_step_mm <= ...
        cfg.surface.maximum_z_step_mm && ...
    cfg.surface.minimum_measured_z_progress_mm > 0.0 && ...
    cfg.surface.minimum_measured_z_progress_mm < ...
        cfg.surface.minimum_actionable_z_step_mm && ...
    cfg.surface.maximum_stagnant_z_steps >= 2, ...
    'M12Demo:SurfaceZQuantizationContract', ...
    ['Minimum actionable surface-Z correction must exceed the KST ', ...
     'deadband and not exceed the bounded Z step.']);
assert(cfg.surface.minimum_xy_progress_mm > 0.0 && ...
    cfg.surface.maximum_stagnant_xy_steps >= 2 && ...
    cfg.surface.maximum_transport_steps > ...
        cfg.surface.maximum_force_settle_steps && ...
    cfg.surface.maximum_excess_transport_actions > ...
        cfg.surface.maximum_force_settle_steps && ...
    cfg.surface.maximum_z_correction_lateral_drift_mm > 0.0 && ...
    cfg.surface.phase_timeout_s == 0.0, ...
    'M12Demo:SurfaceFiniteProgressContract', ...
    ['Surface transport retains finite progress/action bounds while its ', ...
     'arbitrary per-waypoint wall clock is disabled.']);
assert(cfg.surface.force_continuation_min_n > 0.0 && ...
    cfg.surface.force_continuation_min_n <= ...
        cfg.sensor.contact_event_n && ...
    cfg.surface.force_continuation_min_n < ...
        cfg.surface.target_normal_force_n && ...
    cfg.surface.force_continuation_max_n > ...
        cfg.surface.target_normal_force_n && ...
    cfg.surface.force_continuation_max_n < ...
        cfg.surface.soft_relief_trigger_force_n, ...
    'M12Demo:SurfaceForceContinuationContract', ...
    ['The normal-component continuation band may extend below the total-', ...
     'wrench contact event.  Force-held endpoints still require that ', ...
     'persistent event; the separately validated aperture branch instead ', ...
     'requires low wrench plus measured downward progress.']);
assert(cfg.surface.aperture_low_force_normal_max_n > 0.0 && ...
    cfg.surface.aperture_low_force_normal_max_n >= ...
        cfg.surface.force_continuation_min_n && ...
    cfg.surface.aperture_low_force_total_max_n >= ...
        cfg.surface.aperture_low_force_normal_max_n && ...
    cfg.surface.aperture_low_force_total_max_n < ...
        cfg.sensor.contact_event_n && ...
    cfg.surface.aperture_low_force_total_max_n < ...
        cfg.surface.soft_relief_trigger_force_n && ...
    cfg.surface.capture_depth_drop_mm > 0.0 && ...
    cfg.surface.capture_confirmation_extra_drop_mm > 0.0 && ...
    cfg.surface.capture_confirmation_max_steps >= 2 && ...
    cfg.surface.funnel_suspect_depth_mm > 0.0 && ...
    cfg.surface.funnel_suspect_depth_mm < ...
        cfg.surface.capture_depth_drop_mm && ...
    cfg.surface.funnel_suspect_recent_drop_mm > 0.0 && ...
    cfg.surface.funnel_suspect_recent_drop_mm <= ...
        cfg.surface.capture_minimum_recent_drop_mm && ...
    cfg.surface.funnel_xy_segment_mm > ...
        cfg.surface.endpoint_xy_tolerance_mm && ...
    cfg.surface.funnel_xy_segment_mm < cfg.surface.xy_segment_mm && ...
    cfg.surface.funnel_dither_radius_mm > ...
        cfg.motion.command_deadband_mm && ...
    cfg.surface.funnel_dither_radius_mm <= ...
        cfg.surface.funnel_xy_segment_mm && ...
    cfg.surface.funnel_dither_maximum_radius_mm >= ...
        cfg.surface.funnel_dither_radius_mm && ...
    cfg.surface.funnel_dither_maximum_radius_mm <= ...
        cfg.surface.z_stagnation_recenter_limit_mm && ...
    cfg.surface.funnel_dither_radial_increment_mm > 0.0 && ...
    cfg.surface.funnel_dither_points_per_ring >= 4, ...
    'M12Demo:SurfaceLowForceApertureContract', ...
    ['The low-force aperture/recontact band must overlap the weak-contact ', ...
     'continuation band so no recoverable 1--2 N dead zone can terminate a ', ...
     'path.  Capture still requires bounded measured downward progress.']);
assert(cfg.surface.transport_normal_force_min_n >= ...
        cfg.surface.force_continuation_min_n && ...
    cfg.surface.target_normal_force_n - ...
        cfg.surface.force_deadband_n >= ...
            cfg.surface.transport_normal_force_min_n && ...
    cfg.surface.target_normal_force_n + ...
        cfg.surface.force_deadband_n <= ...
            cfg.surface.transport_normal_force_max_n && ...
    cfg.surface.transport_normal_force_min_n < ...
        cfg.surface.target_normal_force_n && ...
    cfg.surface.transport_normal_force_max_n > ...
        cfg.surface.target_normal_force_n && ...
    cfg.surface.transport_normal_force_max_n <= ...
        cfg.surface.negative_observation_normal_max_n && ...
    cfg.surface.negative_observation_normal_min_n >= ...
        cfg.surface.force_continuation_min_n && ...
    cfg.surface.negative_observation_normal_min_n <= ...
        cfg.surface.transport_normal_force_min_n && ...
    cfg.surface.negative_observation_normal_max_n < ...
        cfg.surface.soft_relief_trigger_force_n && ...
    cfg.surface.force_correction_enter_low_n < ...
        cfg.surface.force_correction_exit_low_n && ...
    cfg.surface.force_correction_exit_low_n == ...
        cfg.surface.transport_normal_force_min_n && ...
    cfg.surface.force_correction_enter_high_n > ...
        cfg.surface.force_correction_exit_high_n && ...
    cfg.surface.force_correction_exit_high_n == ...
        cfg.surface.transport_normal_force_max_n && ...
    cfg.surface.negative_observation_xy_tolerance_mm > ...
        cfg.surface.endpoint_xy_tolerance_mm && ...
    cfg.surface.negative_observation_xy_tolerance_mm <= ...
        cfg.surface.z_stagnation_recenter_limit_mm && ...
    cfg.surface.z_stagnation_recenter_limit_mm <= ...
        cfg.surface.maximum_z_correction_lateral_drift_mm, ...
    'M12Demo:SurfaceObservationBandContract', ...
    ['The real 2.5--5.5 N stable band, correction hysteresis, and wider ', ...
     'bounded negative-observation XY handoff must remain inside the ', ...
     'contact/soft-relief hierarchy.']);
assert(cfg.surface.soft_relief_resume_force_n < ...
        cfg.surface.soft_relief_trigger_force_n && ...
    cfg.surface.soft_relief_resume_torque_nm < ...
        cfg.surface.soft_relief_trigger_torque_nm && ...
    cfg.surface.soft_relief_trigger_force_n < ...
        cfg.sensor.hard_force_delta_n && ...
    cfg.surface.soft_relief_trigger_torque_nm < ...
        cfg.sensor.hard_torque_delta_nm && ...
    cfg.surface.soft_relief_tracking_tolerance_mm > ...
        cfg.surface.tracking_tolerance_mm && ...
    cfg.surface.soft_relief_tracking_tolerance_mm <= ...
        cfg.surface.soft_relief_measured_step_envelope_mm && ...
    cfg.surface.soft_relief_measured_step_envelope_mm <= ...
        cfg.surface.maximum_z_correction_lateral_drift_mm && ...
    cfg.surface.capture_soft_force_delta_n < ...
        cfg.sensor.hard_force_delta_n && ...
    cfg.surface.capture_soft_torque_delta_nm < ...
        cfg.sensor.hard_torque_delta_nm, ...
    'M12Demo:SurfaceGuardHierarchyContract', ...
    ['Surface continuation, soft relief, capture evidence, and the ', ...
     'independent hard guards are not correctly ordered.']);
assert(cfg.motion.insertion_tracking_tolerance_mm >= ...
        cfg.motion.insertion_segment_mm && ...
    ~isempty(char(cfg.insertion.controller_tuning_revision)) && ...
    isfinite(cfg.insertion.target_depth_mm) && ...
    cfg.insertion.target_depth_mm > 0.0 && ...
    cfg.insertion.success_depth_before_bottom_margin_mm > 0.0 && ...
    cfg.insertion.success_depth_after_bottom_margin_mm >= 0.0 && ...
    abs(cfg.insertion.success_depth_minimum_mm - ...
        (cfg.insertion.target_depth_mm - ...
         cfg.insertion.success_depth_before_bottom_margin_mm)) < 1e-9 && ...
    abs(cfg.insertion.success_depth_maximum_mm - ...
        (cfg.insertion.target_depth_mm + ...
         cfg.insertion.success_depth_after_bottom_margin_mm)) < 1e-9 && ...
    cfg.motion.insertion_minimum_progress_mm > 0.0 && ...
    cfg.motion.insertion_minimum_progress_mm < ...
        cfg.motion.insertion_segment_mm && ...
    cfg.motion.insertion_maximum_stagnant_steps >= 2 && ...
    cfg.motion.insertion_maximum_actions >= ...
        ceil(cfg.insertion.target_depth_mm / ...
            cfg.motion.insertion_segment_mm) && ...
    cfg.insertion.soft_resume_force_delta_n > 0.0 && ...
    cfg.insertion.soft_resume_force_delta_n < ...
        cfg.sensor.insertion_soft_force_delta_n && ...
    cfg.sensor.insertion_soft_force_delta_n < ...
        cfg.sensor.hard_force_delta_n && ...
    cfg.insertion.soft_resume_torque_delta_nm > 0.0 && ...
    cfg.insertion.soft_resume_torque_delta_nm < ...
        cfg.sensor.insertion_soft_torque_delta_nm && ...
    cfg.sensor.insertion_soft_torque_delta_nm < ...
        cfg.sensor.hard_torque_delta_nm && ...
    cfg.insertion.soft_relief_step_mm > ...
        cfg.motion.command_deadband_mm && ...
    cfg.insertion.soft_relief_maximum_total_mm >= ...
        4.0 * cfg.insertion.soft_relief_step_mm && ...
    cfg.insertion.soft_relief_maximum_total_mm <= ...
        cfg.search.cad_socket_chamfer_depth_mm && ...
    cfg.insertion.post_relief_segment_mm > ...
        cfg.motion.command_deadband_mm && ...
    cfg.insertion.post_relief_segment_mm < ...
        cfg.motion.insertion_segment_mm && ...
    cfg.insertion.post_relief_speed_mm_s < ...
        cfg.motion.insertion_speed_mm_s && ...
    cfg.insertion.capture_xy_correction_deadband_mm > ...
        cfg.motion.command_deadband_mm && ...
    cfg.insertion.capture_xy_correction_deadband_mm < ...
        cfg.insertion.capture_xy_correction_step_mm && ...
    cfg.insertion.capture_xy_correction_step_mm <= ...
        cfg.insertion.capture_xy_tolerance_mm && ...
    cfg.insertion.capture_xy_tolerance_mm <= ...
        cfg.surface.maximum_z_correction_lateral_drift_mm && ...
    cfg.insertion.bore_entry_rebase_depth_mm > ...
        cfg.surface.capture_depth_drop_mm && ...
    cfg.insertion.funnel_dither_radius_mm > ...
        cfg.motion.command_deadband_mm && ...
    cfg.insertion.funnel_dither_radius_mm <= ...
        cfg.insertion.capture_xy_tolerance_mm && ...
    cfg.insertion.funnel_dither_maximum_radius_mm >= ...
        cfg.insertion.funnel_dither_radius_mm && ...
    cfg.insertion.funnel_dither_maximum_radius_mm <= ...
        cfg.insertion.capture_xy_tolerance_mm && ...
    cfg.insertion.funnel_dither_radial_increment_mm > 0.0 && ...
    cfg.insertion.funnel_dither_points_per_ring >= 4 && ...
    cfg.insertion.stagnation_unwedge_radius_mm > ...
        cfg.motion.command_deadband_mm && ...
    cfg.insertion.stagnation_unwedge_maximum_radius_mm >= ...
        cfg.insertion.stagnation_unwedge_radius_mm && ...
    cfg.insertion.stagnation_unwedge_maximum_radius_mm <= ...
        0.50 * cfg.search.cad_socket_mouth_af_mm - ...
        cfg.search.cad_tip_face_af_mm / sqrt(3.0) - ...
        cfg.motion.insertion_tracking_tolerance_mm + 1e-12 && ...
    cfg.insertion.terminal_low_wrench_force_n > 0.0 && ...
    cfg.insertion.terminal_low_wrench_force_n < ...
        cfg.sensor.bottom_event_n && ...
    cfg.insertion.terminal_low_wrench_torque_nm > 0.0 && ...
    cfg.insertion.terminal_low_wrench_torque_nm < ...
        cfg.sensor.insertion_soft_torque_delta_nm && ...
    cfg.insertion.terminal_bottom_lateral_force_max_n > ...
        cfg.sensor.bottom_event_n && ...
    cfg.insertion.terminal_bottom_lateral_force_max_n < ...
        cfg.sensor.insertion_soft_force_delta_n && ...
    cfg.insertion.terminal_bottom_torque_max_nm > ...
        cfg.insertion.terminal_low_wrench_torque_nm && ...
    cfg.insertion.terminal_bottom_torque_max_nm < ...
        cfg.sensor.insertion_soft_torque_delta_nm && ...
    cfg.insertion.terminal_stable_dwells >= 2, ...
    'M12Demo:InsertionFiniteProgressContract', ...
    ['Insertion endpoint tolerance may absorb KST quantization only when ', ...
     'an independent finite measured-progress gate, capture-XY axis lock, ', ...
     'and bounded soft-load relief/re-entry state remain active.']);
end

function validateM12SamplingContract(cfg)
sampling = cfg.sampling;
contact = sampling.contact_stability;
correctionDeadbandMm = 0.08;
if isfield(sampling, 'touchdown_xy_correction_deadband_mm') && ...
        isfinite(sampling.touchdown_xy_correction_deadband_mm) && ...
        sampling.touchdown_xy_correction_deadband_mm >= 0.0
    correctionDeadbandMm = ...
        sampling.touchdown_xy_correction_deadband_mm;
end
assert(~logical(sampling.interactive_confirmation_required) && ...
        strcmp(char(sampling.motion_authorization_source), ...
            'EXPLICIT_DEDICATED_SAMPLING_ENTRYPOINT_INVOCATION'), ...
    'M12Demo:SamplingAuthorizationContract', ...
    ['The dedicated sampling entrypoint itself must authorize this run; ', ...
     'no secondary command-window phrase is permitted.']);
assert(abs(sampling.touchdown_step_mm - 0.10) < 1e-12 && ...
        abs(sampling.touchdown_speed_mm_s - 1.00) < 1e-12 && ...
        abs(correctionDeadbandMm - 0.08) < 1e-12 && ...
        correctionDeadbandMm < sampling.touchdown_step_mm && ...
        sampling.step_tracking_tolerance_mm > ...
            cfg.motion.command_deadband_mm && ...
        sampling.step_tracking_recheck_acceptance_mm > ...
            sampling.step_tracking_tolerance_mm && ...
        sampling.step_tracking_recheck_acceptance_mm < ...
            sampling.maximum_touchdown_xy_lock_error_mm && ...
        sampling.step_tracking_recheck_count == 2 && ...
        sampling.step_tracking_recheck_pause_s > 0.0 && ...
        sampling.minimum_touchdown_down_progress_mm == 0.0 && ...
        sampling.maximum_touchdown_xy_lock_error_mm == 0.25 && ...
        sampling.touchdown_xy_lock_warning_mm == 0.15, ...
    'M12Demo:SamplingTouchdownContract', ...
    ['Sampling touchdown must remain 0.10 mm @ 1.0 mm/s with an ', ...
     'independent 0.15 mm XY correction cap, a 0.08 mm correction ', ...
     'deadband, a 0.12 mm immediate tracking gate, bounded ', ...
     'two-observation 0.15 mm recheck, no duplicate per-step downward ', ...
     'progress abort, and a separate 0.25 mm landing gate.']);
assert(sampling.initial_lift_mm == 2.0 && ...
        sampling.preferred_retract_mm == 0.75 && ...
        sampling.retract_extension_step_mm == 0.25 && ...
        sampling.maximum_retract_mm == 3.0 && ...
        sampling.air_translation_segment_mm == 1.50 && ...
        sampling.air_translation_speed_mm_s == 8.0 && ...
        sampling.maximum_active_time_s == 0.0 && ...
        sampling.baseline_samples == 30 && ...
        sampling.maximum_point_acquisition_attempts == 3 && ...
        isstruct(sampling.persistence) && ...
        sampling.persistence.maximum_attempts == 3 && ...
        sampling.persistence.retry_pause_s > 0.0 && ...
        sampling.persistence.retry_pause_s <= 0.25, ...
    'M12Demo:SamplingTransitContract', ...
    ['The M12 initial lift, adaptive local retract, fast air transit, ', ...
     'unbounded campaign duration, baseline, or bounded point-local ', ...
     'retry/persistence contract changed.']);
assert(contact.target_normal_force_n == 3.5 && ...
        contact.force_deadband_n == 0.5 && ...
        contact.minimum_dwell_s == 0.5 && ...
        contact.minimum_samples == 20 && ...
        contact.maximum_force_std_n == 0.2 && ...
        contact.passive_observation_s == 0.60 && ...
        contact.maximum_observation_s == 1.50 && ...
        contact.maximum_observation_s > ...
            contact.passive_observation_s && ...
        ~logical(contact.issues_motion_commands) && ...
        ~logical(contact.soft_force_quality_can_skip_cone), ...
    'M12Demo:SamplingContactStabilityContract', ...
    ['M12 sampling must passively observe the confirmed touchdown, ', ...
     'prefer 3.5 +/- 0.5 N without issuing settle motion, and treat all ', ...
     'soft force-quality metrics as offline-QC tags rather than cone gates.']);
end

function validateBaselinePolicyContract(cfg)
baseline = cfg.baselines;
assert(baseline.active_time_budget_s == 0.0 && ...
    baseline.spiral_pitch_mm_per_revolution > 0.0 && ...
    baseline.spiral_pitch_mm_per_revolution <= ...
        2.0 * (cfg.search.bayes_capture_radius_mm - ...
            cfg.search.directional_corridor_tracking_allowance_mm) && ...
    abs(baseline.proposed_local_pitch_mm_per_revolution - ...
        1.60 * cfg.search.bayes_capture_radius_mm) < 1e-12 && ...
    baseline.proposed_residual_radius_mm > 0.0 && ...
    baseline.pure_outward_radius_mm >= ...
        baseline.proposed_residual_radius_mm && ...
    baseline.path_waypoint_arc_mm > cfg.motion.command_deadband_mm && ...
    baseline.path_waypoint_arc_mm <= cfg.surface.xy_segment_mm && ...
    baseline.coverage_phase_increment_rad > 0.0 && ...
    baseline.coverage_phase_increment_rad < pi && ...
    cfg.surface.endpoint_xy_tolerance_mm < ...
        baseline.path_waypoint_arc_mm && ...
    baseline.direct_ray_limit_mm > ...
        baseline.pure_outward_radius_mm && ...
    baseline.direct_ray_limit_mm <= ...
        baseline.pure_outward_radius_mm + ...
            2.0 * cfg.search.bayes_capture_radius_mm && ...
    baseline.direct_max_attempts == 3 && ...
    abs(baseline.direct_adjustment_mm - 0.25) < 1e-12 && ...
    baseline.direct_retry_direction_half_width_deg == 20.0 && ...
    isequal(double(baseline.direct_fan_angles_deg), ...
        [0.0, 0.0, 0.0]), ...
    'M12Demo:BaselinePolicyContract', ...
    ['Baseline pitch/radii/ray/retry/micro-adjustment/fan values no ', ...
     'longer match ', ...
     'the disclosed real comparison or the surface microsegment limits.']);
end

